full_pages_ja = {'p2-page-596': '<h2>第11章 キャッシュとファイルシステム</h2>\n'
                '<p>キャッシュマネージャーは、メモリマネージャーと連携するカーネルモード関数とシステムスレッドの集合です。ローカルとネットワークの両方で、すべての Windows '
                'ファイルシステムドライバーにデータキャッシュを提供します。本章では、主要な内部データ構造と関数を含めた動作、システム初期化時のサイズの決まり方、OS '
                'の他のコンポーネントとの連携、パフォーマンスカウンターで動作を観測する方法を説明します。Windows の <code>CreateFile</code> '
                '関数でファイルキャッシュに影響する5つのフラグと、一部の I/O でキャッシュマネージャーを経由しないメモリマップ型ディスクである DAX ボリュームも扱います。</p>\n'
                '<p>Windows のすべてのファイルシステムドライバーは、ディスク I/O をできるだけ速く処理するためにキャッシュマネージャーの機能を使い、密接に連携します。Windows '
                'がサポートする各ファイルシステムを紹介し、特に多く使われる NTFS と ReFS '
                'を詳しく取り上げます。内部構造と基本操作に加え、メモリマネージャーやキャッシュマネージャーなど、他のシステムコンポーネントとの連携も説明します。</p>\n'
                '<p>最後に、ダイナミックディスクの後継として設計された記憶域スペース（Storage '
                'Spaces）の概要を説明します。記憶域スペースは、階層化やシンプロビジョニングを備えた仮想ディスクを作成できます。これらの機能は、その上で動作するファイルシステムから利用できます。</p>\n'
                '<h3>用語</h3>\n'
                '<dl>\n'
                '<dt>ディスク</dt><dd>ハードディスク、CD-ROM、DVD、Blu-ray、SSD、NVMe ディスク、フラッシュドライブなどの物理記憶装置です。</dd>\n'
                '<dt>セクター</dt><dd>記憶媒体上で、ハードウェアがアドレスを指定できるブロックです。サイズはハードウェアで決まります。多くのハードディスクでは4096または512バイトで、DVD-ROM '
                'や Blu-ray では通常2048バイトです。たとえばセクターサイズが4096バイトのディスクで、OS '
                'が先頭から5120バイト目を変更するには、2番目のセクターに4096バイトのブロックを書き込む必要があります。</dd>\n'
                '<dt>パーティション</dt><dd>ディスク上で連続するセクターの集合です。開始セクター、サイズ、その他の特性を記録するパーティションテーブルやディスク管理データベースは、パーティションと同じディスク上にあります。</dd>\n'
                '<dt>ボリューム</dt><dd>ファイルシステムドライバーが常に1つの単位として管理するセクターを表すオブジェクトです。シンプルボリュームは1つのパーティションのセクターを表し、マルチパーティションボリュームは複数のパーティションのセクターを表します。複数のパーティションを使うことで、性能、信頼性、容量の面で、シンプルボリュームにはない機能を提供できます。</dd>\n'
                '</dl>',
 'p2-page-597': '<dl>\n'
                '<dt>ファイルシステム形式</dt><dd>ファイルのデータを記憶媒体に保存する方法を定め、ファイルシステムが提供できる機能を左右します。たとえば、ファイルやディレクトリごとにユーザーのアクセス許可を設定できない形式では、アクセス制御を実装できません。形式によって、ファイルや記憶装置のサイズに上限が設けられる場合もあります。また、大小どちらのファイルやディスクに適した設計かも異なります。NTFS、exFAT、ReFS '
                'は、それぞれ機能と想定用途が異なる形式です。</dd>\n'
                '<dt>クラスター</dt><dd>多くのファイルシステム形式でアドレスを指定できるブロックです。クラスターサイズは必ずセクターサイズの整数倍です。図11-1では黄色の帯が1クラスターを示し、8つのセクターで構成されます。セクターより大きなクラスターでディスクを区切ると、領域を効率よく管理できます。その一方、ファイルサイズがクラスターサイズの整数倍でなければ最後のクラスターに未使用領域が生じます。これを内部断片化と呼びます。</dd>\n'
                '</dl>\n'
                '<p>図11-1 回転式ディスクのセクターとクラスター。1クラスターは8セクターで構成されます。</p>\n'
                '<dl><dt>メタデータ</dt><dd>ファイルシステム形式を管理するためにボリューム上に保存するデータです。たとえば、ボリューム上でのファイルやディレクトリの配置を記録します。通常、アプリケーションから直接アクセスできません。</dd></dl>\n'
                '<h3>キャッシュマネージャーの主な機能</h3>\n'
                '<ul>\n'
                '<li>ローカルとネットワークの両方で、すべての種類のファイルシステムに対応します。各ファイルシステムが独自のキャッシュ管理を実装する必要はありません。</li>\n'
                '<li>メモリマネージャーを使って、どのファイルのどの部分を物理メモリに保持するかを管理します。物理メモリに対するユーザープロセスと OS の要求を調整します。</li>\n'
                '<li>多くのキャッシュがディスクボリューム内のオフセットを使う論理ブロック単位で動作するのに対し、ファイル内のオフセットを使う仮想ブロック単位でキャッシュします。これにより、効率的な先読みや、ファイルシステムドライバーを経由しない高速アクセスが可能になります。この仕組みは高速 '
                'I/O（Fast I/O）と呼ばれ、本章の後半で説明します。</li>\n'
                '</ul>',
 'p2-page-598': '<ul>\n'
                '<li>ランダムアクセスか順次アクセスか、一時ファイルを作成するかなど、アプリケーションがファイルを開くときに渡すヒントに対応します。</li>\n'
                '<li>トランザクションログを用いるものなど、システム障害後にデータを復旧できるファイルシステムをサポートします。</li>\n'
                '<li>SSD、NVMe、直接アクセス（DAX）のディスクをサポートします。</li>\n'
                '</ul>\n'
                '<p>各機能をどう使うかは本章の各所で扱います。ここでは、その前提となる仕組みを説明します。</p>\n'
                '<h3>システム全体で共有するキャッシュ</h3>\n'
                '<p>ファイルシステムごとにデータをキャッシュする OS '
                'もあります。その場合、キャッシュやメモリ管理のコードが重複したり、キャッシュできるデータの種類が限られたりします。Windows '
                'はシステム全体で1つのキャッシュを提供し、ローカルのハードディスク、USB リムーバブルドライブ、ネットワークファイルサーバー、DVD-ROM '
                'など、外部に保存されたデータをキャッシュします。ファイルの内容と継続的な読み書きに関わるユーザーデータストリームも、ディレクトリやファイルのヘッダーなどのファイルシステムのメタデータも対象です。Windows '
                'がキャッシュにアクセスする方法は、対象データの種類によって異なります。</p>\n'
                '<h3>メモリマネージャー</h3>\n'
                '<p>キャッシュマネージャーは、キャッシュされたデータのうち、実際にどれだけが物理メモリにあるかを把握しません。頻繁にアクセスするデータの一部を物理メモリに保持して I/O '
                '性能を上げるのがキャッシュの目的ですが、キャッシュマネージャーは物理メモリを直接管理しません。標準のセクションオブジェクト（Windows API '
                'ではファイルマッピングオブジェクト）を使って、ファイルのビューをシステムの仮想アドレス空間にマップし、そこからデータにアクセスします。セクションオブジェクトはメモリマネージャーの基本機構の1つで、第1部第5章「メモリ管理」で説明しています。ビュー内のアドレスにアクセスすると、物理メモリにないブロックをメモリマネージャーがページインします。物理メモリが必要になれば、ページをキャッシュからアンマップし、変更されたデータを元のファイルに書き戻します。</p>\n'
                '<p>マップされたファイルを使って仮想アドレス空間上でキャッシュすることで、キャッシュマネージャーは、キャッシュ対象のデータにアクセスするたびに読み書きの I/O '
                '要求パケット（IRP）を発行せずに済みます。キャッシュされたファイルの該当部分をマップした仮想アドレスでデータをコピーし、必要なページの出し入れはメモリマネージャーに任せます。そのため、メモリマネージャーはシステム全体の状況を見て、システムキャッシュとユーザープロセスに割り当てる '
                'RAM の量を調整できます。キャッシュマネージャー自身が遅延書き込みなどの I/O '
                'を始める場合もありますが、そのときはメモリマネージャーにページの書き込みを依頼します。また次節で説明するように、キャッシュされたファイルを開いたプロセスと、同じファイルをユーザーアドレス空間にマップした別のプロセスが、同じデータを参照できます。</p>',
 'p2-page-599': '<h3>キャッシュの一貫性</h3>\n'
                '<p>キャッシュマネージャーの重要な役割の1つは、キャッシュ済みのデータにアクセスするどのプロセスにも、その時点で最新のデータを返すことです。たとえば、あるプロセスがファイルを開いてキャッシュが使われる一方で、別のプロセスが '
                'Windows の <code>MapViewOfFile</code> 関数で同じファイルを自分のアドレス空間に直接マップすると、一貫性が問題になり得ます。Windows '
                'では、キャッシュマネージャーもファイルをマップするアプリケーションも、メモリマネージャーの同じファイルマッピング機能を使うため、この問題は起こりません。メモリマネージャーはセクションオブジェクトやビューの数にかかわらず、マップされたファイルごとに1つの内部表現を保持します。したがって図11-2のように、重複するビューも含め、同じファイルのビューは対応する同じ物理ページにマップされます。マップされたファイルをメモリマネージャーがどう扱うかは、第1部第5章を参照してください。</p>\n'
                '<p>図11-2 キャッシュの一貫性。プロセス1とプロセス2の仮想メモリにあるビューは、メモリマネージャーのコントロール領域を通じて、同じファイルの物理ページを参照します。</p>\n'
                '<p>たとえば、プロセス1がファイルのビュー1をユーザーアドレス空間にマップし、プロセス2が同じ範囲にシステムキャッシュ経由でアクセスしているとします。プロセス1がデータを変更すると、プロセス2はディスクへの書き戻しを待たずに、その変更を読み取れます。</p>',
 'p2-page-600': '<p>メモリマネージャーが書き戻すのは、変更済みビットが立っており、書き込みがあったとわかるページだけです。したがって、I/O '
                'システム経由で同じファイルを開くプロセスと、Windows '
                'のファイルマッピング関数でそのファイルを自身のアドレス空間にマップするプロセスが混在していても、どのプロセスも常に最新のデータを参照できます。</p>\n'
                '<aside><p>ここでいうキャッシュの一貫性は、ユーザーモードでマップしたデータとキャッシュ I/O の間の一貫性です。ハードウェアへのアクセスや I/O '
                'でキャッシュありとキャッシュなしを混在させると、ほとんどの場合に一貫性が崩れます。ネットワークリダイレクターでは、ネットワーク上のデータへのアクセス時に一貫性を保つため、追加の書き戻しやキャッシュの破棄が必要です。そのため、ローカルファイルシステムよりも一貫性の確保が難しくなります。</p></aside>\n'
                '<h3>仮想ブロックキャッシュ</h3>\n'
                '<p>Windows '
                'のキャッシュマネージャーは仮想ブロックキャッシュを使い、どのファイルのどの範囲がキャッシュにあるかを追跡します。メモリマネージャーのシステムキャッシュ専用ルーチンを使い、ファイルの256 '
                'KB のビューをシステムの仮想アドレス空間にマップします。この方式には、次の利点があります。</p>\n'
                '<ul>\n'
                '<li>ファイルのどの範囲がキャッシュされているかがわかるため、呼び出し元が次にアクセスする位置を予測して先読みできます。</li>\n'
                '<li>対象データがすでにキャッシュされている場合、I/O システムはファイルシステムを経由せずに要求を処理できます。これを高速 I/O '
                'と呼びます。キャッシュマネージャーは、各ファイルのキャッシュ済み範囲を把握しているので、キャッシュ内のデータのアドレスを返すだけで要求を満たせます。</li>\n'
                '</ul>\n'
                '<p>先読みと高速 I/O の詳細は、本章の「高速 I/O」と「先読みと遅延書き込み」を参照してください。</p>\n'
                '<h3>ストリーム単位のキャッシュ</h3>\n'
                '<p>キャッシュマネージャーは、ファイル内のバイト列であるストリームを単位としてキャッシュします。NTFS '
                'など、一部のファイルシステムでは、1つのファイルに複数のストリームを格納できます。キャッシュマネージャーは、それぞれのストリームを独立してキャッシュします。NTFS '
                'はこの機能を利用し、後述の「マスターファイルテーブル」で説明するマスターファイルテーブルをストリームに分け、それらもキャッシュできます。すべてのファイルには少なくとも1つのデータストリームがあります。ストリームはファイル名で識別され、同じファイルに複数ある場合はストリーム名も使います。</p>\n'
                '<aside><p>キャッシュマネージャーの内部では、ファイル名やストリーム名を直接扱わず、それらを表すデータ構造へのポインターを使います。</p></aside>',
 'p2-page-601': '<h3>回復可能なファイルシステムのサポート</h3>\n'
                '<p>NTFS などの回復可能なファイルシステムは、システム障害後にディスクボリュームの構造を復元できるよう設計されています。障害発生時に進行中だった I/O '
                'は、再起動時にディスク上で最後まで適用するか、完全に取り消さなければなりません。処理が途中まで適用されると、ボリュームが破損し、ボリューム全体にアクセスできなくなる場合があります。これを防ぐため、ファイルシステムは、構造（メタデータ）に加える予定の変更を、ボリュームに書き込む前にログファイルへ記録します。障害によって変更が中断された場合は、ログに保存された情報を使ってボリュームへの更新をやり直します。</p>\n'
                '<p>ボリュームを確実に回復させるには、各更新をボリュームに適用する前に、その更新に対応するログレコードをディスクに完全に書き込む必要があります。ディスクへの書き込みはキャッシュされるため、キャッシュマネージャーとファイルシステムは、メタデータの更新より先にログを書き戻すよう連携します。処理の順序は次のとおりです。</p>\n'
                '<ol>\n'
                '<li>ファイルシステムは、予定しているメタデータの更新をログレコードに書き込みます。</li>\n'
                '<li>ファイルシステムは、キャッシュマネージャーにログレコードをディスクへ書き戻すよう依頼します。</li>\n'
                '<li>ファイルシステムは、ボリュームの更新をキャッシュに書き込み、キャッシュ済みのメタデータを変更します。</li>\n'
                '<li>キャッシュマネージャーは、変更されたメタデータをディスクに書き戻し、ボリュームの構造を更新します。実際には、ログレコードもボリュームの変更も、複数件をまとめて書き戻します。</li>\n'
                '</ol>\n'
                '<aside><p>ここでいうメタデータの変更は、ファイルやディレクトリの作成、名前変更、削除など、ファイルシステムの構造の変更を指します。</p></aside>\n'
                '<p>ファイルシステムがキャッシュへデータを書き込むときは、その更新に対応するログレコードを識別する論理シーケンス番号（LSN）を渡せます。キャッシュマネージャーは、キャッシュ内の各ページに対応する最小と最大の '
                'LSN を記録します。それぞれ最も古いログレコードと最も新しいログレコードを表します。NTFS '
                'は、トランザクションログで保護されたデータストリームを「書き込み禁止」としてマークします。これにより、対応するログが書き込まれる前に、マップ済みページライターがページを書き出すことを防ぎます。ライターはそのようなページを専用リストに移し、キャッシュマネージャーが遅延書き込みなどの適切なタイミングで書き戻します。</p>\n'
                '<p>複数の変更済みページをディスクに書き戻す前に、キャッシュマネージャーは対象ページに対応する最大の LSN '
                'を求め、ファイルシステムに通知します。ファイルシステムはキャッシュマネージャーを呼び返し、その LSN '
                'までのログデータを書き戻すよう指示できます。キャッシュマネージャーは、指定された LSN '
                'までのログをディスクに書き戻してから、対応するボリューム構造の変更を書き戻します。このように、更新の適用より先にログをディスクへ保存することで、システム障害後もディスクボリュームを回復できます。</p>',
 'p2-page-602': '<h3>NTFS の MFT ワーキングセットの改善</h3>\n'
                '<p>キャッシュマネージャーは、メモリマネージャーが OS に提供する一般的なメモリマップ I/O '
                'と同じ仕組みで、ファイルをキャッシュします。ファイルのビューをシステムの仮想アドレス空間にマップし、マップした仮想アドレス範囲を読み取って内容にアクセスします。キャッシュした内容が不要になると、ファイルのビューをアンマップします。どのような場合に不要になるかは後述します。この方式は一般のデータファイルではうまく機能しますが、ファイルシステムがボリューム上のファイルを管理するために保持するメタデータでは問題が生じます。</p>\n'
                '<p>ファイルハンドルが閉じられるか、所有プロセスが終了すると、キャッシュマネージャーはキャッシュ済みデータをワーキングセットから外します。NTFS '
                'はマスターファイルテーブル（MFT）を大きなファイルとして扱い、キャッシュマネージャーはほかのユーザーファイルと同じ方法でキャッシュします。ただし、MFT は System '
                'プロセスのコンテキストでマップされ、処理されるシステムファイルなので、ボリュームをアンマウントするまでハンドルが閉じられません。あるビューがマップされるきっかけとなったプロセスがハンドルを閉じたり、終了したりしても、そのビューはメモリに残ってシステムキャッシュを消費し続ける場合があります。このようなビューは、メモリが逼迫したときにだけアンマップされます。</p>\n'
                '<p>Windows 8.1 は、動的に割り当てる多段配列に各 MFT レコードの参照カウンターを保持することで、この問題を解決しました。この配列は NTFS '
                'のボリューム制御ブロック（VCB）にあります。ファイル制御ブロック（FCB）を作成するたびに、ファイルシステムは対応する MFT レコードの参照カウンターを増やします。MFT '
                'エントリが指すファイルやディレクトリのハンドルがすべて閉じられ、FCB が破棄されると、NTFS は対応する参照カウンターを減らし、キャッシュマネージャーの '
                '<code>CcUnmapFileOffsetFromSystemCache</code> を呼び出して、不要になった MFT の範囲をアンマップします。FCB と VCB '
                'の詳細は本章の後半で説明します。</p>\n'
                '<h3>メモリパーティションのサポート</h3>\n'
                '<p>Windows 10 は、Hyper-V '
                'コンテナーとゲームモードをサポートするためにメモリパーティションを導入しました。第1部第5章で説明したように、各パーティションを表す大きなデータ構造 '
                '<code>MI_PARTITION</code> '
                'は、スタンバイ、変更済み、ゼロ化済み、空きなどのページリストに加え、コミットチャージ、ワーキングセット、ページトリマー、変更ページライター、ゼロページスレッドなどの管理情報を保持します。キャッシュマネージャーは、メモリマネージャーと連携してパーティションをサポートします。NT '
                'カーネルの初期化フェーズ1では、System Executive '
                'パーティション（<code>MemoryPartition0</code>）の一部として、キャッシュマネージャーのパーティションを作成し、初期化します。カーネル初期化の詳細は第12章「起動とシャットダウン」を参照してください。パーティション対応に伴い、キャッシュマネージャーは大幅に改修され、グローバルなデータ構造と変数はすべて、キャッシュマネージャーのパーティション構造 '
                '<code>CC_PARTITION</code> に移されました。</p>',
 'p2-page-603': '<p>キャッシュマネージャーのパーティションには、共有キャッシュマップのグローバルリスト、ワーカースレッドの一覧（先読み、遅延書き込み、追加の遅延書き込み、遅延ライターとそのスキャン、非同期読み取り）、遅延ライターのスキャンイベント、遅延書き込みのスループット履歴を保持する配列、変更済みページ数のしきい値の上下限、現在の変更済みページ数などが格納されます。キャッシュマネージャーのシステムパーティションを初期化すると、必要なシステムスレッドが、そのパーティションに属する '
                'System プロセスのコンテキストで起動します。各パーティションには、<code>NtCreatePartition</code> '
                'でパーティションを作成した時点で生成される最小構成の System プロセスが必ず関連付けられます。</p>\n'
                '<p><code>NtCreatePartition</code> で新しいパーティションを作成すると、システムは空の <code>MI_PARTITION</code> '
                'オブジェクトを作成して初期化します。メモリは親パーティションから子へ移すか、後で <code>NtManagePartition</code> '
                'で稼働中に追加します。キャッシュマネージャーのパーティションオブジェクトは必要になったときにだけ作成します。新しいパーティションのコンテキストでファイルが作成されなければ、このオブジェクトは不要です。ファイルシステムがキャッシュを使ってファイルを作成またはオープンすると、<code>CcInitializeCacheMap</code> '
                'または <code>CcInitializeCacheMapEx</code> '
                'はファイルが所属するパーティションを調べ、そのパーティションに有効なキャッシュマネージャーパーティションへのリンクがあるかを確認します。なければ '
                '<code>CcCreatePartition</code> '
                'で作成・初期化します。新しいパーティションは、先読みや遅延ライターなどの専用スレッドを起動し、そのパーティションに属するページ数を基に変更済みページ数のしきい値を算出します。</p>\n'
                '<p>ファイルオブジェクトは、コントロール領域を介して所属パーティションに関連付けられます。ファイルシステムドライバーは、ストリーム制御ブロック（SCB）を作成してマップするときに、この領域を割り当てます。対象ファイルのパーティション情報は '
                '<code>MemoryPartitionInformation</code> 型のファイルオブジェクト拡張に格納され、メモリマネージャーが SCB '
                '用のセクションオブジェクトを作成するときに確認します。一般にファイルは共有されるため、ファイルシステムドライバーはシステムパーティション以外のパーティションを自動で関連付けられません。アプリケーションは '
                '<code>NtSetInformationFileKernel</code> API に新しい情報クラス '
                '<code>FileMemoryPartitionInformation</code> を指定して、別のパーティションを関連付けられます。</p>\n'
                '<h3>キャッシュの仮想メモリ管理</h3>\n'
                '<p>Windows '
                'のシステムキャッシュマネージャーは仮想アドレスを単位にデータをキャッシュします。そのため、システムの仮想アドレス空間の領域を使用し、仮想アドレス制御ブロック（VACB）という構造で管理します。VACB '
                'は領域をビューと呼ばれる256 KB のスロットに区切ります。起動時にキャッシュマネージャーが初期化されると、キャッシュ領域を記述する最初の VACB '
                '配列を割り当てます。キャッシュの需要が増えてさらにメモリが必要になると、VACB '
                '配列を追加します。他の用途でシステムの資源が逼迫すると、キャッシュ用の仮想アドレス空間を縮小することもできます。</p>\n'
                '<p>ファイルに対する最初の I/O（読み取りまたは書き込み）では、要求されたデータを含む256 KB '
                '境界に整列した領域のビューを、システムキャッシュのアドレス空間の空きスロットにマップします。たとえば、ファイルの先頭から300,000バイトの位置にある10バイトを読み取る場合、ビューはファイル内の2番目の256 '
                'KB 境界にあたる262,144バイトの位置から始まり、256 KB の範囲をカバーします。</p>',
 'p2-page-604': '<p>キャッシュマネージャーは、ファイルのビューをキャッシュのアドレス空間にあるスロットへラウンドロビン方式でマップします。最初に要求されたビューを最初の256 KB '
                'のスロットに、次のビューを2番目のスロットに入れ、以降も同様に処理します。図11-3ではファイルB、A、Cの順にマップしたので、最初のスロットにはファイルBのビューが入ります。ファイルBの先頭256 '
                'KB だけがマップされているのは、アクセスされた範囲がそこに収まるためです。ファイルCは100 KB で1つのビューより小さいものの、専用の256 KB '
                'スロットを使います。</p>\n'
                '<p>図11-3 サイズの異なるファイルをシステムキャッシュにマップする。ファイルAは500 KB、Bは750 KB、Cは100 KB '
                'です。図ではキャッシュ側のスロットを「ビュー」、各ファイルの側の領域を「セクション」と表しています。</p>\n'
                '<p>キャッシュマネージャーは、ビューがアクティブな間はマップを維持します。非アクティブになった後もマップが残る場合があります。ビューがアクティブになるのは、そのファイルの読み取りまたは書き込みの処理中だけです。プロセスが '
                '<code>CreateFile</code> に <code>FILE_FLAG_RANDOM_ACCESS</code> '
                'を指定していなければ、キャッシュマネージャーは順次アクセスを検出すると、そのファイルの新しいビューをマップする際に不要になった非アクティブなビューをアンマップします。</p>\n'
                '<p>アンマップされたビューのページは、変更の有無に応じて変更済みリストまたはスタンバイリストへ移ります。メモリマネージャーはキャッシュマネージャー専用のインターフェイスを公開しているため、キャッシュマネージャーはページをリストの先頭と末尾のどちらへ置くかを指定できます。<code>FILE_FLAG_SEQUENTIAL_SCAN</code> '
                'を指定して開いたファイルのページは先頭に、それ以外は末尾に移します。これにより、順次読み取りしたファイルのページを早めに再利用し、大きなファイルをコピーするときに物理メモリの広い範囲が影響を受けるのを防ぎます。このフラグを指定すると、キャッシュマネージャーはビューのアンマップも積極的に行います。</p>\n'
                '<p>ファイルのビューをマップする必要があるのに空きスロットがなければ、キャッシュマネージャーは最後にマップされてから最も時間が経っている非アクティブなビューをアンマップし、そのスロットを再利用します。再利用できるビューがなければ、処理に必要なシステムリソースが不足していることを示す '
                'I/O '
                'エラーを返します。ビューがアクティブなのは読み書きの処理中に限られ、この状態になるには数千のファイルに同時にアクセスする必要があるため、実際に発生する可能性は極めて低くなります。</p>',
 'p2-page-605': '<h3>キャッシュのサイズ</h3>\n'
                '<p>Windows は、システムキャッシュの仮想サイズと物理サイズを別々に算出します。ほかのメモリ管理と同様に、いくつかの要因がサイズを左右します。</p>\n'
                '<h4>キャッシュの仮想サイズ</h4>\n'
                '<p>32ビット版 Windows では、カーネルモードの仮想アドレス空間の大きさと、必要に応じて設定できるレジストリ値 <code>SystemCacheLimit</code> '
                'によって、システムキャッシュの仮想サイズが制限されます。カーネル仮想アドレス空間のサイズ制限については第1部第5章を参照してください。上限はシステムアドレス空間の2 GB '
                'ですが、システムのページテーブルエントリ（PTE）、非ページプールとページプール、ページテーブルなども同じ空間を使うため、通常はこれよりかなり小さくなります。64ビット版 '
                'Windows の仮想キャッシュの上限は64 TB です。この場合も上限はシステムアドレス空間の大きさで決まり、原本では56ビットアドレス指定に対応する将来のシステムの上限を32 '
                'PB（ペタバイト）としています。</p>\n'
                '<h4>キャッシュのワーキングセットのサイズ</h4>\n'
                '<p>Windows のキャッシュマネージャーは、物理メモリの管理をシステム全体のメモリマネージャーに委ねます。これは他の OS '
                'との主な設計上の違いの1つです。ワーキングセットの拡張や縮小、変更済みリストとスタンバイリストの管理を行う既存のコードで、システムキャッシュのサイズも調整し、プロセスと OS '
                'の物理メモリ需要を動的に釣り合わせます。</p>\n'
                '<p>システムキャッシュは、キャッシュデータ、ページプール、ページング可能なカーネルコードとドライバーコードを含む1つのシステムワーキングセットを共有します。第1部第5章の「システムワーキングセット」で説明したように、内部ではこれをシステムキャッシュワーキングセットと呼びます。本書では、システムキャッシュ以外の領域も含むため、単にシステムワーキングセットと呼びます。同章で述べたとおり、レジストリ値 '
                '<code>LargeSystemCache</code> が1の場合、メモリマネージャーは実行中のプロセスのワーキングセットよりもシステムワーキングセットを優先します。</p>\n'
                '<h4>キャッシュの物理サイズ</h4>\n'
                '<p>システムワーキングセットには、キャッシュの仮想アドレス空間のビューにマップされた物理メモリが含まれます。メモリマネージャーのスタンバイリストや変更済みリストにもファイルデータが残っている場合があるため、物理メモリ上にキャッシュされているファイルデータの総量は、ワーキングセット上の量より多いことがあります。</p>\n'
                '<p>第1部第5章で説明したように、ワーキングセットの縮小やページの置き換えで、メモリマネージャーはページをスタンバイリストまたは変更済みリストへ移します。どちらへ移すかは、ページを再利用する前に、ページファイルなどへの書き戻しが必要かどうかで決まります。</p>',
 'p2-page-606': '<p>これらのリストがなければ、プロセスがワーキングセットから外されたデータに再びアクセスするたびに、メモリマネージャーはハードフォールトを処理してディスクから読み直す必要があります。実際には、どちらかのリストにページが残っていれば、ソフトフォールトの処理だけでプロセスのワーキングセットに戻せます。つまり、これらのリストは、ページファイル、実行イメージ、データファイルの内容を保持するメモリ上のキャッシュとしても機能します。システムでキャッシュされるファイルデータの総量には、システムワーキングセットに加え、スタンバイリストと変更済みページリストに残るデータも含まれます。</p>\n'
                '<p>キャッシュマネージャーがシステムワーキングセットに収まる量を大きく超えるファイルデータを物理メモリに保持できる例として、専用ファイルサーバーを考えます。クライアントアプリケーションがネットワーク経由でファイルにアクセスすると、サーバー側のファイルサーバードライバー（後述する '
                '<code>%SystemRoot%&#92;System32&#92;Drivers&#92;Srv2.sys</code> '
                'など）は、キャッシュマネージャーのインターフェイスを使って、クライアントに代わってファイルを読み書きします。クライアントが1 MB '
                'のファイルを数千個読み取ると、マッピング用の空間を使い切り、VACB '
                'のマッピング領域も広げられなくなった時点で、キャッシュマネージャーは既存のビューの再利用を始めます。その後はファイルを読み取るたびに、既存のビューをアンマップして新しいファイルに割り当て直します。</p>\n'
                '<p>ビューがアンマップされても、メモリマネージャーは対応するファイルデータを破棄せず、キャッシュのワーキングセットからスタンバイリストへ移します。物理メモリを必要とするほかの処理がなければ、スタンバイリストはシステムワーキングセット以外の物理メモリをほぼすべて占めることができます。つまり、図11-4のように、サーバーの物理メモリのほぼすべてをファイルキャッシュとして使えます。</p>\n'
                '<p>図11-4 物理メモリの大半をファイルキャッシュに使う例。8 GB の物理メモリのうち、スタンバイリストが約7 '
                'GB、仮想キャッシュに割り当てられたシステムワーキングセットが960 MB を占め、残りはその他の用途に使われます。</p>\n'
                '<p>キャッシュ済みファイルデータはシステムワーキングセット、変更済みページリスト、スタンバイリストにあり、これらのサイズはすべてメモリマネージャーが管理します。この意味で、物理メモリ上のキャッシュを実際に管理しているのはメモリマネージャーです。キャッシュマネージャーは、メモリマネージャーを通じてファイルデータにアクセスするためのインターフェイスを提供します。また、先読みや遅延書き込みの方針によって、メモリマネージャーがどのデータを物理メモリに保持するかに影響を与え、システム仮想アドレス空間のビューも管理します。</p>\n'
                '<p>タスクマネージャーはシステムでキャッシュされているファイルデータの総量を示すため、「パフォーマンス」に「キャッシュ済み」を表示します。この値にはシステムワーキングセット、スタンバイリスト、変更済みページリストのサイズが反映されます。Process '
                'Explorer では、それぞれ <code>Cache '
                'WS</code>（システムキャッシュワーキングセット）、<code>Standby</code>、<code>Modified</code> '
                'として個別に表示します。図11-5のシステム情報画面では、左下の <code>Physical Memory</code> 欄に <code>Cache WS</code> '
                'があり、中央付近の <code>Paging Lists</code> 欄にスタンバイリストと変更済みリストのサイズがあります。</p>',
 'p2-page-607': '<p>タスクマネージャーの「キャッシュ済み」の値には、Process Explorer の <code>Paged WS</code>、<code>Kernel '
                'WS</code>、<code>Driver WS</code> '
                'に相当する値も含まれます。この指標が決められた当時は、システムワーキングセットの大半をキャッシュのワーキングセットが占めていました。現在ではそうではありませんが、タスクマネージャーには当時の集計方法が残っています。</p>\n'
                '<p>図11-5 Process Explorer のシステム情報ダイアログ。</p>\n'
                '<h3>キャッシュのデータ構造</h3>\n'
                '<p>キャッシュマネージャーは、次のデータ構造を使ってキャッシュされたファイルを追跡します。</p>\n'
                '<ul>\n'
                '<li>システムキャッシュ内の256 KB のスロットは、それぞれ1つの VACB で表します。</li>\n'
                '<li>キャッシュを使ってファイルを開くたびに、専用のプライベートキャッシュマップを用意します。このマップには、後述の「アクセスパターンに応じた先読み」で扱う、先読みの制御に必要な情報が入ります。</li>\n'
                '<li>キャッシュされたファイルごとに共有キャッシュマップが1つあり、そのファイルのビューがマップされたシステムキャッシュ内のスロットを指します。</li>\n'
                '</ul>\n'
                '<p>以下では、これらの構造と相互の関係を説明します。</p>\n'
                '<h4>システム全体のキャッシュデータ構造</h4>\n'
                '<p>キャッシュマネージャーは、非ページプールに保存する仮想アドレス制御ブロック（VACB）の配列を使い、システムキャッシュの各ビューの状態を追跡します。32ビットシステムでは1つの '
                'VACB が32バイト、配列が128 KB なので、1配列に4,096個の VACB が入ります。</p>\n'
                '<figure><img loading="lazy" width="584" height="392" '
                'src="assets/761aca7df6d2ebeb0f8ab3b2.webp" alt="キャッシュの使用状況（原文の図1）"></figure>',
 'p2-page-608': '<p>64ビットシステムでは1つの VACB が40バイトなので、1配列に3,276個入ります。キャッシュマネージャーはシステムの初期化時に最初の VACB '
                '配列を割り当て、システム全体の VACB 配列リスト <code>CcVacbArrays</code> につなぎます。図11-6のように、各 VACB '
                'はシステムキャッシュ内の256 KB のビュー1つに対応します。VACB の構造は図11-7に示します。</p>\n'
                '<p>図11-6 システムの VACB 配列。システム全体の配列リストに各 VACB 配列がつながり、配列内の各エントリがシステムキャッシュのビュー1つに対応します。</p>\n'
                '<p>図11-7 VACB のデータ構造。システムキャッシュ内のデータの仮想アドレス、共有キャッシュマップへのポインター、ファイルオフセット、アクティブ参照数、LRU '
                'リストにつなぐリンク、自身を格納する VACB 配列へのポインターを保持します。</p>',
 'p2-page-609': '<p>各 VACB 配列には、低優先度と高優先度の2種類のマッピング用 VACB があります。システムは各配列に最初から高優先度の VACB を64個割り当てます。高優先度の '
                'VACB '
                'は、ビューをシステムアドレス空間にあらかじめ確保します。データをマップしようとしたとき、メモリマネージャーが新しいビューを提供できず、かつ要求が高優先度なら、キャッシュマネージャーは確保済みのビューの1つを使います。重要なファイルシステムメタデータのマッピングや、キャッシュからデータを破棄する処理などがその例です。高優先度の '
                'VACB も使い切ると、新しいビューを必要とする操作はリソース不足で失敗します。既定のマッピング優先度は低ですが、ファイルシステムがキャッシュ済みデータを固定する際に '
                '<code>PIN_HIGH_PRIORITY</code> を指定すると、必要に応じて高優先度の VACB を要求できます。固定については後述します。</p>\n'
                '<p>図11-7に示すように、VACB '
                'の第1フィールドはシステムキャッシュ内のデータの仮想アドレスです。第2フィールドは、キャッシュ対象のファイルを識別する共有キャッシュマップへのポインターです。第3フィールドは、ファイル内のビューの開始オフセットを表します。これは256 '
                'KB '
                '単位で整列するため、オフセットの下位16ビットは常に0になります。そこで、この16ビットをビューの参照数、つまり現在そのビューにアクセスしている読み書きの処理数の記録に使います。第4フィールドは、VACB '
                'が解放されたときに、最近使われていない VACB を管理する LRU リストへつなぐためのリンクです。キャッシュマネージャーは VACB '
                'の割り当て時に、まずこのリストを調べます。最後の第5フィールドは、VACB 自身を格納する配列のヘッダーを指します。</p>\n'
                '<p>ファイルの I/O を開始すると、対応する VACB の参照数が増え、処理が終わると減ります。参照数が0より大きい VACB '
                'はアクティブです。ファイルシステムのメタデータにアクセスする場合、アクティブ参照数は、ビュー内のページをメモリに固定しているファイルシステムドライバーの数を表します。</p>\n'
                '<h4>実験\u3000VACB と統計を確認する</h4>\n'
                '<p>キャッシュマネージャーは、開発者やサポート担当者がクラッシュダンプをデバッグするときに使える値を内部で記録します。これらの変数名はすべて <code>CcDbg</code> '
                'で始まるため、デバッガーの <code>x</code> コマンドで一覧表示できます。</p>\n'
                '<pre><code>1: kd&gt; x nt!*ccdbg*\n'
                'fffff800`d052741c nt!CcDbgNumberOfFailedWorkQueueEntryAllocations = &lt;no type '
                'information&gt;\n'
                'fffff800`d05276ec nt!CcDbgNumberOfNoopedReadAheads = &lt;no type information&gt;\n'
                'fffff800`d05276e8 nt!CcDbgLsnLargerThanHint = &lt;no type information&gt;\n'
                'fffff800`d05276e4 nt!CcDbgAdditionalPagesQueuedCount = &lt;no type information&gt;\n'
                'fffff800`d0543370 nt!CcDbgFoundAsyncReadThreadListEmpty = &lt;no type information&gt;\n'
                'fffff800`d054336c nt!CcDbgNumberOfCcUnmapInactiveViews = &lt;no type information&gt;\n'
                'fffff800`d05276e0 nt!CcDbgSkippedReductions = &lt;no type information&gt;\n'
                'fffff800`d0542e04 nt!CcDbgDisableDAX = &lt;no type information&gt;\n'
                '...</code></pre>\n'
                '<p>32ビット版と64ビット版の実装の違いにより、変数名が異なるシステムもあります。この実験では、個々の名前よりも調査方法に注目してください。これらの変数と VACB '
                '配列のヘッダー構造を手がかりに、カーネルデバッガーですべての VACB 配列ヘッダーを列挙できます。</p>',
 'p2-page-610': '<p><code>CcVacbArrays</code> は VACB '
                '配列ヘッダーを指すポインターの配列です。各ポインターを間接参照すると、<code>_VACB_ARRAY_HEADER</code> '
                'の内容を表示できます。まず、使用中の最大インデックスを調べます。</p>\n'
                '<pre><code>1: kd&gt; dd nt!CcVacbArraysHighestUsedIndex  l1\n'
                'fffff800`d0529c1c  00000000</code></pre>\n'
                '<p>続いて、最大値まで各インデックスのポインターを間接参照します。このシステムでは、一般的な構成と同じく最大値は0なので、参照するヘッダーは1つだけです。</p>\n'
                '<pre><code>1: kd&gt; ?? (*((nt!_VACB_ARRAY_HEADER***)@@(nt!CcVacbArrays)))[0]\n'
                'struct _VACB_ARRAY_HEADER * 0xffffc40d`221cb000\n'
                '+0x000 VacbArrayIndex   : 0\n'
                '+0x004 MappingCount     : 0x302\n'
                '+0x008 HighestMappedIndex : 0x301\n'
                '+0x00c Reserved\n'
                '                         : 0</code></pre>\n'
                '<p>配列が複数ある場合は、コマンド末尾のインデックスを最大値まで順に増やします。この出力では、VACB 配列は1つで、アクティブな VACB '
                'は770個（<code>0x302</code>）です。</p>\n'
                '<p>空きリストにある VACB の数は <code>CcNumberOfFreeVacbs</code> '
                'に格納されます。検証環境では2,506個（<code>0x9ca</code>）です。</p>\n'
                '<pre><code>1: kd&gt; dd nt!CcNumberOfFreeVacbs  l1\n'
                'fffff800`d0527318  000009ca</code></pre>\n'
                '<p>VACB '
                '配列が1つの64ビットシステムでは、空きの2,506個（<code>0x9ca</code>）とアクティブな770個（<code>0x302</code>）を合わせると、配列1つの要素数である3,276個になります。空き '
                'VACB を使い切った場合、キャッシュマネージャーは新しい VACB 配列の割り当てを試みます。アクティブ数と空き数は別々に読み取るため、その間にシステムが VACB '
                'を割り当てたり解放したりすると、合計が3,276個と一致しない場合があります。その場合は、間を空けずに実験を数回繰り返してください。ただし、ファイルシステムの活動が多い場合などは、安定した値が得られないこともあります。</p>\n'
                '<h4>ファイルごとのキャッシュデータ構造</h4>\n'
                '<p>開かれたファイルの各ハンドルには、対応するファイルオブジェクトがあります。ファイルオブジェクトの詳細は、第1部第6章「I/O '
                'システム」で説明しています。キャッシュを使うファイルのオブジェクトは、直近2回の読み取り位置を保持するプライベートキャッシュマップを指します。キャッシュマネージャーはこの情報を使ってアクセスパターンに応じた先読みを行います。詳細は後述します。同じファイルを開いている各インスタンスのプライベートキャッシュマップは、連結リストにまとめられます。</p>\n'
                '<p>共有キャッシュマップは、個々のファイルオブジェクトではなく、キャッシュ対象のファイルごとに1つあります。所属パーティション、ファイルサイズ、有効データ長など、対象ファイルのキャッシュ状態を記録します。有効データ長の役割は「ライトバックキャッシュと遅延書き込み」で説明します。また、メモリマネージャーが管理し、ファイルの仮想メモリへのマッピングを表すセクションオブジェクトと、そのファイルのプライベートキャッシュマップ一覧を指します。</p>',
 'p2-page-611': '<p>共有キャッシュマップは、そのファイルについてシステムキャッシュに現在マップされているビューを表す VACB '
                'も参照します。セクションオブジェクトへのポインターについては、第1部第5章を参照してください。キャッシュマネージャーは、各ファイルの使用中の共有キャッシュマップを、パーティションのデータ構造内にあるグローバル連結リストにつなぎます。ファイルごとのキャッシュデータ構造の関係を図11-8に示します。</p>\n'
                '<p>図11-8 '
                'ファイルごとのキャッシュデータ構造。共有キャッシュマップは、オープン数、ファイルサイズ、有効データ長、セクションオブジェクトへのポインター、プライベートキャッシュマップのリスト、および '
                'VACB '
                'インデックス配列を管理します。各ファイルオブジェクトに対応するプライベートキャッシュマップには、先読み情報が格納されます。共有・プライベート両方のマップには次のマップへのリンクがあり、必要に応じて追加の '
                'VACB インデックス配列を参照できます。</p>\n'
                '<p>特定のファイルを読み取る要求を受けると、キャッシュマネージャーは次の2点を確認します。</p>\n'
                '<ol>\n'
                '<li>ファイルはキャッシュにあるか。</li>\n'
                '<li>キャッシュにあるなら、要求された位置を指す VACB はどれか。該当する VACB は存在するか。</li>\n'
                '</ol>\n'
                '<p>つまり、指定された位置を含むファイルビューがシステムキャッシュにマップされているかを調べます。指定されたファイルオフセットを含む VACB '
                'がなければ、そのデータは現在システムキャッシュにマップされていません。</p>\n'
                '<p>ファイルのどのビューがマップされているかを追跡するため、キャッシュマネージャーは VACB へのポインターを並べた VACB '
                'インデックス配列を管理します。配列の最初のエントリはファイルの先頭256 KB、2番目は次の256 KB '
                'を指し、以降も同様です。図11-9では、3つのファイルにまたがる4つの領域がシステムキャッシュにマップされています。</p>',
 'p2-page-612': '<p>プロセスがファイル内の特定の位置にアクセスすると、キャッシュマネージャーはそのファイルの VACB インデックス配列で、該当するエントリを調べます。エントリが0以外なら '
                'VACB へのポインターがあり、要求された範囲はすでにキャッシュにマップされています。その VACB '
                'は、ファイルのビューがマップされたシステムキャッシュ内の位置を指します。エントリが0なら、キャッシュマネージャーはシステムキャッシュ内の空きスロットと対応する空き VACB '
                'を探し、必要なビューをマップします。</p>\n'
                '<p>メモリ使用量を抑えるため、共有キャッシュマップ自体に4エントリの VACB インデックス配列が組み込まれています。1つの VACB が256 KB '
                'を表すので、この固定長の配列で最大1 MB のファイルを扱えます。ファイルが1 MB を超える場合は、ファイルサイズを256 KB '
                'で割って端数を切り上げた数のエントリを持つ配列を非ページプールに割り当て、共有キャッシュマップにそのポインターを格納します。</p>\n'
                '<p>図11-9 VACB インデックス配列。ファイルA（500 KB）、B（750 KB）、C（100 '
                'KB）はそれぞれインデックス配列を持ちます。マップ済みの領域に対応するエントリはシステムの VACB 配列を参照し、各 VACB がシステムキャッシュ内のビューを指します。</p>\n'
                '<p>ファイルが32 MB を超えると、非ページプールに割り当てる VACB '
                'インデックス配列は、さらにメモリを節約するため、各配列に128エントリを持つ疎な多段構造になります。必要な段数は、次の式の結果を整数に切り上げて求めます。</p>\n'
                '<pre><code>（ファイルサイズの表現に必要なビット数 − 18）÷ 7</code></pre>\n'
                '<p>18を引くのは、VACB 1つが256 '
                'KB（2<sup>18</sup>バイト）を表すためです。7で割るのは、各段に128（2<sup>7</sup>）エントリあるためです。したがって、キャッシュマネージャーが対応する最大サイズである63ビットで表せる最大のファイルでも、必要な段数は7です。この配列が疎なのは、最下段のインデックス配列にアクティブなビューがある枝だけを割り当てるためです。図11-10は、3段を必要とする大きなスパースファイルの '
                'VACB 配列の例です。</p>',
 'p2-page-613': '<p>図11-10 多段 VACB 配列。共有キャッシュマップは追加の VACB インデックス配列を指します。各段の配列のインデックスは0〜127で、最下段のエントリは VACB '
                'を指します。</p>\n'
                '<p>スパースファイルは、有効なデータをわずかしか含まなくても、ファイルサイズが非常に大きくなることがあります。この方式では、現在マップされているビューの追跡に必要な配列だけを割り当てるため、そのようなファイルも効率よく扱えます。たとえば、32 '
                'GB のスパースファイルのうち256 KB だけがキャッシュの仮想アドレス空間にマップされているとします。32 GB '
                'のファイルには3段の配列が必要ですが、マッピングがあるのは1本の枝だけなので、各段に1つずつ、計3つのインデックス配列を割り当てれば足ります。多段化しなければ、原本の概算で128,000エントリを持つインデックス配列が必要です。これは128エントリの配列1,000個分に相当します。</p>\n'
                '<h3>ファイルシステムのインターフェイス</h3>\n'
                '<p>キャッシュを使う読み取りや書き込みでファイルのデータに初めてアクセスするときは、ファイルシステムドライバーが、ファイルの一部がシステムキャッシュにマップ済みかどうかを確認します。まだマップされていなければ、ドライバーは '
                '<code>CcInitializeCacheMap</code> を呼び出し、前節で説明したファイルごとのデータ構造を初期化します。</p>',
 'p2-page-614': '<p>ファイルのキャッシュアクセスを初期化すると、ファイルシステムドライバーは用途に応じた関数を呼び出してファイルのデータにアクセスします。主なアクセス方法は次の3つです。</p>\n'
                '<ul>\n'
                '<li>コピー方式は、システム空間のキャッシュバッファーとユーザー空間のプロセスバッファーの間でユーザーデータをコピーします。</li>\n'
                '<li>マッピングと固定を使う方式は、仮想アドレスでキャッシュバッファーを直接読み書きします。</li>\n'
                '<li>物理メモリアクセス方式は、物理アドレスでキャッシュバッファーを直接読み書きします。</li>\n'
                '</ul>\n'
                '<p>ファイルシステムドライバーは、キャッシュを使う読み取りと、キャッシュを使わない読み取りの両方を実装する必要があります。これは、メモリマネージャーがページフォールトを処理するときに、読み取り要求が再帰的に発生して無限ループになるのを防ぐためです。メモリマネージャーがページフォールトを解決するため、ファイルシステムにデバイスドライバー経由でデータの取得を求めるときは、IRP '
                'に「キャッシュなし」と「ページング I/O」のフラグを設定し、ページング用の読み取りであることを示します。</p>\n'
                '<p>図11-11は、ユーザーがファイルを読み書きしたときの、キャッシュマネージャー、メモリマネージャー、ファイルシステムドライバーの典型的な連携を示します。ファイルシステムは '
                '<code>CcCopyRead</code> と <code>CcCopyWrite</code> のコピー経路を通じて、キャッシュマネージャーを呼び出します。たとえば '
                '<code>CcFastCopyRead</code> または <code>CcCopyRead</code> '
                'による読み取りでは、キャッシュマネージャーがファイルの対象範囲をマップするビューを用意し、そのビューからユーザーバッファーへデータをコピーします。コピーがビュー内の無効なページにアクセスするたびにページフォールトが生じます。メモリマネージャーはそのページに対応するファイルのデータを取得するため、キャッシュを使わない '
                'I/O をファイルシステムドライバーに要求します。</p>\n'
                '<p>図11-11 '
                'ファイルシステムとキャッシュマネージャー、メモリマネージャーの連携。図中のメモリマネージャーにはページフォールトハンドラーと変更済みページ・マップ済みページのライターがあり、キャッシュマネージャーには遅延ライターと先読み処理があります。非キャッシュ '
                'I/O とページング I/O は、ファイルシステムドライバーを介してストレージデバイスドライバーに渡されます。</p>\n'
                '<p>続く3つの節では、各キャッシュアクセス方式の目的と使い方を説明します。</p>',
 'p2-page-615': '<h4>キャッシュへのコピーとキャッシュからのコピー</h4>\n'
                '<p>システムキャッシュはシステム空間にあり、すべてのプロセスのアドレス空間にマップされています。ただし、ほかのシステム空間のページと同様、ユーザーモードからはアクセスできません。アクセスを認めると、キャッシュ内のファイルデータを、読み取り権限のないプロセスが読めるおそれがあります。このため、ユーザーアプリケーションがキャッシュを使うファイルを読み書きするときは、カーネルモードのルーチンが、システム空間のキャッシュバッファーとプロセスのアドレス空間にあるアプリケーションのバッファーの間でデータをコピーします。</p>\n'
                '<h4>マッピングと固定によるキャッシュアクセス</h4>\n'
                '<p>ユーザーアプリケーションがディスク上のファイルデータを読み書きするように、ファイルシステムドライバーはファイル自体を記述するメタデータ（ボリューム構造を表すデータ）を読み書きします。ドライバーはカーネルモードで動作するため、適切にキャッシュマネージャーと連携すれば、システムキャッシュ内のデータを直接変更できます。そのため、キャッシュマネージャーはメタデータがある仮想アドレスを取得する関数を提供します。ドライバーは中間バッファーを使わずにメタデータを変更できます。</p>\n'
                '<p>キャッシュ内のメタデータを読み取るとき、ファイルシステムドライバーはキャッシュマネージャーのマッピングインターフェイスを呼び出し、対象データの仮想アドレスを取得します。キャッシュマネージャーは要求範囲の全ページにアクセスしてメモリに読み込み、制御をドライバーに戻します。ドライバーはそこから直接データを読み取れます。</p>\n'
                '<p>キャッシュ内のページを変更するときは、キャッシュマネージャーの固定（pinning）機能を呼び出します。これにより、仮想メモリ内でページがアクティブに保たれ、回収されなくなります。DMA '
                '転送のためにデバイスドライバーが行うような、物理メモリへのページのロックは行いません。ファイルシステムドライバーは通常、メタデータストリームを書き込み禁止としてマークします。メモリマネージャーのマップ済みページライター（第1部第5章を参照）は、明示的な指示があるまで、そのページをディスクに書き戻しません。ドライバーが固定を解除すると、キャッシュマネージャーは保持していた資源を解放し、変更を後でディスクに書き戻したり、メタデータが占めていたキャッシュビューを解放したりできるようにします。</p>\n'
                '<p>マッピングと固定は、ファイルシステムの実装で難しいバッファー管理を簡素化します。キャッシュ内のメタデータを直接操作できなければ、ファイルシステムは、ボリューム構造を更新する際に必要となるバッファーの最大数を事前に見積もる必要があります。この方式なら、中間バッファーを用意せず、メモリマネージャーが提供する仮想メモリ上でボリューム構造を直接更新できます。制約は、利用できるメモリの量だけです。</p>\n'
                '<h4>直接メモリアクセスによるキャッシュアクセス</h4>\n'
                '<p>キャッシュマネージャーは、メタデータに直接アクセスするマッピングと固定に加え、3つ目のインターフェイスとして直接メモリアクセス（DMA）を提供します。DMA '
                'の関数は、中間バッファーを介さずにキャッシュページを読み書きします。たとえば、ネットワークファイルシステムがネットワーク上でデータを転送するときに使います。</p>',
 'p2-page-616': '<p>DMA '
                'インターフェイスは、キャッシュ済みのユーザーデータの物理アドレスをファイルシステムに返します。マッピングと固定のインターフェイスが返すのは仮想アドレスです。物理アドレスを使えば、物理メモリからネットワークデバイスにデータを直接転送できます。1〜2 '
                'KB 程度の小さなデータは通常のバッファーを使うコピーインターフェイスでも処理できます。転送量が大きい場合は、DMA '
                'を使うことで、リモートシステムからのファイル要求を処理するネットワークサーバーの性能を大きく改善できます。各物理メモリ領域を記述するには、メモリ記述子リスト（MDL）を使います。MDL '
                'は第1部第5章で紹介しています。</p>\n'
                '<h3>高速 I/O</h3>\n'
                '<p>キャッシュされたファイルの読み書きは、可能なら高速 I/O（Fast I/O）で処理します。高速 I/O は、I/O '
                '要求パケット（IRP）を生成せずにキャッシュされたファイルを読み書きする仕組みです。I/O マネージャーはファイルシステムドライバーの高速 I/O ルーチンを呼び、IRP '
                'を生成せずにキャッシュマネージャーから直接要求を満たせるか確認します。</p>\n'
                '<p>キャッシュマネージャーは仮想メモリサブシステムの上に構築されています。このためファイルシステムドライバーは、IRP '
                'の生成に伴う処理を省き、対象ファイルにマップされたページとの間でデータをコピーするだけで、データにアクセスできます。</p>\n'
                '<p>高速 I/O '
                'を使えない場合もあります。ファイルへの初回の読み取りや書き込みでは、「キャッシュのデータ構造」で説明したとおり、ファイルをキャッシュにマップし、関連するデータ構造を用意する必要があります。また、呼び出し元が非同期の読み取りや書き込みを指定した場合に高速 '
                'I/O を使うと、システムキャッシュとの間でバッファーをコピーするためのページング I/O で呼び出し元が待たされることがあり、非同期という要求を満たせません。同期 I/O '
                'であっても、たとえば Windows の <code>LockFile</code> や <code>UnlockFile</code> '
                'を使った結果、ファイルの一部のバイト範囲がロックされている場合は、ファイルシステムドライバーが高速 I/O '
                'では処理できないと判断することがあります。キャッシュマネージャーはどのファイルのどの部分がロックされているかを把握していないため、ファイルシステムドライバーが読み書きの可否を確認する必要があり、その場合は '
                'IRP を生成します。高速 I/O が使えるかどうかの判定を図11-12に示します。</p>\n'
                '<p>高速 I/O で読み書きを処理する手順は次のとおりです。</p>\n'
                '<ol>\n'
                '<li>スレッドが読み取りまたは書き込みを要求します。</li>\n'
                '<li>ファイルがキャッシュされていて I/O が同期なら、要求をファイルシステムドライバースタックの高速 I/O '
                'エントリポイントに渡します。ファイルがキャッシュされていなければ、ファイルシステムドライバーがキャッシュを準備し、次回の読み書きで高速 I/O を使えるようにします。</li>\n'
                '<li>ファイルシステムドライバーの高速 I/O ルーチンが高速 I/O '
                'を使えると判断したら、キャッシュマネージャーの読み取りまたは書き込みルーチンを呼び、キャッシュ内のファイルデータに直接アクセスします。高速 I/O が使えなければ、制御を I/O '
                'システムに返します。I/O システムは IRP を生成し、最終的にファイルシステムの通常の読み取りルーチンを呼び出します。</li>\n'
                '<li>キャッシュマネージャーは、指定されたファイルオフセットをキャッシュ内の仮想アドレスに変換します。</li>\n'
                '</ol>',
 'p2-page-617': '<ol start="5">\n'
                '<li>読み取りの場合、キャッシュマネージャーは要求元プロセスのバッファーにキャッシュからデータをコピーします。書き込みの場合は、バッファーからキャッシュにコピーします。</li>\n'
                '<li>操作とファイルの設定に応じて、次の処理を行います。\n'
                '<ul>\n'
                '<li>ファイルを開くときに <code>FILE_FLAG_RANDOM_ACCESS</code> '
                'を指定していない場合、読み取り時に呼び出し元のプライベートキャッシュマップにある先読み情報を更新します。<code>FO_RANDOM_ACCESS</code> '
                'が設定されていないファイルでは、先読みをキューに入れる場合もあります。</li>\n'
                '<li>書き込みの場合、キャッシュ内で変更したページのダーティビットを設定し、遅延ライターがディスクへの書き戻し対象として識別できるようにします。</li>\n'
                '<li>ライトスルーを指定したファイルでは、変更内容をディスクに書き出します。</li>\n'
                '</ul></li>\n'
                '</ol>\n'
                '<p>図11-12 高速 I/O の判定フロー。<code>NtReadFile</code> の要求が同期で、かつデータがキャッシュ済みなら、ファイルシステムドライバーは高速 '
                'I/O が可能かを判定します。可能ならキャッシュマネージャーがプロセスのバッファーとキャッシュの間でコピーします。その経路を使えない場合は IRP '
                'を生成します。ファイルが未キャッシュならキャッシュを初期化します。非同期要求の場合、I/O がその場で完了しなければ保留状態を返します。</p>\n'
                '<h3>先読みと遅延書き込み</h3>\n'
                '<p>ここからは、キャッシュマネージャーがファイルシステムドライバーに代わってファイルデータを読み書きする仕組みを説明します。キャッシュマネージャーがファイル I/O '
                'に関与するのは、<code>FILE_FLAG_NO_BUFFERING</code> を指定せずにファイルを開き、Windows の I/O 関数で読み書きするときです。</p>',
 'p2-page-618': '<p>ここでいう Windows の I/O 関数には、<code>ReadFile</code> と <code>WriteFile</code> '
                'などがあります。メモリマップされたファイルや、<code>FILE_FLAG_NO_BUFFERING</code> '
                'を指定して開いたファイルは、キャッシュマネージャーを経由しません。</p>\n'
                '<aside><p>アプリケーションが <code>FILE_FLAG_NO_BUFFERING</code> を指定してファイルを開いた場合、I/O '
                'の開始オフセットと入出力バッファーの仮想アドレスは、デバイスが要求する境界に揃える必要があります。転送サイズも、そのアラインメント単位の整数倍にします。ファイルシステムでは通常、セクターサイズがこの単位に相当します。典型的には '
                'NTFS で4,096バイト、CDFS で2,048バイトです。キャッシュマネージャーは中間バッファーを使うため、キャッシュによる性能向上に加えて、任意のオフセットとサイズで I/O '
                'を行えるという利点があります。</p></aside>\n'
                '<h4>アクセスパターンに応じた先読み</h4>\n'
                '<p>キャッシュマネージャーは空間的局所性を利用し、現在読んでいるデータから、呼び出し元プロセスが次に読む可能性の高いデータを予測して先読みします。システムキャッシュは、同じファイルについて連続する仮想アドレスを使うため、対応するページが物理メモリ上で隣り合っている必要はありません。論理ブロック単位のキャッシュでファイルを先読みするには、ファイルシステムドライバーとブロックキャッシュの密接な連携が必要です。この種のキャッシュはディスク上のデータの相対位置を基準にしますが、ファイルがディスク上の連続する領域に格納されているとは限らないためです。先読みの活動は、<code>Cache: '
                'Read Aheads/sec</code> パフォーマンスカウンターまたはシステム変数 <code>CcReadAheadIos</code> で確認できます。</p>\n'
                '<p>順次アクセスされるファイルの次のブロックを先に読むと、性能が向上します。ただし回転式ディスクでは、ヘッドのシークが発生します。ファイルの前方または後方へ一定間隔で飛びながら読み取る場合にも先読みできるよう、キャッシュマネージャーは、対象ハンドルのプライベートキャッシュマップに直近2回の読み取り要求を保持します。これを履歴付き非同期先読みと呼びます。一見ランダムな要求から規則性を見つけた場合は、そのパターンを外挿します。たとえば、4,000番のページに続いて3,000番を読み取るパターンが確認できれば、次は2,000番と予測し、先に読み込みます。</p>\n'
                '<aside><p>規則性の判定には最低3回の読み取り操作が必要ですが、プライベートキャッシュマップに保持する履歴は2回分です。</p></aside>\n'
                '<p>Win32 の <code>CreateFile</code> に <code>FILE_FLAG_SEQUENTIAL_SCAN</code> '
                'を指定すると、ファイルの先頭から末尾に向かって順にアクセスすることを伝えられます。このフラグがある場合、キャッシュマネージャーは予測用に読み取り履歴を保持せず、順次先読みを行います。また、ファイルの内容をキャッシュのワーキングセットに読み込むにつれ、アクティブでなくなったビューをアンマップします。変更されていないページについては、メモリマネージャーにスタンバイリストの先頭へ置くよう指示し、早く再利用できるようにします。先読みするデータ量も2倍になります。たとえば、通常1 '
                'MB なら2 MB です。呼び出し元が読み進める間、キャッシュマネージャーは追加のブロックを先読みし、現在の読み取り要求と同程度のサイズだけ先行する状態を保ちます。</p>',
 'p2-page-619': '<p>キャッシュマネージャーの先読みは非同期です。呼び出し元とは別のスレッドで、呼び出し元の処理と並行して進みます。キャッシュされたデータの取得を要求されると、まず要求された仮想ページにアクセスして、その要求を満たします。次に、追加データを取得する '
                'I/O '
                '要求をシステムワーカースレッドのキューに入れます。スレッドはバックグラウンドで、呼び出し元の次の読み取り要求を予測してデータを先に読みます。プログラムの実行中にページフォールトを処理して対象ページをメモリに読み込むため、呼び出し元が次のデータを要求したときには、すでにメモリにあります。</p>\n'
                '<p>読み取りパターンを予測できないアプリケーションでは、<code>CreateFile</code> を呼ぶときに '
                '<code>FILE_FLAG_RANDOM_ACCESS</code> '
                'を指定できます。このフラグは、次に読む位置の予測をキャッシュマネージャーに行わせず、先読みを無効にします。また、アクセスに伴う積極的なビューのアンマップを抑えます。アプリケーションがファイル内の以前の範囲に戻ったとき、ビューのマップとアンマップを繰り返さずに済みます。</p>\n'
                '<h4>先読み機能の拡張</h4>\n'
                '<p>Windows 8.1 '
                'では、キャッシュマネージャーの先読み機能が拡張されました。ファイルシステムドライバーやネットワークリダイレクターは、<code>CcSetReadAheadGranularityEx</code> '
                'API で、アクセスパターンに応じた先読みのサイズと、読み進めるにつれてサイズを増やす方法を設定できます。設定できる項目には次のものがあります。</p>\n'
                '<dl>\n'
                '<dt>先読みの粒度</dt><dd>最小の先読み単位と、次の先読みが終わるファイルオフセットを設定します。キャッシュマネージャーの既定値はメモリの1ページに相当する4 KB '
                'です。ファイルシステムは個別にこの値を設定します。たとえば NTFS は64 KB に設定します。</dd>\n'
                '</dl>\n'
                '<p>図11-13は、粒度を64 KB に設定し、200 KB のファイルを先読みする例です。順次読み取りをすでに検出しているときに、ユーザーが境界に揃っていないオフセット '
                '<code>0x10800</code> から1 KB の読み取りを要求すると、先読みは <code>0x10000</code> から <code>0x20000</code> '
                'までの64 KB を対象とする I/O を発行します。順次読み取りがすでに2回を超えていれば、さらに <code>0x20000</code> から '
                '<code>0x30000</code>（192 KB の位置）までの追加読み取りを発行します。</p>\n'
                '<p>図11-13 粒度を64 KB に設定した場合の200 KB のファイルの先読み。</p>\n'
                '<dl><dt>パイプラインサイズ</dt><dd>一部のリモートファイルシステムドライバーでは、大きな先読み I/O '
                'を小さな単位に分け、キャッシュマネージャーのワーカースレッドから並列に発行すると効果があります。ネットワークファイルシステムでは、この方式でスループットを大きく向上できる場合があります。</dd></dl>\n'
                '<figure><img loading="lazy" width="550" height="134" '
                'src="assets/0f4f1be30ce11e166f14ef4d.webp" alt="キャッシュの先読み（原文の図1）"></figure>',
 'p2-page-620': '<dl><dt>先読みの増加率</dt><dd>ファイルシステムドライバーは、3回目の順次読み取りを検出した後、先読みサイズをどれだけ増やすかを決める割合を指定できます。たとえば、アプリケーションが大きなファイルを1 '
                'MB ずつ読み取るとします。10回目の読み取りが終わると、アプリケーションは計10 MB '
                'を読み取ったことになります。その一部はキャッシュマネージャーが先に取得済みかもしれません。この時点で先読み処理は、次の I/O '
                'のサイズを計算します。ファイルシステムが増加率を60％に指定した場合、次の式を使います。</dd></dl>\n'
                '<pre><code>（順次読み取りの回数 × 直前の読み取りサイズ）×（増加率 ÷ 100）</code></pre>\n'
                '<p>この例では、次の先読みサイズは6 MB です。粒度が64 KB で I/O サイズが1 MB の場合、通常は2 MB '
                'です。キャッシュマネージャーの利用側が変更しなければ、増加率の既定値は50％です。</p>\n'
                '<h4>ライトバックキャッシュと遅延書き込み</h4>\n'
                '<p>キャッシュマネージャーは、遅延書き込みを伴うライトバックキャッシュを実装します。ファイルへの書き込みデータはまずメモリ内のキャッシュページに格納され、後でディスクに書き出されます。書き込みを短時間ためてからまとめてディスクに反映することで、ディスク '
                'I/O の総数を減らします。</p>\n'
                '<p>キャッシュマネージャーは、メモリマネージャーにキャッシュページの書き戻しを明示的に求める必要があります。そうしなければ、メモリマネージャーは物理メモリの要求が供給を上回ったときにしか書き戻しません。揮発性データにはそれで十分ですが、キャッシュされたファイルデータはディスク上の不揮発性データです。ユーザーは、プロセスによる変更が適切な時間内にディスクに反映されることを期待します。</p>\n'
                '<p>キャッシュマネージャーは、メモリマネージャーのマップ済みページライタースレッドによる書き出しを止めることもできます。変更済みページリスト（第1部第5章を参照）は論理ブロックアドレス（LBA）順に並んでいません。そのため、ページをまとめて大きな順次 '
                'I/O にしようとしても、うまくいかずにシークが繰り返し発生することがあります。そこでキャッシュマネージャーは、ライターによる書き出しを抑え、ディスク上の LBA '
                '順により近い仮想バイトオフセット（VBO）順にデータを書き出します。書き込みを自ら管理することで、独自のスケジューリングと書き込み量の調整を行い、遅延書き込みよりも先読みを優先してシステムへの影響を抑えられます。</p>\n'
                '<p>書き戻しの間隔は重要です。短すぎると不要な I/O '
                'が増え、システムの性能が落ちます。長すぎると、システム障害時に変更後のデータを失うおそれがあります。アプリケーションで保存を指示していたユーザーにとっては、特に困る問題です。変更済みページが増えすぎて、物理メモリが不足するおそれもあります。</p>',
 'p2-page-621': '<p>書き戻しの頻度とデータ消失のリスクを釣り合わせるため、キャッシュマネージャーは、システムワーカースレッドで遅延ライターのスキャンを1秒に1回実行します。スキャンには次の役割があります。</p>\n'
                '<ul>\n'
                '<li>現在のパーティションの平均空きページ数と変更済みページ数を調べ、変更済みページ数のしきい値の下限と上限を調整します。しきい値自体も、主に前回の周期で書き込んだ変更済みページの総数を基に更新します。詳細は後述します。書き込むべき変更済みページがなければ、スキャンは待機します。</li>\n'
                '<li>内部ルーチン <code>CcCalculatePagesToWrite</code> で、ディスクに書き戻す変更済みページの数を計算します。変更済みページが256枚（1 '
                'MB）を超える場合、総数の8分の1を書き戻しのキューに入れます。変更済みページの発生速度が予定している書き込み速度を上回る場合は、発生速度に追いつくのに必要なページ数を求め、追加で書き込みます。</li>\n'
                '<li>現在のパーティションに属する連結リストで共有キャッシュマップを順に調べ、内部ルーチン <code>CcShouldLazyWriteCacheMap</code> '
                'で、各マップが表すファイルをディスクに書き戻す必要があるかを判定します。たとえば、別のスレッドがすでに I/O '
                'を始めている場合、対象が一時ファイルの場合、マップに変更済みページがない場合には書き戻しません。必要と判定した場合は、今回の書き込み枠が残っているかを確認し、残っていればキャッシュマネージャーのシステムワーカースレッドに処理を登録します。</li>\n'
                '</ul>\n'
                '<aside><p>スキャンは、共有キャッシュマップが指すすべての変更済みページを必ず書き戻すわけではありません。対象がメタデータストリームで、変更済みページが256 KB '
                'を超える場合は、そのストリームの変更済みページの8分の1だけを書き込みます。また、対象ファイルの変更済みページ数が、スキャンで書き戻せる総ページ数より多い場合にも、書き込みを制限します。</p></aside>\n'
                '<p>実際の I/O '
                'は、システム全体のクリティカルワーカースレッドプールの遅延ライターが実行します。メモリマネージャーのマップ済みページライターがすでに書き戻し中であれば、遅延ライターは同じストリームへの書き戻しを延期し、2つのライターが同時に同じファイルへ書き込むのを避けます。</p>\n'
                '<aside><p>キャッシュマネージャーは、ファイルシステムドライバーが、ファイルにいつどれだけ書き込まれたかを追跡できるようにします。遅延ライターが変更済みページをディスクに書き戻すと、ファイルシステムに通知し、そのファイルの有効データ長を更新するよう求めます。キャッシュマネージャーとファイルシステムは、有効データ長をそれぞれメモリ上で管理しています。</p></aside>',
 'p2-page-622': '<h4>実験\u3000キャッシュマネージャーの動作を観察する</h4>\n'
                '<p>エクスプローラーで大きなファイル（この例では DVD イメージ）をローカルの別のディレクトリへコピーします。Process Monitor '
                'を使い、キャッシュマネージャーの先読みと遅延書き込みを含め、背後で起きているファイルシステムの処理を確認します。</p>\n'
                '<p>まず、Process Monitor のフィルターで、コピー元とコピー先のファイルパス、<code>Explorer.exe</code> と '
                '<code>System</code> の両プロセス、<code>ReadFile</code> と <code>WriteFile</code> '
                'の両操作を対象にします。この例でコピー元に指定したのは '
                '<code>C:&#92;Users&#92;Andrea&#92;Documents&#92;Windows_10_RS3.iso</code>、コピー先は '
                '<code>C:&#92;ISOs&#92;Windows_10_RS3.iso</code> です。</p>\n'
                '<p>ファイルをコピーすると、図のようなトレースが Process Monitor に表示されます。最初の数行には、コピーエンジンが最初に発行した I/O '
                'と、それに続くキャッシュマネージャーの処理が記録されます。</p>\n'
                '<ul><li>1行目は、エクスプローラーによる最初の1 MB のキャッシュ読み取りです。この読み取りのサイズは、ファイルサイズに基づく内部の計算で決まり、128 KB から1 MB '
                'の範囲で変化します。この例では対象ファイルが大きいため、コピーエンジンは1 MB を選びました。</li></ul>\n'
                '<figure><img loading="lazy" width="358" height="212" '
                'src="assets/8e1eceb464dbb9512166e833.webp" alt="キャッシュマネージャーの動作を調べる実験（原文の図1）">\n'
                '<img loading="lazy" width="649" height="270" src="assets/953842f3c38fb370bac9b11d.webp" '
                'alt="キャッシュマネージャーの動作を調べる実験（原文の図2）"></figure>',
 'p2-page-623': '<ul>\n'
                '<li>最初の1 MB の読み取りに続いて、キャッシュを使わない1 MB '
                'の読み取りが発生します。非キャッシュ読み取りは、通常、ページフォールトやキャッシュマネージャーによるアクセスに伴って発生します。Process Monitor '
                'で該当する行をダブルクリックして「Stack」タブを開き、スタックトレースを調べます。すると、NTFS ドライバーの読み取りルーチンがキャッシュマネージャーの '
                '<code>CcCopyRead</code> '
                'を呼び出し、それに伴うページフォールトをメモリマネージャーが処理して、コピー元のデータを物理メモリに読み込んだことがわかります。</li>\n'
                '<li>この1 MB のページフォールト I/O の後、キャッシュマネージャーがファイルの先読みを始めます。続いて、<code>System</code> '
                'プロセスによる、オフセット1 MB からの非キャッシュ読み取りが1 MB '
                '分記録されます。キャッシュマネージャーは、ファイルサイズとエクスプローラーの読み取り要求のサイズを基に、先読みサイズを1 MB '
                'と決めました。図に示す先読み操作のスタックトレースから、キャッシュマネージャーのワーカースレッドが先読みを実行していることを確認できます。</li>\n'
                '</ul>\n'
                '<figure><img loading="lazy" width="280" height="328" '
                'src="assets/6d73e1dda4ad3a8a72f23c3a.webp" alt="キャッシュ読み取りの実験（原文の図1）">\n'
                '<img loading="lazy" width="280" height="328" src="assets/bfaef01ad353f4cb773757e0.webp" '
                'alt="キャッシュ読み取りの実験（原文の図2）"></figure>',
 'p2-page-624': '<p>この時点以降、エクスプローラーによる1 MB 単位の読み取りでは、通常はページフォールトが発生しません。先読みスレッドが、キャッシュを使わない1 MB '
                '単位の読み取りで、必要なファイルデータを先に取得しているためです。ただし、ときどき先読みが間に合わず、複数ページをまとめて取り込むページフォールトが発生します。Process '
                'Monitor では、これは同期ページング I/O（Synchronous Paging I/O）として表示されます。</p>\n'
                '<p>該当する行のスタックを調べると、<code>MmPrefetchForCacheManager</code> の代わりに、<code>MmAccessFault</code> '
                'と <code>MiIssueHardFault</code> が呼び出されています。</p>\n'
                '<p>エクスプローラーは読み取りを始めるとすぐに、コピー先のファイルにも書き込みを始めます。書き込みはキャッシュを使い、1 MB ずつ順に行われます。約124 MB '
                'を読み取った時点で、図のように <code>System</code> プロセスによる最初の <code>WriteFile</code> 操作が現れます。</p>\n'
                '<p>図の書き込み操作のスタックトレースから、実際に書き込んだのはメモリマネージャーのマップ済みページライタースレッドだとわかります。最初の数 MB '
                'ではキャッシュマネージャーがまだ遅延書き込みを始めていなかったため、メモリマネージャーのマップ済みページライターが、コピー先ファイルの変更済みデータをディスクに書き戻し始めました。マップ済みページライターの詳細は第10章を参照してください。</p>\n'
                '<figure><img loading="lazy" width="631" height="263" '
                'src="assets/cdc0bccc97c12f36739b491c.webp" alt="エクスプローラーによる読み取りと先読み（原文の図1）">\n'
                '<img loading="lazy" width="631" height="268" src="assets/5e122d28b6a5e1c8102575bf.webp" '
                'alt="エクスプローラーによる読み取りと先読み（原文の図2）"></figure>',
 'p2-page-625': '<p>キャッシュマネージャーの操作を見やすくするには、Process Monitor のフィルターから <code>Explorer.exe</code> を外し、図のように '
                '<code>System</code> プロセスの操作だけを表示します。</p>\n'
                '<p>この表示にすると、キャッシュマネージャーが1 MB ずつ遅延書き込みを行う様子がわかりやすくなります。1回の書き込みの上限は、Windows のクライアント版では1 '
                'MB、サーバー版では32 MB '
                'です。この実験ではクライアント版を使っています。図のスタックトレースを見ると、キャッシュマネージャーのワーカースレッドが遅延書き込みを実行していることを確認できます。</p>\n'
                '<p>追加の実験として、別の Windows '
                'システムにネットワーク経由でコピーしたり、サイズの異なるファイルに替えて同じ手順を試したりしてください。送信側と受信側の両方で、コピーエンジンやキャッシュマネージャーの動作の違いを確認できます。</p>\n'
                '<figure><img loading="lazy" width="649" height="276" '
                'src="assets/4e79c8fe4138a127584efc1b.webp" alt="System プロセスの I/O トレース（原文の図1）">\n'
                '<img loading="lazy" width="313" height="366" src="assets/ff40ffd2b03421fb75abe9d5.webp" '
                'alt="System プロセスの I/O トレース（原文の図2）"></figure>',
 'p2-page-626': '<h4>ファイルの遅延書き込みを無効にする</h4>\n'
                '<p>Windows の <code>CreateFile</code> に <code>FILE_ATTRIBUTE_TEMPORARY</code> '
                'を指定して一時ファイルを作成すると、物理メモリが深刻に不足するか、ファイルの書き戻しを明示的に求められない限り、遅延ライターは変更済みページをディスクへ書き込みません。破棄される可能性のあるデータをすぐにディスクへ書き出さないため、システムの性能が向上します。通常、アプリケーションは一時ファイルを閉じた後、すぐに削除します。</p>\n'
                '<h4>キャッシュからディスクへの書き込みを強制する</h4>\n'
                '<p>ファイルへの書き込みからディスクへの反映まで、わずかな遅延も許容できないアプリケーションがあります。そのため、キャッシュマネージャーはファイルオブジェクト単位のライトスルーキャッシュにも対応しています。ライトスルーでは、変更を加えるとすぐにディスクへ書き込みます。有効にするには、<code>CreateFile</code> '
                'に <code>FILE_FLAG_WRITE_THROUGH</code> を指定します。開いているファイルのデータを特定の時点でディスクに書き込む必要がある場合は、スレッドから '
                'Windows の <code>FlushFileBuffers</code> を呼び出し、明示的に書き戻すこともできます。</p>\n'
                '<h4>マップ済みファイルを書き戻す</h4>\n'
                '<p>遅延ライターが書き戻すビューが別のプロセスのアドレス空間にもマップされていると、処理が複雑になります。キャッシュマネージャーが把握しているのは、自身が変更したページだけです。別のプロセスが変更したページの変更済みビットは、そのプロセス固有のページテーブルエントリに記録されます。この状況に対応するため、ユーザーがファイルをマップすると、メモリマネージャーはキャッシュマネージャーに通知します。</p>\n'
                '<p>たとえば <code>FlushFileBuffers</code> '
                'の呼び出しでこのファイルのキャッシュを書き戻す場合、キャッシュマネージャーはまずキャッシュの変更済みページを書き出し、別のプロセスもファイルをマップしているかを確認します。マップされていれば、別のプロセスが変更したページも書き出せるよう、セクションのビュー全体を書き戻します。キャッシュで開いているファイルのビューをユーザーがマップした場合は、そのビューのアンマップ時に、変更されたページが変更済みとして記録されます。後で遅延ライターがビューを書き戻す際に、そのページもディスクに書き込まれます。この手順が成り立つのは、次の順序を守った場合です。</p>\n'
                '<ol>\n'
                '<li>ユーザーがビューをアンマップします。</li>\n'
                '<li>プロセスがファイルバッファーを書き戻します。</li>\n'
                '</ol>\n'
                '<p>この順序を守らなければ、どのページがディスクに書き込まれるかは予測できません。</p>',
 'p2-page-627': '<h4>実験\u3000キャッシュの書き戻しを観察する</h4>\n'
                '<p>パフォーマンスモニターを起動し、「Cache」グループの <code>Data Maps/sec</code> と <code>Lazy Write '
                'Flushes/sec</code> '
                'を追加します。これらのカウンターで、キャッシュマネージャーがビューをシステムキャッシュにマップし、ページをディスクへ書き戻す様子を観測できます。次に、大きなファイルを別の場所にコピーします。図でおおむね上にある線が '
                '<code>Data Maps/sec</code>、もう一方が <code>Lazy Write Flushes/sec</code> '
                'です。ファイルをコピーしている間、<code>Lazy Write Flushes/sec</code> が大きく増えます。</p>\n'
                '<h4>書き込み量の制限</h4>\n'
                '<p>ファイルシステムとキャッシュマネージャーは、キャッシュへの書き込み要求がシステム性能に影響するかを判断し、必要なら書き込みを延期します。まずファイルシステムは '
                '<code>CcCanIWrite</code> '
                'を呼び、指定されたバイト数を直ちに書き込んでも性能が低下しないかをキャッシュマネージャーに問い合わせます。必要なら書き込みを待たせます。非同期 I/O では '
                '<code>CcDeferWrite</code> を呼び出してコールバックを登録し、書き込みが再び許可されたときに自動で書き込めるようにします。同期 I/O '
                'では、<code>CcCanIWrite</code> から処理を再開できるようになるまで待ちます。</p>\n'
                '<p>書き込み予定の通知を受けると、キャッシュマネージャーは、キャッシュ内の変更済みページの数と利用可能な物理メモリの量を調べます。空き物理ページが少なければ、キャッシュへの書き込みを要求したファイルシステムのスレッドを一時的に待たせます。遅延ライターが変更済みページの一部をディスクに書き戻した後、待機中のスレッドが処理を再開します。ファイルシステムやネットワークサーバーが大量の書き込みを要求しても、メモリ不足でシステム全体の性能が低下するのを防げます。</p>\n'
                '<figure><img loading="lazy" width="588" height="422" '
                'src="assets/fd464a71344dcc195dde13ba.webp" alt="キャッシュの書き戻しを調べる実験（原文の図1）"></figure>',
 'p2-page-628': '<aside><p>書き込み量の制限はボリューム単位で適用されます。たとえば、RAID 0 の SSD 上で大きなファイルをコピーしながら、USB メモリに文書を転送しても、USB '
                'メモリへの書き込みが原因で SSD 側の書き込みが制限されることはありません。</p></aside>\n'
                '<p>変更済みページ数のしきい値は、キャッシュへの書き込みを制限し始めるまでにシステムキャッシュが許容する変更済みページ数です。この値はキャッシュマネージャーのパーティションの初期化時に計算し、クライアント版かサーバー版かによって異なります。システムパーティションは '
                'NT '
                'カーネル起動のフェーズ1で作成・初期化されます。先に述べたように、しきい値の上限と下限も計算します。遅延ライターのスキャンは、メモリ消費量と変更済みページを処理する速度に応じて内部関数 '
                '<code>CcAdjustThrottle</code> '
                'を呼びます。サーバーでは、この関数が計算済みの上限と下限の間で現在のしきい値を動的に調整します。大量の書き込みがいずれキャッシュの容量を圧迫し、制限の対象になる状況でも、読み取り用のキャッシュを維持するためです。</p>\n'
                '<table><caption>表11-1 '
                '変更済みページ数のしきい値の計算方法</caption><thead><tr><th>製品の種類</th><th>しきい値</th><th>上限</th><th>下限</th></tr></thead><tbody>\n'
                '<tr><td>クライアント</td><td>物理ページ数 ÷ 8</td><td>物理ページ数 ÷ 8</td><td>物理ページ数 ÷ 8</td></tr>\n'
                '<tr><td>サーバー</td><td>物理ページ数 ÷ 2</td><td>物理ページ数 ÷ 2</td><td>物理ページ数 ÷ 8</td></tr>\n'
                '</tbody></table>\n'
                '<p>書き込み量の制限は、低速回線でデータを送るネットワークリダイレクターにも役立ちます。たとえば、ローカルプロセスが640 Kbps '
                'の低速回線を通じて、リモートのファイルシステムに大量のデータを書き込むとします。データがリモートのディスクに書き込まれるのは、キャッシュマネージャーの遅延ライターがキャッシュを書き戻すときです。リダイレクターが変更済みページを大量にためて一度に書き戻すと、データ転送が終わる前に受信側でタイムアウトするおそれがあります。キャッシュマネージャーの '
                '<code>CcSetDirtyPageThreshold</code> '
                'を使うと、リダイレクターはストリームごとに許容する変更済みページ数を制限できます。これにより、書き戻しによるネットワークのタイムアウトを防げます。</p>\n'
                '<h4>システムスレッド</h4>\n'
                '<p>キャッシュマネージャーは遅延書き込みと先読みの I/O '
                'を、共用のクリティカルシステムワーカースレッドプールに登録して実行します。ただし、利用するスレッド数の上限は、プールの総数より1つ少なく設定します。クリティカルシステムワーカースレッドの総数はクライアントで5、サーバーで10です。</p>\n'
                '<p>キャッシュマネージャーは内部で作業要求を4つのリストに分けます。すべて同じ Executive ワーカースレッドで処理します。</p>\n'
                '<ul>\n'
                '<li>高速キューは先読みに使います。</li>\n'
                '<li>通常キューは、書き戻すべき変更済みデータを探す遅延ライターのスキャン、遅延書き込み、遅延クローズに使います。</li>\n'
                '</ul>',
 'p2-page-629': '<ul>\n'
                '<li>高速解体キューは、メモリマネージャーがファイルをイメージセクションとして開くために、キャッシュマネージャーのデータセクションが解放されるのを待っているときに使います。<code>CcWriteBehind</code> '
                'は、ファイル全体を書き戻して共有キャッシュマップを解体します。</li>\n'
                '<li>ポストティックキューは、遅延ライタースレッドの各「ティック」、つまり各処理周期の終了時に、キャッシュマネージャーが内部通知を受け取るために使います。</li>\n'
                '</ul>\n'
                '<p>キャッシュマネージャーは、ワーカースレッドに割り当てる処理を追跡するため、各プロセッサにワーカーキュー項目を保持する固定長のルックアサイドリストを用意します。ルックアサイドリストは第1部第5章で説明しています。項目数はクライアントシステムで128、サーバーシステムで256です。複数のプロセッサにまたがる処理の性能を高めるため、同じ大きさのグローバルなルックアサイドリストも割り当てます。</p>\n'
                '<h4>積極的な遅延書き込みと低優先度の遅延書き込み</h4>\n'
                '<p>Windows 8.1 以降では、キャッシュマネージャーの性能を高め、eMMC '
                'などの低速なストレージデバイスに対応するため、遅延ライターに大幅な改良が加えられました。</p>\n'
                '<p>前述のとおり、遅延ライターのスキャンは、変更済みページ数のしきい値と、その上限・下限を調整します。利用可能なページ総数の推移を分析して上限と下限を調整し、しきい値そのものは直前の周期（1秒ごと）で予定どおりのページ数を書き込めたかに応じて調整します。直前の周期で書き込んだ数が '
                '<code>CcCalculatePagesToWrite</code> の算出した予定数を下回れば、ストレージデバイスが発行された I/O '
                'のスループットに追いついていないため、しきい値を下げます。書き込みの制限が強まり、一部の利用側は <code>CcCanIWrite</code> '
                'の呼び出しで待たされます。前の周期から書き残したページがなければ、しきい値を上げられます。どちらの場合も、値は上限と下限の範囲内に収めます。</p>\n'
                '<p>大きな改良は、追加の遅延書き込みワーカースレッドです。サーバー版では最大9本で、クリティカルシステムワーカースレッドの総数より1本少なく、クライアント版では最大1本です。キャッシュマネージャーが遅延書き込みのスキャンを要求すると、システムは、変更済みページ数がしきい値の4分の1と利用可能なページ数の半分をいずれも下回るかを確認し、変更済みページがメモリの逼迫に関係しているかを判定します。メモリが逼迫している場合、システム全体のキャッシュマネージャースレッドプールのルーチン '
                '<code>CcWorkerThread</code> が追加の遅延ライターを起動し、他のライターと並行して変更済みページを書き込めるかを判定します。</p>\n'
                '<p>追加の I/O '
                'を発行するスレッドを増やしてもシステムの性能が落ちないかを判断するため、キャッシュマネージャーは過去の遅延書き込み周期でのディスクスループットを計算し、記録します。現在の周期のスループットが前の周期と同程度かそれ以上なら、ストレージは現在の '
                'I/O 負荷を処理できています。この場合は遅延ライターをもう1本追加する余地があります。このスレッドを追加の遅延書き込み（Extra Write '
                'Behind）スレッドと呼びます。</p>',
 'p2-page-630': '<p>反対に、現在のスループットが前の周期より低ければ、ストレージはこれ以上の並列書き込みを処理できません。この場合は追加の遅延書き込みスレッドを減らします。この機能を積極的な遅延書き込み（Aggressive '
                'Write Behind）と呼びます。</p>\n'
                '<p>Windows '
                'のクライアント版では、キャッシュマネージャーが低速ストレージ向けの最適化を行います。遅延ライターのスキャンが要求されたときや、ファイルシステムドライバーがキャッシュへ書き込むときに、遅延ライターを低優先度で動かすかどうかを判定します。スレッドの優先度については第1部第4章を参照してください。次の両方を満たす場合は低優先度、それ以外の場合は通常の優先度を使います。</p>\n'
                '<ul>\n'
                '<li>呼び出し元が、現在の遅延書き込みのスキャンの完了を待っていない。</li>\n'
                '<li>パーティションの変更済みページの合計サイズが32 MB 未満である。</li>\n'
                '</ul>\n'
                '<p>両方を満たす場合、キャッシュマネージャーは遅延ライターの作業項目を低優先度キューに入れます。遅延ライターは優先度6（Lowest）のシステムワーカースレッドによって起動されます。さらに、対象のファイルシステムドライバーへ '
                'I/O を発行する直前に、遅延ライターは自身の I/O 優先度を Lowest に設定します。</p>\n'
                '<h4>動的メモリ</h4>\n'
                '<p>前節で説明したとおり、変更済みページ数のしきい値は利用可能な物理メモリの量に応じて動的に計算します。キャッシュマネージャーは、この値を使って書き込み要求を制限する時期や、遅延書き込みを増やすかどうかを決めます。</p>\n'
                '<p>パーティションが導入される前は、カーネルの初期化フェーズ1で実行される <code>CcInitializeCacheManager</code> が、グローバル変数 '
                '<code>MmNumberOfPhysicalPages</code> '
                'を参照して計算していました。現在は、キャッシュマネージャーのパーティションを初期化する関数が、対応するメモリパーティションで使える物理ページ数を基に計算します。詳細は本章の「メモリパーティションのサポート」を参照してください。ただし、Windows '
                'は稼働中の物理メモリ追加にも対応するため、初期化時の計算だけでは足りません。Hyper-V はこの機能を子 VM の動的メモリで活用します。</p>\n'
                '<p>メモリマネージャーの初期化フェーズ0では、<code>MiCreatePfnDatabase</code> '
                'がページフレーム番号（PFN）データベースの最大サイズを計算します。64ビットシステムでは、搭載可能な物理メモリの最大量を、アドレス指定できる仮想メモリの全範囲と等しいと仮定します。たとえば、LA57 '
                'を使わないシステムでは256 TB です。システムはメモリマネージャーに、アドレス空間全体の各仮想ページにつき PFN '
                'エントリ1件を保存できる仮想アドレス範囲の予約を求めます。この仮想的な PFN データベースのサイズは約64 GB '
                'です。その後、<code>MiCreateSparsePfnDatabase</code> は Winload が検出した有効な物理メモリ範囲を順に調べ、対応する PFN '
                'エントリをデータベースにマップします。PFN データベースはスパースなメモリを使います。<code>MiAddPhysicalMemory</code> '
                'の各ルーチンが新しい物理メモリを検出すると、PFN データベース内に領域を追加で割り当て、新しい PFN '
                'エントリを作ります。動的メモリの詳細は第9章「仮想化技術」を参照してください。</p>',
 'p2-page-631': '<p>キャッシュマネージャーは、稼働中に物理メモリが追加・削除されたことを検出し、新しい構成に合わせて動作を調整します。追従できない場合には、次の問題が起きます。</p>\n'
                '<ul>\n'
                '<li>メモリの追加を検出できないと、実際より少ないメモリを前提にするため、変更済みページ数のしきい値が低くなります。必要な数のページをキャッシュできず、書き込みを早く制限しすぎます。</li>\n'
                '<li>利用可能なメモリの大部分がロックされるか、削除されて使えなくなると、キャッシュ I/O '
                'が残りのメモリを占め、ほかのアプリケーションの応答性が低下するおそれがあります。</li>\n'
                '</ul>\n'
                '<p>キャッシュマネージャーはメモリマネージャーにコールバックを登録せず、遅延ライターのスキャンスレッド（LWS）で適応的に補正します。LWS '
                'は共有キャッシュマップの一覧から書き出すページを選ぶほか、フォアグラウンドでの書き込み速度、自身の書き戻し速度、利用可能メモリに応じて、変更済みページ数のしきい値を変えます。パーティションの利用可能な物理ページ数の平均と、変更済みページ数の履歴を保持し、1秒ごとに記録を更新して集計値を算出します。集計値に基づいてメモリ容量の変動に追従し、短時間の急変の影響を抑えながら、しきい値の上限と下限を段階的に変えます。</p>\n'
                '<h4>キャッシュマネージャーのディスク I/O の計測</h4>\n'
                '<p>Windows 8.1 より前は、個々のプロセスが行った I/O の総量を正確に求められませんでした。理由は複数あります。</p>\n'
                '<ul>\n'
                '<li>遅延書き込みと先読みは、I/O '
                'のきっかけを作ったプロセスやスレッドのコンテキストでは実行されません。キャッシュマネージャーの実際の書き出しは、元のスレッドとは別のコンテキスト（通常は '
                'System）で完了し、要求元のプロセスがすでに終了していることもあります。先読みでは、プロセスが要求した範囲を超えてファイルを読み込む場合もあります。</li>\n'
                '<li>キャッシュマネージャーは非同期 I/O も扱いますが、キャッシュを使わない I/O など、まったく関与しない処理もあります。</li>\n'
                '<li>一部の特殊なアプリケーションは、ディスクスタックの下位ドライバーを使って低レベルのディスク I/O を発行できます。</li>\n'
                '</ul>\n'
                '<p>Windows は I/O を発行したスレッドへのポインターを IRP の末尾に保存します。そのスレッドが最初に要求を出したとは限らないため、I/O が誤って System '
                'プロセスに計上されることがありました。Windows 8.1 では、キャッシュマネージャーとファイルシステムドライバーが連携して使う '
                '<code>PsUpdateDiskCounters</code> API を導入して解決しました。この関数は、読み書きしたバイト数の合計と I/O の件数を、NT '
                'カーネルがプロセスを表す基本データ構造 <code>EPROCESS</code> に格納します。詳細は第1部第3章を参照してください。</p>\n'
                '<p>キャッシュマネージャーは、公開しているファイルシステム向けインターフェイス経由で、キャッシュありの読み書きを処理するときと、公開 API '
                '<code>CcScheduleReadAheadEx</code> 経由で先読み I/O を発行するときに、<code>PsUpdateDiskCounters</code> '
                'を呼び出して、プロセスのディスクカウンターを更新します。NTFS と ReFS のドライバーは、非キャッシュ I/O とページング I/O の処理中にこの関数を呼び出します。</p>',
 'p2-page-632': '<p><code>CcScheduleReadAheadEx</code> と同様に、<code>CcCopyReadEx</code> や '
                '<code>CcCopyWriteEx</code> など、複数のキャッシュマネージャー API が拡張されました。これらの API は、I/O を発行し、その I/O '
                'を計上する先となるスレッドへのポインターを受け取ります。対応するファイルシステムドライバーは、非同期 I/O でも、どのスレッドに計上するかを指定できます。</p>\n'
                '<p>キャッシュマネージャーはプロセスごとのカウンターに加えて、ファイルシステムがストレージスタックへ発行した I/O を追跡するグローバルディスク I/O '
                'カウンターも管理します。ファイルシステムドライバーが非キャッシュ I/O やページング I/O '
                'を発行するたびに更新します。アプリケーションは、<code>IOCTL_DISK_PERFORMANCE</code> 制御コードを使って、特定のディスクデバイスに発行された I/O '
                'の総量を取得できます。この総量からグローバルカウンターの値を差し引くと、個々のプロセスに帰属させられなかった I/O が求まります。変更済みページライターが発行したページング I/O '
                'や、ミニフィルタードライバーが内部で行った I/O などが該当します。</p>\n'
                '<p>プロセスごとのディスクカウンターは、<code>NtQuerySystemInformation</code> API に情報クラス '
                '<code>SystemProcessInformation</code> を指定して取得できます。タスクマネージャーや Process Explorer '
                'などの診断ツールは、この方法で実行中のプロセスの I/O の値を取得します。</p>\n'
                '<h4>実験\u3000ディスク I/O を計測する</h4>\n'
                '<p>パフォーマンスモニターを開き、「FileSystem Disk Activity」グループから <code>FileSystem Bytes Read</code> と '
                '<code>FileSystem Bytes Written</code> を追加します。次に、プロセス別の値を計測するため、「Process」グループの <code>IO Read '
                'Bytes/sec</code> と <code>IO Write Bytes/sec</code> '
                'を追加します。この2つのカウンターを追加するときは、「選択したオブジェクトのインスタンス」欄で <code>Explorer</code> プロセスを選びます。</p>\n'
                '<p>大きなファイルをコピーし始めると、エクスプローラーのカウンターが上昇し、ファイルシステム全体のディスク活動を示すカウンターの値に達します。</p>\n'
                '<figure><img loading="lazy" width="550" height="299" '
                'src="assets/599864e08aba0409baedd9fc.webp" alt="キャッシュマネージャーの処理（原文の図1）"></figure>',
 'p2-page-633': '<h3>ファイルシステム</h3>\n'
                '<p>この節では、Windows '
                'がサポートするファイルシステム形式の概要を示します。続いて、ファイルシステムドライバーの種類と基本動作を説明します。メモリマネージャーやキャッシュマネージャーなど、他のシステムコンポーネントとの連携も扱います。その後、主要な2つのファイルシステムである '
                'NTFS と ReFS '
                'の機能とデータ構造を詳しく見ていきます。まず内部アーキテクチャを取り上げ、次にディスク上のデータ配置と、圧縮、回復、暗号化、階層化、ファイルのスナップショットなどの高度な機能を説明します。</p>\n'
                '<h4>Windows のファイルシステム形式</h4>\n'
                '<p>Windows は次のファイルシステム形式に対応しています。</p>\n'
                '<ul>\n'
                '<li>CDFS</li>\n'
                '<li>UDF</li>\n'
                '<li>FAT12、FAT16、FAT32</li>\n'
                '<li>exFAT</li>\n'
                '<li>NTFS</li>\n'
                '<li>ReFS</li>\n'
                '</ul>\n'
                '<p>以下では、それぞれがどのような環境に適しているかを説明します。</p>\n'
                '<h4>CDFS</h4>\n'
                '<p>CDFS（CD-ROM '
                'ファイルシステム、<code>%SystemRoot%&#92;System32&#92;Drivers&#92;Cdfs.sys</code>）は、ISO-9660 形式と '
                'Joliet 形式をそれぞれ拡張した形式にも対応する、読み取り専用のファイルシステムドライバーです。ISO-9660 は比較的単純な形式で、たとえば名前に使えるのは大文字の '
                'ASCII 文字で、最大32文字という制限があります。Joliet はより柔軟で、任意の長さの Unicode '
                'の名前を扱えます。幅広い互換性のため、同じディスクに両方の形式のデータ構造が存在する場合、CDFS は Joliet を使用します。CDFS には次の制限があります。</p>\n'
                '<ul>\n'
                '<li>ファイルの最大サイズは4 GB。</li>\n'
                '<li>ディレクトリは最大65,535個。</li>\n'
                '</ul>\n'
                '<p>光学メディアの業界標準には Universal Disk Format（UDF）が採用されたため、CDFS は旧来の形式と見なされています。</p>',
 'p2-page-634': '<h4>UDF</h4>\n'
                '<p>Windows の Universal Disk Format（UDF）ファイルシステムは、Optical Storage Technology '
                'Association（OSTA）の UDF 仕様に準拠しています。UDF は ISO-13346 のサブセットに CD-R や DVD-R/RW '
                'などのための拡張を加えた形式です。OSTA は1995年に、主に DVD-ROM などの記憶媒体で ISO-9660 に代わる形式として UDF を定義しました。UDF は DVD '
                'の仕様に含まれ、CDFS より柔軟です。UDF 形式には次の特徴があります。</p>\n'
                '<ul>\n'
                '<li>ディレクトリ名とファイル名は、ASCII で最大254文字、Unicode で最大127文字です。</li>\n'
                '<li>スパースファイルを扱えます。スパースファイルは後述の「圧縮とスパースファイル」で説明します。</li>\n'
                '<li>ファイルサイズは64ビットで表します。</li>\n'
                '<li>アクセス制御リスト（ACL）をサポートします。</li>\n'
                '<li>代替データストリームをサポートします。</li>\n'
                '</ul>\n'
                '<p>UDF ドライバーはバージョン2.60までに対応します。UDF は書き換え可能なメディアを想定して設計されています。Windows の UDF '
                'ドライバー（<code>%SystemRoot%&#92;System32&#92;Drivers&#92;Udfs.sys</code>）では、Blu-ray、DVD-RAM、CD-R/RW、DVD±R/RW '
                'ドライブで UDF 2.50 を読み書きでき、UDF 2.60 は読み取り専用です。Windows の実装では、名前付きストリームや ACL など、一部の UDF '
                '機能は利用できません。</p>\n'
                '<h4>FAT12、FAT16、FAT32</h4>\n'
                '<p>Windows が FAT をサポートする主な用途は、マルチブート環境でほかの OS との互換性を保つことと、フラッシュドライブやメモリカードを使うことです。Windows の '
                'FAT ファイルシステムドライバーは <code>%SystemRoot%&#92;System32&#92;Drivers&#92;Fastfat.sys</code> '
                'に実装されています。</p>\n'
                '<p>各 FAT 形式の名前に付く数字は、ディスク上のクラスターを識別するのに使うビット数です。FAT12 '
                'は12ビットの識別子を使うため、パーティションのクラスター数は最大で2<sup>12</sup>（4,096）です。Windows で許可されるクラスターサイズは512バイト〜8 '
                'KB なので、FAT12 ボリュームの上限は32 MB です。</p>\n'
                '<aside><p>すべての FAT 形式で、ボリューム内の最初の2クラスターと最後の16クラスターは予約されています。たとえば FAT12 '
                'で実際に使えるクラスター数は、4,096より少なくなります。</p></aside>\n'
                '<p>FAT16 は16ビットの識別子を使い、2<sup>16</sup>（65,536）クラスターを指定できます。セクターサイズが512バイトのディスクで Windows が使う '
                'FAT16 のクラスターサイズは、512バイト（1セクター）〜64 KB です。この場合、ボリュームサイズの上限は4 GB です。セクターサイズが4,096バイトのディスクでは256 '
                'KB のクラスターを使えます。Windows が選ぶクラスターサイズはボリュームの容量によって異なります。各サイズは表11-2に示します。<code>format</code> '
                'コマンドまたは「ディスクの管理」で16 MB 未満のボリュームを FAT でフォーマットすると、Windows は FAT12 を使います。</p>',
 'p2-page-635': '<table><caption>表11-2 Windows の FAT16 '
                'の既定のクラスターサイズ</caption><thead><tr><th>ボリュームサイズ</th><th>既定のクラスターサイズ</th></tr></thead><tbody>\n'
                '<tr><td>8 MB 未満</td><td>非対応</td></tr>\n'
                '<tr><td>8〜32 MB</td><td>512バイト</td></tr>\n'
                '<tr><td>32〜64 MB</td><td>1 KB</td></tr>\n'
                '<tr><td>64〜128 MB</td><td>2 KB</td></tr>\n'
                '<tr><td>128〜256 MB</td><td>4 KB</td></tr>\n'
                '<tr><td>256〜512 MB</td><td>8 KB</td></tr>\n'
                '<tr><td>512〜1,024 MB</td><td>16 KB</td></tr>\n'
                '<tr><td>1〜2 GB</td><td>32 KB</td></tr>\n'
                '<tr><td>2〜4 GB</td><td>64 KB</td></tr>\n'
                '<tr><td>16 GB 超</td><td>非対応</td></tr>\n'
                '</tbody></table>\n'
                '<p>FAT ボリュームは、図11-14のようにいくつかの領域に分かれています。FAT '
                '形式の名前の由来であるファイル割り当てテーブルには、ボリューム内のクラスターごとに1つのエントリがあります。ボリュームの内容を正しく解釈するには、このテーブルが欠かせません。そこで '
                'FAT は同じテーブルを2つ保持します。ディスクの不良セクターなどでファイルシステムドライバーや <code>Chkdsk</code> '
                'などの整合性検査プログラムが一方を読めなくても、もう一方を参照できます。</p>\n'
                '<p>図11-14 FAT '
                '形式の配置。先頭から、ブートセクター、ファイル割り当てテーブル1、ファイル割り当てテーブル2（複製）、ルートディレクトリ、その他のディレクトリとすべてのファイルが並びます。</p>\n'
                '<p>ファイル割り当てテーブルのエントリは、ファイルやディレクトリの割り当てチェーンを構成します（図11-15）。各リンクには、ファイルデータが続く次のクラスターのインデックスが入ります。ファイルのディレクトリエントリには、先頭クラスターを記録します。チェーンの末尾には、FAT16 '
                'では <code>0xFFFF</code>、FAT12 では <code>0xFFF</code> という予約値を記録します。未使用クラスターに対応する FAT '
                'エントリの値は0です。図11-15では、FILE1 がクラスター2、3、4を使用しています。FILE2 は断片化されており、クラスター5、6、8を使います。FILE3 '
                'はクラスター7だけを使います。FAT ボリュームからファイルを読むときは、割り当てチェーンをたどるため、ファイル割り当てテーブルの広い範囲を読み取ることがあります。</p>\n'
                '<p>図11-15 FAT のファイル割り当てチェーンの例。</p>',
 'p2-page-636': '<p>FAT12 と FAT16 '
                'では、ボリュームの先頭側に、ルートディレクトリのエントリ256件分の領域があらかじめ確保されます。このため、ルートディレクトリに格納できるファイルとディレクトリの数に上限があります。FAT32 '
                'のルートディレクトリには、このような領域の事前割り当てや固定のサイズ上限はありません。FAT '
                'のディレクトリエントリは32バイトで、ファイル名、サイズ、先頭クラスター、最終アクセスや作成などの時刻情報を格納します。ファイル名が Unicode を使うか、MS-DOS '
                'の8.3命名規則に従わない場合は、長いファイル名を保存するために追加のエントリを割り当てます。追加エントリは、そのファイルの本体のエントリより前に置かれます。</p>\n'
                '<p>図11-16は「The quick brown fox」という名前のファイルのディレクトリエントリの例です。システムは8.3形式の名前として '
                '<code>THEQUI~1.FOX</code> を作成し、Unicode '
                'の長い名前を2件の追加エントリに格納しています。ピリオドは8文字目の後にあるものとして扱うため、エントリ内には格納されません。図の1行は16バイトです。</p>\n'
                '<p>図11-16 FAT '
                'のディレクトリエントリ。長い名前のエントリが2件あり、それに短い名前のエントリが続きます。図にはチェックサム、作成日時、最終アクセス日、最終更新日時、先頭クラスター、ファイルサイズの位置も示しています。</p>\n'
                '<p>FAT32 は32ビットのクラスター識別子を使いますが、上位4ビットを予約しているため、実際に使えるのは28ビットです。クラスターサイズは最大64 KB なので、理論上は16 '
                'TB のボリュームをアドレス指定できます。原本が扱う Windows では、ほかの OS が作成した32 GB を超える FAT32 ボリュームも利用できますが、新規作成の上限は32 '
                'GB です。FAT32 は FAT16 より多くのクラスターを指定できるため、ディスク領域をより効率的に管理できます。たとえば512バイトのクラスターで最大128 GB '
                'のボリュームを扱えます。表11-3に既定のクラスターサイズを示します。</p>\n'
                '<table><caption>表11-3 FAT32 '
                'ボリュームの既定のクラスターサイズ</caption><thead><tr><th>パーティションサイズ</th><th>既定のクラスターサイズ</th></tr></thead><tbody>\n'
                '<tr><td>32 MB 未満</td><td>非対応</td></tr>\n'
                '<tr><td>32〜64 MB</td><td>512バイト</td></tr>\n'
                '<tr><td>64〜128 MB</td><td>1 KB</td></tr>\n'
                '<tr><td>128〜256 MB</td><td>2 KB</td></tr>\n'
                '<tr><td>256 MB〜8 GB</td><td>4 KB</td></tr>\n'
                '<tr><td>8〜16 GB</td><td>8 KB</td></tr>\n'
                '<tr><td>16〜32 GB</td><td>16 KB</td></tr>\n'
                '<tr><td>32 GB 超</td><td>非対応</td></tr>\n'
                '</tbody></table>',
 'p2-page-637': '<p>FAT32 は、FAT12 や FAT16 '
                'に比べ、扱えるクラスター数が多いほか、ルートディレクトリの配置場所が固定されず、サイズにも固定の上限がありません。信頼性を高めるため、ブートセクターのコピーも保持します。一方、ディレクトリエントリがファイルサイズを32ビット値で保存するため、ファイルサイズの上限は '
                'FAT16 と同じ約4 GB です。</p>\n'
                '<h4>exFAT</h4>\n'
                '<p>Microsoft が設計した Extended File Allocation Table（exFAT、別名 FAT64）は、従来の FAT '
                'を改良し、フラッシュドライブに適したファイルシステムです。主な目的は、NTFS '
                'の高度な機能の一部を提供しつつ、メタデータ構造に伴うオーバーヘッドや、多くのフラッシュメディアに適さない書き込みパターンを生むメタデータのログ記録を避けることです。表11-4に、exFAT '
                'の既定のクラスターサイズを示します。</p>\n'
                '<p>FAT64 の名前が示すように、ファイルサイズを64ビットで表し、理論上は約16エクサバイトのファイルを扱えます。最大クラスターサイズも拡大されており、原本が扱う実装では32 '
                'MB です。exFAT '
                'は空きクラスターを追跡するビットマップを追加し、割り当てと削除を高速化しています。また、1つのディレクトリに1,000件を超えるファイルを格納できます。これらの特徴により、大容量ディスクを扱いやすくなっています。</p>\n'
                '<table><caption>表11-4 セクターサイズが512バイトの exFAT '
                'ボリュームの既定のクラスターサイズ</caption><thead><tr><th>ボリュームサイズ</th><th>既定のクラスターサイズ</th></tr></thead><tbody>\n'
                '<tr><td>256 MB 未満</td><td>4 KB</td></tr>\n'
                '<tr><td>256 MB〜32 GB</td><td>32 KB</td></tr>\n'
                '<tr><td>32〜512 GB</td><td>128 KB</td></tr>\n'
                '<tr><td>512 GB〜1 TB</td><td>256 KB</td></tr>\n'
                '<tr><td>1〜2 TB</td><td>512 KB</td></tr>\n'
                '<tr><td>2〜4 TB</td><td>1 MB</td></tr>\n'
                '<tr><td>4〜8 TB</td><td>2 MB</td></tr>\n'
                '<tr><td>8〜16 TB</td><td>4 MB</td></tr>\n'
                '<tr><td>16〜32 TB</td><td>8 MB</td></tr>\n'
                '<tr><td>32〜64 TB</td><td>16 MB</td></tr>\n'
                '<tr><td>64 TB 以上</td><td>32 MB</td></tr>\n'
                '</tbody></table>\n'
                '<p>exFAT は、アクセス制御リスト（ACL）やトランザクション（Transaction-Safe FAT、TFAT）など、以前は NTFS '
                'だけで使えた機能にも対応しています。これらは Windows Embedded CE に含まれる exFAT に実装されています。通常の Windows の exFAT '
                'では利用できません。</p>\n'
                '<aside><p>第1部第5章「メモリ管理」で説明した ReadyBoost は、exFAT でフォーマットしたフラッシュドライブを使うと、4 GB '
                'を大きく超えるキャッシュファイルにも対応できます。</p></aside>',
 'p2-page-638': '<h4>NTFS</h4>\n'
                '<p>章の冒頭で述べたように、NTFS は Windows のネイティブなファイルシステム形式の1つです。NTFS '
                'は64ビットのクラスター番号を使うため、形式上は最大16エクサクラスターのボリュームをアドレス指定できます。ただし、Windows は NTFS '
                'ボリュームのサイズを32ビットのクラスター番号で表せる範囲に制限します。2 MB のクラスターを使う場合、上限は8 PB 弱です。表11-5に NTFS '
                'ボリュームの既定のクラスターサイズを示します。フォーマット時に別の値を指定できます。NTFS '
                'が1ボリュームに格納できるファイル数は最大2<sup>32</sup>−1です。形式上は約16エクサバイトのファイルを表せますが、原本が扱う実装での上限は16 TB です。</p>\n'
                '<table><caption>表11-5 NTFS '
                'ボリュームの既定のクラスターサイズ</caption><thead><tr><th>ボリュームサイズ</th><th>既定のクラスターサイズ</th></tr></thead><tbody>\n'
                '<tr><td>7 MB 未満</td><td>非対応</td></tr>\n'
                '<tr><td>7 MB〜16 TB</td><td>4 KB</td></tr>\n'
                '<tr><td>16〜32 TB</td><td>8 KB</td></tr>\n'
                '<tr><td>32〜64 TB</td><td>16 KB</td></tr>\n'
                '<tr><td>64〜128 TB</td><td>32 KB</td></tr>\n'
                '<tr><td>128〜256 TB</td><td>64 KB</td></tr>\n'
                '<tr><td>256〜512 TB</td><td>128 KB</td></tr>\n'
                '<tr><td>512〜1,024 TB</td><td>256 KB</td></tr>\n'
                '<tr><td>1〜2 PB</td><td>512 KB</td></tr>\n'
                '<tr><td>2〜4 PB</td><td>1 MB</td></tr>\n'
                '<tr><td>4〜8 PB</td><td>2 MB</td></tr>\n'
                '</tbody></table>\n'
                '<p>NTFS '
                'は、ファイルとディレクトリのアクセス制御、代替データストリーム、ディスククォータ、スパースファイル、圧縮、シンボリックリンクとハードリンク、トランザクション、ジャンクションポイント、暗号化などを備えています。重要な機能の1つは回復可能性です。システムが予期せず停止すると、FAT '
                'ボリュームのメタデータは不整合な状態で残り、多数のファイルやディレクトリのデータが破損するおそれがあります。NTFS '
                'はメタデータの変更をトランザクションとしてログに記録します。これにより、ファイルやディレクトリの構造情報を失わず、ファイルシステムを整合した状態に戻せます。ただし、後述する TxF '
                'を使っていなければ、ファイルのデータ自体は失われることがあります。Windows の NTFS '
                'ドライバーは自己修復も実装しています。これにより、ディスク上のファイルシステム構造に生じた軽微な破損の大半を、Windows を再起動せず、稼働中に修復できます。</p>\n'
                '<aside><p>執筆時点では、ディスクの物理セクターサイズは4 KB '
                'が一般的です。互換性のため、ストレージスタックは、このようなデバイスでもファイルシステムドライバーに512バイトの論理セクターを提示する場合があります。NTFS '
                'ドライバーはクラスターサイズの計算に、実際の物理セクターサイズではなく論理セクターサイズを使います。</p></aside>',
 'p2-page-639': '<p>Windows 10 以降、NTFS は DAX ボリュームにネイティブ対応しています。DAX ボリュームについては本章の後半で説明します。NTFS '
                'のファイルシステムドライバーは、この種のボリュームへの I/O でラージページも利用できます。DAX ボリューム上のファイルをラージページでマップする方法は2つあります。NTFS '
                'がファイルを2 MB のクラスター境界に自動で揃えるか、クラスターサイズを2 MB に指定してボリュームをフォーマットします。</p>\n'
                '<h4>ReFS</h4>\n'
                '<p>Resilient File System（ReFS）は、Windows '
                'がネイティブにサポートするもう1つのファイルシステムです。主に大規模なストレージサーバー向けに設計され、稼働中の自己修復やボリューム修復、ファイルのスナップショットなど、設計当時の '
                'NTFS における制約への対応を目指しました。ReFS '
                'は新しい場所に書き込む方式を採ります。ボリュームのメタデータを更新するときは、常に新しいデータを記憶媒体に書き込み、古いメタデータを削除済みとしてマークします。ディスク上のデータ構造を扱う '
                'ReFS の下位層は Minstore というオブジェクトストアライブラリを使います。Minstore '
                'は呼び出し元にキーと値のテーブルとして操作できるインターフェイスを提供します。現代のデータベースエンジンに似た移植性のある設計で、B+木など、NTFS '
                'とは異なるデータ構造やアルゴリズムを使います。</p>\n'
                '<p>ReFS の重要な設計目標の1つは、記憶域スペースなどで作成される極めて大きなボリュームを扱うことでした。NTFS '
                'と同様に64ビットのクラスター番号を使い、最大16エクサクラスターをアドレス指定できます。ReFS はアドレスに使える値をさらに制限しないため、64 KB '
                'のクラスターを使えば、理論上は最大1ヨタバイトのボリュームを管理できます。</p>\n'
                '<p>Minstore '
                'は、ボリューム上の特定の領域に独自のメタデータを集中させる必要がありません。ただし、オブジェクトテーブルにはある程度集中します。また、アドレスの値に追加の制限がないため、多様なクラスターサイズを用意する必要がありません。ReFS '
                'がサポートするクラスターサイズは4 KB と64 KB です。執筆時点では DAX ボリュームには対応していません。NTFS と ReFS '
                'のデータ構造および高度な機能については、本章の後半で詳しく説明します。</p>\n'
                '<h4>ファイルシステムドライバーのアーキテクチャ</h4>\n'
                '<p>ファイルシステムドライバー（FSD）はファイルシステム形式を管理します。カーネルモードで動作しますが、標準的なカーネルモードドライバーとはいくつかの点で異なります。特に、FSD '
                'として I/O '
                'マネージャーに登録する必要があり、メモリマネージャーとの連携も多くなります。また、性能を高めるため、通常はキャッシュマネージャーの機能も利用します。そのため、標準のドライバーよりも多くの '
                '<code>Ntoskrnl.exe</code> の公開関数を使います。ファイルシステムドライバーの開発には、標準のカーネルモードドライバーと同様に Windows Driver '
                'Kit（WDK）が必要です。詳細は第1部第1章「概念とツール」および <a '
                'href="https://learn.microsoft.com/windows-hardware/drivers/">Windows '
                'ドライバー開発ドキュメント</a>を参照してください。</p>\n'
                '<p>Windows の FSD には2種類あります。</p>\n'
                '<ul><li>ローカル FSD は、そのコンピューターに直接接続されたボリュームを管理します。</li><li>ネットワーク FSD '
                'は、リモートコンピューターに接続されたボリューム上のデータにユーザーがアクセスできるようにします。</li></ul>',
 'p2-page-640': '<h4>ローカルファイルシステムドライバー</h4>\n'
                '<p>ローカル FSD には '
                '<code>Ntfs.sys</code>、<code>Refs.sys</code>、<code>Refsv1.sys</code>、<code>Fastfat.sys</code>、<code>Exfat.sys</code>、<code>Udfs.sys</code>、<code>Cdfs.sys</code>、および '
                '<code>Ntoskrnl.exe</code> に組み込まれた RAW FSD があります。図11-17に、ローカル FSD と I/O '
                'マネージャー、ストレージデバイスドライバーの関係を示します。ローカル FSD は I/O '
                'マネージャーに自身を登録します。登録後、アプリケーションやシステムがボリュームに初めてアクセスすると、I/O マネージャーが FSD '
                'を呼び出し、ボリュームの形式を認識させます。FSD '
                'はボリュームのブートセクターを調べ、整合性を確認するためファイルシステムのメタデータも調べることがあります。登録済みのどのファイルシステムも認識できない場合、システムはボリュームに '
                'RAW ドライバーを割り当て、ユーザーにフォーマットするかどうかを尋ねます。ユーザーがフォーマットしなければ、RAW '
                'ドライバーでボリュームにアクセスできます。ただし読み書きはセクター単位に限られます。</p>\n'
                '<p>ファイルシステム認識機構の目的は、ボリュームのファイルシステムが有効でも、登録済みドライバーでは認識できない場合に、その状態を判別することです。このため、ボリュームの最初のセクターに書き込める固定形式の '
                '<code>FILE_SYSTEM_RECOGNITION_STRUCTURE</code> が定義されています。構造体があれば、OS '
                'は有効な未認識のファイルシステムがあることをユーザーに通知します。ボリュームには RAW '
                'ドライバーを読み込みますが、フォーマットは求めません。ユーザーアプリケーションやカーネルモードドライバーは、ファイルシステムの I/O 制御コード '
                '<code>FSCTL_QUERY_FILE_SYSTEM_RECOGNITION</code> でこの構造体のコピーを取得できます。</p>\n'
                '<p>Windows が対応するファイルシステム形式では、ボリュームの最初のセクターをブートセクターとして予約します。ローカル FSD '
                'は、このセクターの情報から、自身が扱う形式のボリュームかどうかを判別し、ボリューム上のメタデータの配置を調べるのに必要な情報も取得できます。</p>\n'
                '<p>ローカル FSD がボリュームを認識すると、マウントされたファイルシステムを表すデバイスオブジェクトを作成します。I/O '
                'マネージャーは、ボリュームパラメーターブロック（VPB）を使い、ストレージデバイスドライバーが作成したボリュームのデバイスオブジェクトと、FSD '
                'が作成したデバイスオブジェクトを関連付けます。この関連付けにより、I/O マネージャーは、ボリュームのデバイスオブジェクト宛ての I/O 要求を FSD '
                '側のデバイスオブジェクトへ転送します。</p>\n'
                '<p>図11-17 ローカル FSD。ユーザーモードのアプリケーションからの I/O は、カーネルモードの I/O '
                'マネージャー、ファイルシステムドライバー、ストレージデバイスドライバーを経て、論理ボリューム（パーティション）に届きます。</p>',
 'p2-page-641': '<p>ローカル FSD '
                'は通常、性能を高めるために、メタデータを含むファイルシステムのデータをキャッシュマネージャーでキャッシュします。また、ファイルのメモリマッピングが正しく機能するよう、メモリマネージャーとも連携します。たとえば、アプリケーションがファイルを切り詰めようとする場合、FSD '
                'はメモリマネージャーに照会し、新しいファイル終端より後ろの範囲をマップしているプロセスがないことを確認します。メモリマネージャーの詳細は第1部第5章を参照してください。Windows '
                'では、アプリケーションがマップしているファイルデータを、切り詰めやファイルの削除によって取り除くことはできません。</p>\n'
                '<p>ローカル FSD はファイルシステムのマウント解除にも対応します。これにより、システムは FSD '
                'とボリュームオブジェクトの関連付けを解除できます。マウント解除は、アプリケーションがボリュームのディスク上の内容に直接アクセスする必要があるときや、ボリュームに対応するメディアが交換されたときに行います。解除後、最初のアプリケーションがメディアにアクセスすると、I/O '
                'マネージャーはそのメディアのボリュームを改めてマウントします。</p>\n'
                '<h4>リモートファイルシステムドライバー</h4>\n'
                '<p>リモート FSD は、クライアント側とサーバー側の2つのコンポーネントで構成されます。クライアント側の FSD は、アプリケーションからの I/O 要求を受け、SMB '
                'などのネットワークファイルシステムプロトコルのコマンドに変換して、ネットワーク越しにサーバー側の FSD '
                'に送ります。これにより、アプリケーションはリモートのファイルやディレクトリにアクセスできます。サーバー側の FSD '
                'は接続から届くコマンドを待ち受け、対象のファイルやディレクトリがあるボリュームを管理するローカル FSD に I/O 要求を発行して処理します。</p>\n'
                '<p>Windows のクライアント側には LANMan Redirector（通常は単にリダイレクターと呼びます）、サーバー側には LANMan '
                'Server（<code>%SystemRoot%&#92;System32&#92;Drivers&#92;Srv2.sys</code>）があります。図11-18は、クライアントがリダイレクターとサーバー側の '
                'FSD を使って、サーバーにあるファイルにアクセスする経路を示しています。</p>\n'
                '<p>図11-18 Common Internet File System によるファイル共有。クライアントアプリケーションはユーザーモードの '
                '<code>Kernel32.dll</code> と <code>Ntdll.dll</code> を経由し、カーネルモードのリダイレクター FSD '
                'に要求を渡します。両端のプロトコルドライバー（WSK トランスポート）がネットワークを介してやり取りし、サーバー FSD はローカル FSD（NTFS、FAT '
                'など）を通じてディスク上のファイルデータを扱います。図には両端のキャッシュマネージャーも示しています。</p>',
 'p2-page-642': '<p>リダイレクターとサーバーが交換するメッセージの形式には、Common Internet File System（CIFS）プロトコルが使われます。CIFS は '
                'Microsoft の Server Message Block（SMB）プロトコルの一種です。詳細は <a '
                'href="https://learn.microsoft.com/windows/win32/fileio/microsoft-smb-protocol-and-cifs-protocol-overview">Microsoft '
                'の SMB と CIFS の概要</a>を参照してください。</p>\n'
                '<p>ローカル FSD と同様に、クライアント側のリモート FSD '
                'は通常、キャッシュマネージャーを使ってリモートのファイルやディレクトリのデータをローカルにキャッシュします。その場合は、クライアントとサーバーの両方に分散ロックの仕組みが必要です。SMB '
                'のクライアント側 FSD '
                'は、oplock（便宜的ロック）という分散キャッシュの一貫性を保つプロトコルを実装しています。これにより、複数のコンピューター上のアプリケーションが同じリモートファイルにアクセスしても、同じデータを参照できます。サードパーティのファイルシステムは、oplock '
                'を使うことも、独自のプロトコルを実装することもできます。サーバー側の FSD はクライアント間のキャッシュの一貫性を維持します。ローカル FSD のデータはローカル FSD '
                '自身がキャッシュします。</p>\n'
                '<p>複数の利用者が同時にアクセスできる共有リソースには、書き込みを直列化し、同時に書き込む利用者が1つだけになるよう調整する仕組みが必要です。調整しなければ、リソースが破損する場合があります。SMB '
                'を実装するファイルサーバーは、oplock '
                'とリースをロックの仕組みとして使います。どちらを使うかはサーバーとクライアント双方の対応状況によって決まり、両方が対応していればリースを優先します。</p>\n'
                '<h4>便宜的ロック（oplock）</h4>\n'
                '<p>oplock はファイルシステムランタイムライブラリの <code>FsRtlXxx</code> '
                '関数で実装されており、どのファイルシステムドライバーからでも利用できます。リモートファイルサーバーのクライアントは oplock '
                'によってキャッシュ方法を動的に選び、ネットワーク通信を減らします。アプリケーションが共有上のファイルを開こうとすると、ファイルシステムドライバーまたはリダイレクターが、アプリケーションに代わってそのファイルの '
                'oplock を要求します。サーバーが oplock '
                'を付与すると、クライアントは読み書きのたびにサーバーに要求を送らず、ファイルをローカルでキャッシュできます。たとえば、クライアントがファイルを排他的に開けば、すべての読み書きをキャッシュし、ファイルを閉じるときに変更をサーバーに送れます。oplock '
                'が付与されなければ、読み書きの要求をすべてサーバーに送ります。</p>\n'
                '<p>oplock '
                'の付与後は、その種類に応じたキャッシュが可能になります。クライアントがファイルの使用を終える前でも、サーバーが既存のロックと両立しない操作を受け取れば、oplock '
                'はいつでも解除され得ます。そのため、クライアントは解除通知にすばやく応答し、キャッシュ方法をその場で切り替える必要があります。</p>\n'
                '<p>SMB 2.1 より前には、4種類の oplock がありました。</p>\n'
                '<dl>\n'
                '<dt>レベル1（排他アクセス）</dt><dd>クライアントがファイルを排他的に開けます。先読みバッファリングに加え、読み取りと書き込みをキャッシュできます。</dd>\n'
                '<dt>レベル2（共有アクセス）</dt><dd>複数のクライアントが同時にファイルを読み取れます。書き込みは許可されません。先読みバッファリングを行い、ファイルデータと属性の読み取りをキャッシュできます。ファイルへの書き込みが発生すると、ロックを保持するクライアントに解除を通知します。</dd>\n'
                '</dl>',
 'p2-page-643': '<dl>\n'
                '<dt>バッチ（排他アクセス）</dt><dd>名前は、バッチファイル（<code>.bat</code>）を処理するときに使われたロックに由来します。バッチ処理では、ファイルの各行を処理するたびに開閉します。このロックがあれば、アプリケーションが一時的にファイルを閉じても、クライアントはサーバー上でファイルを開いたままにできます。読み取り、書き込み、ハンドルのキャッシュに対応します。</dd>\n'
                '<dt>フィルター（排他アクセス）</dt><dd>他のクライアントが同じファイルにアクセスしようとした場合に、アプリケーションやファイルシステムフィルターがロックを手放せる仕組みです。レベル2とは異なり、削除アクセスを求めてファイルを開くことはできず、他のクライアントに共有違反も返されません。読み取りと書き込みのキャッシュに対応します。</dd>\n'
                '</dl>\n'
                '<p>複数のクライアントがサーバーで共有されている同じファイルをキャッシュしているとします。クライアントやサーバー上のすべてのアプリケーションが読み取りだけを行う限り、各システムはローカルキャッシュから要求を満たせます。サーバーから各システムへファイルの内容を繰り返し送らないため、ネットワーク通信量は大幅に減ります。ロック情報の交換は引き続き必要ですが、使う帯域はわずかです。一方、クライアントが1台でも読み書き用、または排他的な書き込み用にファイルを開くと、ローカルキャッシュは使えなくなり、そのファイルへのすべての '
                'I/O を直ちにサーバーに送る必要があります。実際に書き込まなくても同じです。ロックモードは個々の I/O 要求ではなく、ファイルを開いたときの指定によって決まります。</p>\n'
                '<p>図11-19は oplock の動作例です。サーバーは、サーバー上のファイルを最初に開くクライアントに、レベル1の oplock '
                'を自動で付与します。クライアントのリダイレクターは、読み取ったデータと書き込んだデータをクライアントのファイルキャッシュに保持します。2台目のクライアントが同じファイルを開くと、こちらもレベル1の '
                'oplock を要求します。サーバーは、両方のクライアントに一貫したファイルの内容を返す必要があります。図のように1台目がすでに書き込んでいる場合、サーバーは1台目の oplock '
                'を解除し、どちらにも oplock を付与しません。解除通知を受けた1台目は、キャッシュ内にある変更済みデータをサーバーに書き戻します。</p>\n'
                '<p>図11-19 oplock の例。1台目はレベル1の取得後に読み書きをキャッシュし、解除時に変更済みデータを書き戻します。2台目には oplock '
                'が付与されず、以降は両者ともキャッシュを使わずに読み書きします。</p>',
 'p2-page-644': '<p>1台目のクライアントがまだファイルに書き込んでいなければ、サーバーは1台目の oplock をレベル2に引き下げ、2台目にもレベル2の oplock '
                'を付与します。両方のクライアントが読み取りをキャッシュできますが、どちらかがファイルに書き込むと、サーバーは両方の oplock '
                'を解除し、以後はキャッシュを使わずに処理します。一度解除した oplock '
                'は、ファイルを開いた同じインスタンスには再付与されません。ただし、クライアントがファイルを閉じて開き直すと、サーバーは、どのクライアントがファイルを開いているか、そのうち少なくとも1台が書き込んだかを基に、付与する '
                'oplock のレベルを再評価します。</p>\n'
                '<h4>実験\u3000登録済みのファイルシステムを一覧表示する</h4>\n'
                '<p>I/O マネージャーは、デバイスドライバーをメモリに読み込むとき、通常は、そのドライバーを表すドライバーオブジェクトがオブジェクトマネージャーの '
                '<code>&#92;Driver</code> ディレクトリに入るように名前を付けます。<code>Type</code> 属性が '
                '<code>SERVICE_FILE_SYSTEM_DRIVER</code>（2）のドライバーについては、ドライバーオブジェクトを '
                '<code>&#92;FileSystem</code> ディレクトリに配置します。そのため、Sysinternals の WinObj '
                'などでこのディレクトリを開くと、図のように、システムに登録済みのファイルシステムを確認できます。この一覧には、後述するファイルシステムフィルタードライバーも表示されます。</p>\n'
                '<p>登録済みのファイルシステムは、「システム情報」でも確認できます。スタートメニューの「ファイル名を指定して実行」で <code>Msinfo32</code> '
                'を実行し、「ソフトウェア環境」の「システム ドライバー」を選びます。「種類」列をクリックして一覧を並べ替えると、<code>Type</code> 属性が '
                '<code>SERVICE_FILE_SYSTEM_DRIVER</code> のドライバーがまとまって表示されます。</p>\n'
                '<figure><img loading="lazy" width="478" height="450" '
                'src="assets/7303badc747c258d007d27e8.webp" alt="oplock の動作（原文の図1）"></figure>',
 'p2-page-645': '<p>ファイルシステムドライバーとして登録されていても、ローカル FSD やリモート FSD として動作するとは限りません。たとえば <code>Npfs</code>（Named '
                'Pipe File '
                'System）は、ファイルシステムに似た独自の名前空間を使って名前付きパイプを実装するドライバーです。この一覧には、前述のファイルシステムフィルタードライバーも含まれます。</p>\n'
                '<h4>リース</h4>\n'
                '<p>SMB 2.1 より前の SMB '
                'プロトコルは、クライアントとサーバー間の接続に障害が起きないことを前提とし、一時的なネットワーク障害、サーバーの再起動、クラスターのフェイルオーバーによる切断から復旧できませんでした。クライアントが切断イベントを受け取ると、影響を受けたサーバーで開いていたすべてのハンドルは接続先を失い、それらを使う以後の '
                'I/O '
                'はすべて失敗しました。サーバーも、切断されたユーザーセッションに関連する開いていたハンドルとリソースをすべて解放しました。その結果、アプリケーションの状態が失われ、余分なネットワーク通信も発生しました。</p>\n'
                '<figure><img loading="lazy" width="649" height="454" '
                'src="assets/e9e62b505ef590a30d09024f.webp" alt="ファイルシステムドライバー（原文の図1）"></figure>',
 'p2-page-646': '<p>SMB 2.1 では、oplock と同じ目的で使う新しいクライアント側キャッシュの仕組みとして、リースが導入されました。リースは oplock '
                'より柔軟で、性能も大幅に向上します。</p>\n'
                '<dl>\n'
                '<dt>読み取り（R、共有アクセス）</dt><dd>複数のクライアントが同時に読み取れます。書き込みは許可されません。クライアントは先読みバッファリングと読み取りのキャッシュを行えます。</dd>\n'
                '<dt>読み取り・ハンドル（RH、共有アクセス）</dt><dd>レベル2の oplock '
                'に近い動作に加え、クライアント側のアプリケーションがファイルを閉じても、サーバー上ではファイルを開いたままにできます。キャッシュマネージャーは未書き込みのデータを遅延して書き戻し、利用できるメモリに応じて変更されていないキャッシュページを破棄します。ファイルのハンドルを閉じて開き直すたびにリースを解除する必要がない点は、バッチ '
                'oplock に似ています。開閉を繰り返すファイルでは、閉じるたびにキャッシュを無効化して、次に開くときに読み込み直す処理を省けるため、多数の I/O '
                'を行う複雑なアプリケーションの性能が大幅に向上します。</dd>\n'
                '<dt>読み取り・書き込み（RW、排他アクセス）</dt><dd>クライアントがファイルを排他的に開けます。先読みバッファリングと、読み取りや書き込みのキャッシュが可能です。</dd>\n'
                '<dt>読み取り・書き込み・ハンドル（RWH、排他アクセス）</dt><dd>クライアントがファイルを排他的に開けます。読み取り、書き込み、ハンドルをキャッシュできます。ハンドルのキャッシュは '
                'RH と同様です。</dd>\n'
                '</dl>\n'
                '<p>リースでは、多くのアプリケーションで見られるように、クライアントが同じファイルを複数のハンドルで開いていても、ファイルをキャッシュできます。クライアントは GUID '
                'で表すリースキーを作成し、キャッシュ対象のファイルのファイル制御ブロック（FCB）に関連付けます。同じファイルのハンドルがリースの状態を共有するため、ファイル単位でキャッシュできます。リースの導入前は、同じクライアントからでも、ファイルを新しいハンドルで開くたびに '
                'oplock が解除されました。図11-20に従来の oplock、図11-21にリースの動作を示します。</p>\n'
                '<p>SMB 2.1 より前の oplock '
                'に対する操作は付与と解除に限られていました。リースは種類を切り替えることもでき、たとえば読み取りリースを読み取り・書き込みリースに変更できます。レベル2の oplock '
                'を解除してレベル1を要求し直す場合に必要だったキャッシュの無効化と再読み込みを省けるため、ネットワーク通信量を大幅に減らせます。</p>',
 'p2-page-647': '<table><caption>図11-20 同一クライアントから複数のハンドルを開いた場合の oplock（上から時系列順）</caption>\n'
                '<thead><tr><th>アプリケーション</th><th>クライアント側の '
                'Windows</th><th>ネットワーク</th><th>サーバー</th></tr></thead><tbody>\n'
                '<tr><td>A がサーバー上のファイルを開き、ハンドルを受け取る。</td><td><code>CreateFile</code> に '
                '<code>FILE_GENERIC_READ</code> と <code>FILE_GENERIC_WRITE</code> '
                'を指定する。</td><td>ファイルを開く要求を送り、バッチ oplock の付与を受ける。</td><td>ファイルの最初のハンドルを開く。</td></tr>\n'
                '<tr><td>A が読み取りを要求し、要求した量のデータを受け取る。</td><td><code>ReadFile</code> の I/O が完了し、要求分を A '
                'に返す。先読み分はキャッシュに格納する。</td><td>読み取りデータと先読みデータをサーバーから受け取る。</td><td>ファイルからデータを読み取って返す。</td></tr>\n'
                '<tr><td>A がキャッシュ済みの範囲を読み取る。</td><td><code>ReadFile</code> の I/O が完了し、キャッシュのデータを A '
                'に返す。</td><td>パケットの送受信なし。</td><td>操作を認識しない。</td></tr>\n'
                '<tr><td>A がキャッシュ済みの範囲に書き込む。</td><td><code>WriteFile</code> がキャッシュに書き込み、I/O '
                'が完了する。</td><td>パケットの送受信なし。</td><td>操作を認識しない。</td></tr>\n'
                '<tr><td>B が同じファイルを読み取り用に開き、ハンドルを受け取る。</td><td><code>CreateFile</code> に '
                '<code>FILE_GENERIC_READ</code> を指定する。キャッシュを書き戻し、以後はこのファイルをキャッシュしない。</td><td>ファイルを開く要求とバッチ '
                'oplock の解除通知を交換する。</td><td>バッチ oplock を解除し、ファイルの2つ目のハンドルを開く。</td></tr>\n'
                '<tr><td>A が以前キャッシュしていた範囲を読み取る。</td><td><code>ReadFile</code> の I/O が完了し、データを A '
                'に返す。</td><td>サーバーに読み取りを要求し、データを受け取る。</td><td>ファイルからデータを読み取る。</td></tr>\n'
                '<tr><td>A が以前キャッシュしていた範囲に書き込む。</td><td><code>WriteFile</code> の I/O '
                'が完了する。</td><td>書き込みデータをサーバーへ送る。</td><td>データをファイルに書き込む。</td></tr>\n'
                '</tbody></table>',
 'p2-page-648': '<table><caption>図11-21 同一クライアントから複数のハンドルを開いた場合のリース（上から時系列順）</caption>\n'
                '<thead><tr><th>アプリケーション</th><th>クライアント側の '
                'Windows</th><th>ネットワーク</th><th>サーバー</th></tr></thead><tbody>\n'
                '<tr><td>A がサーバー上のファイルを開き、ハンドルを受け取る。</td><td><code>CreateFile</code> に '
                '<code>FILE_GENERIC_READ</code> と <code>FILE_GENERIC_WRITE</code> '
                'を指定する。</td><td>ファイルを開く要求を送り、読み取り・ハンドル（RH）リースの付与を受ける。</td><td>ファイルの最初のハンドルを開く。</td></tr>\n'
                '<tr><td>A が読み取りを要求し、要求した量のデータを受け取る。</td><td><code>ReadFile</code> の I/O が完了し、要求分を A '
                'に返す。先読み分はキャッシュに格納する。</td><td>読み取りデータと先読みデータをサーバーから受け取る。</td><td>ファイルからデータを読み取って返す。</td></tr>\n'
                '<tr><td>A がキャッシュ済みの範囲を読み取る。</td><td><code>ReadFile</code> の I/O が完了し、キャッシュのデータを A '
                'に返す。</td><td>パケットの送受信なし。</td><td>操作は通知されない。</td></tr>\n'
                '<tr><td>A がキャッシュ済みの範囲に書き込む。</td><td><code>WriteFile</code> がキャッシュに書き込み、I/O '
                'が完了する。</td><td>パケットの送受信なし。</td><td>この時点では操作は通知されない。</td></tr>\n'
                '<tr><td>B が同じファイルを読み取り用に開き、ハンドルを受け取る。</td><td><code>CreateFile</code> に '
                '<code>FILE_GENERIC_READ</code> '
                'を指定する。</td><td>ファイルを開く要求を送る。リースの解除通知はない。</td><td>ファイルの2つ目のハンドルを開く。リースは維持される。</td></tr>\n'
                '<tr><td>B がキャッシュ済みの範囲を読み取る。</td><td><code>ReadFile</code> の I/O が完了し、キャッシュのデータを B '
                'に返す。</td><td>パケットの送受信なし。</td><td>操作は通知されない。</td></tr>\n'
                '<tr><td>A がキャッシュ済みの範囲に再び書き込む。</td><td><code>WriteFile</code> がキャッシュに書き込み、I/O '
                'が完了する。</td><td>書き込み時点ではパケットの送受信なし。</td><td>操作はその場では通知されない。クライアントが後で変更をサーバーに書き戻す。</td></tr>\n'
                '</tbody></table>\n'
                '<aside><p>原図には「キャッシュを書き戻し、以後はこのファイルをキャッシュしない」という注記もありますが、同じ図は2つ目のハンドルを開いてもリースが維持され、その後の読み書きもキャッシュで処理されることを示しています。</p></aside>',
 'p2-page-649': '<h4>ファイルシステムの操作</h4>\n'
                '<p>アプリケーションとシステムがファイルにアクセスする方法は2つあります。<code>ReadFile</code> や <code>WriteFile</code> '
                'などのファイル I/O '
                '関数を使って直接アクセスする方法と、ファイルのセクションをマップしたアドレス空間の一部を読み書きして間接的にアクセスする方法です。マップ済みファイルの詳細は第1部第5章を参照してください。図11-22は、これらのファイルシステム操作に関わるコンポーネントと、その連携を簡略化して示しています。ファイルシステムドライバー（FSD）が呼び出される経路には、次のものがあります。</p>\n'
                '<ul>\n'
                '<li>ファイル I/O を明示的に行うユーザーまたはシステムのスレッドから。</li>\n'
                '<li>メモリマネージャーの変更済みページライターやマップ済みページライターから。</li>\n'
                '<li>キャッシュマネージャーの遅延ライターから間接的に。</li>\n'
                '<li>キャッシュマネージャーの先読みスレッドから間接的に。</li>\n'
                '<li>メモリマネージャーのページフォールトハンドラーから。</li>\n'
                '</ul>\n'
                '<p>図11-22 ファイルシステム I/O に関わるコンポーネント。図にはプロセスのハンドルテーブルとファイルオブジェクト、NTFS '
                'のファイル制御ブロックとストリーム制御ブロック、データ属性と名前付きストリーム、ディスク上の NTFS データベースとマスターファイルテーブルが示されています。</p>\n'
                '<p>以下では、それぞれの経路で I/O が発生する状況と、FSD '
                'が通常どのように処理するかを説明します。どの経路でも、メモリマネージャーとキャッシュマネージャーが重要な役割を果たします。</p>',
 'p2-page-650': '<h4>明示的なファイル I/O</h4>\n'
                '<p>アプリケーションは <code>CreateFile</code>、<code>ReadFile</code>、<code>WriteFile</code> '
                'など、Windows の I/O 関数を使ってファイルにアクセスできます。<code>CreateFile</code> でファイルを開き、返されたハンドルを別の Windows '
                '関数に渡してファイルを読み取り、書き込み、削除します。Windows のクライアント側 DLL である <code>Kernel32.dll</code> に実装された '
                '<code>CreateFile</code> は、渡されたパスに含まれる <code>.</code> と <code>..</code> '
                'を処理してルートからの完全なパスを組み立て、先頭に <code>&#92;??</code> を付けてネイティブ関数 <code>NtCreateFile</code> '
                'を呼び出します。変換後のパスの例は <code>&#92;??&#92;C:&#92;Daryl&#92;Todo.txt</code> です。</p>\n'
                '<p>システムサービス <code>NtCreateFile</code> は <code>ObOpenObjectByName</code> '
                'を使ってファイルを開きます。この関数は、オブジェクトマネージャーのルートディレクトリから、パスの最初の要素である <code>??</code> '
                'を起点に名前を解析します。オブジェクトマネージャーの名前解決とプロセスのデバイスマップについては第8章「システム機構」で詳しく説明しました。ここでは、ボリュームのドライブ文字を検索する手順に絞ります。</p>\n'
                '<p>まずオブジェクトマネージャーは、<code>&#92;??</code> '
                'をプロセスのセッション別名前空間のディレクトリに変換します。このディレクトリは、プロセスオブジェクト内のデバイスマップの '
                '<code>DosDevicesDirectory</code> '
                'が指します。デバイスマップは、ログオンセッションのトークンにあるログオンセッション参照フィールドを使い、そのセッションの最初のプロセスから引き継がれたものです。通常、このディレクトリにはネットワーク共有のボリューム名と、<code>Subst.exe</code> '
                'で割り当てたドライブ文字だけが格納されます。目的の名前（この例では '
                '<code>C:</code>）が見つからない場合、オブジェクトマネージャーは、セッション別ディレクトリに対応するデバイスマップの '
                '<code>GlobalDosDevicesDirectory</code> が指すディレクトリで検索し直します。このフィールドは常に、ローカルボリュームのドライブ文字を格納する '
                '<code>&#92;GLOBAL??</code> を指します。詳細は第8章「セッション名前空間」を参照してください。プロセスは独自のデバイスマップも持てます。これは RPC '
                'などのプロトコルで偽装を行うときに重要です。</p>\n'
                '<p>ドライブ文字のシンボリックリンクは <code>&#92;Device</code> '
                '配下のボリュームデバイスオブジェクトを指します。ダイナミックディスク上のボリュームでは、中間のシンボリックリンクを経由します。オブジェクトマネージャーは、ボリュームオブジェクトに到達すると、未解決のパスを、I/O '
                'マネージャーがデバイスオブジェクト用に登録した解析関数 <code>IopParseDevice</code> '
                'に渡します。図11-23はこの経路の例で、<code>&#92;GLOBAL??&#92;C:</code> が '
                '<code>&#92;Device&#92;HarddiskVolume6</code> を指しています。</p>\n'
                '<p><code>IopParseDevice</code> は呼び出し元のセキュリティコンテキストをロックし、トークンからセキュリティ情報を取得します。次に '
                '<code>IRP_MJ_CREATE</code> 型の I/O '
                '要求パケット（IRP）と、開こうとしているファイル名を格納するファイルオブジェクトを作成します。ボリュームデバイスオブジェクトの VPB '
                'をたどってマウント済みのファイルシステムデバイスオブジェクトを探し、<code>IoCallDriver</code> でそのオブジェクトを所有するファイルシステムドライバーに '
                'IRP を渡します。</p>\n'
                '<p>FSD は <code>IRP_MJ_CREATE</code> '
                'を受け取ると、指定されたファイルを検索してアクセス権を検証します。ファイルが存在し、ユーザーに要求された方法でアクセスする権限があれば、成功ステータスを返します。オブジェクトマネージャーは、プロセスのハンドルテーブルにファイルオブジェクトのハンドルを作成します。ハンドルは呼び出し元へ順に返され、最終的にアプリケーションに届きます。</p>',
 'p2-page-651': '<p>アプリケーションには、このハンドルが <code>CreateFile</code> の戻り値として返ります。ファイルシステムが作成要求を失敗として処理した場合、I/O '
                'マネージャーはそのファイルのために作ったファイルオブジェクトを削除します。</p>\n'
                '<p>ここまで、FSD がボリューム上で対象ファイルを探す詳細は省略しました。<code>ReadFile</code> を呼び出した場合も、FSD '
                'とキャッシュマネージャー、ストレージドライバーの処理の多くは、ファイルを開く場合と共通です。<code>ReadFile</code> と '
                '<code>CreateFile</code> はいずれも、対応する I/O マネージャーの関数へシステムコールを通じて要求を渡します。<code>NtReadFile</code> '
                'では名前を検索する必要がなく、オブジェクトマネージャーに、<code>ReadFile</code> '
                'から渡されたハンドルをファイルオブジェクトへのポインターに変換させます。ハンドルを開いた時点で呼び出し元に読み取り権限が付与されていれば、<code>NtReadFile</code> '
                'は <code>IRP_MJ_READ</code> 型の IRP を作り、対象ファイルがあるボリュームの FSD に送ります。その際、ファイルオブジェクトに格納された FSD '
                'のデバイスオブジェクトを取得し、<code>IoCallDriver</code> を呼び出します。I/O マネージャーは、このデバイスオブジェクトから FSD を特定し、IRP '
                'を渡します。</p>\n'
                '<p>図11-23 ドライブ文字の名前解決。</p>\n'
                '<figure><img loading="lazy" width="594" height="678" '
                'src="assets/565a6f19ebee4508494e6c03.webp" alt="ファイルの作成要求（原文の図1）"></figure>',
 'p2-page-652': '<p>ファイルを開くときに <code>CreateFile</code> に <code>FILE_FLAG_NO_BUFFERING</code> '
                'を指定していなければ、読み取りにキャッシュを使えます。FSD は、そのファイルオブジェクトのキャッシュをすでに初期化したか確認します。初期化済みなら、ファイルオブジェクトの '
                '<code>PrivateCacheMap</code> フィールドは、前節で説明したプライベートキャッシュマップを指します。FSD '
                'はファイルオブジェクトに対する最初の読み書きでキャッシュを初期化するため、それ以前の <code>PrivateCacheMap</code> は NULL です。FSD が '
                '<code>CcInitializeCacheMap</code> '
                'を呼ぶと、キャッシュマネージャーはプライベートキャッシュマップを作成します。同じファイルを参照する別のファイルオブジェクトがまだキャッシュを初期化していなければ、共有キャッシュマップとセクションオブジェクトも作成します。</p>\n'
                '<p>キャッシュを使えることを確認したら、FSD は、キャッシュマネージャーの仮想メモリから、要求されたデータをスレッドが <code>ReadFile</code> '
                'に渡したバッファーへコピーします。無効なアプリケーションバッファーに起因するフォールトを捕捉するため、コピーは <code>try/except</code> '
                'ブロック内で行います。ファイルシステムはコピーにキャッシュマネージャーの <code>CcCopyRead</code> '
                'を使い、ファイルオブジェクト、ファイル内のオフセット、長さを渡します。</p>\n'
                '<p><code>CcCopyRead</code> は、ファイルオブジェクトから共有キャッシュマップへのポインターを取得します。共有キャッシュマップは、ファイルの256 KB '
                'ブロックごとに仮想アドレス制御ブロック（VACB）へのポインターを保持します。読み取る範囲の VACB ポインターが NULL なら、<code>CcCopyRead</code> '
                'は VACB を割り当て、キャッシュマネージャーの仮想アドレス空間に256 KB のビューを予約し、<code>MmMapViewInSystemCache</code> '
                'でファイルの該当範囲をビューにマップします。その後、マップ済みのビューから、もともと <code>ReadFile</code> '
                'に渡されたバッファーへデータをコピーします。データが物理メモリになければ、コピー時にページフォールトが発生し、<code>MmAccessFault</code> '
                'が処理します。</p>\n'
                '<p>ページフォールトが発生すると、<code>MmAccessFault</code> は原因となった仮想アドレスを調べ、発生元のプロセスの VAD '
                'ツリーから仮想アドレス記述子（VAD）を探します。VAD ツリーについては第1部第5章を参照してください。この場合、VAD '
                'は読み取り対象のファイルをキャッシュマネージャーがマップしたビューを記述します。<code>MmAccessFault</code> は '
                '<code>MiDispatchFault</code> を呼び、有効な仮想アドレスで発生したフォールトを処理します。<code>MiDispatchFault</code> は '
                'VAD '
                'が指すコントロール領域を取得し、そこから開いているファイルを表すファイルオブジェクトを探します。同じファイルが複数回開かれていれば、プライベートキャッシュマップ内のポインターでつながったファイルオブジェクトの一覧が存在する場合があります。</p>\n'
                '<p><code>MiDispatchFault</code> はファイルオブジェクトを取得すると、I/O マネージャーの <code>IoPageRead</code> を呼んで '
                '<code>IRP_MJ_READ</code> 型の IRP を組み立てます。続いて、ファイルオブジェクトが指すデバイスオブジェクトを所有する FSD に IRP '
                'を送ります。ファイルシステムは、自身が <code>CcCopyRead</code> を通じて要求したデータを読み取るために再び呼び出されますが、今回は IRP が非キャッシュ '
                'I/O とページング I/O としてマークされています。FSD '
                'はこのフラグを見て、対象データがあるディスク上のクラスターを特定し、ファイルが置かれたボリュームのデバイスオブジェクトを所有するボリュームマネージャーに IRP '
                'を送ります。クラスターを特定する方法はファイルシステムによって異なります。FSD '
                'のデバイスオブジェクトでは、ボリュームパラメーターブロック（VPB）フィールドがボリュームのデバイスオブジェクトを指します。</p>\n'
                '<p>メモリマネージャーは、FSD が IRP '
                'の読み取りを完了するのを待って、キャッシュマネージャーに制御を戻します。キャッシュマネージャーは、ページフォールトで中断したコピーを再開します。<code>CcCopyRead</code> '
                'が完了すると、要求されたファイルデータは両マネージャーの協力によって呼び出し元のバッファーにコピーされています。FSD は <code>NtReadFile</code> '
                'を呼び出したスレッドに制御を返します。</p>',
 'p2-page-653': '<p><code>WriteFile</code> の経路も同様です。ただし、システムサービス <code>NtWriteFile</code> は '
                '<code>IRP_MJ_WRITE</code> 型の IRP を生成し、FSD は <code>CcCopyRead</code> の代わりに '
                '<code>CcCopyWrite</code> を呼び出します。<code>CcCopyWrite</code> は <code>CcCopyRead</code> '
                'と同様に、ファイルの対象範囲がキャッシュにマップされていることを確認し、<code>WriteFile</code> に渡されたバッファーの内容をキャッシュへコピーします。</p>\n'
                '<p>ファイルデータがすでにシステムのワーキングセットにある場合、前述の処理は状況によって変わります。データがキャッシュにあれば、<code>CcCopyRead</code> '
                'はページフォールトを起こしません。また、条件によっては <code>NtReadFile</code> と <code>NtWriteFile</code> が、IRP '
                'を直ちに組み立てて送る代わりに、FSD の高速 I/O エントリポイントを呼び出します。条件の例として、読み取る範囲がファイルの先頭4 GB '
                '以内にあること、ファイルがロックされていないこと、読み書きする範囲が現在割り当てられているファイルサイズに収まることが挙げられます。</p>\n'
                '<p>多くの FSD は、高速 I/O の読み取りと書き込みのエントリポイントから、<code>CcFastCopyRead</code> と '
                '<code>CcFastCopyWrite</code> '
                'を呼び出します。これらは標準のコピールーチンの派生で、ファイルデータがファイルシステムキャッシュにマップされていることを確認してからコピーします。その条件を満たさなければ、高速 '
                'I/O は実行できないと返します。その場合、<code>NtReadFile</code> と <code>NtWriteFile</code> は IRP '
                'を生成する経路に切り替えます。詳細は本章の「高速 I/O」を参照してください。</p>\n'
                '<h4>メモリマネージャーの変更済みページライターとマップ済みページライター</h4>\n'
                '<p>メモリマネージャーの変更済みページライターとマップ済みページライターは、定期的に、または利用可能メモリが少なくなったときに起動し、変更済みページをディスク上の保存先へ書き戻します。各スレッドは '
                '<code>IoAsynchronousPageWrite</code> を呼び、<code>IRP_MJ_WRITE</code> 型の IRP '
                'を作成して、ページファイル、またはマップ後に変更されたファイルにページを書き込みます。<code>MiDispatchFault</code> が作る IRP と同じく、これらの '
                'IRP には非キャッシュ I/O とページング I/O のフラグが設定されます。FSD はファイルシステムキャッシュを経由せず、ストレージドライバーへ直接 IRP '
                'を発行して、メモリの内容をディスクに書き込みます。</p>\n'
                '<h4>キャッシュマネージャーの遅延ライター</h4>\n'
                '<p>キャッシュマネージャーの遅延ライターも、キャッシュにマップされたファイルセクションの変更済みビューを定期的に書き戻します。キャッシュマネージャーが '
                '<code>MmFlushSection</code> '
                'を呼ぶと、メモリマネージャーは、指定されたセクション範囲にある変更済みページをディスクに書き込みます。<code>MmFlushSection</code> は '
                '<code>IoSynchronousPageWrite</code> を使って FSD にデータを渡します。</p>\n'
                '<h4>キャッシュマネージャーの先読みスレッド</h4>\n'
                '<p>キャッシュは、プログラムがコードやデータを参照するときの2つの性質、時間的局所性と空間的局所性を利用します。時間的局所性とは、参照したメモリ位置が近いうちに再び参照されやすいことです。空間的局所性とは、あるメモリ位置を参照すると、その近くの位置もまもなく参照されやすいことです。一般にキャッシュは、直近にアクセスされた位置へのアクセスを効率よく高速化しますが、まだアクセスされていない領域を自力で先回りして高速化することはできません。</p>',
 'p2-page-654': '<p>まもなく使われそうなデータをキャッシュに入れるため、キャッシュマネージャーは先読みスレッドと Superfetch の2つの仕組みを利用します。</p>\n'
                '<p>先読みスレッドは、アプリケーション、ドライバー、システムスレッドが明示的に要求する前に、ファイルからデータを読み込もうとします。先読みする量は、そのファイルオブジェクトのプライベートキャッシュマップに保存された読み取り履歴を基に決めます。先読みを実行するときは、必要な範囲をキャッシュへマップし（必要なら '
                'VACB '
                'を割り当て）、マップしたデータにアクセスします。このメモリアクセスで発生したページフォールトをハンドラーが処理し、ページをシステムのワーキングセットに読み込みます。</p>\n'
                '<p>先読みスレッドが扱えるのは、すでに開いているファイルだけです。Windows に追加された Superfetch '
                'は、ファイルが開かれる前にキャッシュに読み込みます。メモリマネージャーはページの使用状況を Superfetch '
                'サービス（<code>%SystemRoot%&#92;System32&#92;Sysmain.dll</code>）に送り、ファイルシステムのミニフィルターはファイル名の解決情報を提供します。Superfetch '
                'は、毎週金曜日の12時に給与計算を行う、毎朝8時に Outlook '
                'を起動するといった、ファイルの利用パターンを見つけようとします。パターンを検出すると、情報をデータベースに格納し、タイマーを設定します。ファイルが使われそうな時刻の直前にタイマーが発火すると、メモリマネージャーは低優先度のディスク '
                'I/O '
                'でファイルを読み込み、低優先度のメモリに配置します。その後ファイルが開かれれば、データはすでにメモリにあり、ディスクから読み込むのを待たずに済みます。開かれなければ、システムがそのメモリを回収します。Superfetch '
                'サービスの内部動作は第1部第5章を参照してください。</p>\n'
                '<h4>メモリマネージャーのページフォールトハンドラー</h4>\n'
                '<p>ページフォールトハンドラーは、明示的なファイル I/O '
                'やキャッシュマネージャーの先読みに加え、アプリケーションがマップ済みファイルのビューにアクセスし、対象のページがまだメモリにない場合にも呼び出されます。メモリマネージャーの '
                '<code>MmAccessFault</code> ハンドラーは、<code>CcCopyRead</code> や <code>CcCopyWrite</code> '
                'がページフォールトを起こした場合と同じ処理を行い、<code>IoPageRead</code> を介して、ファイルを格納するファイルシステムに IRP を送ります。</p>\n'
                '<h4>ファイルシステムフィルタードライバーとミニフィルター</h4>\n'
                '<p>ファイルシステムドライバーの上に重ねるフィルタードライバーを、ファイルシステムフィルタードライバーと呼びます。Windows の I/O モデルは2種類に対応します。</p>\n'
                '<ul><li>従来型のファイルシステムフィルタードライバーは通常、1つ以上のデバイスオブジェクトを作成し、<code>IoAttachDeviceToDeviceStack</code> '
                'API でファイルシステムのデバイスに接続します。キャッシュマネージャーや I/O マネージャーから届くすべての要求を捕捉し、通常の IRP ディスパッチ関数と高速 I/O '
                '経路の両方を実装する必要があります。同期処理、非公開インターフェイス、下位ファイルシステムへの依存などが開発を難しくしていたため、Microsoft '
                'はミニフィルターという専用ドライバーを使う統一フィルターモデルを開発し、従来型を非推奨にしました。DAX ボリュームに対する '
                '<code>IoAttachDeviceToDeviceStack</code> の呼び出しは失敗します。</li></ul>',
 'p2-page-655': '<ul><li>ミニフィルタードライバーは、ファイルシステムフィルターマネージャー（<code>Fltmgr.sys</code>）を利用します。フィルターマネージャー自体は従来型のファイルシステムフィルタードライバーで、ファイルシステムドライバーとキャッシュマネージャーの複雑なやり取りを隠蔽し、フィルターの開発に使う公開インターフェイスを提供します。ミニフィルターは '
                '<code>FltRegisterFilter</code> '
                'で登録し、通常はインスタンスのセットアップルーチンと操作ごとのコールバックを指定します。フィルターマネージャーは、ファイルシステムが管理する有効な各ボリュームデバイスについてセットアップルーチンを呼び出します。ミニフィルターはこのとき、そのボリュームに接続するかどうかを決められます。主要な '
                'IRP '
                '関数コードごとに、操作前（Pre）と操作後（Post）のコールバックを指定できます。ファイルシステムへのアクセスに関係するメモリマネージャーやキャッシュマネージャーの内部処理のうち、一部は疑似操作として同様に扱えます。操作前コールバックはファイルシステムドライバーが '
                'I/O を処理する前に、操作後コールバックは I/O '
                'が完了した後に実行されます。フィルターマネージャーは、ミニフィルターと対応するユーザーモードアプリケーションの間で使える独自の通信機構も提供します。</li></ul>\n'
                '<p>ファイルシステムへの要求をすべて観測し、必要に応じて変更や完了ができるため、リモートファイルのレプリケーション、暗号化、効率的なバックアップ、ライセンス管理などに応用できます。マルウェア対策製品には通常、アプリケーションによるファイルのオープンや変更を捕捉するミニフィルターが少なくとも1つ含まれます。たとえば、スキャナーは対象のファイルシステムドライバーへ '
                'IRP を渡す前に、開こうとしているファイルを調べます。問題なければ IRP '
                'を渡し、感染していればファイルを隔離または駆除します。駆除できない場合は、マルウェアが動作しないよう、ドライバーが要求を失敗として完了します。通常はアクセス拒否エラーを返します。</p>\n'
                '<p>従来型のフィルタードライバーの構造については第1部第6章「I/O システム」、ミニフィルターの詳細については <a '
                'href="https://learn.microsoft.com/windows-hardware/drivers/ifs/file-system-minifilter-drivers">Microsoft '
                'のファイルシステムミニフィルタードライバーの解説</a>を参照してください。</p>\n'
                '<h4>データスキャン用セクション</h4>\n'
                '<p>Windows 8.1 '
                '以降、フィルターマネージャーはファイルシステムドライバーと連携し、マルウェア対策製品が使えるデータスキャン用セクションオブジェクトを提供します。このオブジェクトは第1部第5章で説明した標準のセクションオブジェクトに似ていますが、次の点が異なります。</p>\n'
                '<ul>\n'
                '<li>データスキャン用セクションは、ミニフィルターで <code>IRP_MJ_CREATE</code> '
                'を扱うコールバックから作成できます。フィルターマネージャーは、アプリケーションがファイルを開くか作成するときに、このコールバックを呼び出します。スキャナーはセクションを作成し、コールバックを完了する前にスキャンを開始できます。</li>\n'
                '<li>作成用 API の <code>FltCreateSectionForDataScan</code> は <code>FILE_OBJECT</code> '
                'へのポインターを受け取ります。そのため、呼び出し元がファイルハンドルを用意する必要はありません。この時点では通常、ファイルハンドルはまだ存在しません。<code>FltCreateFile</code> '
                'で別途作成すると、ファイル作成 IRP が追加で発行され、下位のファイルシステムフィルターが再帰的に呼ばれます。新しい API '
                'はその追加の呼び出しを発生させないため、処理が大幅に速くなります。</li>\n'
                '</ul>',
 'p2-page-656': '<p>データスキャン用セクションは、従来の API '
                'を使って通常のセクションと同様にマップできます。これにより、マルウェア対策製品はスキャンエンジンをユーザーモードのアプリケーションとしても、カーネルモードのドライバー内にも実装できます。セクションをマップしたときもミニフィルターに '
                '<code>IRP_MJ_READ</code> イベントが発生しますが、ミニフィルターで読み取りコールバックを登録する必要はありません。</p>\n'
                '<h4>名前付きパイプとメールスロットのフィルタリング</h4>\n'
                '<p>ユーザーアプリケーションのプロセスは、ほかのプロセス、カーネルドライバー、リモートアプリケーションと通信するときに、OS の機能を使えます。古くから使われている代表例は、ほかの '
                'OS '
                'にも移植しやすい名前付きパイプとメールスロットです。名前付きパイプは、パイプサーバーと1つ以上のクライアントをつなぐ、名前の付いた通信チャネルです。すべてのインスタンスはパイプ名を共有しますが、インスタンスごとに独自のバッファーとハンドルを持ち、クライアントとサーバーの間に独立した通信経路を提供します。名前付きパイプを実装するのは、NPFS '
                'ファイルシステムドライバー（<code>Npfs.sys</code>）です。</p>\n'
                '<p>メールスロットは、サーバーと1つ以上のクライアントをつなぐ通信チャネルです。サーバーは Win32 API の <code>CreateMailslot</code> '
                'でメールスロットを作るプロセスで、クライアントから送られた短いメッセージの読み取りだけを行います。リモートコンピューター間では、メッセージは最大424バイトです。クライアントは標準の '
                '<code>CreateFile</code> API でメールスロットに接続し、<code>WriteFile</code> '
                'でメッセージを送ります。メールスロットは一般に、ドメイン内でメッセージを一斉配信するために使います。ドメイン内で複数のサーバープロセスが同じ名前のメールスロットを作ると、その名前を宛先としてドメインに送ったメッセージをすべての参加プロセスが受信します。メールスロットを実装するのは、メールスロットファイルシステムドライバー '
                '<code>Msfs.sys</code> です。</p>\n'
                '<p>メールスロットと NPFS '
                'の両ドライバーは、簡素なファイルシステムを実装します。ファイルとディレクトリからなる名前空間を管理し、アクセス制御のほか、オープン、クローズ、読み取り、書き込みなどをサポートします。両ドライバーの実装の詳細は本章の範囲外です。</p>\n'
                '<p>Windows 8 以降、フィルターマネージャーはメールスロットと名前付きパイプに対応しています。登録時に '
                '<code>FLTFL_REGISTRATION_SUPPORT_NPFS_MSFS</code> を指定すると、ミニフィルターは論理上のボリューム '
                '<code>&#92;Device&#92;NamedPipe</code> と <code>&#92;Device&#92;Mailslot</code> '
                'に接続できます。これにより、ローカルとリモートのプロセス間や、ユーザーアプリケーションとカーネルドライバー間のパイプおよびメールスロットの I/O '
                'を捕捉・変更できます。また、<code>FltCreateNamedPipeFile</code> または <code>FltCreateMailslotFile</code> '
                'を使えば、再帰的なイベントを発生させずに、パイプやメールスロットを開くか作成できます。</p>\n'
                '<aside><p>名前付きパイプとメールスロットのファイルシステムドライバーが NTFS や ReFS '
                'より簡素な理由の1つは、キャッシュマネージャーとの連携が少ないことです。名前付きパイプは高速 I/O '
                'の経路を実装しますが、キャッシュ読み取りや遅延書き込みはサポートしません。メールスロットはキャッシュマネージャーを使いません。</p></aside>',
 'p2-page-657': '<h4>再解析ポイントの動作を制御する</h4>\n'
                '<p>NTFS は、アプリケーションやシステムが定義する最大16 KB '
                'の再解析データを個々のファイルに関連付ける、再解析ポイントをサポートします。再解析ポイントは本章の後半でも扱います。ボリュームマウントポイントやシンボリックリンクなど、一部の再解析ポイントには、目印となる元のファイルまたは空のディレクトリと、同じボリュームまたは別のボリューム上にある対象とのリンクが含まれます。NTFS '
                'ドライバーはパスの途中で再解析ポイントに遭遇すると、デバイススタックの上位ドライバーにステータスを返します。上位ドライバーはフィルタードライバーの場合もあり、再解析データの内容を調べます。シンボリックリンクなら、対象のボリュームデバイスへ新たに '
                'I/O を発行します。</p>\n'
                '<p>この処理はフィルタードライバーにとって複雑です。ミニフィルターは <code>STATUS_REPARSE</code> '
                'を捕捉し、<code>FltCreateFileEx2</code> API で再解析ポイントを開き直せます。この API '
                'は追加作成パラメーター（ECP）のリストを受け取ります。ECP '
                'はミニフィルターのコンテキストで、対象ファイルを開く、または作成する際の動作を細かく指定します。フィルターマネージャーは複数の ECP に対応し、各 ECP は GUID '
                'で一意に識別されます。ECP とそのリストを扱う公開 API も複数あります。通常、ミニフィルターは '
                '<code>FltAllocateExtraCreateParameter</code> で ECP '
                'を割り当てて値を設定し、<code>FltInsertExtraCreateParameter</code> でリストに追加してから、フィルターマネージャーの I/O API '
                'を呼び出します。</p>\n'
                '<p>追加作成パラメーター <code>FLT_CREATEFILE_TARGET</code> '
                'に所定のフラグを指定すると、フィルターマネージャーがボリュームをまたぐファイル作成を自動で処理します。ミニフィルターが個別に転送先を解決する必要はありません。</p>\n'
                '<p>コンテナーの分離をサポートするため、空でないディレクトリにも再解析ポイントを設定でき、そのようなディレクトリを含むパスに新しいファイルを作成できます。空でないディレクトリに対する既定の処理は、その再解析ポイントが完全パスの最後の要素かどうかによって変わります。最後の要素なら、空のディレクトリの場合と同じく '
                '<code>STATUS_REPARSE</code> を返します。途中の要素なら、残りのパスの探索を続けます。</p>\n'
                '<p>フィルターマネージャーは、この種類の再解析ポイントを別の ECP である <code>TYPE_OPEN_REPARSE</code> で扱います。この ECP '
                'の各記述子（<code>OPEN_REPARSE_LIST_ENTRY</code>）は、再解析タグでポイントの種類を指定し、パスの解析中にその種類を見つけたときに適用する処理を指定します。ミニフィルターは記述子リストを初期化した後、次のいずれかの方法で動作を適用できます。</p>\n'
                '<ul>\n'
                '<li><code>FltCreateFileEx2</code> で、パスのいずれかの要素に再解析ポイントを含むファイルを開くか作成します。この手順は '
                '<code>FLT_CREATEFILE_TARGET</code> ECP を使う場合と同様です。</li>\n'
                '<li>作成前コールバックが捕捉するすべてのファイルに、新しい再解析動作を適用します。作成前コールバックで、実際にファイルが作成される前に '
                '<code>FltAddOpenReparseEntry</code> と <code>FltRemoveOpenReparseEntry</code> '
                'を使って、対象ファイルの再解析動作を設定できます。Windows '
                'のコンテナー分離ミニフィルタードライバー（<code>Wcifs.sys</code>）はこの方法を使います。</li>\n'
                '</ul>',
 'p2-page-658': '<h4>Process Monitor</h4>\n'
                '<p>本書で繰り返し使ってきた Sysinternals のシステム活動監視ツール Process '
                'Monitor（Procmon）は、アプリケーションとファイルシステムドライバーの間を流れる IRP を変更せずに観測するミニフィルターの一例です。</p>\n'
                '<p>システム起動後に初めて実行すると、Process Monitor は <code>Procmon.exe</code> '
                'のリソースとして格納されたファイルシステムミニフィルタードライバーを取り出し、メモリに読み込んだ後、ディスクからドライバーイメージを削除します。起動時の監視を継続するよう設定した場合は削除しません。画面から、ドライブ文字の付いたローカルボリューム、ネットワーク共有、名前付きパイプ、メールスロットのファイルシステム活動を監視できます。ボリュームの監視開始を指示すると、ドライバーはフィルターマネージャーにコールバックを登録します。フィルターマネージャーは、そのボリュームにマウントされたファイルシステムのデバイスオブジェクトに接続されています。接続後、I/O '
                'マネージャーは下位のデバイスオブジェクト宛ての IRP を、接続先デバイスを所有するフィルターマネージャーへ転送します。フィルターマネージャーは、登録済みのミニフィルターである '
                'Process Monitor にイベントを通知します。</p>\n'
                '<p>Process Monitor のドライバーは IRP '
                'を捕捉すると、対象ファイル名、読み書きの長さやオフセットなど、コマンド固有のパラメーターを非ページカーネルバッファーに記録します。GUI '
                'プログラムは500ミリ秒ごとにインターフェイス用のデバイスオブジェクトへ IRP '
                'を送り、最新の活動を含むバッファーのコピーを取得して、結果をウィンドウに表示します。発生したファイル操作をその場で確認できるので、ファイルシステムに関係するシステムやアプリケーションの障害調査に使えます。システム上で初めて実行するには、ドライバーの読み込みとデバッグの特権が必要です。読み込んだドライバーはメモリに常駐するため、それ以降の実行にはデバッグ特権だけが必要です。</p>\n'
                '<p>Process Monitor は基本モードで起動し、障害調査でよく使うファイルシステムの活動を表示します。基本モードでは次の操作は表示しません。</p>\n'
                '<ul>\n'
                '<li>NTFS のメタデータファイルに対する I/O</li>\n'
                '<li>ページファイルに対する I/O</li>\n'
                '<li>System プロセスによる I/O</li>\n'
                '<li>Process Monitor プロセス自身による I/O</li>\n'
                '</ul>\n'
                '<p>基本モードでは、操作を表す IRP の種類の代わりに、読みやすい操作名を表示します。たとえば <code>IRP_MJ_WRITE</code> と '
                '<code>FASTIO_WRITE</code> はどちらも <code>WriteFile</code> と表示されます。<code>IRP_MJ_CREATE</code> '
                'は、既存ファイルを開く場合は <code>Open</code>、新規ファイルを作成する場合は <code>Create</code> と表示されます。</p>',
 'p2-page-659': '<h4>実験\u3000Process Monitor のミニフィルタードライバーを確認する</h4>\n'
                '<p>読み込まれているミニフィルタードライバーを確認するには、管理者としてコマンドプロンプトを開き、フィルターマネージャーの制御プログラム '
                '<code>%SystemRoot%&#92;System32&#92;Fltmc.exe</code> を実行します。次に Process '
                'Monitor（<code>Procmon.exe</code>）を起動して、もう一度 <code>Fltmc</code> を実行します。Process Monitor '
                'のフィルタードライバー（この例では <code>PROCMON20</code>）が読み込まれ、<code>Instances</code> '
                '列に0以外の値が表示されます。Process Monitor を終了して再度 <code>Fltmc</code> '
                'を実行すると、ドライバーは読み込まれたままですが、インスタンス数は0になります。</p>\n'
                '<h3>NT ファイルシステム（NTFS）</h3>\n'
                '<p>ここからは、設計時の要件を出発点に、NTFS '
                'の内部構造を見ていきます。ディスク上のデータ構造に続いて、障害からの回復、階層化ボリューム、暗号化ファイルシステム（EFS）など、NTFS '
                'が提供する高度な機能を説明します。</p>\n'
                '<h4>エンタープライズ向けファイルシステムの要件</h4>\n'
                '<p>NTFS '
                'は当初から、エンタープライズ向けファイルシステムに求められる機能を備えるよう設計されました。予期しない停止やクラッシュによるデータの損失を抑えるには、メタデータの整合性を常に保証する必要があります。機密データへの不正アクセスを防ぐためには、セキュリティモデルをファイルシステムに組み込む必要があります。また、ユーザーデータを保護するため、ハードウェアによる冗長化より低コストな選択肢として、ソフトウェアによる冗長化にも対応する必要があります。以下では、NTFS '
                'がそれぞれの要件をどう満たすかを説明します。</p>\n'
                '<figure><img loading="lazy" width="642" height="396" '
                'src="assets/1a326a43b4530a91528f2e99.webp" alt="Process Monitor のミニフィルター（原文の図1）"></figure>',
 'p2-page-660': '<h4>回復可能性</h4>\n'
                '<p>データを確実に保存し、アクセスできるように、NTFS '
                'はアトミックなトランザクションに基づくファイルシステムの回復機能を備えています。この手法では、データベースを更新する途中でシステム障害が発生しても、データベースの正しさと整合性が保たれます。トランザクションとは、ここではファイルシステムのデータやボリュームのディレクトリ構造を変更する '
                'I/O '
                '操作です。トランザクションを構成する個々のディスク更新は、全体として不可分に実行します。開始したらすべての更新を完了させます。障害で中断した場合は、完了した部分を取り消します。この操作をロールバックと呼び、トランザクションが発生する前の既知の整合した状態にデータベースを戻します。</p>\n'
                '<p>NTFS は、ディレクトリ構造の変更、ファイルの拡張、新規ファイル用の領域の割り当てなど、ボリューム構造を変える I/O '
                '操作をアトミックなトランザクションとして扱います。全体を完了させるか、途中でシステム障害が発生した場合はロールバックすることを保証します。詳細は後述の「NTFS '
                'の回復機能」を参照してください。重要なファイルシステム情報は冗長に保存するため、ディスク上のセクターが故障しても、NTFS はボリュームの重要なデータにアクセスできます。</p>\n'
                '<h4>セキュリティ</h4>\n'
                '<p>NTFS のセキュリティは Windows のオブジェクトモデルに基づき、権限のないユーザーによるファイルやディレクトリへのアクセスを防ぎます。Windows '
                'のセキュリティは第1部第7章で説明しています。開いているファイルはファイルオブジェクトで表され、そのセキュリティ記述子は、ディスク上の隠しメタファイル '
                '<code>$Secure</code> にある <code>$SDS</code>（Security Descriptor '
                'Stream）に保存されます。ファイルオブジェクトを含め、プロセスがオブジェクトのハンドルを開く前に、Windows '
                'のセキュリティ機構が必要な権限を確認します。ユーザーにログオンとパスワードによる本人確認を求め、セキュリティ記述子でアクセス権を検査することで、システム管理者またはファイルの所有者から権限を与えられたプロセスだけが、ファイルにアクセスできます。詳細は第1部第7章「セキュリティ記述子とアクセス制御」を参照してください。</p>\n'
                '<h4>データの冗長性と耐障害性</h4>\n'
                '<p>ファイルシステムの回復に加え、停電や重大なディスク障害からユーザーデータも保護する必要がある環境があります。NTFS '
                'の回復機能でボリュームのファイルシステムには引き続きアクセスできますが、ユーザーファイルが完全に回復する保証はありません。ファイルデータの損失を許容できないアプリケーションは、データの冗長化で保護します。</p>\n'
                '<p>ユーザーファイルの冗長化は、ディスクの耐障害性を提供する Windows の階層化ドライバーで実装します。NTFS '
                'はボリュームマネージャーと通信し、ボリュームマネージャーがディスクドライバーを使ってデータを書き込みます。ボリュームマネージャーは、1台のディスクのデータを別のディスクへ複製し、必要なときに冗長コピーからデータを取り出せるようにします。この仕組みは一般にミラーリングと呼ばれます。</p>',
 'p2-page-661': '<p>前ページのミラーリングは RAID 1 '
                'とも呼ばれます。ボリュームマネージャーは、3台以上のディスクにデータを分散して書き込むストライピングも行えます。この構成では、ディスク1台分の容量をパリティ情報の保持に使います。1台のディスクのデータを失ったり、アクセスできなくなったりしても、ドライバーは排他的論理和（XOR）でそのディスクの内容を復元できます。この方式を '
                'RAID 5 と呼びます。</p>\n'
                '<p>Windows 7 では、Windows の階層化ドライバーによる NTFS のデータ冗長化をダイナミックディスクが提供していました。Windows 8.1 '
                'は、ストレージハードウェアを仮想化する記憶域スペース（Storage '
                'Spaces）を導入し、ダイナミックディスクのさまざまな制約を解消しました。記憶域スペースは、冗長性と耐障害性を備えた仮想ディスクを作成できます。ボリュームマネージャーは仮想ディスクと物理ディスクを同じ方法で扱うため、ユーザーモードのコンポーネントからは両者の違いが見えません。NTFS '
                'ドライバーは記憶域スペースと協調し、階層化されたディスクや、仮想ディスクの RAID '
                '構成をサポートします。記憶域スペースと記憶域スペースダイレクトについては、本章の後半で説明します。</p>\n'
                '<h4>NTFS の高度な機能</h4>\n'
                '<p>NTFS '
                'は、重要な業務システムに求められる回復可能性、セキュリティ、信頼性、効率性に加え、幅広いアプリケーションを支える次の機能を備えています。一部はアプリケーションが利用できる API '
                'で公開され、ほかは内部機能です。</p>\n'
                '<ul>\n'
                '<li>複数のデータストリーム</li>\n'
                '<li>Unicode の名前</li>\n'
                '<li>汎用インデックス機能</li>\n'
                '<li>不良クラスターの動的な再マップ</li>\n'
                '<li>ハードリンク</li>\n'
                '<li>シンボリックリンク（ソフトリンク）とジャンクション</li>\n'
                '<li>圧縮とスパースファイル</li>\n'
                '<li>変更のログ記録</li>\n'
                '<li>ユーザーごとのボリュームクォータ</li>\n'
                '<li>リンクの追跡</li>\n'
                '<li>暗号化</li>\n'
                '<li>POSIX のサポート</li>\n'
                '<li>デフラグ</li>\n'
                '<li>読み取り専用のサポートと動的なパーティション管理</li>\n'
                '<li>階層化ボリュームのサポート</li>\n'
                '</ul>\n'
                '<p>以下では、これらの機能の概要を説明します。</p>',
 'p2-page-662': '<h4>複数のデータストリーム</h4>\n'
                '<p>NTFS は、ファイル名、所有者、タイムスタンプ、内容など、ファイルに関連する情報の各単位を、ファイル属性（NTFS '
                'オブジェクトの属性）として実装します。各属性は1つのストリーム、つまり単純なバイト列で構成されます。この共通の構造により、ファイルに属性とストリームを追加しやすくなっています。ファイルのデータ自体も属性の1つなので、NTFS '
                'のファイルやディレクトリは複数のデータストリームを持てます。</p>\n'
                '<p>NTFS '
                'のファイルには、名前のない既定のデータストリームが1つあります。アプリケーションは、名前付きデータストリームを追加し、その名前を指定してアクセスできます。Windows の I/O '
                'API はファイル名を文字列の引数として受け取ります。API '
                'を変更せずにストリーム名を指定できるよう、ファイル名の後にコロンとストリーム名を付けます。コロンは予約文字なので、次の例のようにファイル名とストリーム名の区切りとして使えます。</p>\n'
                '<pre><code>myfile.dat:stream2</code></pre>\n'
                '<p>ストリームごとに、割り当てサイズ（予約済みのディスク領域）、実際のサイズ（呼び出し元が使用したバイト数）、有効データ長（初期化済みの範囲）があります。また、各ストリームは独自のファイルロックを持ち、バイト範囲をロックしながら並行アクセスを許可できます。</p>\n'
                '<p>複数のデータストリームを使う Windows コンポーネントの1つが Attachment Execution Service です。Edge や Outlook '
                'などのアプリケーションが、インターネット上の添付ファイルを保存するために Windows の標準 API '
                'を使うと、このサービスが呼び出されます。ファイルのダウンロード元がマイコンピューター、イントラネット、信頼されていないゾーンなどのどれに当たるかに応じて、エクスプローラーは信頼できない場所から取得した可能性があると警告したり、アクセスを遮断したりします。図11-24は、Sysinternals '
                'のサイトからダウンロードした Process Explorer を実行するときに表示されるダイアログの例です。ダウンロード元のゾーンを保存するデータストリームは '
                '<code>Zone.Identifier</code> といい、一般に Mark of the Web と呼ばれます。</p>\n'
                '<aside><p>ダイアログの「このファイルを開く前に常に確認する」のチェックを外すと、そのファイルからゾーン識別子のデータストリームが削除されます。</p></aside>\n'
                '<p>図11-24 インターネットからダウンロードしたファイルに対するセキュリティ警告。</p>\n'
                '<figure><img loading="lazy" width="298" height="220" '
                'src="assets/f6838b523c810cf59a2d5a19.webp" alt="複数のデータストリーム（原文の図1）"></figure>',
 'p2-page-663': '<p>ほかのアプリケーションも複数のデータストリームを利用できます。たとえば、バックアップツールは、ファイルに追加のストリームを作り、バックアップ固有のタイムスタンプを保存できます。アーカイブツールは、指定日より古いファイルや、一定期間アクセスがないファイルをオフラインストレージに移す階層型ストレージを実装できます。その場合、ファイルをオフラインストレージにコピーし、元のファイルの既定データストリームを長さ0にして、保存先を記録したストリームを追加できます。</p>\n'
                '<h4>実験\u3000データストリームを確認する</h4>\n'
                '<p>Windows アプリケーションの大半は名前付きの代替データストリームを扱うように設計されていませんが、<code>echo</code> と '
                '<code>more</code> では扱えます。次の例では、<code>echo</code> でファイル <code>test</code> に名前付きストリーム '
                '<code>stream</code> を作成し、<code>more</code> で内容を表示します。</p>\n'
                '<pre><code>c:&#92;Test&gt;echo Hello from a named stream! &gt; test:stream\n'
                'c:&#92;Test&gt;more &lt; test:stream\n'
                'Hello from a named stream!\n'
                'c:&#92;Test&gt;</code></pre>\n'
                '<p>ディレクトリを一覧表示しても、<code>test</code> のファイルサイズには代替ストリームのデータが含まれません。NTFS '
                'は、ディレクトリ一覧などのファイル情報の照会に対して、名前のないデータストリームのサイズだけを返すためです。</p>\n'
                '<pre><code>c:&#92;Test&gt;dir test\n'
                ' ドライブ C のボリューム ラベルは OS です\n'
                ' ボリューム シリアル番号は F080-620F です\n'
                '\n'
                ' c:&#92;Test のディレクトリ\n'
                '\n'
                '12/07/2018  05:33 PM                 0 test\n'
                '               1 個のファイル                   0 バイト\n'
                '               0 個のディレクトリ  18,083,577,856 バイトの空き領域\n'
                'c:&#92;Test&gt;</code></pre>\n'
                '<p>代替データストリームを持つファイルやディレクトリは、Sysinternals の Streams ツールや、<code>dir</code> の <code>/r</code> '
                'オプションで確認できます。次は Streams の出力例です。</p>\n'
                '<pre><code>c:&#92;Test&gt;streams test\n'
                '\n'
                'streams v1.60 - NTFS の代替ストリームを表示\n'
                'Copyright (C) 2005-2016 Mark Russinovich\n'
                'Sysinternals - www.sysinternals.com\n'
                '\n'
                'c:&#92;Test&#92;test:\n'
                '   :stream:$DATA       29</code></pre>',
 'p2-page-664': '<h4>Unicode の名前</h4>\n'
                '<p>Windows のほかの部分と同様に、NTFS はファイル、ディレクトリ、ボリュームの名前を、16ビットのコード単位を使う '
                'Unicode（UTF-16）で保存します。Unicode '
                'は世界の主要な言語の文字に加え、絵文字にも固有の表現を割り当てるため、国や地域が異なる環境間でデータをやり取りしやすくなります。従来の2バイト文字コード方式では、文字によって8ビットまたは16ビットで表し、利用できる文字は読み込んだコードページによって決まりました。Unicode '
                'の文字表現は、どのコードページを読み込んだかに依存しません。パスを構成する個々のディレクトリ名とファイル名は最大255文字で、Unicode '
                'の文字、名前の途中にある空白、複数のピリオドを含められます。</p>\n'
                '<h4>汎用インデックス機能</h4>\n'
                '<p>NTFS '
                'では、B木を使ってボリューム上の任意のファイル属性にインデックスを付けられるように設計されています。任意の属性にインデックスを作成する機能は、ユーザー向けには公開されていません。ファイルシステムはこの構造を使って、特定のディレクトリ内のすべてのファイルなど、条件に合うファイルを効率よく見つけられます。FAT '
                'はファイル名を管理しますが、名前順に並べないため、大きなディレクトリでは検索が遅くなります。</p>\n'
                '<p>NTFS '
                'の複数の機能が汎用インデックスを利用します。一例は、セキュリティ記述子を集約する機能です。ボリューム上のファイルとディレクトリのセキュリティ記述子を1つの内部ストリームにまとめ、重複を除き、NTFS '
                'が定義する内部セキュリティ識別子でインデックスを付けます。これらの機能での使い方は、後述の「NTFS のディスク上の構造」を参照してください。</p>\n'
                '<h4>不良クラスターの動的な再マップ</h4>\n'
                '<p>通常は、プログラムがディスクの不良セクターを読み取ろうとすると、読み取りが失敗し、そのクラスターにあるデータにアクセスできなくなります。耐障害性を備えた NTFS '
                'ボリュームでは、冗長化を担当する Windows のボリュームマネージャーまたは記憶域スペースが、不良セクターにあったデータの正常なコピーを取得し、セクターの障害を NTFS '
                'に通知します。NTFS は、不良セクターを含むクラスターの代わりに新しいクラスターを割り当て、正常なデータをそこにコピーします。不良クラスターは、ボリュームの隠しメタデータファイル '
                '<code>$BadClus</code> にある一覧へ追加し、以後は使用しません。</p>\n'
                '<p>このデータ回復と動的な再マップは、ファイルサーバー、耐障害性が必要なシステム、データの損失を許容できないアプリケーションで特に役立ちます。起動の早い段階など、セクターの障害時にボリュームマネージャーや記憶域スペースを使えない場合も、NTFS '
                'はクラスターを置き換え、不良クラスターを再利用しません。ただし、不良セクターにあったデータは回復できません。</p>',
 'p2-page-665': '<h4>ハードリンク</h4>\n'
                '<p>ハードリンクを使うと、複数のパスで同じファイルを参照できます。ディレクトリにはハードリンクを作れません。たとえば、既存の '
                '<code>C:&#92;Users&#92;Administrator&#92;Documents&#92;Spec.doc</code> に対するハードリンクを '
                '<code>C:&#92;Documents&#92;Spec.doc</code> '
                'として作ると、どちらのパスもディスク上の同じファイルを指します。どちらからでもファイルを変更できます。プログラムは Windows の '
                '<code>CreateHardLink</code> 関数でハードリンクを作成できます。</p>\n'
                '<p>NTFS はファイル本体への参照数を管理します。ハードリンクを作るたびに、同じデータを参照するファイル名が1つ増えます。そのため、元の名前（ここでは '
                '<code>C:&#92;Users&#92;Administrator&#92;Documents&#92;Spec.doc</code>）を削除しても、別のハードリンク（<code>C:&#92;Documents&#92;Spec.doc</code>）は残り、同じデータを指します。ハードリンクは、ファイルレコード番号で表されるディスク上のローカル参照なので、同じボリューム内でのみ作成できます。</p>\n'
                '<h4>実験\u3000ハードリンクを作成する</h4>\n'
                '<p>ハードリンクは <code>fsutil hardlink create</code> でも、<code>mklink</code> の <code>/H</code> '
                'オプションでも作成できます。ここでは、後でシンボリックリンクを作るときにも使う <code>mklink</code> を使います。まず <code>test.txt</code> '
                'を作成して文字列を書き込みます。</p>\n'
                '<pre><code>C:&#92;&gt;echo Hello from a Hard Link &gt; test.txt</code></pre>\n'
                '<p>次に、<code>hard.txt</code> というハードリンクを作成します。</p>\n'
                '<pre><code>C:&#92;&gt;mklink /H hard.txt test.txt\n'
                'hard.txt &lt;&lt;===&gt;&gt; test.txt のハードリンクが作成されました</code></pre>\n'
                '<p>ディレクトリを一覧表示すると、両方の名前で同じファイルを参照していることがわかります。作成日時、アクセス許可、ファイルサイズは同じで、ファイル名だけが異なります。</p>\n'
                '<pre><code>C:&#92;&gt;dir *.txt\n'
                ' ドライブ C のボリューム ラベルは OS です\n'
                ' ボリューム シリアル番号は F080-620F です\n'
                '\n'
                ' C:&#92; のディレクトリ\n'
                '\n'
                '12/07/2018  05:46 PM                26 hard.txt\n'
                '12/07/2018  05:46 PM                26 test.txt\n'
                '               2 個のファイル                  52 バイト\n'
                '               0 個のディレクトリ  15,150,333,952 バイトの空き領域</code></pre>\n'
                '<h4>シンボリックリンク（ソフトリンク）とジャンクション</h4>\n'
                '<p>NTFS '
                'は、ファイルに別名を与える方法として、シンボリックリンク（ソフトリンク）もサポートします。リンクには、アクセス時に解釈する相対パスまたは絶対パスを格納します。別のローカルボリュームや、別のコンピューター上の共有を指すこともできます。シンボリックリンクを作っても、参照先ファイルの参照数は増えません。参照先を削除するとデータは失われ、リンクは存在しないファイルを指したまま残ります。シンボリックリンクはファイルに加えて、ディレクトリも指すことができます。</p>',
 'p2-page-666': '<p>たとえば <code>C:&#92;Drivers</code> が <code>%SystemRoot%&#92;System32&#92;Drivers</code> '
                'を指すディレクトリのシンボリックリンクなら、アプリケーションが <code>C:&#92;Drivers&#92;Ntfs.sys</code> を読み取ると、実際には '
                '<code>%SystemRoot%&#92;System32&#92;Drivers&#92;Ntfs.sys</code> '
                'が読み取られます。ディレクトリのシンボリックリンクを使うと、元のツリーの構造や内容を変えずに、深い階層にあるディレクトリへ短いパスでアクセスできます。この例では、ボリュームのルートに '
                '<code>Drivers</code> へのリンクを置き、<code>Ntfs.sys</code> '
                'に至るディレクトリの階層を3段から1段に減らしています。ファイルのシンボリックリンクも同様に動作します。エクスプローラーが管理する <code>.lnk</code> '
                'ショートカットに似ていますが、ファイルシステムが直接処理します。シンボリックリンクは <code>mklink</code> を <code>/H</code> '
                'なしで使うか、<code>CreateSymbolicLink</code> を呼び出して作成します。</p>\n'
                '<p>一部の従来型アプリケーションは、特にマシンをまたぐ場合にシンボリックリンクを安全に扱えないことがあります。このため、リンクの作成には通常、管理者に付与される '
                '<code>SeCreateSymbolicLink</code> 特権が必要です。Windows 10 '
                '以降で開発者モードが有効なら、<code>CreateSymbolicLink</code> に '
                '<code>SYMBOLIC_LINK_FLAG_ALLOW_UNPRIVILEGED_CREATE</code> '
                'を指定でき、標準ユーザーもコマンドプロンプトからリンクを作成できます。ファイルシステムには、リンクをたどる条件を制御する <code>SymLinkEvaluation</code> '
                'オプションもあり、次のコマンドで設定します。</p>\n'
                '<pre><code>fsutil behavior set SymLinkEvaluation</code></pre>\n'
                '<p>Windows の既定のポリシーでは、ローカルにあるリンクからローカルまたはリモートの参照先にアクセスできます。リモートにあるリンクからの参照は、既定で無効です。</p>\n'
                '<pre><code>D:&#92;&gt;fsutil behavior query SymLinkEvaluation\n'
                'ローカルからローカルへのシンボリックリンクは有効です。\n'
                'ローカルからリモートへのシンボリックリンクは有効です。\n'
                'リモートからローカルへのシンボリックリンクは無効です。\n'
                'リモートからリモートへのシンボリックリンクは無効です。</code></pre>\n'
                '<p>シンボリックリンクは、NTFS '
                'の再解析ポイントとして実装されています。再解析ポイントは、再解析データと呼ばれるデータブロックを関連付けたファイルまたはディレクトリです。このデータには状態や場所など、ユーザーが定義した情報が含まれ、データを作成したアプリケーション、ファイルシステムフィルタードライバー、I/O '
                'マネージャーが読み取れます。NTFS がファイルやディレクトリを探す途中で再解析ポイントを見つけると、<code>STATUS_REPARSE</code> '
                'を返します。これを受けて、ボリュームに接続されたフィルタードライバーと I/O '
                'マネージャーが再解析データを調べます。再解析ポイントの種類は固有の再解析タグで識別できるため、処理を担当するコンポーネントは、再解析データの中身を確認する前に、自分が扱う種類かどうかを判断できます。タグを所有するフィルタードライバーまたは '
                'I/O マネージャーは、次のような処理を選べます。</p>\n'
                '<ul>\n'
                '<li>再解析ポイントを通るファイル I/O のパス名を変更し、変更後のパスで I/O '
                'を再発行します。後述のジャンクションでは、この方法でディレクトリの検索先を切り替えます。</li>\n'
                '<li>ファイルから再解析ポイントを削除して、必要な変更をファイルに加えた後、ファイル I/O を再発行します。</li>\n'
                '</ul>',
 'p2-page-667': '<p>任意の再解析ポイントを作成する専用の Windows 関数はありません。プロセスは <code>DeviceIoControl</code> にファイルシステム制御コード '
                '<code>FSCTL_SET_REPARSE_POINT</code> を指定して作成します。内容の照会には '
                '<code>FSCTL_GET_REPARSE_POINT</code> を使います。再解析ポイントにはファイル属性 '
                '<code>FILE_ATTRIBUTE_REPARSE_POINT</code> が設定されるため、アプリケーションは <code>GetFileAttributes</code> '
                'で確認できます。</p>\n'
                '<p>NTFS がサポートする別の種類の再解析ポイントに、ボリュームマウントポイントとも呼ばれるジャンクションがあります。ジャンクションは従来からある NTFS '
                'の機能で、ディレクトリのシンボリックリンクに近い動作をします。参照先はローカルボリューム上に限られます。ジャンクションを選ぶ利点は、ディレクトリのシンボリックリンクに対応していない古い '
                'Windows でも使えることです。</p>\n'
                '<p>前節で述べたように、新しい Windows '
                'では空でないディレクトリも再解析ポイントとして扱えます。システムの動作は、対象ファイルの完全パスで再解析ポイントがどこにあるかによって変わり、ミニフィルタードライバーから制御できます。フィルターマネージャーと '
                'NTFS、ReFS のドライバーは、公開 API <code>FsRtlIsNonEmptyDirectoryReparsePointAllowed</code> '
                'で、その種類の再解析ポイントを空でないディレクトリに使用できるか確認します。</p>\n'
                '<h4>実験\u3000シンボリックリンクを作成する</h4>\n'
                '<p>同じボリューム上でも、シンボリックリンクとハードリンクの動作には違いがあります。前の実験で作成した <code>test.txt</code> を指すシンボリックリンク '
                '<code>soft.txt</code> を作成します。</p>\n'
                '<pre><code>C:&#92;&gt;mklink soft.txt test.txt\n'
                'soft.txt &lt;&lt;===&gt;&gt; test.txt のシンボリック リンクが作成されました</code></pre>\n'
                '<p>ディレクトリを表示すると、シンボリックリンクにはファイルサイズが表示されず、種類が <code>&lt;SYMLINK&gt;</code> '
                'になっています。作成日時も、参照先とは別にリンク自体が持つ値です。シンボリックリンクには、参照先とは異なるアクセス許可も設定できます。</p>\n'
                '<pre><code>C:&#92;&gt;dir *.txt\n'
                ' ドライブ C のボリューム ラベルは OS です\n'
                ' ボリューム シリアル番号は 38D4-EA71 です\n'
                '\n'
                ' C:&#92; のディレクトリ\n'
                '\n'
                '05/12/2012  11:55 PM                 8 hard.txt\n'
                '05/13/2012  12:28 AM    &lt;SYMLINK&gt;      soft.txt [test.txt]\n'
                '05/12/2012  11:55 PM                 8 test.txt\n'
                '               3 個のファイル                  16 バイト\n'
                '               0 個のディレクトリ  10,636,480,512 バイトの空き領域</code></pre>\n'
                '<p>最後に、元の <code>test.txt</code> '
                'を削除します。ハードリンクとシンボリックリンクは両方とも残ります。ハードリンクからは同じデータを参照できますが、シンボリックリンクの参照先は存在しなくなります。</p>',
 'p2-page-668': '<h4>圧縮とスパースファイル</h4>\n'
                '<p>NTFS はファイルデータの圧縮に対応しています。圧縮と展開は NTFS '
                'が透過的に行うため、アプリケーションを変更する必要はありません。ディレクトリも圧縮対象にでき、そのディレクトリ内に以後作成するファイルは圧縮されます。</p>\n'
                '<p>アプリケーションは <code>DeviceIoControl</code> にファイルシステム制御コード <code>FSCTL_SET_COMPRESSION</code> '
                'を渡して圧縮を設定または解除します。ファイルやディレクトリの圧縮状態を照会するには <code>FSCTL_GET_COMPRESSION</code> '
                'を使います。圧縮したファイルやディレクトリには属性 <code>FILE_ATTRIBUTE_COMPRESSED</code> '
                'が設定されるため、<code>GetFileAttributes</code> でも状態を確認できます。</p>\n'
                '<p>ストレージ使用量を減らす別の仕組みがスパースファイルです。ファイルをスパースにすると、アプリケーションが空と指定した範囲に NTFS '
                'はボリューム上の領域を割り当てません。アプリケーションが空の範囲を読み取ると、NTFS '
                'はゼロで埋めたバッファーを返します。この方式は、リングバッファー方式でログを記録するクライアント・サーバー型のアプリケーションに役立ちます。サーバーがファイルに情報を記録し、クライアントが非同期で読み取る構成では、クライアントが読み終えた情報を保持する必要はありません。ファイルをスパース化しておけば、クライアントは読み終えた範囲を空として指定し、ボリューム上の領域を解放できます。サーバーは、ファイルがボリュームの空き容量を使い切る心配をせずに、新しい情報を末尾へ追加できます。</p>\n'
                '<p>圧縮ファイルと同様に、NTFS はスパースファイルを透過的に管理します。アプリケーションは <code>DeviceIoControl</code> に '
                '<code>FSCTL_SET_SPARSE</code> を指定してスパース属性を設定します。範囲を空にするには '
                '<code>FSCTL_SET_ZERO_DATA</code>、どの範囲に領域が割り当てられているかの照会には '
                '<code>FSCTL_QUERY_ALLOCATED_RANGES</code> を使います。次に説明する NTFS '
                'の変更ジャーナルも、スパースファイルの用途の1つです。</p>\n'
                '<h4>変更のログ記録</h4>\n'
                '<p>さまざまなアプリケーションが、ボリューム上のファイルやディレクトリの変更を監視する必要があります。たとえば自動バックアップでは、初回に完全バックアップを取り、その後はファイルの変更に基づいて増分バックアップを取ります。変更を監視する方法の1つは、ボリュームを走査してファイルとディレクトリの状態を記録し、次の走査で差分を検出することです。ただし、数千件から数万件のファイルがあるシステムでは、特に性能が低下しやすくなります。</p>\n'
                '<p>別の方法は、Windows の <code>FindFirstChangeNotification</code> または '
                '<code>ReadDirectoryChangesW</code> '
                'でディレクトリの変更通知を登録することです。監視対象のディレクトリを指定すると、内容が変わったときに関数が戻ります。ボリューム全体の走査より効率的ですが、アプリケーションを常時動かす必要があります。また、<code>FindFirstChangeNotification</code> '
                'はディレクトリ内で何かが変わったことだけを知らせるため、変更点の特定にはディレクトリを走査する場合があります。<code>ReadDirectoryChangesW</code> '
                'には、FSD が変更情報を書き込むバッファーを渡せます。</p>',
 'p2-page-669': '<p>FSD はバッファーに変更レコードを書き込みます。バッファーがあふれた場合に備え、アプリケーションはディレクトリの走査に切り替えられるようにしておく必要があります。</p>\n'
                '<p>NTFS は、ボリューム全体の走査とディレクトリ変更通知の欠点を補う方法として、変更ジャーナルを提供します。アプリケーションは '
                '<code>DeviceIoControl</code> にファイルシステム制御コード <code>FSCTL_CREATE_USN_JOURNAL</code> を指定し、NTFS '
                'がファイルとディレクトリの変更情報を内部ファイルである変更ジャーナルに記録するよう設定できます。USN は更新シーケンス番号（Update Sequence '
                'Number）の略です。変更ジャーナルは通常、アプリケーションが変更を取りこぼさずに処理できるだけの十分な容量を持ちます。<code>FSCTL_QUERY_USN_JOURNAL</code> '
                'でジャーナルの情報を照会し、<code>FSCTL_READ_USN_JOURNAL</code> で変更レコードを読み取ります。読み取り時には、新しいレコードが利用可能になるまで '
                '<code>DeviceIoControl</code> を待機させることもできます。</p>\n'
                '<h4>ユーザーごとのボリュームクォータ</h4>\n'
                '<p>システム管理者は、共有ストレージボリュームでユーザーごとのディスク使用量を追跡したり、制限したりする必要があります。NTFS '
                'のクォータ管理では、使用量の追跡と上限の適用をユーザーごとに設定し、警告しきい値または上限に達したことを検出できます。警告しきい値を超えた場合は、システムイベントログにイベントを記録できます。ユーザーが上限を超える領域を使おうとしたときも、システムイベントログに記録し、上限超過の原因となるファイル '
                'I/O に「ディスクがいっぱいです」というエラーを返せます。</p>\n'
                '<p>NTFS はファイルやディレクトリに作成者のセキュリティ識別子（SID）を記録し、ユーザーのボリューム使用量を追跡します。SID '
                'は第1部第7章「セキュリティ」で説明しました。クォータに算入されるのは、そのユーザーが所有するファイルやディレクトリの論理サイズです。したがって、上限を超える大きさの空のスパースファイルを作り、後からゼロ以外のデータで埋めても、クォータを回避できません。同様に、50 '
                'KB のファイルを圧縮して10 KB になっても、クォータには50 KB が計上されます。</p>\n'
                '<p>ボリュームのクォータ追跡は既定で無効です。図11-25のボリュームの「プロパティ」にある「クォータ」タブで、有効化、既定の警告しきい値と上限の指定、それらに達したときの '
                'NTFS の動作を設定します。このダイアログから「クォータ エントリ」を開くと、管理者はユーザーごとに異なる上限と動作を指定できます。アプリケーションは '
                '<code>IDiskQuotaControl</code>、<code>IDiskQuotaUser</code>、<code>IDiskQuotaEvents</code> '
                'などの COM インターフェイスで NTFS のクォータ管理を利用します。</p>',
 'p2-page-670': '<p>図11-25 ボリュームの「プロパティ」から開く「クォータ設定」ダイアログ。</p>\n'
                '<h4>リンクの追跡</h4>\n'
                '<p>シェルのショートカットを使うと、ファイルシステム上のファイルへのリンクを、デスクトップなどのシェル名前空間に配置できます。Windows '
                'のスタートメニューでも、シェルのショートカットが広く使われます。同様に、OLE（Object Linking and '
                'Embedding）のリンクを使うと、あるアプリケーションの文書を別のアプリケーションの文書に透過的に埋め込めます。Microsoft Office の '
                'PowerPoint、Excel、Word などが OLE リンクを使います。</p>\n'
                '<p>シェルのショートカットや OLE '
                'リンクを使うと、ファイル同士や、ファイルとシェル名前空間を簡単に関連付けられます。ただし、リンク先のファイルやディレクトリを移動すると、リンクの管理が難しくなります。Windows '
                'の NTFS は、移動後もシェルと OLE のリンクが有効になるよう、分散リンク追跡サービスをサポートします。NTFS '
                'ボリューム上のリンク先が、元のボリュームと同じドメイン内にある別の NTFS '
                'ボリュームに移動すると、サービスは移動を追跡し、新しい場所を指すようリンクを自動で更新できます。</p>\n'
                '<p>NTFS のリンク追跡は、オブジェクト ID という任意のファイル属性を使います。アプリケーションは、ファイルシステム制御コード '
                '<code>FSCTL_CREATE_OR_GET_OBJECT_ID</code>（ID が未設定なら割り当てます）または '
                '<code>FSCTL_SET_OBJECT_ID</code> で、オブジェクト ID を割り当てられます。照会には '
                '<code>FSCTL_CREATE_OR_GET_OBJECT_ID</code> または <code>FSCTL_GET_OBJECT_ID</code> を使います。削除には '
                '<code>FSCTL_DELETE_OBJECT_ID</code> を使います。</p>\n'
                '<figure><img loading="lazy" width="690" height="362" '
                'src="assets/1e1199471b2994b89367554f.webp" alt="ボリュームのクォータ設定（原文の図1）"></figure>',
 'p2-page-671': '<h4>暗号化</h4>\n'
                '<p>企業の利用者は、機密情報を自分のコンピューターに保存することがあります。社内サーバー上のデータは通常、適切なネットワーク設定と物理的なアクセス制御で保護されます。一方、ノート '
                'PC に保存したデータは、紛失や盗難に遭ったときに漏えいするおそれがあります。NTFS のファイルアクセス許可が効くのは、読み取りに使う OS '
                'がその設定を適用する場合です。端末から取り出したストレージの内容を直接読み取る場合には、この制御が働きません。また、第1部で説明したように、管理者アカウントには所有権の取得やバックアップの特権があり、通常のアクセス許可を超えて保護されたオブジェクトにアクセスできる場合があります。</p>\n'
                '<p>NTFS '
                'には、機密データを暗号化するための暗号化ファイルシステム（EFS）があります。ファイル圧縮と同様に、暗号化と復号はアプリケーションから透過的です。閲覧を許可されたユーザーのアカウントで動作するアプリケーションがデータを読むと、自動で復号します。許可されたアプリケーションがデータを変更すると、自動で暗号化します。</p>\n'
                '<aside><p>NTFS では、システムボリュームのルートや <code>&#92;Windows</code> ディレクトリにあるファイルを EFS '
                'で暗号化できません。これらの場所には起動時に必要なファイルが多く、起動中は EFS が動作しないためです。これらのファイルも保護するには、ボリューム全体を暗号化する '
                'BitLocker が適しています。BitLocker と NTFS の連携については後述します。</p></aside>\n'
                '<p>EFS は Windows がユーザーモードで提供する暗号化サービスを利用します。NTFS '
                'と密接に連携するカーネルモードのコンポーネントと、ローカルセキュリティ機関サブシステム（LSASS）や暗号化 DLL と通信するユーザーモードの DLL で構成されます。</p>\n'
                '<p>暗号化ファイルにアクセスするには、許可されたアカウントの EFS 鍵ペアに含まれる秘密鍵が必要です。秘密鍵はアカウントのパスワードで保護されます。そのため、ノート PC '
                'を紛失したり盗まれたりしても、データの閲覧を許可されたアカウントのパスワードがなければ、暗号を総当たりで破る場合を除き、EFS で暗号化されたファイルを読み取れません。</p>\n'
                '<p>アプリケーションは Windows API の <code>EncryptFile</code> と <code>DecryptFile</code> '
                'でファイルを暗号化・復号できます。ファイルやディレクトリが暗号化されているかなど、EFS に関する属性の照会には <code>FileEncryptionStatus</code> '
                'を使います。暗号化されたファイルやディレクトリには <code>FILE_ATTRIBUTE_ENCRYPTED</code> '
                '属性が設定されるため、<code>GetFileAttributes</code> でも暗号化状態を確認できます。</p>',
 'p2-page-672': '<h4>POSIX 方式のファイル削除</h4>\n'
                '<p>従来の POSIX サブシステムは廃止され、Windows Subsystem for Linux（WSL）に置き換わりました。NTFS ドライバーは、Windows と '
                'Linux の I/O 操作の違いを吸収するために更新されました。その一例が、ファイル名やディレクトリ名を削除する Linux の <code>unlink</code> や '
                '<code>rm</code> の動作です。従来の Windows では、別のアプリケーションがハンドルを開いているファイルは削除できませんでした。Linux '
                'では通常、名前を削除した後も、既存のハンドルを通じて元のファイルを使い続けられます。Windows 10 の NTFS ドライバーは、WSL 対応のため POSIX '
                '方式の削除をサポートしました。</p>\n'
                '<p>従来の Win32 <code>DeleteFile</code> は、まず対象ファイルを開いてハンドルを作り、ネイティブ API の '
                '<code>NtSetInformationFile</code> で削除予定を設定します。NTFS '
                'ドライバーは、ファイル制御ブロック（FCB）の参照数が1で、ほかに開いているハンドルがないことを確認します。条件を満たす場合は、クローズ時に削除するようマークして戻ります。実際にファイルが削除されるのは、ハンドルを閉じたときに '
                '<code>IRP_MJ_CLEANUP</code> のディスパッチルーチンが実行されてからです。</p>\n'
                '<p>WSL は、<code>NtSetInformationFile</code> に情報クラス <code>FileDispositionInformationEx</code> '
                'とフラグ <code>FILE_DISPOSITION_POSIX_SEMANTICS</code> を指定します。NTFS '
                'は、ディスク上のオブジェクトを開いたインスタンスの状態を表すコンテキスト制御ブロック（CCB）にフラグを立て、POSIX '
                '方式の削除として記録します。続いて専用の内部ルーチンでファイルを開き直し、新しいハンドル（ここでは PosixDeleted '
                'ハンドルと呼びます）をストリーム制御ブロック（SCB）に関連付けます。元のハンドルを閉じると、NTFS は PosixDeleted '
                'ハンドルの存在を検出し、それを閉じる処理をキューに入れます。その処理でクリーンアップルーチンは POSIX 削除のマークを確認し、ファイルを隠しディレクトリ '
                '<code>&#92;$Extend&#92;$Deleted</code> '
                'に移します。ファイルは元の名前空間から消えますが、他のアプリケーションは既存のハンドルで操作を続けられます。最初の削除要求で FCB '
                'にクローズ時削除のマークが付いているため、最後のハンドルを閉じた時点で削除されます。</p>\n'
                '<p>カーネルドライバーの不具合で解放されない参照が残った場合や、突然の停電などで削除できなかった場合、NTFS は次にボリュームをマウントするときに '
                '<code>&#92;$Extend&#92;$Deleted</code> を調べ、残ったファイルを標準の削除ルーチンですべて削除します。</p>\n'
                '<aside><p>Windows 10 May 2019 Update（19H1）以降は、<code>DeleteFile</code> も既定で POSIX '
                '方式の削除を使います。</p></aside>',
 'p2-page-673': '<h4>実験\u3000POSIX 方式の削除を確認する</h4>\n'
                '<p>本書のダウンロード資料に含まれる FsTool を使い、POSIX 方式の削除を確認します。新しい Windows クライアント版では既定でこの方式が使われるため、実験には '
                'Windows Server 2019（RS5）を使います。コマンドプロンプトを開き、<code>/touch</code> オプションで、FsTool '
                'が排他的に使用するテキストファイルを作成します。</p>\n'
                '<pre><code>D:&#92;&gt;FsTool.exe /touch d:&#92;Test.txt\n'
                'NTFS / ReFS Tool v0.1\n'
                'Copyright (C) 2018 Andrea Allievi (AaLl86)\n'
                '\n'
                '「d:&#92;Test.txt」の作成に成功しました。\n'
                'ファイルハンドルは有効です。Enter キーを押すとファイルに書き込みます。</code></pre>\n'
                '<p>Enter キーを押すよう求められたら、そのままにして別のコマンドプロンプトを開き、ファイルの読み取りと削除を試します。</p>\n'
                '<pre><code>D:&#92;&gt;type Test.txt\n'
                '別のプロセスが使用しているため、ファイルにアクセスできません。\n'
                '\n'
                'D:&#92;&gt;del Test.txt\n'
                '\n'
                'D:&#92;&gt;dir Test.txt\n'
                ' ドライブ D のボリューム ラベルは DATA です\n'
                ' ボリューム シリアル番号は 62C1-9EB3 です\n'
                '\n'
                ' D:&#92; のディレクトリ\n'
                '\n'
                '12/13/2018  12:34 AM                49 Test.txt\n'
                '               1 個のファイル                  49 バイト\n'
                '               0 個のディレクトリ  1,486,254,481,408 バイトの空き領域</code></pre>\n'
                '<p>FsTool '
                'が排他的にアクセスしている間は、別のプロセスからファイルを開けません。削除を試すと、システムはファイルを削除予定としてマークしますが、まだファイルシステムの名前空間から取り除けません。エクスプローラーで削除を試しても同じ結果になります。最初のコマンドプロンプトで '
                'Enter キーを押し、FsTool を終了すると、NTFS ドライバーが実際にファイルを削除します。</p>\n'
                '<p>次に FsTool の <code>/pdel</code> オプションで、POSIX '
                '方式の削除を試します。元のファイルはすでに削除予定になっており、同じファイルをもう一度削除することはできません。最初のコマンドプロンプトで FsTool を '
                '<code>/touch</code> オプション付きで起動し直します。Enter キーを押す前に2つ目のウィンドウに切り替え、次を実行します。</p>\n'
                '<pre><code>D:&#92;&gt;FsTool /pdel Test.txt\n'
                'NTFS / ReFS Tool v0.1\n'
                'Copyright (C) 2018 Andrea Allievi (AaLl86)\n'
                '\n'
                '「Test.txt」を POSIX 方式で削除しました。\n'
                '何かキーを押して終了します。</code></pre>',
 'p2-page-674': '<pre><code>D:&#92;&gt;dir Test.txt\n'
                ' ドライブ D のボリューム ラベルは DATA です\n'
                ' ボリューム シリアル番号は 62C1-9EB3 です\n'
                '\n'
                ' D:&#92; のディレクトリ\n'
                '\n'
                'ファイルが見つかりません</code></pre>\n'
                '<p>この場合、<code>Test.txt</code> はファイルシステムの名前空間から取り除かれていますが、ファイル自体はまだ有効です。最初のコマンドプロンプトで Enter '
                'キーを押すと、FsTool はそのファイルに引き続きデータを書き込めます。内部では、ファイルが隠しシステムディレクトリ '
                '<code>&#92;$Extend&#92;$Deleted</code> に移動しているためです。</p>\n'
                '<h4>デフラグ</h4>\n'
                '<p>NTFS '
                'は、ファイルを拡張するときに、なるべく連続したブロックを割り当てます。それでも、ファイルの拡張を繰り返したり、ボリュームの空き容量が少なくなったりすると、時間とともに断片化する場合があります。ファイルのデータが連続しないクラスターに分かれている状態を断片化と呼びます。図11-26では、断片化したファイルが5つの断片に分かれています。Windows '
                'の FAT など、多くのファイルシステムと同様に、NTFS でファイルを連続した領域へ再配置するのは、組み込みのデフラグ機能です。ただし NTFS '
                'は、マスターファイルテーブル（MFT）のために、MFT '
                'ゾーンという領域を予約します。ボリュームの空きが少なくなれば、ほかのファイルにもこの領域を割り当てます。領域を確保しておくことで MFT の連続性を保ちやすくなりますが、MFT '
                '自体が断片化する場合もあります。詳細は後述の「マスターファイルテーブル」を参照してください。</p>\n'
                '<p>図11-26 断片化したファイルと、連続した領域にあるファイル。</p>\n'
                '<p>Windows は、サードパーティのデフラグツールを開発できるよう、ファイルデータを連続したクラスターへ移動する API '
                'を提供します。ボリュームの空きクラスターと使用中のクラスターのマップは '
                '<code>FSCTL_GET_VOLUME_BITMAP</code>、ファイルに割り当てられたクラスターのマップは '
                '<code>FSCTL_GET_RETRIEVAL_POINTERS</code> で取得し、ファイルの移動には <code>FSCTL_MOVE_FILE</code> '
                'を使います。</p>',
 'p2-page-675': '<p>Windows '
                'に組み込まれたデフラグ機能は、図11-27に示す「ドライブの最適化」（<code>%SystemRoot%&#92;System32&#92;Dfrgui.exe</code>）から利用できます。コマンドライン版の '
                '<code>%SystemRoot%&#92;System32&#92;Defrag.exe</code> '
                'は、手動で実行することも、実行をスケジュールすることもできます。詳細なレポートの出力や、特定のファイルやディレクトリを除外するといった処理の指定には対応していません。</p>\n'
                '<p>図11-27 「ドライブの最適化」ツール。</p>\n'
                '<p>NTFS の実装でデフラグできないのは、ページファイルと NTFS のログファイルです。「ドライブの最適化」は、Windows 7 に搭載されていた「ディスク デフラグ '
                'ツール」の後継です。階層化ボリューム、SMR ディスク、SSD '
                'に対応するよう更新されました。最適化エンジンは「ドライブの最適化」サービス（<code>Defragsvc.dll</code>）に実装されています。グラフィカルなツールとコマンドライン版は、どちらもサービスが公開する '
                'COM インターフェイス <code>IDefragEngine</code> を使います。</p>\n'
                '<p>SSD に対しては再 TRIM も行います。この処理を理解するには、まず SSD の構造を知る必要があります。SSD はフラッシュメモリセルにデータを保存します。セルは4〜16 '
                'KB '
                'のページにまとめられ、通常は128〜512ページで1ブロックを構成します。セルに直接書き込めるのは空のときだけです。データが入っていれば、書き込みの前に消去する必要があります。SSD '
                'は1ページ単位で書き込めますが、ハードウェアの制約により、消去は常にブロック全体に及びます。そのため、空のページへの書き込みは非常に速く、すでにデータがあるページを上書きする場合は大幅に遅くなります。</p>\n'
                '<figure><img loading="lazy" width="597" height="431" '
                'src="assets/d291240d7bcdeb582ff87481.webp" alt="ドライブの最適化（原文の図1）"></figure>',
 'p2-page-676': '<p>上書きする場合は、まずブロック全体の内容をキャッシュに退避し、SSD '
                '上のブロック全体を消去します。キャッシュ内の対象ページを書き換えてから、更新後のブロック全体をフラッシュメモリに書き戻します。この負担を抑えるため、NTFS '
                'ドライバーはファイルの一部または全部に対応するクラスターを解放するたびに、SSD コントローラーへ TRIM コマンドを送ろうとします。TRIM を受け取った SSD '
                'は、可能であれば不要になったブロック全体を非同期に消去します。解放された領域がブロックの一部のページにしか対応しない場合、そのブロックを丸ごと消去することはできません。</p>\n'
                '<p>再 TRIM では SSD を調べ、空き領域のすべてのクラスターを対象に、1 MB 単位に分けて TRIM の要求を送ります。これには次の理由があります。</p>\n'
                '<ul>\n'
                '<li>ファイルシステムは、クラスターを解放するたびに必ず TRIM を発行するわけではありません。</li>\n'
                '<li>NTFS が TRIM の対象にするのはページで、SSD の消去ブロック全体とは限りません。原本の説明では、ドライブの最適化は再 TRIM '
                'の際に断片化したブロックを探します。有効なデータを一時ブロックに移し、ほかの断片化したブロックに属するページもまとめて、元のブロックを空けます。最後に、空いたブロックに対して '
                'TRIM を発行します。</li>\n'
                '</ul>\n'
                '<aside><p>空き領域へ TRIM を発行する手順には、スパースファイルを使います。ドライブの最適化は、論理サイズが1 GB '
                'で有効なデータを持たないスパースファイルを作り、128 KB から1 GB の空き領域を探します。次に、<code>FSCTL_MOVE_FILE</code> '
                'を使って、その領域へスパースファイルのデータを移動するようファイルシステムに要求します。有効なデータのないスパース範囲を読むとゼロが返ります。下位のファイルシステムが対象の SSD '
                'ブロックを解放し、SSD のファームウェアが TRIM を処理します。</p></aside>\n'
                '<p>階層化ディスクと SMR ディスクに対して、「ドライブの最適化」はスラブの統合（Slabify または Slab '
                'Consolidation）と階層の最適化もサポートします。階層化ボリューム上の大きなファイルは、異なる階層に配置された複数のエクステントからなる場合があります。スラブの統合では、ファイルのエクステントテーブルの断片化を解消するだけでなく、ファイルの内容をまとめて配置し、使うスラブの数を減らします。スラブはシンプロビジョニングされたディスクの割り当て単位です。詳細は本章の「記憶域スペース」を参照してください。</p>\n'
                '<p>階層の最適化は、頻繁にアクセスされるファイルや、明示的に固定されたファイルを容量階層から性能階層へ移し、アクセス頻度が低いファイルを性能階層から容量階層へ移します。最適化エンジンは階層化エンジンに問い合わせます。階層化エンジンは、ユーザーがアクセスしたファイルごとのアクセス頻度を示すヒートマップを基に、どのエクステントを各階層に移すべきかを返します。</p>\n'
                '<aside><p>階層化ディスクと階層化エンジンは、本章の後半で詳しく説明します。</p></aside>',
 'p2-page-677': '<h4>実験\u3000SSD ボリュームで再 TRIM を実行する</h4>\n'
                '<p>高速な SSD や NVMe のボリュームでは、<code>defrag.exe</code> の <code>/L</code> オプションで再 TRIM '
                'を実行できます。次は実行例です。</p>\n'
                '<pre><code>D:&#92;&gt;defrag /L c:\n'
                'Microsoft Drive Optimizer\n'
                'Copyright (c) Microsoft Corp.\n'
                '\n'
                '(C:) で再 TRIM を実行しています...\n'
                '操作は正常に完了しました。\n'
                '\n'
                '最適化後のレポート\n'
                '  ボリュームサイズ     = 475.87 GB\n'
                '  空き領域             = 343.80 GB\n'
                '  TRIM の対象領域の合計 = 341.05 GB</code></pre>\n'
                '<p>この例では、容量475.87 GB のボリュームに343.80 GB の空きがあり、そのうち約341 GB が TRIM の対象になりました。従来の HDD '
                '上のボリュームでこのコマンドを実行すると、ボリュームのハードウェアが要求された操作に対応していないというエラーになります。</p>\n'
                '<h4>パーティションの動的なサイズ変更</h4>\n'
                '<p>NTFS '
                'ドライバーでは、システムパーティションを含むパーティションのサイズを動的に変更し、利用可能な領域に応じて縮小または拡張できます。ディスクに十分な空き領域があれば、ファイルシステム制御コード '
                '<code>FSCTL_EXPAND_VOLUME</code> '
                'で拡張できます。縮小は、切り離す範囲にあるファイルシステムのデータを、縮小後に残る領域へ移す必要があるため、より複雑です。この処理はデフラグに似ており、縮小エンジンとファイルシステムドライバーが連携して実行します。</p>\n'
                '<p>縮小エンジンはユーザーモードに実装され、NTFS '
                'と通信して回収可能な最大バイト数を調べます。これは、切り離す範囲のデータを、残す範囲へどの程度移せるかによって決まります。縮小エンジンは前述の標準のデフラグ機構を使います。この機構では、使用中のページファイルの断片や、<code>FSCTL_MARK_HANDLE</code> '
                'で移動不可とされたファイル（休止状態ファイルなど）は移動できません。マスターファイルテーブルのバックアップ（<code>$MftMirr</code>）、NTFS '
                'のメタデータトランザクションログ（<code>$LogFile</code>）、ボリュームラベルファイル（<code>$Volume</code>）も移動できません。これらの位置によって縮小後のボリュームの最小サイズが決まり、使われていない領域が残る場合があります。</p>',
 'p2-page-678': '<p>ファイルシステムドライバーの縮小処理は、操作の途中でもボリュームの整合性を保ちます。そのため、<code>FSCTL_SHRINK_VOLUME</code> '
                '制御コードを通じて3種類の要求を受け取るインターフェイスを提供します。</p>\n'
                '<dl>\n'
                '<dt><code>ShrinkPrepare</code></dt><dd>他の操作より先に発行します。縮小後のボリュームサイズをセクター数で指定すると、ファイルシステムは新しい境界の外側への割り当てを止めます。指定した大きさまで実際に縮小できるかは検証しません。指定値が数値として有効か、別の縮小処理が進行中でないかを確認します。準備後、ボリュームのハンドルが縮小要求に関連付けられます。そのハンドルを閉じると、操作は中止されたものとして扱います。</dd>\n'
                '<dt><code>ShrinkCommit</code></dt><dd><code>ShrinkPrepare</code> '
                'の後に縮小エンジンが発行します。ファイルシステムは直近の準備要求で指定された数のクラスターを取り除こうとします。異なるサイズで複数回準備要求を送った場合は、最後の指定が有効です。縮小エンジンによるデータ移動が完了していることが前提で、切り離す範囲に割り当て済みのブロックが残っていると失敗します。</dd>\n'
                '<dt><code>ShrinkAbort</code></dt><dd>縮小エンジンが発行するか、ボリュームのハンドルを閉じた場合などに発生します。縮小処理を取り消してパーティションを元のサイズに戻し、縮小後の境界より外側にも再び割り当てられるようにします。ただし、縮小エンジンが行ったデフラグの変更は残ります。</dd>\n'
                '</dl>\n'
                '<p>縮小中にシステムが再起動すると、NTFS '
                'は後述のメタデータ回復機構でファイルシステムを整合した状態に戻します。実際の縮小は他の操作がすべて完了した後に行うため、確定前ならボリュームは元のサイズを保ち、ディスクへ書き戻し済みのデフラグの変更だけが残ります。</p>\n'
                '<p>ボリュームの縮小はボリュームシャドウコピー（VSS）にも影響します。コピーオンライトでは、実際に変更した部分だけを別に保持し、それ以外は元のファイルデータを参照できます。ファイルを削除すると、VSS '
                'が参照しているデータでも、可視のファイルには関連付けられず、空き領域として見える場合があります。その領域が縮小で切り離される範囲に含まれることもあります。そのため、縮小エンジンは '
                'VSS と連携します。VSS '
                'は削除済みファイルのデータを差分領域へコピーし、必要に応じて差分領域を拡張します。この処理があるため、ボリュームに十分な空きがあっても、縮小できるサイズには制約があります。</p>\n'
                '<h4>NTFS の階層化ボリュームのサポート</h4>\n'
                '<p>階層化ボリュームは、種類や性能の異なるストレージを組み合わせ、通常は1台の物理ディスクまたは仮想ディスクの上に作ります。記憶域スペースでは、高速な NVMe '
                'ディスク、SSD、回転式ハードディスクなど、異なる種類の物理ディスクから仮想ディスクを作れます。この種の仮想ディスクを階層化ディスクと呼び、記憶域スペースでは記憶域階層（Storage '
                'Tiers）と呼びます。物理 SMR ディスクの上でも階層化ボリュームを作れます。SMR '
                'ディスクには、従来方式でランダムアクセスできる高速領域と、順次アクセスを厳格に求める容量領域があります。</p>',
 'p2-page-679': '<p>階層化ボリュームには、高速なランダム I/O に対応する性能階層と、速度は低くても大容量の容量階層があります。容量階層がランダム I/O '
                'に対応するかどうかは、記憶媒体によって異なります。</p>\n'
                '<aside><p>SMR ディスク、階層化ボリューム、記憶域スペースの詳細は、本章の後半で説明します。</p></aside>\n'
                '<p>NTFS ドライバーは、次のように階層化ボリュームに対応します。</p>\n'
                '<ul>\n'
                '<li>ボリュームを、階層化ディスクの容量領域と性能領域に対応する2つのゾーンに分けます。</li>\n'
                '<li><code>$LOGGED_UTILITY_STREAM</code> 型の属性 <code>$DSC</code> は、ファイルを配置する階層を指定します。NTFS '
                'の固定（pinning）インターフェイスで特定の階層にファイルを固定すると、階層化エンジンは自動でそのファイルを別の階層へ移しません。</li>\n'
                '<li>記憶域階層管理サービスが階層化を管理します。NTFS ドライバーはファイルのストリームを読み書きするたびに、アクセス頻度を計測するための ETW '
                'イベントを記録します。階層化エンジンはイベントを受け取り、1 MB 単位で集計して、1時間ごとに JET '
                'データベースに保存します。4時間ごとにこのデータベースを処理し、過去のアクセスの影響を時間とともに弱めるアルゴリズムで、最近よく使われるファイル（ホット）と、利用頻度が下がったファイル（コールド）を判定します。その結果に基づき、性能階層と容量階層の間でファイルを移動します。</li>\n'
                '</ul>\n'
                '<p>NTFS のアロケーターも、<code>$DSC</code> '
                '属性の指定に従ってファイルのクラスターを割り当てるよう変更されました。ボリューム内のどの階層から割り当てるかを、次の順序で判断します。</p>\n'
                '<ol>\n'
                '<li>ボリュームの USN ジャーナルは、常に容量階層から割り当てます。</li>\n'
                '<li>MFT エントリ（ファイルレコード）とシステムメタデータファイルは、常に性能階層から割り当てます。</li>\n'
                '<li>ファイルが明示的に固定されている場合は、<code>$DSC</code> 属性で指定された記憶域階層から割り当てます。</li>\n'
                '<li>Windows のクライアント版では性能階層を優先し、それ以外では容量階層から割り当てます。</li>\n'
                '<li>性能階層に空きがなければ、容量階層から割り当てます。</li>\n'
                '</ol>\n'
                '<p>アプリケーションは、<code>NtSetInformationFile</code> に情報クラス '
                '<code>FileDesiredStorageClassInformation</code> '
                'を指定して、ファイルを希望する階層に固定できます。新規ファイルのハンドルに対して実行すると、NTFS '
                'のアロケーターが新しいファイルデータを指定の階層に割り当てます。既存ファイルが別の階層にある場合は、階層化エンジンが次回の実行時に指定先へ移します。この処理を階層の最適化と呼び、階層化エンジンのスケジュールタスクまたは '
                '<code>SchedulerDefrag</code> タスクから開始できます。</p>',
 'p2-page-680': '<aside><p>ここで説明した NTFS の階層化ボリュームの仕組みは、ReFS ドライバーが提供する仕組みとは異なります。</p></aside>\n'
                '<h4>実験\u3000階層化ボリュームでファイルの固定を確認する</h4>\n'
                '<p>前節で説明したように、NTFS '
                'のアロケーターは所定の規則に従ってクラスターを割り当てる階層を決めます。この実験では、大きなファイルを階層化ボリュームにコピーし、ファイルを特定の階層に固定したときの効果を確認します。コピーが終わったら、スタートメニューのアイコンを右クリックし、「Windows '
                'PowerShell（管理者）」を選びます。<code>Get-FileStorageTier</code> でファイルの配置情報を取得します。</p>\n'
                '<pre><code>PS E:&#92;&gt; Get-FileStorageTier -FilePath &#39;E:&#92;Big_Image.iso&#39; | FL '
                'FileSize,\n'
                'DesiredStorageTierClass, FileSizeOnPerformanceTierClass, FileSizeOnCapacityTierClass,\n'
                'PlacementStatus, State\n'
                '\n'
                'FileSize                       : 4556566528\n'
                'DesiredStorageTierClass        : Unknown\n'
                'FileSizeOnPerformanceTierClass : 0\n'
                'FileSizeOnCapacityTierClass    : 4556566528\n'
                'PlacementStatus                : Unknown\n'
                'State                          : Unknown</code></pre>\n'
                '<p>Windows Server で実行したこの例では、<code>Big_Image.iso</code> '
                '全体が容量階層に割り当てられています。実際に確認するには、階層化ディスクから高速な SSD '
                'ボリュームへファイルをコピーします。転送速度は回転式ディスクの性能によって異なりますが、通常は160〜250 MB/s 程度です。</p>\n'
                '<figure><img loading="lazy" width="380" height="243" '
                'src="assets/01b60fa2715339464912bdd1.webp" alt="階層化ボリューム（原文の図1）"></figure>',
 'p2-page-681': '<p>次に、<code>Set-FileStorageTier</code> でファイルを指定の階層に固定します。まず <code>Get-StorageTier</code> で '
                'SSD の階層名を確認します。</p>\n'
                '<pre><code>PS E:&#92;&gt; Get-StorageTier -MediaType SSD | FL FriendlyName, Size, '
                'FootprintOnPool, UniqueId\n'
                '\n'
                'FriendlyName    : SSD\n'
                'Size            : 128849018880\n'
                'FootprintOnPool : 128849018880\n'
                'UniqueId        : {448abab8-f00b-42d6-b345-c8da68869020}\n'
                '\n'
                'PS E:&#92;&gt; Set-FileStorageTier -FilePath &#39;E:&#92;Big_Image.iso&#39; '
                '-DesiredStorageTierFriendlyName &#39;SSD&#39;\n'
                'PS E:&#92;&gt; Get-FileStorageTier -FilePath &#39;E:&#92;Big_Image.iso&#39; | FL FileSize,\n'
                'DesiredStorageTierClass, FileSizeOnPerformanceTierClass, FileSizeOnCapacityTierClass,\n'
                'PlacementStatus, State\n'
                '\n'
                'FileSize                       : 4556566528\n'
                'DesiredStorageTierClass        : Performance\n'
                'FileSizeOnPerformanceTierClass : 0\n'
                'FileSizeOnCapacityTierClass    : 4556566528\n'
                'PlacementStatus                : Not on tier\n'
                'State                          : Pending</code></pre>\n'
                '<p>ファイルの固定先には性能階層が設定されましたが、データはまだ容量階層にあります。階層化エンジンのスケジュールタスクが実行されると、ファイルのエクステントを容量階層から性能階層へ移します。すぐに階層を最適化するには、Windows '
                'に組み込まれた <code>defrag.exe</code> を <code>/g</code> オプション付きで実行します。</p>\n'
                '<pre><code>PS E:&gt; defrag /g /h e:\n'
                'Microsoft Drive Optimizer\n'
                'Copyright (c) Microsoft Corp.\n'
                '\n'
                'Test (E:) の階層を最適化しています...\n'
                '\n'
                '最適化前のレポート\n'
                '  ボリューム情報\n'
                '    ボリュームサイズ         = 2.22 TB\n'
                '    空き領域                 = 1.64 TB\n'
                '    断片化した領域の割合     = 36%\n'
                '    最大の連続空き領域       = 1.56 TB\n'
                '\n'
                '注: 64 MB を超えるファイルの断片は、断片化の統計に含まれません。\n'
                '\n'
                '操作は正常に完了しました。\n'
                '\n'
                '最適化後のレポート\n'
                '  ボリューム情報\n'
                '    ボリュームサイズ         = 2.22 TB\n'
                '    空き領域                 = 1.64 TB\n'
                '\n'
                '記憶域階層の最適化レポート</code></pre>',
 'p2-page-682': '<pre><code>性能階層で処理する I/O の割合    必要な性能階層の容量\n'
                '                        100%                   28.51 GB *\n'
                '                         95%                   22.86 GB\n'
                '                          …\n'
                '                         20%                    2.44 GB\n'
                '                         15%                    1.58 GB\n'
                '                         10%                  873.80 MB\n'
                '                          5%                  361.28 MB\n'
                '\n'
                '* 現在の性能階層の容量: 474.98 GB\n'
                '  全 I/O のうち性能階層で処理した割合: 99%\n'
                '\n'
                '性能階層に固定されたファイルの容量: 4.21 GB\n'
                '全 I/O に占める割合: 1%\n'
                '\n'
                '容量階層に固定されたファイルの容量: 0バイト\n'
                '全 I/O に占める割合: 0%</code></pre>\n'
                '<p>「ドライブの最適化」のレポートで、ファイルが固定されたことを確認できます。固定の状態をもう一度調べるには、<code>Get-FileStorageTier</code> '
                'を実行し、ファイルを再び SSD ボリュームにコピーします。ファイルの内容がすべて性能階層にあれば、転送速度は前回より大幅に上がるはずです。</p>\n'
                '<pre><code>PS E:&#92;&gt; Get-FileStorageTier -FilePath &#39;E:&#92;Big_Image.iso&#39; | FL '
                'FileSize, DesiredStorageTierClass,\n'
                'FileSizeOnPerformanceTierClass, FileSizeOnCapacityTierClass, PlacementStatus, State\n'
                '\n'
                'FileSize                       : 4556566528\n'
                'DesiredStorageTierClass        : Performance\n'
                'FileSizeOnPerformanceTierClass : 0\n'
                'FileSizeOnCapacityTierClass    : 4556566528\n'
                'PlacementStatus                : Completely on tier\n'
                'State                          : OK</code></pre>\n'
                '<aside><p>原本の出力例では、配置状態が <code>Completely on tier</code> '
                'である一方、バイト数の欄には性能階層が0、容量階層がファイル全体と表示されています。この出力だけでは、データがすべて性能階層に移ったことは確認できません。</p></aside>\n'
                '<p>Windows 10 のクライアント版では、ファイルのクラスターが既定で性能階層から割り当てられるため、容量階層に固定して同じ実験を繰り返せます。本書のダウンロード資料にある '
                'FsTool にも同じ固定機能があり、希望する階層へファイルを直接コピーできます。</p>\n'
                '<figure><img loading="lazy" width="379" height="242" '
                'src="assets/5017672aea9608ad05f9a88b.webp" alt="パフォーマンス層の容量（原文の図1）"></figure>',
 'p2-page-683': '<h4>NTFS ファイルシステムドライバー</h4>\n'
                '<p>第1部第6章で説明したとおり、Windows の I/O システムでは、NTFS '
                'などのファイルシステムは、カーネルモードで動作するロード可能なデバイスドライバーです。アプリケーションが Windows の I/O API '
                'などを使うと、これらのドライバーが間接的に呼び出されます。図11-28に示すように、Windows '
                'の環境サブシステムがシステムサービスを呼ぶと、システムサービスは、読み込み済みのドライバーから対象を探して呼び出します。この振り分け処理については、第8章「システムサービスのディスパッチ」を参照してください。</p>\n'
                '<p>図11-28 Windows I/O システムの構成要素。ユーザーモードの環境サブシステムまたは DLL が、カーネルモードの Windows '
                'システムサービスを呼び出します。図にはカーネルと Windows '
                'Executive、およびオブジェクトマネージャー、セキュリティ参照モニター、高度なローカルプロシージャ呼び出し（ALPC）、メモリマネージャー、I/O '
                'マネージャーが示されています。NTFS ドライバー、ボリュームマネージャー、ディスクドライバーは階層を構成します。</p>\n'
                '<p>各階層のドライバーは、Windows Executive の I/O マネージャーを呼び出して、互いに I/O 要求を渡します。I/O '
                'マネージャーが仲介するため、各ドライバーは独立性を保ち、ほかのドライバーに影響を与えずに読み込みやアンロードができます。NTFS '
                'ドライバーはさらに、図11-29の左側に示す、ファイルシステムと密接に関係する Windows Executive の3つのコンポーネントと連携します。</p>\n'
                '<p>ログファイルサービス（LFS）は、ディスクへの書き込みのログを管理する NTFS のコンポーネントです。システム障害が発生すると、NTFS は LFS '
                'が書き込んだログを使って、NTFS でフォーマットされたボリュームを回復します。詳細は後述の「ログファイルサービス」を参照してください。</p>',
 'p2-page-684': '<p>図11-29 NTFS と関連コンポーネント。NTFS '
                'ドライバーは、ログファイルサービスにトランザクションの記録とログの書き戻しを求めます。ファイルの読み書きにはキャッシュマネージャーが関わり、メモリマネージャーはマップ済みファイルへのアクセスやキャッシュの書き戻しを処理します。I/O '
                'マネージャーを介して、ボリュームマネージャーがミラー化またはストライプ化されたボリュームを読み書きし、ディスクドライバーがディスクとの間でデータを転送します。</p>\n'
                '<p>キャッシュマネージャーは Windows Executive の一部で、NTFS '
                'や、サーバーやリダイレクターなどのネットワークファイルシステムドライバーに、システム全体で共通のキャッシュ機能を提供します。Windows '
                '用のファイルシステムは、キャッシュ対象のファイルをシステムアドレス空間にマップし、仮想メモリを通じてアクセスします。キャッシュマネージャーはこのために、ファイルシステムが '
                'Windows '
                'のメモリマネージャーを利用する専用インターフェイスを提供します。プログラムがキャッシュに読み込まれていない範囲にアクセスすると、キャッシュミスが起きます。メモリマネージャーは '
                'NTFS '
                'を呼び出し、ディスクドライバーを介してファイルの内容を取得します。キャッシュマネージャーはまた、遅延ライタースレッドからメモリマネージャーを呼び出し、バックグラウンドでキャッシュの内容をディスクへ非同期に書き戻すことで、ディスク '
                'I/O を効率化します。</p>\n'
                '<p>NTFS はほかのファイルシステムと同様に、ファイルをオブジェクトとして実装し、Windows のオブジェクトモデルに組み込みます。これにより、Executive '
                'レベルのすべてのオブジェクトを管理するオブジェクトマネージャーが、ファイルの共有と保護を扱えます。オブジェクトマネージャーの詳細は第8章を参照してください。</p>\n'
                '<p>アプリケーションはほかの Windows オブジェクトと同じく、オブジェクトハンドルを使ってファイルを作成し、アクセスします。I/O 要求が NTFS '
                'に届くまでに、オブジェクトマネージャーとセキュリティ機構は、要求された方法でファイルオブジェクトへアクセスする権限が呼び出し元プロセスにあることを確認しています。セキュリティ機構は、呼び出し元のアクセストークンとファイルオブジェクトのアクセス制御リストのエントリを照合します。アクセス制御リストの詳細は第1部第7章を参照してください。また、I/O '
                'マネージャーはファイルハンドルをファイルオブジェクトへのポインターに変換します。NTFS はこのオブジェクト内の情報を使って、ディスク上のファイルにアクセスします。</p>\n'
                '<p>図11-30に、ファイルハンドルとディスク上のファイルシステム構造を結び付けるデータ構造を示します。</p>',
 'p2-page-685': '<p>図11-30 NTFS のデータ構造。オブジェクトマネージャーが管理するプロセスのハンドルテーブルから、ファイルオブジェクトを参照します。NTFS '
                'はファイルオブジェクトからストリーム制御ブロック、ファイル制御ブロックをたどり、ディスク上の NTFS データベースにあるマスターファイルテーブルのレコードを特定します。</p>\n'
                '<p>NTFS '
                'は、ファイルオブジェクトから複数の参照をたどって、ディスク上のファイルの位置を見つけます。図11-30のように、ファイルを開くシステムサービスの1回の呼び出しに対応するファイルオブジェクトは、呼び出し元が読み書きしようとしているファイル属性のストリーム制御ブロック（SCB）を指します。図のプロセスは、同じファイルの名前のないデータ属性と名前付きストリーム（代替データ属性）の両方を開いています。各 '
                'SCB は1つのファイル属性を表し、その属性をファイル内で見つけるための情報を保持します。</p>\n'
                '<p>同じファイルのすべての SCB は、共通のファイル制御ブロック（FCB）を指します。FCB '
                'には、ディスク上のマスターファイルテーブル（MFT）にあるファイルレコードへの参照が入っています。この参照の実体は MFT '
                '内のインデックスです。詳細は後述の「ファイルレコード番号」を参照してください。MFT は次節で詳しく説明します。</p>\n'
                '<h4>NTFS のディスク上の構造</h4>\n'
                '<p>ここからは、ディスク上の NTFS '
                'ボリュームの構造を説明します。ディスク領域をどのようにクラスターに分けて管理するか、ファイルをどのようにディレクトリに整理するか、ファイルのデータと属性情報をディスク上にどう格納するかを見ていきます。最後に、NTFS '
                'のデータ圧縮を説明します。</p>',
 'p2-page-686': '<h4>ボリューム</h4>\n'
                '<p>NTFS の構造の基本単位はボリュームです。ボリュームはディスク上の論理パーティションに対応し、ディスクの全体または一部を NTFS '
                'でフォーマットすると作成されます。記憶域スペースを使えば、複数の物理ディスクにまたがる RAID '
                '仮想ディスクも作成できます。コントロールパネルの「記憶域スペースの管理」や、Windows PowerShell のコマンドから操作できます。たとえば '
                '<code>New-StoragePool</code> は新しい記憶域プールを作成するコマンドです。ほかのコマンドは <a '
                'href="https://learn.microsoft.com/powershell/module/storagespaces/">記憶域スペースの PowerShell '
                'リファレンス</a>を参照してください。</p>\n'
                '<p>1台のディスクに1つまたは複数のボリュームを作成できます。NTFS は各ボリュームを独立して扱います。図11-31に、2 TB '
                'のハードディスクの構成例を3つ示します。</p>\n'
                '<table><caption>図11-31 '
                'ディスク構成の例</caption><thead><tr><th>構成</th><th>C:</th><th>D:</th></tr></thead><tbody>\n'
                '<tr><td>1</td><td>NTFS、2 TB</td><td>なし</td></tr>\n'
                '<tr><td>2</td><td>NTFS、1 TB</td><td>ReFS、1 TB</td></tr>\n'
                '<tr><td>3</td><td>ReFS、1 TB</td><td>exFAT、1 TB</td></tr>\n'
                '</tbody></table>\n'
                '<p>ボリュームは、一連のファイルと、ディスクパーティションに残った未割り当て領域からなります。すべての FAT '
                '形式では、ファイルシステム専用にフォーマットされた領域もボリュームに含まれます。NTFS と ReFS '
                'では、ビットマップ、ディレクトリ、システムのブートストラップを含むファイルシステムのデータをすべて通常のファイルとして保存します。</p>\n'
                '<aside><p>Windows 10 と Windows Server 2019 の NTFS ボリュームのディスク上の形式はバージョン3.1で、Windows XP と '
                'Windows Server 2003 以降、同じバージョンが使われています。ボリュームのバージョン番号は <code>$Volume</code> '
                'メタデータファイルに格納されます。</p></aside>\n'
                '<h4>クラスター</h4>\n'
                '<p>NTFS ボリュームのクラスターサイズ（クラスターファクター）は、<code>format</code> コマンドまたは「ディスクの管理」MMC '
                'スナップインでボリュームをフォーマットするときに決まります。既定値はボリュームの大きさによって異なります。クラスターは常に、1、2、4、8のように2の累乗個の物理セクターで構成されます。クラスターファクターは、512バイト、1 '
                'KB、2 KB のように、クラスターあたりのバイト数で表します。</p>',
 'p2-page-687': '<p>NTFS は内部ではクラスターを単位として扱います。ただし、低レベルのボリューム I/O '
                'では、クラスターの開始位置をセクター境界に揃え、長さをセクターサイズの整数倍にします。割り当て単位をクラスターにすることで、物理セクターサイズに依存せず、大容量ディスクではクラスターサイズを大きくでき、512バイト以外のセクターを持つディスクにも対応できます。大容量ボリュームでクラスターを大きくすると、断片化を減らし、割り当てを速くできますが、未使用領域も増えます。たとえば、64 '
                'KB のクラスターに16 KB のファイルを保存すると、48 KB が余ります。コマンドプロンプトの <code>format</code> '
                'や、「ディスクの管理」の「操作」メニューで「すべてのタスク」から選ぶ「フォーマット」は、ボリュームサイズに応じて既定のクラスターサイズを選びます。必要に応じて別の値を指定できます。</p>\n'
                '<p>NTFS はディスク上の位置を、論理クラスター番号（LCN）で表します。LCN はボリュームの先頭から末尾まで、すべてのクラスターに順に割り振った番号です。LCN '
                'にクラスターサイズを掛けると、ディスクドライバーのインターフェイスが必要とする、ボリューム上の物理バイトオフセットが得られます。一方、ファイル内のデータは仮想クラスター番号（VCN）で表します。VCN '
                'は、そのファイルに属するクラスターに0から <var>m</var> までの番号を割り振ります。連続する VCN がディスク上で連続するとは限らず、ボリューム上の離れた LCN '
                'にも対応付けられます。</p>\n'
                '<h4>マスターファイルテーブル</h4>\n'
                '<p>NTFS '
                'はボリューム上のデータをすべてファイルとして保存します。ファイルを探して読み出すためのデータ構造、ブートストラップデータ、ボリューム全体の割り当て状態を記録するビットマップなどのメタデータも含まれます。こうすることで、ファイルシステムはデータを探して管理しやすくなり、個々のファイルをセキュリティ記述子で保護できます。ディスクの一部が故障した場合も、NTFS '
                'はメタデータファイルを移し、ディスク全体へのアクセスが失われるのを防げます。</p>\n'
                '<p>MFT は NTFS ボリュームの中心となる構造で、ファイルレコードの配列として実装されます。レコードサイズはフォーマット時に1 KB または4 KB '
                'に決まります。一般に、ネイティブセクターが4 KB の新しい物理ディスクや階層化ディスクでは4 KB、セクターが512バイトの古いディスクでは1 KB です。MFT '
                'エントリのサイズはクラスターサイズに依存せず、フォーマット時に <code>Format /l</code> '
                'で変更できます。レコードの構造は後述の「ファイルレコード」で説明します。論理上は、MFT 自体も含め、ボリューム上のファイルごとに1件のレコードがあります。各 NTFS '
                'ボリュームには MFT '
                'のほかにも、ファイルシステムの構造を実装するための情報を格納したメタデータファイルがあります。これらは名前がドル記号（<code>$</code>）で始まる隠しファイルです。たとえば '
                'MFT のファイル名は <code>$MFT</code> です。図11-32に示すように、残りは通常のユーザーファイルとディレクトリです。</p>\n'
                '<p>通常は、MFT '
                'の各レコードが別々のファイルに対応します。ただし、属性が多いか、断片化が進んだ場合には、1つのファイルに複数のレコードが必要になることがあります。このとき、ほかのレコードの位置を記録する最初のレコードを、ベースファイルレコードと呼びます。</p>',
 'p2-page-688': '<table><caption>図11-32 MFT にある NTFS '
                'メタデータファイルのレコード</caption><thead><tr><th>ファイル</th><th>用途</th></tr></thead><tbody>\n'
                '<tr><td><code>$MFT</code></td><td>マスターファイルテーブル</td></tr>\n'
                '<tr><td><code>$MFTMirr</code></td><td>MFT のミラー</td></tr>\n'
                '<tr><td><code>$LogFile</code></td><td>ログファイル</td></tr>\n'
                '<tr><td><code>$Volume</code></td><td>ボリューム情報</td></tr>\n'
                '<tr><td><code>$AttrDef</code></td><td>属性定義テーブル</td></tr>\n'
                '<tr><td><code>&#92;</code></td><td>ルートディレクトリ</td></tr>\n'
                '<tr><td><code>$Bitmap</code></td><td>ボリュームのクラスター割り当て情報</td></tr>\n'
                '<tr><td><code>$Boot</code></td><td>ブートセクター</td></tr>\n'
                '<tr><td><code>$BadClus</code></td><td>不良クラスターの一覧</td></tr>\n'
                '<tr><td><code>$Secure</code></td><td>セキュリティ設定</td></tr>\n'
                '<tr><td><code>$UpCase</code></td><td>大文字への文字マッピング</td></tr>\n'
                '<tr><td><code>$Extend</code></td><td>拡張メタデータのディレクトリ</td></tr>\n'
                '<tr><td><code>$Extend&#92;$Quota</code></td><td>クォータ情報</td></tr>\n'
                '<tr><td><code>$Extend&#92;$ObjId</code></td><td>分散リンク追跡情報</td></tr>\n'
                '<tr><td><code>$Extend&#92;$Reparse</code></td><td>再解析ポイントへの逆参照</td></tr>\n'
                '<tr><td><code>$Extend&#92;$RmMetadata</code></td><td>リソースマネージャーのメタデータディレクトリ</td></tr>\n'
                '<tr><td><code>$Extend&#92;$RmMetadata&#92;$Repair</code></td><td>リソースマネージャーの修復情報</td></tr>\n'
                '<tr><td><code>$Extend&#92;$Deleted</code></td><td>POSIX 方式で削除されたファイル</td></tr>\n'
                '<tr><td><code>$Extend&#92;$RmMetadata&#92;$Txf</code></td><td>TxF のメタデータディレクトリ</td></tr>\n'
                '<tr><td><code>$Extend&#92;$RmMetadata&#92;$TxfLog</code></td><td>TxF のログディレクトリ</td></tr>\n'
                '<tr><td><code>$Extend&#92;$RmMetadata&#92;$TxfLog&#92;$Tops</code></td><td>TOPS '
                'ファイル</td></tr>\n'
                '<tr><td><code>$Extend&#92;$RmMetadata&#92;$TxfLog&#92;$TxfLog.blf</code></td><td>TxF の BLF '
                'ファイル</td></tr>\n'
                '<tr><td><code>$TxfLogContainer00000000000000000001</code><br><code>$TxfLogContainer00000000000000000002</code></td><td>TxF '
                'のログコンテナー</td></tr>\n'
                '</tbody></table>\n'
                '<p>NTFS '
                'はボリュームに初めてアクセスするときに、ディスク上のメタデータを読み、アプリケーションからのアクセスを処理するための内部データ構造を組み立てます。この処理をマウントと呼びます。MFT '
                'の物理ディスクアドレスは、LCN 0にあるボリュームブートレコード（VBR）のブートパラメーターブロック（BPB）から取得します。テーブルの最初のレコードは MFT '
                '自体を表します。2番目のレコードは、ディスクの中ほどにある MFT ミラー（<code>$MFTMirr</code>）を指します。ミラーには MFT '
                'の先頭4レコードのコピーがあり、MFT の一部を読み取れないときに、メタデータファイルの位置を特定するために使います。</p>\n'
                '<p>NTFS は MFT のファイルレコードを見つけると、そのデータ属性から VCN と LCN の対応情報を取得してメモリに保持します。各連続領域（ラン）は、VCN と LCN '
                'の対応とランの長さを持ちます。この2つの情報があれば、任意の VCN に対応する LCN がわかります。ランの詳細は後述の「常駐属性と非常駐属性」を参照してください。</p>',
 'p2-page-689': '<p>この対応情報から、NTFS は MFT を構成する各ランのディスク上の位置を特定します。次に、ほかのメタデータファイルの MFT '
                'レコードをいくつか処理し、それらのファイルを開きます。続いて、後述の「回復」で説明するファイルシステムの回復処理を実行し、残りのメタデータファイルを開きます。これでユーザーがボリュームにアクセスできるようになります。</p>\n'
                '<aside><p>本章の本文と図では、説明のためランを VCN、LCN、長さの組で表します。実際に NTFS がディスク上に保持するのは、LCN と次の VCN の組です。次の '
                'VCN から開始 VCN を引けば、ランの長さが求まります。</p></aside>\n'
                '<p>システムの稼働中、NTFS は重要なメタデータファイルの1つであるログファイル <code>$LogFile</code> '
                'に書き込みます。ファイルの作成や、コピーなどディレクトリ構造を変更する操作も含め、NTFS '
                'ボリュームの構造に影響するすべての操作を記録します。システム障害後にボリュームを回復する際はこのログを使います。詳細は「回復」を参照してください。</p>\n'
                '<p>MFT の別のエントリは、ルートディレクトリ（たとえば <code>C:&#92;</code>）用に予約されています。そのファイルレコードには、NTFS '
                'のディレクトリ構造のルートにあるファイルとディレクトリのインデックスが含まれます。ファイルを初めて開くとき、NTFS '
                'はルートディレクトリのファイルレコードから検索を始めます。ファイルを開いた後は、そのファイルの MFT '
                'レコード番号を保持し、以後の読み書きでそのレコードに直接アクセスします。</p>\n'
                '<p>NTFS はボリュームの割り当て状態をビットマップファイル <code>$Bitmap</code> '
                'に記録します。データ属性にはボリュームのクラスターを1ビットずつ表すビットマップがあり、そのクラスターが空きか、ファイルに割り当て済みかを示します。</p>\n'
                '<p>セキュリティファイル <code>$Secure</code> '
                'は、ボリューム全体のセキュリティ記述子データベースを保持します。ファイルとディレクトリには個別にセキュリティ記述子を設定できます。NTFS '
                'は設定を共通ファイルにまとめ、設定が同じファイルやディレクトリから同じ記述子を参照することで容量を節約します。多くの環境ではディレクトリツリー全体で同じ設定が使われるため、この最適化でディスク使用量を大きく減らせます。</p>\n'
                '<p>システムボリュームでは、システムファイル <code>$Boot</code> に Windows '
                'の起動コードが入ります。システムボリューム以外では、そのボリュームから起動しようとしたときにエラーを画面に表示するコードが入ります。ブートマネージャーが見つけられるよう、起動コードはディスク上の所定の位置に置く必要があります。フォーマット時には、<code>format</code> '
                'コマンドがこの領域のファイルレコードを作成し、ファイルとして登録します。すべてのファイルは MFT '
                'に登録され、すべてのクラスターは空きか、ファイルへの割り当て済みです。ユーザーに表示されないメタデータファイルはありますが、MFT '
                'や割り当て管理の外にあるファイルやクラスターはありません。ブートファイルと NTFS のメタデータファイルも、ほかの Windows '
                'オブジェクトと同様に、セキュリティ記述子で個別に保護できます。起動コードもファイルとして扱うため、通常のファイル I/O '
                'の仕組みで変更できますが、ブートファイルは編集から保護されています。</p>\n'
                '<p>NTFS は、ボリューム上の不良箇所を記録する <code>$BadClus</code> と、ボリューム名などを保持するボリュームファイル '
                '<code>$Volume</code> も管理します。</p>',
 'p2-page-690': '<p><code>$Volume</code> には、ボリュームのフォーマットに使った NTFS '
                'のバージョンと、ボリュームの状態を示すフラグも格納されます。たとえば、ボリュームが破損しており <code>Chkdsk</code> '
                'で修復する必要があることを示すビットがあります。<code>Chkdsk</code> の詳細は後述します。<code>$UpCase</code> '
                'には、小文字を大文字に変換するテーブルが入っています。<code>$AttrDef</code> '
                'の属性定義テーブルは、ボリュームが対応する属性の型と、インデックスを付けられるか、システムの回復時に復元できるかといった性質を定義します。</p>\n'
                '<aside><p>図11-32は、NTFS '
                'ボリュームのマスターファイルテーブルと、メタデータファイルに対応するエントリの例を示しています。固定位置が保証されるのは、レコード番号が16未満のものです。16より後のエントリの位置は、NTFS '
                'がメタデータファイルを作成する順序によって変わります。フォーマットツールは16より後の位置にメタデータファイルを作成しません。フォーマット後の初回マウント時に NTFS '
                'ドライバーが作るため、その順序は保証されません。</p></aside>\n'
                '<p>NTFS は拡張メタデータディレクトリ <code>$Extend</code> に、オブジェクト識別子ファイル <code>$ObjId</code>、クォータファイル '
                '<code>$Quota</code>、変更ジャーナル <code>$UsnJrnl</code>、再解析ポイントファイル <code>$Reparse</code>、POSIX '
                '削除用ディレクトリ <code>$Deleted</code>、既定リソースマネージャーのディレクトリ <code>$RmMetadata</code> などを保存します。これらは '
                'NTFS の拡張機能に関する情報を保持します。<code>$ObjId</code> はファイルのオブジェクト ID、<code>$Quota</code> '
                'はクォータを有効にしたボリュームの上限と動作設定、<code>$UsnJrnl</code> はファイルとディレクトリの変更を記録します。<code>$Reparse</code> '
                'は、ボリューム上のどのファイルやディレクトリに再解析データがあるかを記録します。</p>\n'
                '<p><code>$Deleted</code> には、POSIX '
                '方式で削除された、ユーザーからは見えないファイルが入ります。最初に削除を要求したアプリケーションがハンドルを閉じると、ファイルはこのディレクトリに移されます。元のファイル名は名前空間から消えますが、有効な参照を保持する別のアプリケーションは、そのファイルを引き続き操作できます。詳しくは前述の「POSIX '
                '方式のファイル削除」を参照してください。</p>\n'
                '<p>既定リソースマネージャーのディレクトリには、トランザクション NTFS（TxF）を支えるログディレクトリ '
                '<code>$TxfLog</code>、トランザクション分離用ディレクトリ <code>$Txf</code>、および修復用の <code>$Repair</code> '
                'があります。<code>$TxfLog</code> には TxF のベースログファイル <code>$TxfLog.blf</code> '
                'と、トランザクションログのサイズに応じた数のログコンテナーが入ります。コンテナーは最低でも2つあり、<code>$TxfLogContainer00000000000000000001</code> '
                'はカーネルトランザクションマネージャー（KTM）のログストリーム、<code>$TxfLogContainer00000000000000000002</code> は TxF '
                'のログストリームに使います。このディレクトリには、後述する TxF の旧ページストリーム <code>$Tops</code> も含まれます。</p>',
 'p2-page-691': '<h4>実験\u3000NTFS のボリューム情報を確認する</h4>\n'
                '<p>組み込みのコマンドラインツール <code>Fsutil.exe</code> で、NTFS ボリュームの情報を表示できます。出力には、MFT と MFT '
                'ゾーンの位置やサイズが含まれます。</p>\n'
                '<pre><code>d:&#92;&gt;fsutil fsinfo ntfsinfo d:\n'
                'NTFS ボリュームのシリアル番号 : 0x48323940323933f2\n'
                'NTFS バージョン               : 3.1\n'
                'LFS バージョン                : 2.0\n'
                'セクター数                    : 0x000000011c5f6fff\n'
                '総クラスター数                : 0x00000000238bedff\n'
                '空きクラスター数              : 0x000000001a6e5925\n'
                '予約済みクラスターの総数      : 0x00000000000011cd\n'
                '論理セクターあたりのバイト数  : 512\n'
                '物理セクターあたりのバイト数  : 4096\n'
                'クラスターあたりのバイト数    : 4096\n'
                'ファイルレコードセグメントあたりのバイト数    : 4096\n'
                'ファイルレコードセグメントあたりのクラスター数: 1\n'
                'MFT の有効データ長            : 0x0000000646500000\n'
                'MFT の開始 LCN                : 0x00000000000c0000\n'
                'MFT ミラーの開始 LCN          : 0x0000000000000002\n'
                'MFT ゾーンの開始位置          : 0x00000000069f76e0\n'
                'MFT ゾーンの終了位置          : 0x00000000069f7700\n'
                'デバイスの TRIM 範囲数の上限  : 4294967295\n'
                'デバイスの TRIM バイト数の上限: 0x10000000\n'
                'ボリュームの TRIM 範囲数の上限: 62\n'
                'ボリュームの TRIM バイト数の上限: 0x10000000\n'
                'リソースマネージャーの識別子  : 81E83020-E6FB-11E8-B862-D89EF33A38A7</code></pre>\n'
                '<p>この例の D: ボリュームは、512バイトの論理セクターを提示する4 KB の物理セクターのディスク上にあります。ファイルレコード（MFT エントリ）もクラスターも4 KB '
                'です。</p>\n'
                '<h4>ファイルレコード番号</h4>\n'
                '<p>NTFS ボリューム上のファイルは、ファイル番号とシーケンス番号からなる64ビットのファイルレコード番号で識別されます。ファイル番号は、MFT '
                '内でのファイルレコードの位置から1を引いた値です。1つのファイルに複数のレコードがあれば、ベースファイルレコードの位置を使います。MFT '
                'のレコード位置が再利用されるたびにシーケンス番号が増えるため、NTFS は古い参照を検出し、内部の整合性を確認できます。</p>\n'
                '<p>図11-33 ファイルレコード番号。下位48ビット（ビット0〜47）がファイル番号、上位16ビット（ビット48〜63）がシーケンス番号です。</p>',
 'p2-page-692': '<h4>ファイルレコード</h4>\n'
                '<p>NTFS '
                'はファイルを属性と値の組の集まりとして格納します。テキストやバイナリの内容は、そのうちの1つである名前のないデータ属性に入ります。ファイルを構成するほかの属性には、ファイル名、タイムスタンプ、必要に応じて追加される名前付きデータ属性があります。図11-34に小さなファイルの '
                'MFT レコードの例を示します。</p>\n'
                '<p>図11-34 小さなファイルの MFT レコード。マスターファイルテーブルの1件のレコードに、標準情報、ファイル名、データの各属性が格納されています。</p>\n'
                '<p>ファイルの各属性は、独立したバイト列であるストリームとして保存されます。NTFS '
                'が実際に読み書きするのは、ファイル内の属性ストリームです。属性に対しては作成、削除、バイト範囲の読み取り、バイト範囲の書き込みができます。通常、読み書きの処理は名前のないデータ属性を対象にします。呼び出し元は、名前付きデータストリームの構文で別のデータ属性を指定できます。</p>\n'
                '<p>表11-6に NTFS '
                'ボリューム上のファイルが持ち得る属性を示します。あるファイルがすべての属性を持つとは限りません。各属性には名前を付けることも、名前を付けずに使うこともできます。名前付き属性の一例は、NTFS '
                'の複数のコンポーネントが異なる目的で使う <code>$LOGGED_UTILITY_STREAM</code> です。指定できる名前とその用途を表11-7に示します。</p>',
 'p2-page-693': '<table>\n'
                '<caption>表11-6 NTFS ファイルの属性</caption>\n'
                '<thead><tr><th>属性</th><th>属性型の名前</th><th>常駐の有無</th><th>説明</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><th '
                'scope="row">ボリューム情報</th><td><code>$VOLUME_INFORMATION</code>、<code>$VOLUME_NAME</code></td><td>両方とも常駐</td><td>メタデータファイル '
                '$Volume にだけ存在し、ボリュームのバージョンとラベルを保存します。</td></tr>\n'
                '<tr><th '
                'scope="row">標準情報</th><td><code>$STANDARD_INFORMATION</code></td><td>常に常駐</td><td>読み取り専用やアーカイブなどのファイル属性と、作成日時や最終変更日時などのタイムスタンプを保存します。</td></tr>\n'
                '<tr><th scope="row">ファイル名</th><td><code>$FILE_NAME</code></td><td>場合による</td><td>Unicode 1.0 '
                'の文字で表したファイル名です。ハードリンクがある場合や、長いファイル名に対して MS-DOS や16ビット Windows '
                'アプリケーション用の短い名前が自動生成された場合など、1つのファイルが複数のファイル名属性を持つことがあります。</td></tr>\n'
                '<tr><th '
                'scope="row">セキュリティ記述子</th><td><code>$SECURITY_DESCRIPTOR</code></td><td>場合による</td><td>以前の '
                'NTFS との互換性のために残っており、NTFS 3.1 ではめったに使われません。以前の NTFS '
                'はファイルやディレクトリごとに個別のセキュリティ記述子を保存していました。現在はほとんどの記述子をメタデータファイル $Secure '
                'に保存し、設定が同じファイルやディレクトリ間で共有します。$Boot など、一部のファイルには今も $SECURITY_DESCRIPTOR 属性があります。</td></tr>\n'
                '<tr><th scope="row">データ</th><td><code>$DATA</code></td><td>場合による</td><td>ファイルの内容です。NTFS '
                'ファイルには既定の名前なしデータ属性が1つあり、名前付きのデータ属性を追加することで複数のデータストリームを持てます。ディレクトリには既定のデータ属性がありませんが、名前付きのデータ属性を追加できます。名前付きデータストリームはシステム固有の用途にも使われます。たとえばストレージサービスは、ボリュームに領域を予約するためにストレージ予約領域テーブル（SRAT）のストリーム '
                '$SRAT を使います。この属性はメタデータファイル $Bitmap にだけ適用されます。ストレージ予約については本章の後半で説明します。</td></tr>\n'
                '<tr><th '
                'scope="row">インデックスルート、インデックス割り当て</th><td><code>$INDEX_ROOT</code>、<code>$INDEX_ALLOCATION</code></td><td>順に常駐、非常駐</td><td>これらとインデックスビットマップの3つの属性は、ディレクトリや、セキュリティ、クォータなどのメタデータファイルで使う '
                'B 木を実装します。</td></tr>\n'
                '<tr><th '
                'scope="row">属性リスト</th><td><code>$ATTRIBUTE_LIST</code></td><td>場合による</td><td>ファイルを構成する属性と、各属性を格納する '
                'MFT エントリのファイルレコード番号を列挙します。1つのファイルに複数の MFT ファイルレコードが必要な場合に存在します。</td></tr>\n'
                '<tr><th '
                'scope="row">インデックスビットマップ</th><td><code>$BITMAP</code></td><td>場合による</td><td>用途は対象によって異なります。非常駐のディレクトリには '
                '$INDEX_ALLOCATION があり、ビットマップは B 木で使用中の4 KBのインデックスブロックと、B 木の拡張に使える空きブロックを記録します。MFT には名前のない '
                '$Bitmap 属性があり、使用中の MFT セグメントと、新規ファイルや追加領域が必要な既存ファイルに割り当てられる空きセグメントを記録します。</td></tr>\n'
                '</tbody></table>',
 'p2-page-694': '<table><caption>表11-6 NTFS ファイルの属性（続き）</caption>\n'
                '<thead><tr><th>属性</th><th>属性型の名前</th><th>常駐の有無</th><th>説明</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><th scope="row">オブジェクト '
                'ID</th><td><code>$OBJECT_ID</code></td><td>常に常駐</td><td>ファイルまたはディレクトリを識別する16バイトの GUID '
                'です。リンク追跡サービスはシェルのショートカットや OLE リンクの参照元ファイルに ID を割り当てます。NTFS の API '
                'を使うと、ファイルやディレクトリを名前の代わりにオブジェクト ID で開けます。</td></tr>\n'
                '<tr><th '
                'scope="row">再解析情報</th><td><code>$REPARSE_POINT</code></td><td>場合による</td><td>ファイルの再解析ポイントのデータを格納します。NTFS '
                'のジャンクションとマウントポイントがこの属性を持ちます。</td></tr>\n'
                '<tr><th '
                'scope="row">拡張属性</th><td><code>$EA、$EA_INFORMATION</code></td><td>順に場合による、常に常駐</td><td>名前と値の組です。通常は使われませんが、OS/2 '
                'アプリケーションとの互換性のために提供されます。</td></tr>\n'
                '<tr><th '
                'scope="row">ログ付きユーティリティストリーム</th><td><code>$LOGGED_UTILITY_STREAM</code></td><td>場合による</td><td>NTFS '
                'のコンポーネントがそれぞれの用途に使う属性型です。詳細は表11-7を参照してください。</td></tr>\n'
                '</tbody></table>\n'
                '<table><caption>表11-7 $LOGGED_UTILITY_STREAM 属性</caption>\n'
                '<thead><tr><th>属性</th><th>属性型の名前</th><th>常駐の有無</th><th>説明</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><th scope="row">暗号化ファイルストリーム</th><td><code>$EFS</code></td><td>場合による</td><td>EFS '
                'がファイルの暗号化を管理するためのデータを格納します。たとえば、ファイルの復号に必要な鍵を暗号化したものや、ファイルへのアクセスを許可されたユーザーの一覧が含まれます。</td></tr>\n'
                '<tr><th '
                'scope="row">オンライン暗号化のバックアップ</th><td><code>$EfsBackup</code></td><td>場合による</td><td>EFS '
                'のオンライン暗号化が、元の暗号化済みデータストリームの断片を格納します。</td></tr>\n'
                '<tr><th scope="row">トランザクション NTFS '
                'データ</th><td><code>$TXF_DATA</code></td><td>場合による</td><td>ファイルやディレクトリがトランザクションに参加すると、TxF '
                'はファイル固有のトランザクション ID などをこの属性に保存します。</td></tr>\n'
                '<tr><th '
                'scope="row">優先ストレージクラス</th><td><code>$DSC</code></td><td>常駐</td><td>ファイルを優先するストレージ階層に固定します。詳細は「階層化ボリュームの '
                'NTFS サポート」を参照してください。</td></tr>\n'
                '</tbody></table>\n'
                '<p>表11-6では属性を名前で示していますが、各属性型には数値の型コードが対応します。NTFS はこのコードの昇順に、MFT '
                'のファイルレコード内の属性を並べます。複数のデータ属性やファイル名がある場合など、同じ型が複数回現れることもあります。すべての属性型とその名前は、メタデータファイル '
                '<code>$AttrDef</code> に列挙されています。</p>\n'
                '<p>ファイルレコード内の各属性は、属性型コードで識別され、値と任意の名前を持ちます。属性の値は、その属性を構成するバイトストリームです。たとえば、<code>$FILE_NAME</code> '
                'の値はファイル名で、<code>$DATA</code> の値はユーザーがファイルに保存したバイト列です。</p>\n'
                '<p>ほとんどの属性に名前は付きませんが、インデックス関連の属性や <code>$DATA</code> '
                '属性には名前が付くことがあります。名前は、同じファイルにある同型の属性を区別するために使います。たとえば名前付きデータストリームを持つファイルには、2つの '
                '<code>$DATA</code> '
                '属性があります。名前なしの属性は既定の名前なしストリームを格納します。名前付きの属性は代替ストリームの名前を持ち、そのストリームのデータを格納します。</p>',
 'p2-page-695': '<h4>ファイル名</h4>\n'
                '<p>NTFS と FAT では、パスを構成する各ファイル名を最大255文字にできます。ファイル名には Unicode '
                '文字のほか、複数のピリオドや途中の空白も使えます。ただし、MS-DOS に付属する FAT ファイルシステムでは、ファイル名は Unicode '
                '以外の8文字と、ピリオドに続く3文字の拡張子に制限されます。Windows がサポートするファイル名前空間とその包含関係を図11-35に示します。</p>\n'
                '<p>Windows Subsystem for Linux（WSL）は、Windows '
                'がサポートするアプリケーション実行環境のうち最も広い名前空間を必要とします。このため、NTFS の名前空間は WSL の名前空間と同じです。WSL '
                'では末尾にピリオドや空白を含む名前など、Windows や MS-DOS のアプリケーションから見えない名前を作れます。広い POSIX 名前空間を使うのは、通常、そのファイルを '
                'WSL アプリケーションで使う場合なので、問題にはなりません。</p>\n'
                '<figure><table>\n'
                '<thead><tr><th>名前空間</th><th>ファイル名の例</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>WSL</td><td><code>TrailingDots...</code>、大文字と小文字だけが異なる '
                '<code>SameNameDifferentCase</code> と <code>samenamedifferentcase</code>、末尾に空白が3つある '
                '<code>TrailingSpaces</code></td></tr>\n'
                '<tr><td>Windows '
                'サブシステム</td><td><code>LongFileName</code>、<code>UnicodeName.</code>、<code>File.Name.With.Dots</code>、<code>File.Name2.With.Dots</code>、<code>Name '
                'With Embedded Spaces</code>、<code>.BeginningDot</code></td></tr>\n'
                '<tr><td>MS-DOS および16ビット Windows '
                'クライアント</td><td><code>EIGHTCHR.123</code>、<code>CASEBLND.TYP</code></td></tr>\n'
                '</tbody></table><figcaption>図11-35 Windows のファイル名前空間。WSL の範囲に Windows サブシステムの範囲が含まれ、その内側に '
                'MS-DOS と16ビット Windows のクライアントが扱える範囲があります。</figcaption></figure>\n'
                '<p>32ビット Windows アプリケーションと、MS-DOS や16ビット Windows アプリケーションの名前空間は、さらに近い関係にあります。図11-35の '
                'Windows の領域は、Windows サブシステムが NTFS ボリュームに作成でき、MS-DOS や16ビット Windows '
                'アプリケーションからはその名前で参照できないファイル名を表します。これには MS-DOS の8.3形式より長い名前、Unicode '
                'の国際文字を含む名前、ピリオドが複数ある名前やピリオドで始まる名前、途中に空白を含む名前が該当します。互換性のため、このような名前でファイルを作成すると、NTFS は MS-DOS '
                '形式の別名を自動生成します。Windows では <code>dir /x</code> でこれらの短い名前を表示できます。</p>\n'
                '<p>MS-DOS 形式のファイル名は、NTFS ファイルを同じように操作できる別名で、長いファイル名と同じディレクトリに格納されます。自動生成された MS-DOS '
                '形式のファイル名を持つファイルの MFT レコードを図11-36に示します。</p>',
 'p2-page-696': '<figure>\n'
                '<figcaption>図11-36 MS-DOS ファイル名属性を持つ MFT ファイルレコード</figcaption>\n'
                '<p>レコードには標準情報、NTFS ファイル名、MS-DOS ファイル名、データが含まれます。\n'
                'MS-DOS ファイル名は追加されたファイル名属性です。</p></figure>\n'
                '<p>NTFS のファイル名と自動生成された MS-DOS のファイル名は同じファイルレコードに格納され、同じファイルを指します。\n'
                'MS-DOS の名前で、ファイルを開いたり、読み書きしたり、コピーしたりできます。\n'
                '長い名前と短い名前のどちらを指定して名前を変更しても、新しい名前が既存の両方の名前に置き換わります。\n'
                '新しい名前が有効な MS-DOS の名前でなければ、NTFS は別の MS-DOS の名前を生成します。\n'
                'NTFS が MS-DOS 形式の名前を生成するのは、最初のファイル名に対してだけです。</p>\n'
                '<blockquote><p><strong>注記</strong> ハードリンクの実装も似ています。\n'
                'ハードリンクを作ると、NTFS はファイルの MFT ファイルレコードにファイル名属性を追加し、新しいリンクが置かれるディレクトリのインデックス割り当て属性にエントリを追加します。\n'
                '複数のハードリンクがあるファイルでは、リンクを一つ削除してもファイルとそのレコードは残ります。\n'
                '最後のファイル名（ハードリンク）を削除した時点でファイルとレコードが削除されます。\n'
                '一方、NTFS の名前と自動生成された MS-DOS の名前が付いたファイルは、どちらの名前を指定してもファイルを削除できます。</p></blockquote>\n'
                '<p>NTFS は次の手順で長いファイル名から MS-DOS の名前を生成します。\n'
                'このアルゴリズムを実装しているカーネル関数は <code>RtlGenerate8dot3Name</code> で、将来の Windows '
                'リリースで動作が変わる可能性があります。\n'
                'CDFS、FAT、サードパーティー製ファイルシステムなど、ほかのドライバーもこの関数を使います。</p>\n'
                '<ol>\n'
                '<li>長い名前から、空白や Unicode 文字など、MS-DOS の名前に使えない文字を取り除きます。\n'
                '先頭と末尾のピリオドを取り除き、残ったピリオドのうち最後の一つだけを残します。</li>\n'
                '<li>ピリオドがある場合はその手前、なければ名前全体を最大6文字に切り詰めます。\n'
                'MS-DOS で使えない文字が一つでもあればこの処理を行うため、元から6文字以下の場合もあります。\n'
                '2文字以下なら、4桁の16進チェックサムを生成して末尾に連結します。\n'
                'さらに <code>~n</code> を付けます。\n'
                '<code>n</code> は1から始まり、切り詰めると同じ名前になるファイルを区別します。\n'
                'ピリオドがある場合は、その後ろを最大3文字に切り詰めます。</li>\n'
                '<li>結果を大文字に変換します。\n'
                'MS-DOS は大文字と小文字を区別しないため、この処理で大文字と小文字だけが異なる名前が生成されるのを防ぎます。</li>\n'
                '<li>生成した名前がディレクトリ内の既存の名前と重複したら、<code>~n</code> の番号を増やします。\n'
                '<code>n</code> が4を超え、チェックサムがまだ付いていない場合は、ピリオドより前の部分を2文字に切り詰め、4桁の16進チェックサムを生成して連結します。</li>\n'
                '</ol>',
 'p2-page-697': '<p>表11-8は図11-35に挙げた Windows の長いファイル名と、NTFS が生成する MS-DOS 形式の名前を示しています。\n'
                '現在のアルゴリズムと図11-35の例から、NTFS がどのような短い名前を生成するかが分かります。</p>\n'
                '<blockquote><p><strong>注記</strong> Windows 8.1以降では、起動用でない NTFS ボリュームの短いファイル名の生成は既定で無効です。\n'
                '古い Windows でも、レジストリの '
                '<code>HKLM\\SYSTEM\\CurrentControlSet\\Control\\FileSystem\\NtfsDisable8dot3NameCreation</code> '
                'に DWORD 値の1を設定して再起動すれば、短い名前の生成を無効にできます。\n'
                'これにより古いアプリケーションとの互換性が失われる可能性があります。</p></blockquote>\n'
                '<table><caption>表11-8 NTFS が生成するファイル名</caption>\n'
                '<thead><tr><th>Windows の長い名前</th><th>NTFS が生成する短い名前</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td><code>LongFileName</code></td><td><code>LONGFI~1</code></td></tr>\n'
                '<tr><td><code>UnicodeName.FDPL</code></td><td><code>UNICOD~1</code></td></tr>\n'
                '<tr><td><code>File.Name.With.Dots</code></td><td><code>FILENA~1.DOT</code></td></tr>\n'
                '<tr><td><code>File.Name2.With.Dots</code></td><td><code>FILENA~2.DOT</code></td></tr>\n'
                '<tr><td><code>File.Name3.With.Dots</code></td><td><code>FILENA~3.DOT</code></td></tr>\n'
                '<tr><td><code>File.Name4.With.Dots</code></td><td><code>FILENA~4.DOT</code></td></tr>\n'
                '<tr><td><code>File.Name5.With.Dots</code></td><td><code>FIF596~1.DOT</code></td></tr>\n'
                '<tr><td><code>Name With Embedded Spaces</code></td><td><code>NAMEWI~1</code></td></tr>\n'
                '<tr><td><code>.BeginningDot</code></td><td><code>BEGINN~1</code></td></tr>\n'
                '<tr><td><code>25¢.two characters</code></td><td><code>255440~1.TWO</code></td></tr>\n'
                '<tr><td><code>©</code></td><td><code>6E2D~1</code></td></tr>\n'
                '</tbody></table>\n'
                '<h4>トンネリング</h4>\n'
                '<p>古いプログラムには、ファイルが削除されたり名前を変更されたりした後も、ファイルシステムが特定のメタデータを一定時間保持することを前提とするものがあります。\n'
                'NTFS は<strong>トンネリング</strong>によってこの動作との互換性を保ちます。\n'
                '一定時間内に元のファイルと同じ名前で新しいファイルを作成すると、一部のメタデータを引き継ぎます。</p>\n'
                '<p>この仕組みは、MS-DOS のプログラムが安全に保存する手順で想定していた動作を再現します。\n'
                'この手順では、変更したデータを一時ファイルにコピーし、元のファイルを削除して、一時ファイルを元の名前に変更します。\n'
                '名前を変更した一時ファイルは元のファイルと同じように見えることが期待されます。\n'
                '作成日時を引き継がなければ、更新のたびに変更日時と同様に作成日時も変わってしまいます。</p>\n'
                '<p>ディレクトリからファイル名が取り除かれると、NTFS は長い名前、短い名前、作成日時をキャッシュに保存します。\n'
                'ディレクトリにファイルが追加されると、引き継ぐデータがあるかどうかをキャッシュで調べます。\n'
                'これらの処理はディレクトリ単位で行うため、ディレクトリごとにキャッシュがあり、ディレクトリを削除すると対応するキャッシュも削除されます。</p>',
 'p2-page-698': '<p>次の操作の組み合わせで同じファイル名が取り除かれ、再び作られると、NTFS はトンネリングを適用します。</p>\n'
                '<ul>\n'
                '<li>削除してから作成</li>\n'
                '<li>削除してから名前を変更</li>\n'
                '<li>名前を変更してから作成</li>\n'
                '<li>名前を変更してから別のファイルの名前を変更</li>\n'
                '</ul>\n'
                '<p>NTFS は既定でトンネリングのキャッシュを15秒間保持します。\n'
                '保持時間を変更するには、レジストリキー <code>HKLM\\SYSTEM\\CurrentControlSet\\Control\\FileSystem</code> に '
                '<code>MaximumTunnelEntryAgeInSeconds</code> という値を作成します。\n'
                '<code>MaximumTunnelEntries</code> を新規作成して0に設定すると、トンネリングを完全に無効にできます。\n'
                '無効にすると、この互換動作に依存する古いアプリケーションが動作しなくなります。\n'
                '前節で説明した短いファイル名の生成を無効にしている NTFS ボリュームでは、トンネリングも既定で無効です。</p>\n'
                '<p>コマンドプロンプトで次の実験を行うと、トンネリングの動作を確認できます。</p>\n'
                '<ol>\n'
                '<li><code>file1</code> というファイルを作成します。</li>\n'
                '<li>既定のキャッシュ保持時間である15秒より長く待ちます。</li>\n'
                '<li><code>file2</code> というファイルを作成します。</li>\n'
                '<li><code>dir /TC</code> を実行し、それぞれの作成日時を控えます。</li>\n'
                '<li><code>file1</code> を <code>file</code> に改名します。</li>\n'
                '<li><code>file2</code> を <code>file1</code> に改名します。</li>\n'
                '<li><code>dir /TC</code> を実行し、両方のファイルの作成日時が一致することを確認します。</li>\n'
                '</ol>\n'
                '<h4>常駐属性と非常駐属性</h4>\n'
                '<p>小さなファイルでは、すべての属性とその値（ファイルのデータなど）が、そのファイルを記述するファイルレコードに収まります。\n'
                '属性値が MFT 内にある場合、その属性を<strong>常駐属性</strong>と呼びます。\n'
                '格納先はファイルの主レコードでも、MFT 内の別の場所にある拡張レコードでもかまいません。\n'
                '図11-37の例は、すべての属性が常駐する場合です。\n'
                'NTFS が非常駐属性の位置を特定できるよう、一部の属性は常駐すると定められています。\n'
                'たとえば標準情報属性とインデックスルート属性は常に常駐します。</p>\n'
                '<p>各属性の先頭には標準ヘッダーがあり、NTFS はそこに記録された情報を使って異なる種類の属性を共通の方法で管理します。\n'
                'ヘッダーは常駐し、属性値が常駐か非常駐かを記録します。\n'
                '常駐属性の場合、値のヘッダーからのオフセットと長さも記録します。\n'
                '図11-37にファイル名属性の例を示します。</p>\n'
                '<p>属性値を MFT に直接格納すると、NTFS が値を取得する時間が大幅に短くなります。</p>',
 'p2-page-699': '<p>たとえば FAT は、テーブルでファイルを検索した後、データを見つけるまで割り当て単位を順に読み取ります。\n'
                'MFT に値が直接格納されていれば、NTFS はディスクに一度アクセスするだけでデータを取得できます。</p>\n'
                '<figure><p>標準情報、ファイル名、データのうち、ファイル名属性のヘッダーには「常駐」、オフセット <code>8h</code>、長さ <code>18h</code> '
                'が記録されています。\n'
                '属性値は <code>MYFILE.DAT</code> です。</p>\n'
                '<figcaption>図11-37 常駐属性のヘッダーと値</figcaption></figure>\n'
                '<p>図11-38に示すように、小さなディレクトリの属性も MFT に常駐できます。\n'
                '小さなディレクトリのインデックスルート属性には、配下のファイルとサブディレクトリのファイルレコード番号を B 木にまとめたインデックスが入ります。</p>\n'
                '<figure><p>MFT レコードには標準情報、ファイル名、インデックスルートがあり、インデックスには '
                '<code>file1</code>、<code>file2</code>、<code>file3</code> などが並びます。\n'
                'レコードには空き領域もあります。</p>\n'
                '<figcaption>図11-38 小さなディレクトリの MFT ファイルレコード</figcaption></figure>\n'
                '<p>ファイルやディレクトリの属性値は、固定長の1 KB または4 KB の MFT レコードに収まらないことがあります。\n'
                'ファイルのデータ属性など、属性値が大きすぎる場合、NTFS はその値のために MFT の外にクラスターを割り当てます。\n'
                '連続するクラスターのまとまりを<strong>ラン</strong>または<strong>エクステント</strong>と呼びます。\n'
                'ファイルにデータを追記するなどして属性値が大きくなると、NTFS は増えた分のデータに別のランを割り当てます。\n'
                '値をランに格納する属性を<strong>非常駐属性</strong>と呼びます。\n'
                '常駐か非常駐かはファイルシステムが決めるため、アクセスするプロセスはデータの格納場所を意識する必要がありません。</p>\n'
                '<p>大きなファイルのデータ属性などが非常駐である場合、ヘッダーにはディスク上の属性値を特定するために必要な情報が入ります。\n'
                '図11-39に、2つのランに格納された非常駐データ属性を示します。</p>\n'
                '<figure><p>MFT のレコードには標準情報、ファイル名、データの各属性があり、NTFS の拡張属性も示されています。\n'
                'データ属性の値はレコード外の2つのデータランに格納されています。</p>\n'
                '<figcaption>図11-39 2つのデータランを持つ大きなファイルの MFT ファイルレコード</figcaption></figure>',
 'p2-page-700': '<p>標準の属性のうち、非常駐になり得るのはサイズが増える属性だけです。\n'
                'ファイルではデータ属性と属性リストがこれに該当します。\n'
                '属性リストは図11-39では省略しています。\n'
                '標準情報属性とファイル名属性は常に常駐します。</p>\n'
                '<p>図11-40に示すように、大きなディレクトリでも、属性全体またはその一部が非常駐になることがあります。\n'
                'この例では、ディレクトリ内のファイルを索引付けする B 木が MFT ファイルレコードに収まりません。\n'
                'インデックスの一部はインデックスルート属性に格納され、残りは<strong>インデックス割り当て</strong>と呼ばれる非常駐のランに格納されます。\n'
                '図ではインデックスルート、インデックス割り当て、ビットマップの各属性を簡略化しています。\n'
                'これらの属性は次節で詳しく説明します。\n'
                '標準情報属性とファイル名属性は常に常駐します。\n'
                'ディレクトリの場合、インデックスルート属性のヘッダーと、値の少なくとも一部も常駐します。</p>\n'
                '<figure><p>MFT ファイルレコードには標準情報、ファイル名、インデックスルート、インデックス割り当て、ビットマップの各属性が並びます。\n'
                'ファイルのインデックスは、インデックスルート側の <code>file4</code>、<code>file8</code> と、外部のインデックスバッファーにある '
                '<code>file1</code>、<code>file2</code>、<code>file3</code>、<code>file5</code>、<code>file6</code> '
                'に分かれています。</p>\n'
                '<figcaption>図11-40 非常駐のファイル名インデックスを持つ大きなディレクトリの MFT ファイルレコード</figcaption></figure>\n'
                '<p>属性値が MFT ファイルレコードに収まらず別途領域を割り当てる場合、NTFS は VCN と LCN の対応でランを管理します。\n'
                'LCN はボリューム全体のクラスターに0から <var>n</var> までの番号を付けます。\n'
                'VCN は個々のファイルに属するクラスターに0から <var>m</var> までの番号を付けます。\n'
                '図11-41に、非常駐データ属性のクラスター番号の例を示します。</p>\n'
                '<figure>\n'
                '<table><thead><tr><th>ファイル16のデータラン</th><th>VCN</th><th>LCN</th></tr></thead>\n'
                '<tbody><tr><td>1番目</td><td>0〜3</td><td>1355〜1358</td></tr>\n'
                '<tr><td>2番目</td><td>4〜7</td><td>1588〜1591</td></tr></tbody></table>\n'
                '<figcaption>図11-41 非常駐データ属性の '
                'VCN。ファイル16のレコードには標準情報、ファイル名、データの属性があり、データは2つのランに格納されています。</figcaption></figure>\n'
                '<p>このファイルに3つ目のランがあれば、その先頭は VCN 8 になります。\n'
                '図11-42に示すように、データ属性ヘッダーには2つのランの VCN と LCN の対応が記録され、NTFS はそこからディスク上の割り当て位置を特定できます。</p>',
 'p2-page-701': '<figure>\n'
                '<p>ファイル16の MFT レコードには標準情報、ファイル名、データの各属性があります。\n'
                'データ属性のヘッダーは、次の2つのデータランを記録します。</p>\n'
                '<table><thead><tr><th>開始 VCN</th><th>開始 LCN</th><th>クラスター数</th></tr></thead>\n'
                '<tbody><tr><td>0</td><td>1355</td><td>4</td></tr><tr><td>4</td><td>1588</td><td>4</td></tr></tbody></table>\n'
                '<figcaption>図11-42 非常駐データ属性の VCN と LCN の対応。VCN 0〜3 は LCN 1355〜1358、VCN 4〜7 は LCN 1588〜1591 '
                'に対応します。</figcaption></figure>\n'
                '<p>図11-41ではデータのランだけを示しましたが、MFT ファイルレコードに収まらない属性はほかの種類でもランに格納できます。\n'
                'ファイルの属性が多く、1つの MFT レコードに収まらない場合は、追加の属性を2つ目の MFT レコードに格納します。\n'
                '非常駐属性の場合は、そのヘッダーを2つ目のレコードに格納します。\n'
                'この場合、NTFS は<strong>属性リスト</strong>を追加します。\n'
                '属性リストには、ファイルの各属性の名前と型コード、およびその属性を格納する MFT レコードのファイル番号が入ります。</p>\n'
                '<p>属性リストは、すべての属性が1つのファイルレコードに収まらない場合に使います。\n'
                'ファイルが極端に大きくなったり断片化したりして、すべてのランを特定するための VCN と LCN の対応が1つの MFT レコードに収まらなくなった場合にも使います。\n'
                'ランが200を超えるファイルでは、通常、属性リストが必要です。\n'
                '属性ヘッダーは常に MFT のファイルレコード内にあります。\n'
                '属性値は、MFT の外にある1つ以上のエクステントに格納されることがあります。</p>\n'
                '<h4>データ圧縮とスパースファイル</h4>\n'
                '<p>NTFS は LZ77 の変種である LZNT1 を使って、ファイル、ディレクトリ、ボリューム単位の圧縮をサポートします。\n'
                'NTFS 圧縮の対象はユーザーデータだけです。ファイルシステムのメタデータは対象外です。</p>\n'
                '<p>Windows 8.1以降では、圧縮率が最も高い LZX や、処理速度の高い順に4 KB、8 KB、16 KB のブロックサイズを選べる XPRESS '
                'など、新しいアルゴリズムでもファイルを圧縮できます。\n'
                'この圧縮は、シェルの <code>compact</code> コマンドや File Provider API から利用できます。\n'
                '処理を担うのは NTFS ドライバーとは別のファイルシステムフィルタードライバー、Windows Overlay '
                'Filter（WOF、<code>Wof.sys</code>）です。\n'
                'WOF は NTFS の代替データストリームとスパースファイルを使います。\n'
                'WOF の詳細は本書の範囲外です。<a '
                'href="https://devblogs.microsoft.com/oldnewthing/20190618-00/?p=102597">Microsoft '
                'の解説</a>を参照してください。</p>\n'
                '<p>ボリュームが圧縮されているかは Windows の <code>GetVolumeInformation</code> 関数で確認できます。\n'
                'ファイルの実際の圧縮後サイズを取得するには <code>GetCompressedFileSize</code> を使います。\n'
                'ファイルやディレクトリの圧縮設定を確認または変更するには、<code>DeviceIoControl</code> 関数を使います。\n'
                '対応するファイルシステム制御コードは <code>FSCTL_GET_COMPRESSION</code> と <code>FSCTL_SET_COMPRESSION</code> '
                'です。</p>\n'
                '<p>ファイルの圧縮設定を変えると、その場で圧縮または展開が行われます。\n'
                'ディレクトリやボリュームの圧縮設定を変更した場合、設定されるのは既定の圧縮状態です。\n'
                '既存の内容はその場では圧縮も展開もされません。</p>',
 'p2-page-702': '<p>そのディレクトリやボリューム内に新しく作るファイルとサブディレクトリには、設定した既定の圧縮状態が適用されます。\n'
                'エクスプローラーでディレクトリのプロパティから圧縮を設定した場合は、ディレクトリツリー全体の内容がその場で圧縮されます。</p>\n'
                '<p>まずスパースデータの単純な圧縮を例に、NTFS の圧縮を説明します。\n'
                '続いて、通常のファイルとスパースファイルの圧縮を扱います。</p>\n'
                '<blockquote><p><strong>注記</strong> DAX ボリュームと暗号化されたファイルは、NTFS 圧縮の対象外です。</p></blockquote>\n'
                '<h5>スパースデータの圧縮</h5>\n'
                '<p><strong>スパースデータ</strong>はデータ全体が大きくても、そのサイズに比べてゼロ以外の値が少ないデータです。\n'
                '疎行列が一例です。\n'
                'NTFS は前述のように、ファイルのクラスターに0から <var>m</var> までの VCN を付けます。\n'
                '各 VCN は、ディスク上のクラスター位置を示す LCN に対応します。\n'
                '図11-43に、圧縮していない通常のファイルのラン（ディスク上の割り当て）と、VCN と LCN の対応を示します。</p>\n'
                '<figure><table><thead><tr><th>ラン</th><th>VCN</th><th>対応する LCN</th></tr></thead>\n'
                '<tbody><tr><td>1</td><td>0〜3</td><td>1355〜1358</td></tr>\n'
                '<tr><td>2</td><td>4〜7</td><td>1588〜1591</td></tr>\n'
                '<tr><td>3</td><td>8〜11</td><td>2033〜2036</td></tr></tbody></table>\n'
                '<figcaption>図11-43 圧縮していないファイルのラン</figcaption></figure>\n'
                '<p>このファイルは4クラスターずつの3つのランに格納され、合計で12クラスターを使います。\n'
                '図11-44に、このファイルの MFT レコードを示します。\n'
                '前述のように、MFT レコードのデータ属性では領域を節約するため、VCN と LCN の対応をクラスターごとではなくランごとに1件だけ格納します。\n'
                'その形式でも、VCN 0〜11 にはそれぞれ対応する LCN があります。\n'
                '最初の項目は VCN 0 から4クラスター、次は VCN 4 から4クラスターを表し、以降も同じ形式です。\n'
                'これは圧縮していないファイルの典型的な記録形式です。</p>\n'
                '<figure><p>MFT レコードには標準情報、ファイル名、データの各属性があります。\n'
                'データ属性は次の対応を格納します。</p>\n'
                '<table><thead><tr><th>開始 VCN</th><th>開始 LCN</th><th>クラスター数</th></tr></thead>\n'
                '<tbody><tr><td>0</td><td>1355</td><td>4</td></tr>\n'
                '<tr><td>4</td><td>1588</td><td>4</td></tr>\n'
                '<tr><td>8</td><td>2033</td><td>4</td></tr></tbody></table>\n'
                '<figcaption>図11-44 圧縮していないファイルの MFT レコード</figcaption></figure>\n'
                '<p>ユーザーが NTFS ボリューム上のファイルを圧縮するとき、NTFS が使う手法の一つは、ファイル内の長く連続するゼロを取り除くことです。\n'
                'データがスパースなら、通常、この手法によってディスク上の占有領域は元の数分の一になります。</p>',
 'p2-page-703': '<p>以降、そのファイルに書き込むとき、NTFS はゼロ以外のデータを含むランにだけ領域を割り当てます。</p>\n'
                '<p>図11-45はスパースデータを含む圧縮ファイルのランを示します。\n'
                'VCN 16〜31 と64〜127にはディスク領域が割り当てられていません。</p>\n'
                '<figure><table>\n'
                '<thead><tr><th>VCN</th><th>LCN</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>0〜15</td><td>133〜148</td></tr>\n'
                '<tr><td>32〜47</td><td>193〜208</td></tr>\n'
                '<tr><td>48〜63</td><td>96〜111</td></tr>\n'
                '<tr><td>128〜143</td><td>324〜339</td></tr>\n'
                '</tbody></table>\n'
                '<figcaption>図11-45 スパースデータを含む圧縮ファイルのラン</figcaption></figure>\n'
                '<p>この圧縮ファイルの MFT レコードには、データがすべてゼロで物理領域を割り当てていない VCN の範囲は記録されません。\n'
                'たとえば図11-46のデータ属性の最初の項目は VCN 0 から16クラスターを表します。\n'
                '2番目の項目は VCN 32 まで飛び、そこから16クラスターを表します。</p>\n'
                '<figure><p>MFT レコードには標準情報、ファイル名、データの各属性があります。\n'
                'データ属性には以下の対応が記録されています。</p>\n'
                '<table><thead><tr><th>開始 VCN</th><th>開始 LCN</th><th>クラスター数</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>0</td><td>133</td><td>16</td></tr>\n'
                '<tr><td>32</td><td>193</td><td>16</td></tr>\n'
                '<tr><td>48</td><td>96</td><td>16</td></tr>\n'
                '<tr><td>128</td><td>324</td><td>16</td></tr>\n'
                '</tbody></table>\n'
                '<figcaption>図11-46 スパースデータを含む圧縮ファイルの MFT レコード</figcaption></figure>\n'
                '<p>プログラムが圧縮ファイルからデータを読み取ると、NTFS は MFT レコードを調べ、読み取り位置を含む VCN と LCN の対応があるかを確認します。\n'
                '割り当てのない「穴」を読む場合、その部分のデータはすべてゼロなので、NTFS はディスクに追加でアクセスせずにゼロを返します。\n'
                'プログラムが穴にゼロ以外のデータを書き込む場合、NTFS はプログラムに意識させることなくディスク領域を割り当ててからデータを書き込みます。\n'
                'この手法は、ゼロを多く含むスパースなファイルデータに対して効率的です。</p>',
 'p2-page-704': '<h5>スパースでないデータの圧縮</h5>\n'
                '<p>前のスパースファイルの圧縮例は、説明のために単純化したものです。\n'
                'ファイルのいくつかの区間が丸ごとゼロで埋まっており、「圧縮」を行っても残りのデータは変化しませんでした。\n'
                'ほとんどのファイルのデータはスパースではありませんが、圧縮アルゴリズムを適用すれば圧縮できます。</p>\n'
                '<p>NTFS では、ファイル単位で圧縮を指定することも、ディレクトリ内のすべてのファイルに指定することもできます。\n'
                '圧縮を設定したディレクトリに新しく作るファイルは、自動的に圧縮されます。\n'
                'プログラムから <code>FSCTL_SET_COMPRESSION</code> で圧縮を有効にする場合、既存のファイルは個別に圧縮する必要があります。</p>\n'
                '<p>ファイルを圧縮するとき、NTFS は圧縮前のデータを16クラスターずつの<strong>圧縮単位</strong>に分けます。\n'
                'たとえば、1クラスターが8 KB なら、圧縮単位は128 KB です。\n'
                'データによってはほとんど、あるいはまったく圧縮できないこともあるため、NTFS は圧縮単位ごとに、圧縮で少なくとも1クラスター分の領域を節約できるかを調べます。</p>\n'
                '<p>1クラスターも節約できない場合は16クラスターのランを割り当て、その単位のデータを圧縮せずにディスクに書き込みます。\n'
                '15クラスター以下に圧縮できる場合は、圧縮後のデータを格納するのに必要な数だけクラスターを割り当て、書き込みます。</p>\n'
                '<p>図11-47に、4つのランを持つファイルを圧縮した例を示します。\n'
                '原図で網掛けのない領域が、圧縮後にファイルが実際に占有する領域です。\n'
                '1番目、2番目、4番目のランは圧縮され、3番目は圧縮されていません。\n'
                '非圧縮のランが1つあっても、このファイルの圧縮で26クラスター、約41%のディスク領域を節約できました。</p>\n'
                '<figure><table>\n'
                '<thead><tr><th>VCN</th><th>実際に占有する LCN</th><th>格納形式</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>0〜15</td><td>19〜22</td><td>圧縮</td></tr>\n'
                '<tr><td>16〜31</td><td>23〜30</td><td>圧縮</td></tr>\n'
                '<tr><td>32〜47</td><td>97〜112</td><td>非圧縮</td></tr>\n'
                '<tr><td>48〜63</td><td>113〜122</td><td>圧縮</td></tr>\n'
                '</tbody></table>\n'
                '<figcaption>図11-47 圧縮ファイルのデータラン</figcaption></figure>\n'
                '<blockquote><p><strong>注記</strong> 本章の図では連続した LCN '
                'を示していますが、1つの圧縮単位を物理的に連続したクラスターに格納する必要はありません。\n'
                '不連続なクラスターにまたがるランがある場合、MFT レコードは図11-47の例より少し複雑になります。</p></blockquote>',
 'p2-page-705': '<p>圧縮ファイルにデータを書き込むとき、NTFS は各ランを仮想アドレス上の16クラスター境界から始めます。\n'
                'したがって、各ランの開始 VCN は16の倍数で、長さは最大16クラスターです。\n'
                'NTFS は圧縮ファイルの読み書きを少なくとも1圧縮単位ずつ行います。\n'
                '圧縮データを書き込む際は、後から1回の I/O で読み取れるよう、圧縮単位をできるだけ物理的に連続した場所に格納します。</p>\n'
                '<p>圧縮単位を16クラスターとしたのは、内部断片化を抑えるためです。\n'
                '圧縮単位を大きくすると、データの格納に必要なディスク領域の合計は小さくなります。\n'
                '一方、キャッシュミスが発生するたびに16クラスター相当のデータを展開する必要があり、ランダムアクセスではキャッシュミスが起きやすくなります。\n'
                '16クラスターという大きさは、圧縮後のファイルサイズとランダム読み取りの速度を考慮したものです。\n'
                '図11-48は図11-47の圧縮ファイルの MFT レコードです。</p>\n'
                '<figure>\n'
                '<p>レコードは標準情報、ファイル名、データの各属性を持ちます。\n'
                'データ属性に記録されたランを表に示します。</p>\n'
                '<table><thead><tr><th>開始 VCN</th><th>開始 LCN</th><th>クラスター数</th></tr></thead>\n'
                '<tbody><tr><td>0</td><td>19</td><td>4</td></tr>\n'
                '<tr><td>16</td><td>23</td><td>8</td></tr>\n'
                '<tr><td>32</td><td>97</td><td>16</td></tr>\n'
                '<tr><td>48</td><td>113</td><td>10</td></tr></tbody></table>\n'
                '<figcaption>図11-48 圧縮ファイルの MFT レコード</figcaption></figure>\n'
                '<p>先ほどのスパースデータを含む圧縮ファイルの例と異なり、このファイルには16クラスター未満のランが3つあります。\n'
                'NTFS は MFT ファイルレコードからランの長さを読み取り、データが圧縮されているかを判断します。\n'
                '16クラスター未満のランには圧縮データが入り、そのデータを初めてキャッシュに読み込むときに展開します。\n'
                'ちょうど16クラスターのランには圧縮データが入っていないため、展開は不要です。</p>\n'
                '<p>ランのデータが圧縮されている場合、NTFS は作業用バッファーに展開してから、呼び出し元のバッファーにコピーします。\n'
                '展開済みのデータはキャッシュにも格納するため、同じランを再度読み取るときは、ほかのキャッシュ済みデータを読む場合と同じ速度で読み取れます。\n'
                'ファイルへの更新もキャッシュに書き込みます。\n'
                '遅延書き込みを担うレイジーライターが、変更されたデータを非同期に圧縮してディスクに書き込みます。\n'
                'この方法により、圧縮ファイルへの書き込みでも、非圧縮ファイルへの書き込みと比べて大きな遅延は生じません。</p>\n'
                '<p>NTFS は圧縮ファイルのディスク領域を可能な限り連続して割り当てます。\n'
                '図11-47の LCN を見ると、最初の2つのランと最後の2つのランがそれぞれ物理的に連続しています。\n'
                '2つ以上のランが連続していると、NTFS はほかのファイルのデータと同じようにディスクの先読みを行います。\n'
                'プログラムがデータを要求する前に、連続したデータを非同期に読み込んで展開します。\n'
                'その後はキャッシュから直接取得できるため、読み取り性能が大幅に向上します。</p>',
 'p2-page-706': '<h5>スパースファイル</h5>\n'
                '<p>NTFS のファイル種別である<strong>スパースファイル</strong>では、スパースでないデータには圧縮を適用しません。\n'
                '先に説明したスパースデータからなるファイルは、データの性質を指しています。\n'
                'NTFS はスパースファイルの MFT レコードにあるランの情報を、スパースなデータとそうでないデータが混在する圧縮ファイルと同じ方法で管理します。</p>\n'
                '<h5>変更ジャーナルファイル</h5>\n'
                '<p><strong>変更ジャーナルファイル</strong>（<code>\\$Extend\\$UsnJrnl</code>）は、NTFS '
                'がファイルやディレクトリの変更記録を格納するスパースファイルです。\n'
                'Windows のファイルレプリケーションサービス（FRS）や Windows Search '
                'サービスなどは、このジャーナルを使ってファイルやディレクトリの変更に随時対応します。</p>\n'
                '<p>ジャーナルは変更エントリを <code>$J</code> データストリームに、ジャーナルの最大サイズを <code>$Max</code> データストリームに格納します。\n'
                'エントリにはバージョンがあり、ファイルやディレクトリの変更について以下の情報を含みます。</p>\n'
                '<ul>\n'
                '<li>変更日時</li>\n'
                '<li>変更理由（表11-9参照）</li>\n'
                '<li>対象ファイルまたはディレクトリの属性</li>\n'
                '<li>対象ファイルまたはディレクトリの名前</li>\n'
                '<li>対象ファイルまたはディレクトリの MFT ファイルレコード番号</li>\n'
                '<li>親ディレクトリのファイルレコード番号</li>\n'
                '<li>セキュリティ ID</li>\n'
                '<li>レコードの更新シーケンス番号（USN）</li>\n'
                '<li>変更元（ユーザーや FRS など）についての追加情報</li>\n'
                '</ul>\n'
                '<table><caption>表11-9 変更ジャーナルの変更理由</caption>\n'
                '<thead><tr><th>識別子</th><th>理由</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td><code>USN_REASON_DATA_OVERWRITE</code></td><td>ファイルまたはディレクトリのデータが上書きされました。</td></tr>\n'
                '<tr><td><code>USN_REASON_DATA_EXTEND</code></td><td>ファイルまたはディレクトリにデータが追加されました。</td></tr>\n'
                '<tr><td><code>USN_REASON_DATA_TRUNCATION</code></td><td>ファイルまたはディレクトリのデータが切り詰められました。</td></tr>\n'
                '<tr><td><code>USN_REASON_NAMED_DATA_OVERWRITE</code></td><td>ファイルのデータストリームのデータが上書きされました。</td></tr>\n'
                '<tr><td><code>USN_REASON_NAMED_DATA_EXTEND</code></td><td>ファイルのデータストリームが拡張されました。</td></tr>\n'
                '<tr><td><code>USN_REASON_NAMED_DATA_TRUNCATION</code></td><td>ファイルのデータストリームのデータが切り詰められました。</td></tr>\n'
                '<tr><td><code>USN_REASON_FILE_CREATE</code></td><td>新しいファイルまたはディレクトリが作成されました。</td></tr>\n'
                '<tr><td><code>USN_REASON_FILE_DELETE</code></td><td>ファイルまたはディレクトリが削除されました。</td></tr>\n'
                '<tr><td><code>USN_REASON_EA_CHANGE</code></td><td>ファイルまたはディレクトリの拡張属性が変更されました。</td></tr>\n'
                '<tr><td><code>USN_REASON_SECURITY_CHANGE</code></td><td>ファイルまたはディレクトリのセキュリティ記述子が変更されました。</td></tr>\n'
                '<tr><td><code>USN_REASON_RENAME_OLD_NAME</code></td><td>ファイルまたはディレクトリが改名されました。このレコードは変更前の名前を示します。</td></tr>\n'
                '</tbody></table>',
 'p2-page-707': '<table><caption>表11-9 変更ジャーナルの変更理由（続き）</caption>\n'
                '<thead><tr><th>識別子</th><th>理由</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td><code>USN_REASON_RENAME_NEW_NAME</code></td><td>ファイルまたはディレクトリが改名されました。このレコードは変更後の名前を示します。</td></tr>\n'
                '<tr><td><code>USN_REASON_INDEXABLE_CHANGE</code></td><td>インデックスサービスが対象のファイルまたはディレクトリを処理するかどうかの設定が変わりました。</td></tr>\n'
                '<tr><td><code>USN_REASON_BASIC_INFO_CHANGE</code></td><td>ファイルまたはディレクトリの属性かタイムスタンプ、あるいは両方が変わりました。</td></tr>\n'
                '<tr><td><code>USN_REASON_HARD_LINK_CHANGE</code></td><td>ファイルまたはディレクトリへのハードリンクが追加または削除されました。</td></tr>\n'
                '<tr><td><code>USN_REASON_COMPRESSION_CHANGE</code></td><td>ファイルまたはディレクトリの圧縮状態が変わりました。</td></tr>\n'
                '<tr><td><code>USN_REASON_ENCRYPTION_CHANGE</code></td><td>ファイルまたはディレクトリの EFS '
                '暗号化が有効または無効になりました。</td></tr>\n'
                '<tr><td><code>USN_REASON_OBJECT_ID_CHANGE</code></td><td>ファイルまたはディレクトリのオブジェクト ID '
                'が変わりました。</td></tr>\n'
                '<tr><td><code>USN_REASON_REPARSE_POINT_CHANGE</code></td><td>ファイルまたはディレクトリの再解析ポイントが変更されたか、シンボリックリンクなどの再解析ポイントが追加または削除されました。</td></tr>\n'
                '<tr><td><code>USN_REASON_STREAM_CHANGE</code></td><td>ファイルのデータストリームが追加、削除、または改名されました。</td></tr>\n'
                '<tr><td><code>USN_REASON_TRANSACTED_CHANGE</code></td><td>変更理由とのビット単位の論理和により、直前にコミットした TxF '
                'トランザクションによる変更であることを示します。</td></tr>\n'
                '<tr><td><code>USN_REASON_CLOSE</code></td><td>ファイルまたはディレクトリのハンドルが閉じられ、この一連の操作での最後の変更であることを示します。</td></tr>\n'
                '<tr><td><code>USN_REASON_INTEGRITY_CHANGE</code></td><td>ファイルのエクステント（ラン）の内容が変わり、対応する整合性ストリームが新しいチェックサムで更新されました。この識別子は '
                'ReFS が生成します。</td></tr>\n'
                '<tr><td><code>USN_REASON_DESIRED_STORAGE_CLASS_CHANGE</code></td><td>ストリームが容量層とパフォーマンス層の間をどちらかの方向に移動したとき、NTFS '
                'ドライバーがこのイベントを生成します。</td></tr>\n'
                '</tbody></table>\n'
                '<h5>実験\u3000変更ジャーナルを読み取る</h5>\n'
                '<p>Windows 標準の <code>%SystemRoot%\\System32\\Fsutil.exe</code> '
                'を使うと、ジャーナルを作成、削除したり、その情報を照会したりできます。\n'
                '次は D: ボリュームのジャーナルを照会した例です。</p>\n'
                '<pre><code>d:\\&gt;fsutil usn queryjournal d:\n'
                'ジャーナル ID             : 0x01d48f4c3853cc72\n'
                '最初の USN                : 0x0000000000000000\n'
                '次の USN                  : 0x0000000000000a60\n'
                '有効な最小 USN            : 0x0000000000000000\n'
                '最大 USN                  : 0x7fffffffffff0000\n'
                '最大サイズ                : 0x0000000000a00000\n'
                '割り当ての増分            : 0x0000000000200000\n'
                '対応する最小レコードバージョン : 2\n'
                '対応する最大レコードバージョン : 4\n'
                '書き込み範囲の追跡         : 無効</code></pre>\n'
                '<p>出力には、ボリューム上の変更ジャーナルの最大サイズ（10 MB）と現在の状態が表示されます。\n'
                'NTFS が変更を記録する様子を確認するため、現在のディレクトリに <code>Usn.txt</code> を作成し、<code>UsnNew.txt</code> '
                'に改名してから、Fsutil でジャーナルを出力します。</p>\n'
                '<pre><code>d:\\&gt;echo Hello USN Journal! &gt; Usn.txt\n'
                'd:\\&gt;ren Usn.txt UsnNew.txt</code></pre>',
 'p2-page-708': '<pre><code>d:\\&gt;fsutil usn readjournal d:\n'
                '...\n'
                '\n'
                'USN\n'
                '                   : 2656\n'
                'ファイル名\n'
                '                   : USN.txt\n'
                'ファイル名の長さ  : 14\n'
                '理由\n'
                '                   : 0x00000100: ファイル作成\n'
                'タイムスタンプ\n'
                '                   : 12/8/2018 15:22:05\n'
                'ファイル属性   : 0x00000020: アーカイブ\n'
                'ファイル ID\n'
                '                   : 0000000000000000000c000000617912\n'
                '親ファイル ID    : 00000000000000000018000000617ab6\n'
                '変更元の情報\n'
                '                   : 0x00000000: なし\n'
                'セキュリティ ID\n'
                '                   : 0\n'
                'メジャーバージョン     : 3\n'
                'マイナーバージョン     : 0\n'
                'レコード長     : 96\n'
                '\n'
                'USN\n'
                '                   : 2736\n'
                'ファイル名\n'
                '                   : USN.txt\n'
                'ファイル名の長さ  : 14\n'
                '理由\n'
                '                   : 0x00000102: データ拡張 | ファイル作成\n'
                'タイムスタンプ\n'
                '                   : 12/8/2018 15:22:05\n'
                'ファイル属性   : 0x00000020: アーカイブ\n'
                'ファイル ID\n'
                '                   : 0000000000000000000c000000617912\n'
                '親ファイル ID    : 00000000000000000018000000617ab6\n'
                '変更元の情報\n'
                '                   : 0x00000000: なし\n'
                'セキュリティ ID\n'
                '                   : 0\n'
                'メジャーバージョン     : 3\n'
                'マイナーバージョン     : 0\n'
                'レコード長     : 96\n'
                '\n'
                'USN\n'
                '                   : 2816\n'
                'ファイル名\n'
                '                   : USN.txt\n'
                'ファイル名の長さ  : 14\n'
                '理由\n'
                '                   : 0x80000102: データ拡張 | ファイル作成 | ハンドルを閉じる\n'
                'タイムスタンプ\n'
                '                   : 12/8/2018 15:22:05\n'
                'ファイル属性   : 0x00000020: アーカイブ\n'
                'ファイル ID\n'
                '                   : 0000000000000000000c000000617912\n'
                '親ファイル ID    : 00000000000000000018000000617ab6\n'
                '変更元の情報\n'
                '                   : 0x00000000: なし\n'
                'セキュリティ ID\n'
                '                   : 0\n'
                'メジャーバージョン     : 3\n'
                'マイナーバージョン     : 0\n'
                'レコード長     : 96\n'
                '\n'
                'USN\n'
                '                   : 2896\n'
                'ファイル名\n'
                '                   : USN.txt\n'
                'ファイル名の長さ  : 14\n'
                '理由\n'
                '                   : 0x00001000: 改名前の名前\n'
                'タイムスタンプ\n'
                '                   : 12/8/2018 15:22:15\n'
                'ファイル属性   : 0x00000020: アーカイブ\n'
                'ファイル ID\n'
                '                   : 0000000000000000000c000000617912\n'
                '親ファイル ID    : 00000000000000000018000000617ab6\n'
                '変更元の情報\n'
                '                   : 0x00000000: なし\n'
                'セキュリティ ID\n'
                '                   : 0</code></pre>',
 'p2-page-709': '<pre><code>メジャーバージョン     : 3\n'
                'マイナーバージョン     : 0\n'
                'レコード長     : 96\n'
                '\n'
                'USN\n'
                '                   : 2976\n'
                'ファイル名\n'
                '                   : USNNew.txt\n'
                'ファイル名の長さ  : 20\n'
                '理由\n'
                '                   : 0x00002000: 改名後の名前\n'
                'タイムスタンプ\n'
                '                   : 12/8/2018 15:22:15\n'
                'ファイル属性   : 0x00000020: アーカイブ\n'
                'ファイル ID\n'
                '                   : 0000000000000000000c000000617912\n'
                '親ファイル ID    : 00000000000000000018000000617ab6\n'
                '変更元の情報\n'
                '                   : 0x00000000: なし\n'
                'セキュリティ ID\n'
                '                   : 0\n'
                'メジャーバージョン     : 3\n'
                'マイナーバージョン     : 0\n'
                'レコード長     : 96\n'
                '\n'
                'USN\n'
                '                   : 3056\n'
                'ファイル名\n'
                '                   : USNNew.txt\n'
                'ファイル名の長さ  : 20\n'
                '理由\n'
                '                   : 0x80002000: 改名後の名前 | ハンドルを閉じる\n'
                'タイムスタンプ\n'
                '                   : 12/8/2018 15:22:15\n'
                'ファイル属性   : 0x00000020: アーカイブ\n'
                'ファイル ID\n'
                '                   : 0000000000000000000c000000617912\n'
                '親ファイル ID    : 00000000000000000018000000617ab6\n'
                '変更元の情報\n'
                '                   : 0x00000000: なし\n'
                'セキュリティ ID\n'
                '                   : 0\n'
                'メジャーバージョン     : 3\n'
                'マイナーバージョン     : 0\n'
                'レコード長     : 96</code></pre>\n'
                '<p>各エントリは、コマンドラインで実行した操作に伴う個々の変更を記録しています。\n'
                'ボリュームで変更ジャーナルが有効になっていなければ、次のコマンドで作成できます。\n'
                'ファイル変更通知や USN ジャーナルの作成を要求したアプリケーションがない非システムボリュームでは、とくに無効のままになっていることがあります。\n'
                'この例では10 MBのジャーナルを要求します。</p>\n'
                '<pre><code>d:\\&gt;fsutil usn createJournal d: m=10485760 a=2097152</code></pre>\n'
                '<p>ジャーナルはスパースファイルなので、古い記録の領域を解放して容量超過を防げます。\n'
                '使用中のディスク領域がファイルに設定した上限を超えると、NTFS は最新の変更情報を上限サイズ分だけ残し、それより古い部分のデータをゼロに置き換えます（図11-49）。\n'
                'アプリケーションがジャーナルの上限を継続的に超える場合にサイズを頻繁に変更せずに済むよう、NTFS '
                'は設定上限を超えた分がアプリケーション指定の値の2倍に達した場合にだけ、ジャーナルを縮小します。</p>',
 'p2-page-710': '<figure>\n'
                '<p><code>$UsnJrnl:$J</code> の仮想サイズには、古い記録を解放した空き領域と、残っている変更エントリの領域の両方が含まれます。\n'
                '物理サイズに含まれるのは後者だけです。\n'
                '代替データストリーム <code>$J</code> の変更エントリには、ファイル名、変更の種類、変更日時、ファイルの MFT エントリ番号などが入ります。</p>\n'
                '<figcaption>図11-49 変更ジャーナル（<code>$UsnJrnl</code>）の領域割り当て</figcaption></figure>\n'
                '<h4>インデックス作成</h4>\n'
                '<p>NTFS のファイルディレクトリは、ファイル名と対応するファイルレコード番号を B 木にまとめたファイル名インデックスです。\n'
                'NTFS は、ディレクトリに含まれるファイルのファイル名属性から、このインデックスを作ります。\n'
                '図11-50にボリュームのルートディレクトリの MFT レコードを示します。</p>\n'
                '<figure><p>ファイル5の MFT '
                'レコードには、標準情報、ファイル名（<code>&#92;</code>）、インデックスルート、インデックス割り当て、ビットマップが入ります。\n'
                'インデックスルートにある <code>file4</code>、<code>file10</code>、<code>file15</code> '
                'の項目の間に、下位のインデックス領域がつながります。\n'
                'インデックス割り当て属性には、下位領域の位置を示す VCN と LCN の対応が入ります。</p>\n'
                '<table><thead><tr><th>VCN</th><th>LCN</th><th>インデックス内のファイル名</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>0〜3</td><td>1355〜1358</td><td><code>file0</code>、<code>file1</code>、<code>file3</code></td></tr>\n'
                '<tr><td>4〜7</td><td>1588〜1591</td><td><code>file6</code>、<code>file8</code>、<code>file9</code></td></tr>\n'
                '<tr><td>8〜11</td><td>2033〜2036</td><td><code>file11</code>、<code>file12</code>、<code>file13</code>、<code>file14</code></td></tr>\n'
                '</tbody></table>\n'
                '<figcaption>図11-50 ボリュームのルートディレクトリのファイル名インデックス</figcaption></figure>',
 'p2-page-711': '<p>概念上、ディレクトリの MFT エントリは、ディレクトリ内のファイルを並べ替えた一覧をインデックスルート属性に持ちます。\n'
                '大きなディレクトリでは、実際にはインデックス割り当て属性の非常駐の値である4 KB固定長のインデックスバッファーにファイル名を格納し、整理します。\n'
                'インデックスバッファーは B 木を構成し、とくに大きなディレクトリで、特定のファイルを探すために必要なディスクアクセスを少なくします。\n'
                'インデックスルート属性は B 木の最上位階層（ルート直下のサブディレクトリ）を保持し、次の階層を収めたインデックスバッファーを指します。\n'
                '次の階層には、さらに下位のサブディレクトリやファイルが入ることがあります。</p>\n'
                '<p>図11-50ではインデックスルート属性とインデックスバッファーにファイル名（たとえば <code>file6</code>）だけを示しています。\n'
                '実際のエントリには、ファイルを記述する MFT レコードの番号と、ファイルのタイムスタンプおよびサイズも入ります。\n'
                'これらのタイムスタンプとサイズは、ファイルの MFT レコードから複製したものです。\n'
                'FAT と NTFS が使うこの方式では、更新した情報を2か所に書き込む必要があります。\n'
                'その代わり、ディレクトリ内のすべてのファイルを個別に開かずにタイムスタンプとサイズを表示できるため、ディレクトリの閲覧が大幅に速くなります。</p>\n'
                '<p>インデックス割り当て属性は、インデックスバッファーを格納するランの VCN と、ディスク上の位置を表す LCN の対応を記録します。\n'
                'ビットマップ属性は、インデックスバッファーのどの VCN が使用中で、どれが空いているかを管理します。\n'
                '図11-50では1 VCN、つまり1クラスターあたり1件のファイルエントリを示しています。\n'
                '実際には、各クラスターにファイル名エントリを詰めて格納します。\n'
                '4 KBのインデックスバッファーには通常20〜30件ほど入り、実際の件数はディレクトリ内のファイル名の長さによって変わります。</p>\n'
                '<p>B 木は平衡木の一種です。\n'
                'エントリを検索するためのディスクアクセスを少なくできるので、ディスク上で整列済みのデータを管理するのに適しています。\n'
                'ディレクトリの MFT レコードのインデックスルート属性には、B 木の第2階層を探すための目印となるファイル名がいくつかあります。\n'
                'それぞれの名前には、インデックスバッファーへのポインターが付くことがあります。\n'
                'ポインターが指すバッファーには、辞書順でその名前より前に来る名前が入ります。\n'
                '図11-50では、最上位階層の <code>file4</code> が、辞書順でより前に来る '
                '<code>file0</code>、<code>file1</code>、<code>file3</code> を含むバッファーを指します。\n'
                '<code>file1</code> や <code>file3</code> などは、図に示された順に辞書順で並ぶファイルの相対位置を表すための例示名です。</p>\n'
                '<p>ファイル名を B 木に格納すると、名前が整列済みなのでディレクトリ内の検索が速くなります。\n'
                '上位のソフトウェアがディレクトリ内のファイルを列挙すると、NTFS は整列済みの名前を返します。\n'
                'B 木は深さより幅が増えやすいので、ディレクトリが大きくなっても検索の速さを保てます。</p>\n'
                '<p>NTFS はファイル名以外のデータにも汎用のインデックスを作れます。\n'
                'オブジェクト ID、クォータ追跡、セキュリティ情報の一元管理などの機能は、内部データの管理にインデックスを使います。\n'
                'B 木インデックスで管理できるデータには、セキュリティ記述子、セキュリティ ID、オブジェクト ID、ディスククォータのレコード、再解析ポイントがあります。\n'
                'ディレクトリのインデックスを<strong>ファイル名インデックス</strong>と呼び、その他の種類を<strong>ビューインデックス</strong>と呼びます。</p>',
 'p2-page-712': '<h5>オブジェクト ID</h5>\n'
                '<p>NTFS はファイルやディレクトリに割り当てたオブジェクト ID を、各 MFT レコードの <code>$OBJECT_ID</code> 属性に格納します。\n'
                'さらに、オブジェクト ID とファイルレコード番号の対応を、メタデータファイル <code>\\$Extend\\$ObjId</code> の <code>$O</code> '
                'インデックスで管理します。\n'
                'このインデックスは GUID であるオブジェクト ID の順にエントリを並べるため、NTFS は ID からファイルをすばやく探せます。\n'
                'アプリケーションはネイティブ API の <code>NtCreateFile</code> に <code>FILE_OPEN_BY_FILE_ID</code> '
                'フラグを指定すると、オブジェクト ID でファイルやディレクトリを開けます。\n'
                '図11-51に <code>$ObjId</code> メタデータファイルと MFT レコードの <code>$OBJECT_ID</code> 属性の対応を示します。</p>\n'
                '<figure><p>アプリケーションがファイルを開く際に渡したオブジェクト ID を、<code>$ObjId</code> の <code>$O</code> '
                'インデックスで引きます。\n'
                '<code>$ObjId</code> の MFT エントリは、標準情報、ファイル名、<code>$O</code> のインデックスルートとインデックス割り当てを持ちます。\n'
                '図のオブジェクト ID 0、1、2の各インデックスエントリには、対応する MFT エントリ番号と <code>FILE_OBJECTID_BUFFER</code> '
                'が入っています。\n'
                'ファイル1、2、3の MFT エントリにも、各ファイルの <code>$OBJECT_ID</code> 属性が入っています。</p>\n'
                '<figcaption>図11-51 <code>$ObjId</code> と <code>$OBJECT_ID</code> の関係</figcaption></figure>\n'
                '<h5>クォータ追跡</h5>\n'
                '<p>NTFS はクォータ情報をメタデータファイル <code>\\$Extend\\$Quota</code> に格納します。\n'
                'このファイルは名前付きインデックスルート属性の <code>$O</code> と <code>$Q</code> からなります。\n'
                '図11-52に両インデックスの構成を示します。\n'
                'NTFS はセキュリティ記述子ごとに固有の内部セキュリティ ID を割り当てるのと同様に、ユーザーごとに固有のユーザー ID を割り当てます。\n'
                '管理者がユーザーのクォータを設定すると、NTFS はユーザーの SID に対応するユーザー ID を割り当てます。\n'
                '<code>$O</code> インデックスに SID からユーザー ID への対応を作り、SID の順に並べます。\n'
                '<code>$Q</code> インデックスにはクォータ管理エントリを作ります。\n'
                'クォータ管理エントリにはユーザーのクォータ上限と、そのユーザーがボリューム上で消費しているディスク容量が入ります。</p>\n'
                '<p>アプリケーションがファイルやディレクトリを作成すると、NTFS はアプリケーションを実行するユーザーの SID を取得し、<code>$O</code> インデックスでユーザー '
                'ID を引きます。\n'
                'そのユーザー ID を新しいファイルやディレクトリの <code>$STANDARD_INFORMATION</code> '
                '属性に記録し、そこに割り当てたディスク容量をすべてユーザーのクォータ使用量に計上します。\n'
                '次に <code>$Q</code> インデックスのクォータエントリを調べ、新しい割り当てによってユーザーが警告しきい値または上限を超えるかどうかを判定します。</p>',
 'p2-page-713': '<p>新しい割り当てでしきい値を超えると、NTFS はシステムイベントログに記録したり、ファイルやディレクトリの作成を拒否したりします。\n'
                'ファイルやディレクトリのサイズが変わると、NTFS は <code>$STANDARD_INFORMATION</code> 属性に記録されたユーザー ID '
                'に対応するクォータ管理エントリを更新します。\n'
                'NTFS は汎用の B 木インデックスを使い、アカウントの SID とユーザー ID を効率よく対応付け、ユーザー ID からクォータ管理情報を検索します。</p>\n'
                '<figure>\n'
                '<p>ファイルやディレクトリの作成時は、アプリケーションから取得した SID を使い、<code>$O</code> インデックスでユーザー ID を引きます。\n'
                'ファイル操作時は、<code>$STANDARD_INFORMATION</code> 属性から取得したユーザー ID を使い、<code>$Q</code> '
                'インデックスでクォータエントリを引きます。</p>\n'
                '<table><thead><tr><th><code>$O</code> のキー</th><th><code>$O</code> の値および <code>$Q</code> '
                'のキー</th><th><code>$Q</code> の値</th></tr></thead>\n'
                '<tbody><tr><td>SID 0</td><td>ユーザー ID 0</td><td>ユーザー0のクォータエントリ</td></tr>\n'
                '<tr><td>SID 1</td><td>ユーザー ID 1</td><td>ユーザー1のクォータエントリ</td></tr>\n'
                '<tr><td>SID 2</td><td>ユーザー ID 2</td><td>ユーザー2のクォータエントリ</td></tr></tbody></table>\n'
                '<figcaption>図11-52 <code>$Quota</code> のインデックス</figcaption></figure>\n'
                '<h5>セキュリティ記述子の一元管理</h5>\n'
                '<p>NTFS は当初から、個々のファイルやディレクトリにアクセスできるユーザーを管理者が指定できる仕組みを備えています。\n'
                'セキュリティ記述子の格納に必要なディスク領域を節約するため、NTFS はメタデータファイル <code>$Secure</code> '
                'に、ボリューム上の各セキュリティ記述子を一つずつ格納します。</p>\n'
                '<p>図11-53に示すように、<code>$Secure</code> はインデックス属性の <code>$SDH</code>（セキュリティ記述子ハッシュ）と '
                '<code>$SII</code>（セキュリティ ID インデックス）、データストリーム属性の <code>$SDS</code>（セキュリティ記述子ストリーム）を持ちます。\n'
                'NTFS はボリューム上の異なるセキュリティ記述子に固有の内部セキュリティ ID を割り当て、単純なアルゴリズムで記述子のハッシュを求めます。\n'
                'コンピューターやユーザーアカウントを一意に識別する Windows の SID とは別の識別子です。\n'
                'ハッシュは記述子を短い値で表したもので、異なる記述子でも同じ値になることがあります。\n'
                '<code>$SDH</code> は記述子のハッシュを <code>$SDS</code> 内の格納位置に対応付けます。\n'
                '<code>$SII</code> は NTFS のセキュリティ ID を <code>$SDS</code> 内の格納位置に対応付けます。</p>\n'
                '<p>ファイルやディレクトリにセキュリティ記述子を適用すると、NTFS は記述子のハッシュを計算し、<code>$SDH</code> で一致する項目を探します。\n'
                '<code>$SDH</code> のエントリは対応する記述子のハッシュ順に並び、B 木に格納されています。\n'
                'ハッシュが一致したエントリのオフセットを使って、<code>$SDS</code> からセキュリティ記述子を読み取ります。\n'
                'ハッシュが一致しても記述子が異なるときは、同じハッシュを持つ別のエントリを探します。\n'
                '記述子まで一致すれば、適用先のファイルやディレクトリは <code>$SDS</code> の既存の記述子を参照できます。</p>',
 'p2-page-714': '<p>NTFS は <code>$SDH</code> のエントリから内部セキュリティ ID を読み出し、適用先の '
                '<code>$STANDARD_INFORMATION</code> 属性に記録して参照を作ります。\n'
                'すべてのファイルやディレクトリが持つこの属性には、ファイル属性、タイムスタンプ、セキュリティ ID などの基本情報が入ります。</p>\n'
                '<figure><p>セキュリティ設定の適用時には、記述子のハッシュを <code>$SDH</code> で検索します。\n'
                'アクセス権の検査時には、対象の <code>$STANDARD_INFORMATION</code> から取得した内部セキュリティ ID を <code>$SII</code> '
                'で検索します。\n'
                '図ではハッシュ0、1、2とセキュリティ ID 0、1、2が、それぞれ対応する記述子0、1、2の <code>$SDS</code> 内のオフセットを指します。</p>\n'
                '<figcaption>図11-53 <code>$Secure</code> のインデックス</figcaption></figure>\n'
                '<p>適用するセキュリティ記述子と一致するものが <code>$SDH</code> に見つからなければ、そのボリュームにまだ存在しない記述子なので、NTFS '
                'は新しい内部セキュリティ ID を割り当てます。\n'
                '内部セキュリティ ID は32ビットで、SID は通常その数倍の大きさです。\n'
                '内部 ID を使うことで <code>$STANDARD_INFORMATION</code> 内の領域を節約できます。\n'
                'NTFS は記述子を <code>$SDS</code> の末尾に追加し、そのオフセットを参照するエントリを <code>$SDH</code> と '
                '<code>$SII</code> に追加します。</p>\n'
                '<p>アプリケーションがファイルやディレクトリを開こうとすると、NTFS は <code>$SII</code> を使ってセキュリティ記述子を探します。\n'
                'まず対象の MFT エントリの <code>$STANDARD_INFORMATION</code> から内部セキュリティ ID を読みます。\n'
                '次に <code>$Secure</code> の <code>$SII</code> から、その ID に対応する <code>$SDS</code> '
                '内のオフセットを取得します。\n'
                'その位置の記述子を読み取って、アクセス権の検査を完了します。\n'
                'NTFS は直近にアクセスした32件のセキュリティ記述子と対応する <code>$SII</code> エントリをキャッシュするため、必要なエントリがキャッシュにない場合だけ '
                '<code>$Secure</code> にアクセスします。</p>\n'
                '<p>ボリューム上のどのファイルやディレクトリも参照しなくなっても、NTFS は <code>$Secure</code> のエントリを削除しません。\n'
                '長期間使われたボリュームでも、通常は異なる記述子の数が比較的少ないため、残しておいてもディスクの空き容量には大きく影響しません。</p>\n'
                '<p>NTFS は汎用の B 木インデックスにより、同じセキュリティ設定を持つファイルやディレクトリ間で記述子を効率よく共有できます。\n'
                'アクセス権の検査時には <code>$SII</code> ですばやく記述子を探せます。\n'
                '設定を適用する際は <code>$SDH</code> で記述子が <code>$Secure</code> にすでに存在し、共有できるかどうかをすばやく確認できます。</p>',
 'p2-page-715': '<h5>再解析ポイント</h5>\n'
                '<p>再解析ポイントは、アプリケーションが定義する最大16 KBの再解析データと32ビットの再解析タグで構成され、ファイルやディレクトリの '
                '<code>$REPARSE_POINT</code> 属性に格納されます。\n'
                'アプリケーションが再解析ポイントを作成または削除すると、NTFS はメタデータファイル <code>&#92;$Extend&#92;$Reparse</code> を更新します。\n'
                'このファイルには再解析ポイントを持つファイルやディレクトリのファイルレコード番号が入ります。\n'
                '記録を一元化することで、NTFS はボリューム上の再解析ポイントをすべて列挙したり、マウントポイントなど特定の種類だけを列挙したりするためのインターフェイスを提供できます。\n'
                'このファイルは NTFS の汎用 B 木を使い、<code>$R</code> インデックスに再解析タグとファイルレコード番号の順でエントリを並べます。</p>\n'
                '<h6>実験\u3000異なる種類の再解析ポイントを調べる</h6>\n'
                '<p>ファイルやディレクトリの再解析ポイントには任意のデータを格納できます。\n'
                '第8章の実験と同様に、標準の <code>fsutil.exe</code> でシンボリックリンクとモダンアプリの <code>AppExecutionAlias</code> '
                'を調べます。\n'
                'まずシンボリックリンクを作ります。</p>\n'
                '<pre><code>C:\\&gt;mklink test_link.txt d:\\Test.txt\n'
                'symbolic link created for test_link.txt &lt;&lt;===&gt;&gt; d:\\Test.txt</code></pre>\n'
                '<p><code>fsutil reparsePoint query</code> で再解析ポイントの内容を確認します。</p>\n'
                '<pre><code>C:\\&gt;fsutil reparsePoint query test_link.txt\n'
                '再解析タグ値 : 0xa000000c\n'
                'タグ値: Microsoft\n'
                'タグ値: 名前の代理\n'
                'タグ値: シンボリックリンク</code></pre>\n'
                '<p>内容は Microsoft のドキュメントに記載されている <code>REPARSE_DATA_BUFFER</code> 構造体で、リンク先と表示用ファイル名が入ります。\n'
                '<code>fsutil reparsePoint delete</code> で再解析ポイント自体を削除することもできます。</p>\n'
                '<pre><code>再解析データ長: 0x00000040\n'
                '再解析データ:\n'
                '0000:  16 00 1e 00 00 00 16 00  00 00 00 00 64 00 3a 00  ............d.:.\n'
                '0010:  5c 00 54 00 65 00 73 00  74 00 2e 00 74 00 78 00  \\.T.e.s.t...t.x.\n'
                '0020:  74 00 5c 00 3f 00 3f 00  5c 00 64 00 3a 00 5c 00  t.\\.?.?.\\.d.:.\\.\n'
                '0030:  54 00 65 00 73 00 74 00  2e 00 74 00 78 00 74 00  '
                'T.e.s.t...t.x.t.</code></pre><pre><code>C:\\&gt;more test_link.txt\n'
                'This is a test file!</code></pre>',
 'p2-page-716': '<p>再解析ポイントを削除すると、ファイルは0バイトになります。\n'
                'リンクファイルの名前なしデータストリーム（<code>$DATA</code>）が空であるためです。\n'
                'インストール済みのモダンアプリの <code>AppExecutionAlias</code> でも同じ実験を行えます。\n'
                'この例では Spotify を使います。</p>\n'
                '<pre><code>C:\\&gt;cd C:\\Users\\Andrea\\AppData\\Local\\Microsoft\\WindowsApps\n'
                'C:\\Users\\andrea\\AppData\\Local\\Microsoft\\WindowsApps&gt;fsutil reparsePoint query '
                'Spotify.exe\n'
                '再解析タグ値 : 0x8000001b\n'
                'タグ値: Microsoft</code></pre><pre><code>再解析データ長: 0x00000178\n'
                '再解析データ:\n'
                '0000:  03 00 00 00 53 00 70 00  6f 00 74 00 69 00 66 00  ....S.p.o.t.i.f.\n'
                '0010:  79 00 41 00 42 00 2e 00  53 00 70 00 6f 00 74 00  y.A.B...S.p.o.t.\n'
                '0020:  69 00 66 00 79 00 4d 00  75 00 73 00 69 00 63 00  i.f.y.M.u.s.i.c.\n'
                '0030:  5f 00 7a 00 70 00 64 00  6e 00 65 00 6b 00 64 00  _.z.p.d.n.e.k.d.\n'
                '0040:  72 00 7a 00 72 00 65 00  61 00 30 00 00 00 53 00  r.z.r.e.a.0...S\n'
                '0050:  70 00 6f 00 74 00 69 00  66 00 79 00 41 00 42 00  p.o.t.i.f.y.A.B.\n'
                '0060:  2e 00 53 00 70 00 6f 00  74 00 69 00 66 00 79 00  ..S.p.o.t.i.f.y.\n'
                '0070:  4d 00 75 00 73 00 69 00  63 00 5f 00 7a 00 70 00  M.u.s.i.c._.z.p.\n'
                '0080:  64 00 6e 00 65 00 6b 00  64 00 72 00 7a 00 72 00  d.n.e.k.d.r.z.r.\n'
                '0090:  65 00 61 00 30 00 21 00  53 00 70 00 6f 00 74 00  e.a.0.!.S.p.o.t.\n'
                '00a0:  69 00 66 00 79 00 00 00  43 00 3a 00 5c 00 50 00  i.f.y...C.:.\\.P.\n'
                '00b0:  72 00 6f 00 67 00 72 00  61 00 6d 00 20 00 46 00  r.o.g.r.a.m. .F.\n'
                '00c0:  69 00 6c 00 65 00 73 00  5c 00 57 00 69 00 6e 00  i.l.e.s.\\.W.i.n.\n'
                '00d0:  64 00 6f 00 77 00 73 00  41 00 70 00 70 00 73 00  d.o.w.s.A.p.p.s.\n'
                '00e0:  5c 00 53 00 70 00 6f 00  74 00 69 00 66 00 79 00  \\.S.p.o.t.i.f.y.\n'
                '00f0:  41 00 42 00 2e 00 53 00  70 00 6f 00 74 00 69 00  A.B...S.p.o.t.i.\n'
                '0100:  66 00 79 00 4d 00 75 00  73 00 69 00 63 00 5f 00  f.y.M.u.s.i.c._.\n'
                '0110:  31 00 2e 00 39 00 34 00  2e 00 32 00 36 00 32 00  1...9.4...2.6.2.\n'
                '0120:  2e 00 30 00 5f 00 78 00  38 00 36 00 5f 00 5f 00  ..0._.x.8.6._._.\n'
                '0130:  7a 00 70 00 64 00 6e 00  65 00 6b 00 64 00 72 00  z.p.d.n.e.k.d.r.\n'
                '0140:  7a 00 72 00 65 00 61 00  30 00 5c 00 53 00 70 00  z.r.e.a.0.\\.S.p.\n'
                '0150:  6f 00 74 00 69 00 66 00  79 00 4d 00 69 00 67 00  o.t.i.f.y.M.i.g.\n'
                '0160:  72 00 61 00 74 00 6f 00  72 00 2e 00 65 00 78 00  r.a.t.o.r...e.x.\n'
                '0170:  65 00 00 00 30 00 00 00                           e...0...</code></pre>\n'
                '<p>出力には、モダンアプリが使う別種の再解析ポイントである <code>AppExecutionAlias</code> が表示されています。\n'
                '詳しくは第8章を参照してください。</p>\n'
                '<h4>ストレージの予約領域と NTFS の領域予約</h4>\n'
                '<p>Windows Update と Windows '
                'セットアップは、システムボリュームがほぼ満杯でも、重要なセキュリティ更新プログラムを適用できるだけの容量を確保する必要があります。\n'
                'Windows 10はそのためにストレージの予約領域を導入しました。\n'
                'その仕組みを説明する前に、NTFS が領域を予約する方法と、予約が必要な理由を説明します。</p>\n'
                '<p>NTFS はマウント時にボリュームの使用済み容量と空き容量を計算します。\n'
                'この2つのカウンターを保持する属性はディスク上にありません。\n'
                'NTFS は全クラスターの状態を表すボリュームビットマップをディスク上で管理します。\n'
                'マウント処理はビットマップを走査し、ビットが1の使用中クラスターを数えます。</p>',
 'p2-page-717': '<p>ボリューム全体のクラスター数から使用中のクラスター数を引くと、空きクラスター数が得られます。\n'
                'NTFS は使用中と空きの両方のカウンターを、マウントされたボリュームを表す<strong>ボリューム制御ブロック</strong>（VCB）に保存します。\n'
                'VCB はボリュームをアンマウントするまでメモリ上にだけ存在します。</p>\n'
                '<p>通常の I/O 処理中、NTFS は予約済みクラスターの総数を管理します。\n'
                'このカウンターは次の目的で使います。</p>\n'
                '<ul>\n'
                '<li>圧縮ファイルやスパースファイルに書き込む際は、アプリケーションがファイル全体に有効な非圧縮データを格納する可能性を考慮し、ファイル全体に書き込めることを保証します。</li>\n'
                '<li>実行可能イメージを基盤とする書き込み可能なセクションを初めて作成するときは、ボリュームに物理領域をまだ割り当てていなくても、ファイルシステムがセクション全体の容量を予約します。</li>\n'
                '<li>USN ジャーナルと TxF は、このカウンターを使って USN ログと NTFS トランザクションのための空き容量を確保します。</li>\n'
                '</ul>\n'
                '<p>NTFS は通常の I/O 中、ユーザーが新しいファイルやデータの保存に使える空き容量の総計も管理します。\n'
                '使用済みと空きの情報、予約済みの総数、利用可能な空き容量は、NTFS の領域予約を構成します。\n'
                'これらのカウンターはメモリ内の揮発性データで、ボリュームをアンマウントすると破棄されます。</p>\n'
                '<p>ストレージの予約領域は NTFS の領域予約を利用し、ファイルを特定の予約領域に割り当てられるようにします。\n'
                '予約領域は15種類あり、そのうち2種類は OS 用です。\n'
                '領域の情報はメモリと NTFS のディスク上のデータ構造の両方に保存します。</p>\n'
                '<p>アプリケーションはファイルシステム制御コードで、予約する容量の総量と領域 ID をデータ構造に指定し、ボリュームの予約領域を定義します。\n'
                '原文は定義に <code>FSCTL_QUERY_STORAGE_RESERVE</code> と記載しています。\n'
                '定義時には、VCB 内で予約領域を管理する複数のカウンターが更新され、メタデータファイル <code>$Bitmap</code> の名前付きデータストリーム '
                '<code>$SRAT</code> に新しいデータが追加されます。\n'
                '<code>$SRAT</code> は各予約領域の予約済みクラスター数、使用済みクラスター数などを保持します。\n'
                '情報の照会には <code>FSCTL_QUERY_STORAGE_RESERVE</code>、削除には '
                '<code>FSCTL_DELETE_STORAGE_RESERVE</code> を使います。</p>\n'
                '<p>予約領域を定義すると、その容量はほかのコンポーネントには使用されません。\n'
                'アプリケーションはネイティブ API の <code>NtSetInformationFile</code> に情報クラス '
                '<code>FileStorageReserveIdInformationEx</code> を指定し、ファイルやディレクトリを予約領域に割り当てます。\n'
                'NTFS ドライバーはメモリ上の領域の予約済みおよび使用済みクラスター数と、ボリューム全体の NTFS 予約済みクラスター数を更新します。\n'
                '対象ファイルのディスク上の標準情報属性（原文表記は <code>$STANDARD_INFO</code>）も更新し、その4ビットに予約領域 ID を格納します。\n'
                'これにより、システムは MFT エントリを解析するだけで対象のファイルをすばやく列挙できます。\n'
                'NTFS は列挙を <code>FSCTL_QUERY_FILE_LAYOUT</code> のディスパッチ関数で実装しています。\n'
                'ユーザーは <code>fsutil storageReserve findByID</code> にボリュームのパスと予約領域 ID '
                'を指定して、その領域に属するファイルを列挙できます。</p>',
 'p2-page-718': '<p>ストレージの予約領域を使うと、ファイルの作成や改名などの基本操作にも追加の処理が生じます。\n'
                '新規ファイルやディレクトリは親の予約領域 ID を自動で継承します。\n'
                '改名によって別の親に移動したファイルやディレクトリにも同じ規則が適用されます。\n'
                '改名で予約領域 ID が変わることがあるため、空き容量の不足で改名が失敗する場合があります。\n'
                '空でないディレクトリを別の親に移動すると、配下のファイルとサブディレクトリすべてに新しい予約領域 ID が再帰的に適用されます。\n'
                '予約領域の容量を使い切ると、システムはボリュームの利用可能な空き容量を使います。\n'
                'このため、操作が常に成功するとは限りません。</p>\n'
                '<h5>実験\u3000ストレージの予約領域を確認する</h5>\n'
                '<p>Windows 10 の May 2019 Update（19H1）以降では、標準の <code>fsutil.exe</code> で既存の NTFS '
                'の予約領域を確認できます。</p>\n'
                '<pre><code>C:\\&gt;fsutil storagereserve query c:\n'
                '予約 ID:       1\n'
                'フラグ:            0x00000000\n'
                '保証容量:  0x0\n'
                '                                      (0 MB)\n'
                '使用済み容量:       0x0\n'
                '                                      (0 MB)</code></pre><pre><code>予約 ID:       2\n'
                'フラグ:\n'
                '                   0x00000000\n'
                '保証容量:  0x0\n'
                '                                      (0 MB)\n'
                '使用済み容量:\n'
                '                   0x199ed000\n'
                '                                      (409 MB)</code></pre>\n'
                '<p>Windows セットアップは2つの予約領域を定義します。\n'
                '<strong>ハード予約</strong>（ID 1）にはセットアップのファイルを格納し、ほかのアプリケーションはそれらを削除したり置き換えたりできません。\n'
                '<strong>ソフト予約</strong>（ID 2）には、システムログや Windows Update がダウンロードしたファイルなどの一時ファイルを格納します。\n'
                'この例では、セットアップはすべてのファイルのインストールを終え、Windows Update も動作していないので、ハード予約は空です。\n'
                'ソフト予約の領域はすべて割り当て済みです。\n'
                '<code>fsutil storagereserve findById</code> ですべての所属ファイルを列挙できます。\n'
                '出力が長い場合は <code>&gt;</code> でファイルにリダイレクトできます。</p>\n'
                '<pre><code>C:\\&gt;fsutil storagereserve findbyid c: 2\n'
                '...</code></pre><pre><code>********* File 0x0002000000018762 *********\n'
                'ファイル参照番号   : 0x0002000000018762\n'
                'ファイル属性\n'
                '                         : 0x00000020: アーカイブ\n'
                'ファイルエントリのフラグ        : 0x00000000\n'
                'リンク（親 ID と名前）   : 0x0001000000001165: NTFS 名    :\n'
                'Windows\\System32\\winevt\\Logs\\OAlerts.evtx\n'
                'リンク（親 ID と名前）   : 0x0001000000001165: DOS 名     : OALERT~1.EVT\n'
                '作成日時\n'
                '                         : 12/9/2018 3:26:55\n'
                '最終アクセス日時\n'
                '                         : 12/10/2018 0:21:57\n'
                '最終書き込み日時\n'
                '                         : 12/10/2018 0:21:57\n'
                '変更日時\n'
                '                         : 12/10/2018 0:21:57\n'
                '最終 USN\n'
                '                         : 44,846,752\n'
                '所有者 ID\n'
                '                         : 0\n'
                'セキュリティ ID\n'
                '                         : 551</code></pre>',
 'p2-page-719': '<pre><code>予約領域 ID\n'
                '                         : 2\n'
                'ストリーム\n'
                '                         : 0x010  ::$STANDARD_INFORMATION\n'
                '属性\n'
                '                         : 0x00000000: なし\n'
                'フラグ\n'
                '                         : 0x0000000c: 常駐 | クラスター割り当てなし\n'
                'サイズ\n'
                '                         : 72\n'
                '割り当てサイズ\n'
                '                         : 72\n'
                'ストリーム\n'
                '                         : 0x030  ::$FILE_NAME\n'
                '属性\n'
                '                         : 0x00000000: なし\n'
                'フラグ\n'
                '                         : 0x0000000c: 常駐 | クラスター割り当てなし\n'
                'サイズ\n'
                '                         : 90\n'
                '割り当てサイズ\n'
                '                         : 96\n'
                'ストリーム\n'
                '                         : 0x030  ::$FILE_NAME\n'
                '属性\n'
                '                         : 0x00000000: なし\n'
                'フラグ\n'
                '                         : 0x0000000c: 常駐 | クラスター割り当てなし\n'
                'サイズ\n'
                '                         : 90\n'
                '割り当てサイズ\n'
                '                         : 96\n'
                'ストリーム\n'
                '                         : 0x080  ::$DATA\n'
                '属性\n'
                '                         : 0x00000000: なし\n'
                'フラグ\n'
                '                         : 0x00000000: なし\n'
                'サイズ\n'
                '                         : 69,632\n'
                '割り当てサイズ\n'
                '                         : 69,632\n'
                'エクステント\n'
                '                         : 1 エクステント\n'
                '                         : 1: VCN: 0 クラスター数: 17 LCN: 3,820,235</code></pre>\n'
                '<h4>トランザクションのサポート</h4>\n'
                '<p>NTFS は、カーネルのカーネルトランザクションマネージャー（KTM）と、共通ログファイルシステム（CLFS）の機能を利用して、<strong>トランザクション '
                'NTFS</strong>（TxF）というトランザクションモデルを実装しています。\n'
                'アプリケーションは、TxF のユーザーモード API を使ってファイルやディレクトリをトランザクション内で操作できます。\n'
                'TxF はリソースマネージャーを管理するファイルシステム制御（FSCTL）インターフェイスも提供します。</p>\n'
                '<blockquote><p><strong>注記</strong> Windows Vista は Windows にアトミックなトランザクションを導入するため、TxF '
                'を追加しました。\n'
                'NTFS ドライバーは変更されましたが、ディスク上のデータ構造の形式は変わりませんでした。\n'
                'このため、NTFS の形式バージョンは Windows XP と Windows Server 2003 以降と同じ3.1です。\n'
                'TxF は、以前は EFS 専用だった <code>$LOGGED_UTILITY_STREAM</code> '
                '属性型を再利用して後方互換性を保ちます。</p></blockquote>\n'
                '<p>TxF は多くの機能を備えていますが、API が複雑で、開発者が考慮すべき点も多いため、採用したアプリケーションは少数です。\n'
                '本書の執筆時点で、Microsoft は将来の Windows で TxF API を非推奨にすることを検討しています。\n'
                '本書では TxF のアーキテクチャの概要だけを扱います。</p>\n'
                '<p>図11-54に示す TxF のアーキテクチャは、次のコンポーネントから構成されます。</p>\n'
                '<ul>\n'
                '<li><code>Kernel32.dll</code> に実装されたトランザクション対応 API</li>\n'
                '<li>TxF ログを読み取るライブラリ（<code>%SystemRoot%&#92;System32&#92;Txfw32.dll</code>）</li>\n'
                '</ul>',
 'p2-page-720': '<ul>\n'
                '<li>TxF のログ機能を提供する COM コンポーネント（<code>%SystemRoot%&#92;System32&#92;Txflog.dll</code>）</li>\n'
                '<li>NTFS ドライバー内のトランザクション NTFS ライブラリ</li>\n'
                '<li>ログレコードを読み書きする CLFS 基盤</li>\n'
                '</ul>\n'
                '<figure><p>ユーザーモードのアプリケーションはトランザクション対応 API を呼び出します。\n'
                'カーネルモードには、TxF ライブラリを含む NTFS ドライバーと、CLFS ライブラリを含む CLFS ドライバーがあります。</p>\n'
                '<figcaption>図11-54 TxF のアーキテクチャ</figcaption></figure>\n'
                '<h5>分離性</h5>\n'
                '<p>第10章で説明したトランザクションレジストリ（TxR）と同じように、ファイル操作をトランザクションに含めるには、アプリケーションによる明示的な指定が必要です。\n'
                '一方、TxF はトランザクション内の操作を分離するため、トランザクションに対応していないアプリケーションの動作にも影響します。\n'
                'たとえば、他のアプリケーションがトランザクション内で変更中のファイルをウイルス対策ソフトウェアが検査するとき、TxF '
                'は検査側にトランザクション前のデータを読み取らせ、トランザクション内からアクセスするアプリケーションには変更後のデータを見せます。\n'
                'このモデルを<strong>コミット済み読み取りの分離性</strong>と呼びます。</p>\n'
                '<p>このモデルでは、トランザクション内の書き込み側と読み取り側を区別します。\n'
                '書き込み側には、ファイルに関連付けられたトランザクションが行ったすべての変更を含む最新版が見えます。\n'
                '同じファイルについて、同時に存在できるトランザクション内の書き込み側は一つで、書き込み権限は排他的です。\n'
                '読み取り側がアクセスできるのは、ファイルを開いた時点でコミットされていたバージョンだけです。\n'
                '書き込み側が変更をコミットしても、読み取り側は一貫した内容を読み続けます。\n'
                '更新後のデータを読むには、新しいハンドルでファイルを開き直す必要があります。</p>\n'
                '<p>トランザクションに参加していない書き込み側は、トランザクション内の書き込み側または読み取り側によってファイルを開くことを阻止されます。\n'
                'そのため、トランザクションに参加せずにファイルを変更することはできません。\n'
                'トランザクションに参加していない読み取り側にも、ハンドルを開いた時点では最後にコミットされた内容だけが見えます。\n'
                'ただし、コミット済み読み取りの分離性は適用されないため、新しいハンドルを開かなくても、その後にコミットされた最新版が見えます。\n'
                'これにより、トランザクションに対応していないアプリケーションも従来どおりに動作します。</p>',
 'p2-page-721': '<p>TxF のコミット済み読み取りの分離モデルには次の性質があります。</p>\n'
                '<ul>\n'
                '<li>変更は、トランザクション内の読み取り側から分離されます。</li>\n'
                '<li>関連するトランザクションをロールバックした場合、システムがクラッシュした場合、またはボリュームを強制的にアンマウントした場合、変更は取り消されます。</li>\n'
                '<li>関連するトランザクションがコミットされると、変更がディスクに書き出されます。</li>\n'
                '</ul>\n'
                '<h5>トランザクション対応 API</h5>\n'
                '<p>TxF は Windows のファイル I/O API のトランザクション対応版を実装しています。\n'
                '名前の末尾に <code>Transacted</code> が付きます。</p>\n'
                '<ul>\n'
                '<li>作成：<code>CreateDirectoryTransacted</code>、<code>CreateFileTransacted</code>、<code>CreateHardLinkTransacted</code>、<code>CreateSymbolicLinkTransacted</code></li>\n'
                '<li>検索：<code>FindFirstFileNameTransacted</code>、<code>FindFirstFileTransacted</code>、<code>FindFirstStreamTransacted</code></li>\n'
                '<li>照会：<code>GetCompressedFileSizeTransacted</code>、<code>GetFileAttributesTransacted</code>、<code>GetFullPathNameTransacted</code>、<code>GetLongPathNameTransacted</code></li>\n'
                '<li>削除：<code>DeleteFileTransacted</code>、<code>RemoveDirectoryTransacted</code></li>\n'
                '<li>コピー、移動、改名：<code>CopyFileTransacted</code>、<code>MoveFileTransacted</code></li>\n'
                '<li>設定：<code>SetFileAttributesTransacted</code></li>\n'
                '</ul>\n'
                '<p><code>CreateFileTransacted</code> '
                'で作成したハンドルなど、トランザクションに属するファイルハンドルを受け取ると、自動的にトランザクションに参加する API もあります。\n'
                '表11-10に、トランザクションに属するファイルハンドルを扱う際に動作が変わる Windows API を示します。</p>\n'
                '<table><caption>表11-10 TxF によって変わる API の動作</caption>\n'
                '<thead><tr><th>API 名</th><th>変更点</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td><code>CloseHandle</code></td><td>すべてのアプリケーションが対象ファイルのトランザクション付きハンドルを閉じるまで、トランザクションはコミットされません。</td></tr>\n'
                '<tr><td><code>CreateFileMapping</code>、<code>MapViewOfFile</code></td><td>トランザクションに属するファイルのマップ済みビューに加えた変更も、同じトランザクションに関連付けられます。</td></tr>\n'
                '<tr><td><code>FindNextFile</code>、<code>ReadDirectoryChanges</code>、<code>GetInformationByHandle</code>、<code>GetFileSize</code></td><td>ファイルハンドルがトランザクションに属する場合、これらの操作に読み取りの分離規則が適用されます。</td></tr>\n'
                '<tr><td><code>GetVolumeInformation</code></td><td>ボリュームが TxF をサポートする場合、結果に '
                '<code>FILE_SUPPORTS_TRANSACTIONS</code> が含まれます。</td></tr>\n'
                '<tr><td><code>ReadFile</code>、<code>WriteFile</code></td><td>トランザクション付きファイルハンドルへの読み書きはトランザクションに含まれます。</td></tr>\n'
                '<tr><td><code>SetFileInformationByHandle</code></td><td>ファイルハンドルがトランザクションに属する場合、<code>FileBasicInfo</code>、<code>FileRenameInfo</code>、<code>FileAllocationInfo</code>、<code>FileEndOfFileInfo</code>、<code>FileDispositionInfo</code> '
                'の変更はトランザクションに含まれます。</td></tr>\n'
                '<tr><td><code>SetEndOfFile</code>、<code>SetFileShortName</code>、<code>SetFileTime</code></td><td>ファイルハンドルがトランザクションに属する場合、変更はトランザクションに含まれます。</td></tr>\n'
                '</tbody></table>',
 'p2-page-722': '<h5>ディスク上の実装</h5>\n'
                '<p>表11-7で示したように、TxF '
                'は現在または過去にトランザクションに参加したファイルやディレクトリの追加データを、<code>$LOGGED_UTILITY_STREAM</code> 型の属性に格納します。\n'
                'この属性は <code>$TXF_DATA</code> と呼ばれ、TxF がトランザクションに参加するファイルのオフラインデータを有効な状態に保つための情報が入ります。\n'
                '後述する理由により、このストリームはファイルがトランザクションから外れた後も MFT に残ります。</p>\n'
                '<figure><p>主なフィールドは、リソースマネージャーのルートのファイルレコード番号、フラグ、TxF ファイル ID（TxID）、NTFS メタデータの '
                'LSN、ユーザーデータの LSN、ディレクトリインデックスの LSN、USN インデックスです。</p>\n'
                '<figcaption>図11-55 <code>$TXF_DATA</code> 属性</figcaption></figure>\n'
                '<p>最初のフィールドは、ファイルに関連付けられたトランザクションを担当するリソースマネージャーのルートのファイルレコード番号です。\n'
                '既定のリソースマネージャーでは、図11-31に示したとおり、MFT 内のルートディレクトリ（<code>&#92;</code>）のファイルレコード番号である5が入ります。\n'
                'TxF はファイルの FCB を作るときに、この番号で正しいリソースマネージャーと結び付けます。\n'
                'NTFS がトランザクション付きのファイル操作要求を受け取ると、リソースマネージャーはそのトランザクションへの参加を表す登録を作ります。</p>\n'
                '<p>もう一つの重要なフィールドが、TxF ファイル ID（TxID）です。\n'
                'NTFS はトランザクションログのレコードにファイル名を書き込むため、同じディレクトリで同じ名前だったファイルを識別する仕組みが必要です。\n'
                'たとえば、同じトランザクション内で <code>sample.txt</code> を削除し、同じディレクトリにその名前で新しいファイルを作った場合、TxF は2つの '
                '<code>sample.txt</code> を区別しなければなりません。\n'
                'TxID はそのための一意な64ビットの番号で、TxF は新しいファイルや同名の新しい実体がトランザクションに参加するたびに番号を増やします。\n'
                'TxID は再利用されない永続的な識別子なので、<code>$TXF_DATA</code> 属性はファイルから削除されません。</p>\n'
                '<p>トランザクションに参加する各ファイルには、共通ログファイルシステム（CLFS）のログシーケンス番号（LSN）が3つ格納されます。\n'
                'ファイルの作成、改名、書き込みなどのトランザクション操作中、TxF は CLFS ログにレコードを書き込みます。\n'
                '各レコードに割り当てられた LSN は、<code>$TXF_DATA</code> の該当するフィールドに入ります。\n'
                '1つ目は、ファイルに関する NTFS メタデータの変更を記述したレコードの LSN です。\n'
                'たとえばトランザクション操作でファイルの標準属性が変わると、TxF は対応する MFT ファイルレコードを更新し、その変更を記述したログレコードの LSN を格納します。\n'
                '2つ目はファイルのデータの変更に使います。\n'
                '3つ目は、ファイルが参加したトランザクションに関連してディレクトリのファイル名インデックスを変更する場合や、ディレクトリがトランザクションに参加して TxID '
                'を受け取った場合に使います。</p>',
 'p2-page-723': '<p><code>$TXF_DATA</code> は、TxF が使う状態情報を表す内部フラグと、コミット時にファイルへ適用した USN レコードのインデックスも保持します。\n'
                '1つの TxF トランザクションが複数の USN レコードにまたがることがあり、後述する NTFS の回復処理がその一部だけを更新していることもあります。\n'
                'インデックスを参照すれば、回復後にあと何件の USN レコードを適用すべきか分かります。</p>\n'
                '<p>TxF はボリュームごとに既定のリソースマネージャーを使い、トランザクションの状態を管理します。\n'
                '開発者は追加の<strong>セカンダリリソースマネージャー</strong>を定義し、任意のディレクトリにメタデータを配置できます。\n'
                'これにより、取り消し、バックアップ、復元、再実行のための独自のトランザクション作業単位を定義できます。\n'
                'どちらのリソースマネージャーにも、現在の状態を記述する次のメタデータファイルとディレクトリがあります。</p>\n'
                '<ul>\n'
                '<li><code>$Extend&#92;$RmMetadata</code> 内の <code>$Txf</code> ディレクトリ。\n'
                'トランザクション操作で削除または上書きされたファイルは、ここにリンクされます。</li>\n'
                '<li><code>$Tops</code> ファイル（TxF の旧ページストリーム、TOPS）。\n'
                '既定のデータストリームには、リソースマネージャーの GUID、CLFS ログのポリシー、回復開始位置の LSN などのメタデータが入ります。\n'
                '代替データストリーム <code>$T</code> は、トランザクション内の書き込みで一部分が上書きされるファイルのデータを保持します。\n'
                'ファイル全体を上書きする場合、ファイルは <code>$Txf</code> に移されます。</li>\n'
                '<li>トランザクションレコードを格納する CLFS 形式の TxF ログファイル。\n'
                '既定のリソースマネージャーは <code>$TxfLog</code> ディレクトリを使い、セカンダリリソースマネージャーは任意の場所に格納できます。\n'
                'TxF は <code>$TxfLog.blf</code> という多重化されたベースログファイルを使います。\n'
                '<code>&#92;$Extend&#92;$RmMetadata&#92;$TxfLog&#92;$TxfLog</code> '
                'には2つのストリームがあり、<code>KtmLog</code> にカーネルトランザクションマネージャーのメタデータレコードを、<code>TxfLog</code> に TxF '
                'のログレコードを格納します。</li>\n'
                '</ul>\n'
                '<h6>実験\u3000リソースマネージャーの情報を照会する</h6>\n'
                '<p>Windows 標準の <code>Fsutil.exe</code> では、既定のリソースマネージャーの情報を照会できます。\n'
                'また、セカンダリリソースマネージャーを作成、開始、停止し、ログのポリシーや動作を設定できます。\n'
                '次のコマンドは、ルートディレクトリ（<code>&#92;</code>）で識別される既定のリソースマネージャーの情報を照会します。</p>\n'
                '<pre><code>d:\\&gt;fsutil resource info \\\n'
                'リソースマネージャーの識別子 :      81E83020-E6FB-11E8-B862-D89EF33A38A7\n'
                'リソースマネージャーの KTM ログパス:  '
                '\\Device\\HarddiskVolume8\\$Extend\\$RmMetadata\\$TxfLog\\$TxfLog::KtmLog\n'
                'TOPS の使用領域:   1 Mb\n'
                'TOPS の空き領域:      100%\n'
                'リソースマネージャーの状態:             稼働中\n'
                '実行中のトランザクション: 0\n'
                '1フェーズコミット:    0\n'
                '2フェーズコミット:    0\n'
                'システムが開始したロールバック: 0\n'
                '最も古いトランザクションの経過時間:  00:00:00\n'
                'ログモード:         シンプル\n'
                'コンテナー数: 2</code></pre>',
 'p2-page-724': '<pre><code>コンテナーのサイズ     : 10 Mb\n'
                'ログの総容量           : 20 Mb\n'
                'ログの空き容量         : 19 Mb\n'
                'コンテナーの最小数     : 2\n'
                'コンテナーの最大数     : 20\n'
                'ログの拡張単位         : 2コンテナー\n'
                '自動縮小               : 無効\n'
                '\n'
                'リソースマネージャーは整合性より可用性を優先します。</code></pre>\n'
                '<p><code>fsutil resource</code> には TxF のリソースマネージャーを設定するためのオプションが多数あります。\n'
                'セカンダリリソースマネージャーは任意のディレクトリに作成できます。\n'
                'たとえば <code>fsutil resource create c:&#92;rmtest</code> で Rmtest ディレクトリに作成し、<code>fsutil '
                'resource start c:&#92;rmtest</code> で起動します。\n'
                'このディレクトリに <code>$Tops</code> と <code>$TxfLogContainer*</code> のファイル、および <code>TxfLog</code> '
                'と <code>$Txf</code> のディレクトリがあることを確認します。</p>\n'
                '<h5>ログの実装</h5>\n'
                '<p>実行中のトランザクションによってディスクに変更が加わるたびに、TxF はその変更をログに記録します。\n'
                'TxF は複数の種類のログレコードで変更を追跡します。\n'
                'どのレコードにも共通のヘッダーがあり、レコードの種類、関連する操作、適用先の TxID、および関連する KTM トランザクションの GUID が入ります。</p>\n'
                '<p><strong>再実行レコード</strong>は、すでにボリュームにコミットされたトランザクションの変更がキャッシュからディスクに書き出されていない場合に、変更を再適用する方法を指定します。\n'
                '<strong>取り消しレコード</strong>は、ロールバック時点で未コミットの変更を取り消す方法を指定します。\n'
                '再実行情報だけを持ち、対応する取り消し情報を持たないレコードもあれば、両方の情報を持つレコードもあります。</p>\n'
                '<p>TxF は TOPS ファイルにベース LSN と再開 LSN を保持します。\n'
                'ベース LSN はログの最初の有効なレコードの LSN を示します。\n'
                '再開 LSN は、リソースマネージャーの起動時に回復を始める LSN を示します。\n'
                'TxF は再開レコードを書き込むときに両方の値を更新します。\n'
                'この更新はボリュームへの変更がディスクに書き出され、新しい再開 LSN までファイルシステムの整合性が保たれていることを示します。</p>\n'
                '<p>TxF は<strong>補償ログレコード</strong>（CLR）も書き込みます。\n'
                'CLR はトランザクションのロールバック中に行う操作を記録し、主に次に取り消すレコードの LSN を保持します。\n'
                '回復中にシステムが停止し、取り消し処理の一部だけが完了した場合は、この LSN を使って処理済みの取り消しレコードを飛ばし、同じ操作の繰り返しを避けられます。\n'
                'TxF は準備レコード、中止レコード、コミットレコードも扱います。\n'
                'これらは、TxF に関連する KTM トランザクションの状態を記述します。</p>',
 'p2-page-725': '<h4>NTFS の回復機能</h4>\n'
                '<p>停電やシステム障害が発生しても、NTFS の回復機能により、ファイルシステムの操作（トランザクション）が未完了のまま残ることはありません。\n'
                'ディスク修復ツールを実行しなくても、ディスクのボリューム構造は維持されます。\n'
                '不良セクター、電気的な異常、ディスク故障などの I/O エラーや、ソフトウェアの不具合によってディスクが深刻に破損した場合は、NTFS の <code>Chkdsk</code> '
                'ユーティリティで修復します。\n'
                'NTFS の回復機能があるため、<code>Chkdsk</code> が必要になることはまれです。</p>\n'
                '<p>「回復可能性」の節で説明したように、NTFS はトランザクション処理を使って回復を実現します。\n'
                'この方式では、最大規模のディスクでも数秒程度でディスク全体を回復できます。\n'
                'NTFS の回復処理はファイルシステムのデータを対象とし、少なくともファイルシステムの破損によってボリューム全体が失われる事態を防ぎます。\n'
                'ただし、アプリケーションがキャッシュ済みのファイルをディスクに書き出すなどの措置を取らなければ、クラッシュ時にユーザーデータへの更新がすべて反映される保証はありません。\n'
                'この保証を担うのがトランザクション NTFS（TxF）です。</p>\n'
                '<p>以下では、NTFS がファイルシステムのデータ構造への変更を記録するトランザクションログの仕組みと、システム障害後にボリュームを回復する手順を説明します。</p>\n'
                '<h5>設計</h5>\n'
                '<p>NTFS は<strong>回復可能なファイルシステム</strong>として設計されています。\n'
                'この種のファイルシステムは、もともとトランザクション処理向けに開発されたログ記録（ジャーナリングとも呼ばれます）によって、ボリュームの整合性を保ちます。\n'
                'OS がクラッシュすると、ログファイルに保存した情報を使って回復処理を行い、整合性を取り戻します。\n'
                'ディスクへの書き込みは記録済みなので、回復はボリュームのサイズにかかわらず数秒で済みます。\n'
                'FAT ではボリュームのサイズによって修復時間が変わります。\n'
                'ログに基づく回復では、ボリュームを確実に整合した状態に戻せます。</p>\n'
                '<p>回復を可能にするには、ボリューム構造を変えるトランザクションの部分操作ごとに、ログファイルに1件のレコードを書き込む必要があります。\n'
                'ファイルシステムは複数のレコードをまとめて1回の I/O で書き込むことで、この負荷を抑えます。\n'
                '遅延書き込みを行うファイルシステムの最適化手法も利用できます。\n'
                'キャッシュの変更をディスクに書き出す前にシステムがクラッシュしても、ファイルシステムのメタデータは回復できるため、フラッシュ間隔をさらに長くできます。\n'
                '従来の遅延書き込み方式と比べたキャッシュ性能の向上で、ログ記録の負荷を相殺でき、性能の向上がその負荷を上回ることもよくあります。</p>\n'
                '<p>書き込み順序を慎重に制御する方式でも遅延書き込み方式でも、ユーザーファイルのデータが保護される保証はありません。\n'
                'アプリケーションがファイルに書き込んでいる最中にシステムがクラッシュすると、そのファイルは失われたり破損したりすることがあります。\n'
                '遅延書き込み方式では、クラッシュがファイルシステム自体を破損させ、既存のファイルを失わせたり、ボリューム全体にアクセスできなくしたりすることもあります。</p>\n'
                '<p>NTFS は、従来のファイルシステムよりも信頼性を高めるため、複数の回復手法を備えています。\n'
                '第一に、NTFS の回復機能はボリューム構造を保護するため、システム障害後もすべてのファイルにアクセスできます。\n'
                '第二に、システムがクラッシュするとキャッシュ内の変更の一部が失われることがあり、NTFS はユーザーデータの保護を保証しません。</p>',
 'p2-page-726': '<p>アプリケーションは NTFS のライトスルーとキャッシュのフラッシュを利用して、必要な間隔でファイルの変更をディスクに記録できます。</p>\n'
                '<p><strong>ライトスルー</strong>は、書き込みを直ちにディスクに反映する方式です。\n'
                '<strong>キャッシュのフラッシュ</strong>は、キャッシュの内容を強制的にディスクへ書き出す操作です。\n'
                'NTFS では、どちらも効率よく実行できます。\n'
                '複数のファイルシステムデータ構造への変更をログファイルに1回で書き込むため、変更をフラッシュするために各データ構造へ追加のディスク I/O を発行する必要がありません。\n'
                '障害でキャッシュの内容が失われても、ログからファイルシステムへの変更を回復できます。\n'
                'NTFS はさらに、ライトスルーやキャッシュのフラッシュが完了した時点でユーザーデータが整合した状態で利用でき、その後システムが障害を起こしても利用できることを保証します。\n'
                'FAT にはこの保証がありません。</p>\n'
                '<h5>メタデータのログ記録</h5>\n'
                '<p>NTFS は TxF と同じログ記録の手法で、ファイルシステムを回復できるようにします。\n'
                'ファイルシステムのメタデータを変更する操作をすべてログファイルに記録する手法です。\n'
                'TxF は CLFS を使いますが、NTFS に組み込まれた回復機能は<strong>ログファイルサービス</strong>という内部のログ記録機構を使います。\n'
                'ログファイルサービスは、第10章で説明したバックグラウンドのサービスプロセスとは別の仕組みです。\n'
                'また、TxF が呼び出し元から指定された操作にだけ適用されるのに対し、NTFS '
                'はシステム障害後にファイルシステムの整合性を回復できるよう、すべてのメタデータの変更を記録します。</p>\n'
                '<h5>ログファイルサービス</h5>\n'
                '<p><strong>ログファイルサービス</strong>（LFS）は、NTFS ドライバーがログファイルへのアクセスに使うカーネルモードルーチンの集まりです。\n'
                'NTFS は、アクセス対象のログファイルを指定するために、開いているファイルのファイルオブジェクトへのポインターを LFS に渡します。\n'
                '図11-56に示すように、LFS は新しいログファイルを初期化するか、Windows のキャッシュマネージャーを呼び出して既存のログファイルにキャッシュ経由でアクセスします。\n'
                'LFS と CLFS は動作が似ている部分も多いですが、異なる目的に使われる別々のログ記録機構です。</p>\n'
                '<figure><p>NTFS ドライバーはトランザクションを LFS に記録し、ボリュームの更新を I/O マネージャー経由で書き込みます。\n'
                'LFS はログファイルの読み取り、書き込み、フラッシュをキャッシュマネージャーに要求します。\n'
                'キャッシュマネージャーはログファイルのフラッシュを I/O マネージャーに要求し、マップ済みファイルにアクセスするときはメモリマネージャーを呼び出します。</p>\n'
                '<figcaption>図11-56 ログファイルサービス（LFS）</figcaption></figure>',
 'p2-page-727': '<p>LFS は図11-57のように、ログファイルを再開領域と「無限」のログ記録領域に分けます。</p>\n'
                '<figure><p>先頭の LFS 再開領域には2つのコピーがあり、その後にログレコードを格納するログ記録領域が続きます。</p>\n'
                '<figcaption>図11-57 ログファイルの領域</figcaption></figure>\n'
                '<p>NTFS は LFS を呼び出して再開領域を読み書きします。\n'
                '再開領域には、システム障害からの回復時にログ記録領域のどの位置から読み始めるかといった、回復に必要な情報が入ります。\n'
                'LFS は最初のコピーが破損などで読み取れなくなった場合に備え、再開データのコピーをもう一つ保持します。</p>\n'
                '<p>ファイルの残りはログ記録領域です。\n'
                'ここには、システム障害後にボリュームを回復するために NTFS が書き込むトランザクションレコードが入ります。\n'
                'LFS は必要な情報を上書きしないようにしながら領域を循環して再利用するため、ログファイルを無限に使い続けられるように見せられます。\n'
                'CLFS と同様、LFS はログファイルに書き込んだレコードを LSN で識別します。\n'
                'LFS はファイルを循環して使う間も LSN の値を増やします。\n'
                'NTFS の LSN は64ビットで、取り得る番号は事実上尽きません。</p>\n'
                '<p>NTFS はトランザクションをログファイルに直接書き込んだり、そこから直接読み取ったりする代わりに、LFS が提供する処理を呼び出します。\n'
                'LFS はログファイルを開く、レコードを書き込む、順方向または逆方向に読み取る、指定した LSN までをフラッシュする、ログの先頭をより大きい LSN '
                'へ進める、といった処理を提供します。\n'
                '回復時、NTFS は TxF の回復と同様に LFS を使います。\n'
                'まずコミット済みでフラッシュされていない変更を再実行し、次に未コミットの変更を取り消します。</p>\n'
                '<p>システムは次の順序で処理し、ボリュームを回復できるようにします。</p>\n'
                '<ol>\n'
                '<li>NTFS はまず LFS を呼び出し、ボリューム構造を変えるトランザクションをキャッシュ内のログファイルに記録します。</li>\n'
                '<li>NTFS はキャッシュ内でボリュームを変更します。</li>\n'
                '<li>キャッシュマネージャーは LFS にログファイルをディスクへフラッシュするよう要求します。\n'
                'LFS はキャッシュマネージャーを呼び返し、フラッシュ対象のメモリページを伝えます（図11-56の呼び出し順序を参照）。</li>\n'
                '<li>キャッシュマネージャーはログファイルをディスクに書き出した後、ボリュームへの変更、つまりメタデータ操作そのものをディスクに書き出します。</li>\n'
                '</ol>\n'
                '<p>この順序なら、ファイルシステムへの変更が完了しなかった場合でも、ログファイルから対応するトランザクションを取得し、回復処理の一環として再実行または取り消しできます。</p>',
 'p2-page-728': '<p>システムを再起動した後、そのボリュームを初めて使用すると、ファイルシステムの回復が自動で始まります。\n'
                'NTFS はクラッシュ前にログへ記録したトランザクションがボリュームに反映されたかを確認し、未反映なら再実行します。\n'
                'クラッシュ前に記録を完了できなかったトランザクションについても、ボリュームに結果が残らないように取り消します。</p>\n'
                '<h5>ログレコードの種類</h5>\n'
                '<p>NTFS の回復機構は TxF の回復機構と似た種類のログレコードを使います。\n'
                '<strong>更新レコード</strong>は TxF の再実行レコードと取り消しレコードに対応し、<strong>チェックポイントレコード</strong>は TxF '
                'の再開レコードに相当します。\n'
                '図11-58は、新規ファイルを作成するトランザクションの3つの部分操作を示します。\n'
                '各更新レコードには、その部分操作をボリュームに再適用するための再実行項目と、ロールバックするための取り消し項目が入ります。</p>\n'
                '<figure><p>ログファイルは LFS 再開領域とログ記録領域からなります。\n'
                'ログ記録領域に以下の更新レコードが順に並び、その後にもレコードが続きます。</p>\n'
                '<table><thead><tr><th>レコード</th><th>再実行</th><th>取り消し</th></tr></thead>\n'
                '<tbody><tr><td>T1a</td><td>MFT ファイルレコードを割り当てて初期化する</td><td>ファイルレコードの割り当てを解除する</td></tr>\n'
                '<tr><td>T1b</td><td>ビットマップのビット3〜9をセットする</td><td>ビット3〜9をクリアする</td></tr>\n'
                '<tr><td>T1c</td><td>ファイル名をインデックスに追加する</td><td>ファイル名をインデックスから削除する</td></tr></tbody></table>\n'
                '<figcaption>図11-58 ログファイル内の更新レコード</figcaption></figure>\n'
                '<p>トランザクションを記録した後、NTFS はキャッシュ内のボリュームに対して各部分操作を実行します。\n'
                'この例では、LFS を呼び出して3つの更新レコードをログファイルに書き込んだ後に実行します。\n'
                'キャッシュの更新が終わると、NTFS はトランザクション全体の完了を示すレコードをログファイルに追加します。\n'
                'この部分操作を<strong>トランザクションのコミット</strong>と呼びます。\n'
                'コミット後は、OS が障害を起こしてもトランザクション全体がボリュームに反映されます。</p>\n'
                '<p>システム障害からの回復時、NTFS はログファイルを読み、コミット済みの各トランザクションを再実行します。\n'
                '障害前に完了していたトランザクションでも、キャッシュマネージャーが間に合うように変更をディスクに書き出したかは分かりません。\n'
                '障害でキャッシュ内の更新が失われた可能性があるため、NTFS はコミット済みのトランザクションを再実行し、ディスクを最新の状態にします。</p>\n'
                '<p>コミット済みのトランザクションを再実行した後、NTFS は障害時点で未コミットだったトランザクションをログファイルから探し、記録された部分操作を一つずつ取り消します。\n'
                '図11-58の例では、まず T1c を取り消し、直前のレコードを指すポインターをたどって T1b を取り消します。\n'
                'トランザクションの最初の部分操作に達するまで、ポインターを逆にたどって取り消しを続けます。\n'
                'このポインターをたどることで、ロールバックに必要な更新レコードとその件数が分かります。</p>',
 'p2-page-729': '<p>再実行と取り消しの情報には、物理的な記述と論理的な記述の2通りがあります。\n'
                'NTFS はファイルシステムの構造を管理する最下層のソフトウェアなので、更新レコードには、ディスク上のどのバイト範囲を変更または移動するかといった物理的な記述を書き込みます。\n'
                'TxF は「ファイル <code>A.dat</code> を削除する」といった操作で更新を表す論理的な記述を使います。\n'
                'NTFS は以下の各トランザクションについて更新レコードを書き込みます。\n'
                '通常は、1つのトランザクションにつき複数のレコードが必要です。</p>\n'
                '<ul>\n'
                '<li>ファイルを作成する</li>\n'
                '<li>ファイルを削除する</li>\n'
                '<li>ファイルを拡張する</li>\n'
                '<li>ファイルを切り詰める</li>\n'
                '<li>ファイル情報を設定する</li>\n'
                '<li>ファイル名を変更する</li>\n'
                '<li>ファイルに適用されたセキュリティ設定を変更する</li>\n'
                '</ul>\n'
                '<p>更新レコードの再実行情報と取り消し情報は、同じ操作が繰り返されても扱えるように設計する必要があります。\n'
                'NTFS '
                'はトランザクションの取り消し時やシステム障害からの回復時、さらには通常の動作中にも、実行済みのトランザクションを再実行したり、実行されなかったか取り消し済みのトランザクションを取り消したりすることがあります。\n'
                '複数の更新レコードからなるトランザクションの一部だけがディスクに反映されている段階で、再実行や取り消しを行う場合もあります。\n'
                '更新レコードの形式は、同じ再実行や取り消しを繰り返しても状態が変わらないようにしなければなりません。\n'
                'この性質を<strong>冪等性</strong>と呼びます。\n'
                'たとえば、すでに1のビットを1に設定しても値は変わりませんが、反転操作を繰り返すと値が変わります。\n'
                'ファイルシステムは、変更の一部だけが反映されたボリュームの中間状態も正しく扱う必要があります。</p>\n'
                '<p>NTFS は更新レコードに加えて、図11-59のようにチェックポイントレコードを定期的にログファイルに書き込みます。</p>\n'
                '<figure><p>LFS 再開領域には NTFS の再開情報が入ります。\n'
                'ログ記録領域には LSN 2058、2059、2060、2061 などのレコードが並び、その中にチェックポイントレコードがあります。</p>\n'
                '<figcaption>図11-59 ログファイル内のチェックポイントレコード</figcaption></figure>\n'
                '<p>チェックポイントレコードは、その時点でシステムがクラッシュした場合に、ボリュームの回復に必要な処理を NTFS が判断するために使います。\n'
                'たとえば、回復を始めるにはログファイルをどこまでさかのぼればよいかが分かります。\n'
                'NTFS はチェックポイントレコードを書き込んだ後、その LSN を再開領域に保存します。\n'
                'これにより、クラッシュ後に回復を始めるとき、最後に書き込んだチェックポイントレコードをすぐに見つけられます。\n'
                'TxF が再開 LSN を使うのも同じ理由です。</p>',
 'p2-page-730': '<p>LFS はログファイルを無限に使えるように見せますが、実際の容量には上限があります。\n'
                'ログファイルには十分な容量があり、書き込むたびに通常は空き領域を増やせるチェックポイントレコードも頻繁に書き込むため、満杯になることはまれです。\n'
                'それでも LFS は CLFS と同様に、容量不足に備えて以下の値を追跡します。</p>\n'
                '<ul>\n'
                '<li>ログの空き容量</li>\n'
                '<li>新しいログレコードの書き込みと、必要になった場合にその書き込みを取り消すために必要な容量</li>\n'
                '<li>実行中で未コミットのすべてのトランザクションを、必要に応じてロールバックするための容量</li>\n'
                '</ul>\n'
                '<p>ログの空き容量が後ろの2項目の合計を下回ると、LFS はログファイルが満杯であることを示すエラーを返し、NTFS は例外を発生させます。\n'
                'NTFS の例外ハンドラーは現在のトランザクションをロールバックし、後で再開するためにキューに入れます。</p>\n'
                '<p>ログファイルの空き容量を増やすには、ファイルに対する新たなトランザクションを一時的に止める必要があります。\n'
                'NTFS はファイルの作成と削除を止め、すべてのシステムファイルに排他アクセスを、すべてのユーザーファイルに共有アクセスを要求します。\n'
                '実行中のトランザクションは順次、正常終了するか、ログファイルが満杯であることを示す例外を受け取ります。\n'
                'NTFS は例外を受け取ったトランザクションをロールバックし、キューに入れます。</p>\n'
                '<p>トランザクションの処理を止めた後、NTFS '
                'はキャッシュマネージャーに、ログファイルの未書き込みデータも含め、まだディスクに反映されていないデータをフラッシュするよう要求します。\n'
                'すべてをディスクに書き出すと、それまでのログデータは不要になります。\n'
                'そこで NTFS はログファイルの先頭を現在位置に移し、ログを論理的に空にします。\n'
                '続いてキューに入れたトランザクションを再開します。\n'
                'このエラーが実行中のプログラムに与える影響は、I/O 処理が短時間止まることだけです。</p>\n'
                '<p>この例では、NTFS がファイルシステムの回復に加え、通常動作中のエラーからの回復にもログを使っています。\n'
                '以下では回復処理を詳しく説明します。</p>\n'
                '<h5>回復</h5>\n'
                '<p>システム起動後、プログラムが NTFS ボリュームに初めてアクセスすると、NTFS はディスクの回復処理を自動的に実行します。\n'
                '回復が不要なら処理はすぐに終わります。\n'
                '回復には、NTFS がメモリ内で管理する2つのテーブルを使います。\n'
                '<strong>トランザクションテーブル</strong>は TxF が管理する同名のテーブルと同様に動作します。\n'
                '<strong>ダーティページテーブル</strong>は、ディスクにまだ書き込まれていないファイルシステム構造の変更を含むキャッシュページを記録します。\n'
                'その変更は回復中にディスクへ書き出す必要があります。</p>\n'
                '<p>NTFS は5秒に1回、ログファイルにチェックポイントレコードを書き込みます。\n'
                'その直前に LFS を呼び出し、トランザクションテーブルとダーティページテーブルの最新のコピーをログファイルに保存します。\n'
                'NTFS は、コピーを収めたログレコードの LSN をチェックポイントレコードに記録します。\n'
                '障害後に回復を開始すると、NTFS は LFS '
                'を呼び出して、最新のチェックポイントレコードと両テーブルの最新コピーを含むログレコードを探し、テーブルをメモリにコピーします。</p>\n'
                '<p>通常、ログファイルには最後のチェックポイントレコードの後にも更新レコードが続きます。\n'
                'これらは最後のチェックポイントレコードを書き込んだ後に発生したボリュームの変更を表します。</p>',
 'p2-page-731': '<p>NTFS はチェックポイント後の操作をトランザクションテーブルとダーティページテーブルに反映します。\n'
                'テーブルの更新後、NTFS は両テーブルとログファイルの内容を使い、ボリューム自体を更新します。</p>\n'
                '<p>ボリュームの回復では、NTFS はログファイルを3回走査します。\n'
                'ディスク I/O を最小限に抑えるため、最初の走査中にファイルをメモリに読み込みます。\n'
                '各走査の目的は次のとおりです。</p>\n'
                '<ol>\n'
                '<li>ログの分析</li>\n'
                '<li>トランザクションの再実行</li>\n'
                '<li>トランザクションの取り消し</li>\n'
                '</ol>\n'
                '<h6>分析パス</h6>\n'
                '<p>図11-60に示すように、分析パスでは、最後のチェックポイント処理の開始位置からログファイルを順方向に走査して、更新レコードを探します。\n'
                'これらのレコードを使い、メモリにコピーしたトランザクションテーブルとダーティページテーブルを更新します。\n'
                'チェックポイント処理は3つのレコードをログファイルに格納します。\n'
                'それらの間に更新レコードが挟まる場合があるため、NTFS はチェックポイント処理の開始位置から走査する必要があります。</p>\n'
                '<figure><p>チェックポイント処理の開始位置から、ダーティページテーブル、途中に挟まる更新レコード、トランザクションテーブル、チェックポイントレコードの順に読み、処理の終了位置より後の更新レコードも続けて読みます。</p>\n'
                '<figcaption>図11-60 分析パス</figcaption></figure>\n'
                '<p>チェックポイント処理の開始後にログへ現れる更新レコードの大半は、トランザクションテーブルかダーティページテーブルへの変更を表します。\n'
                'たとえば、コミットを示すレコードを見つけたら、対応するトランザクションをトランザクションテーブルから削除します。\n'
                'ファイルシステムのデータ構造を変更するページ更新レコードを見つけたら、その変更をダーティページテーブルに反映します。</p>\n'
                '<p>メモリ内のテーブルを最新の状態にしたら、NTFS は両テーブルを調べ、ディスクにまだ反映されていない操作を記録した最も古い更新レコードの LSN を求めます。\n'
                'トランザクションテーブルには未コミット（未完了）のトランザクションの LSN が入っています。\n'
                'ダーティページテーブルには、キャッシュ内にあり、まだディスクに書き出されていないレコードの LSN が入っています。\n'
                '両テーブルで見つかった最も古い更新レコードの LSN が、再実行パスの開始位置になります。\n'
                '最後のチェックポイントレコードのほうが古ければ、そこから再実行パスを開始します。</p>\n'
                '<blockquote><p><strong>注記</strong> TxF の回復では、再実行パスが分析パスに相当する処理も担います。\n'
                '詳しくは TxF の回復の節を参照してください。</p></blockquote>',
 'p2-page-732': '<h6>再実行パス</h6>\n'
                '<p>図11-61に示すように、再実行パスでは、分析パスで見つけた最も古い更新レコードの LSN から、ログファイルを順方向に走査します。\n'
                'NTFS は、システム障害前に記録され、まだディスクに書き出されていない可能性のあるボリュームの変更を含むページ更新レコードを探します。\n'
                '該当する更新をキャッシュ内で再実行します。</p>\n'
                '<figure><p>走査の起点は、チェックポイント処理の開始位置より前にある、ディスクに未反映の最も古いログレコードです。\n'
                'チェックポイント処理の開始後には、ダーティページテーブル、更新レコード、トランザクションテーブル、チェックポイントレコードなどが続きます。\n'
                '走査はそれらを通過し、その後の更新レコードにも進みます。</p>\n'
                '<figcaption>図11-61 再実行パス</figcaption></figure>\n'
                '<p>ログファイルの末尾に達した時点で、NTFS は必要なボリュームの変更をキャッシュに反映しています。\n'
                'キャッシュマネージャーのレイジーライターは、キャッシュの内容をバックグラウンドでディスクに書き出し始めることができます。</p>\n'
                '<h6>取り消しパス</h6>\n'
                '<p>再実行パスを終えると、NTFS は取り消しパスを開始し、システム障害時に未コミットだったすべてのトランザクションをロールバックします。\n'
                '図11-62には、ログファイル内の2つのトランザクションが示されています。\n'
                'トランザクション1は停電前にコミットされ、トランザクション2は未コミットでした。\n'
                'NTFS が取り消す必要があるのはトランザクション2です。</p>\n'
                '<figure><p>ログには LSN 4044〜4049 のレコードが並び、トランザクション1にはコミットを示すレコードがあります。\n'
                '停電時に未コミットだったトランザクション2について、取り消しパスは末尾から以前のレコードへさかのぼります。</p>\n'
                '<figcaption>図11-62 取り消しパス</figcaption></figure>\n'
                '<p>トランザクション2がファイルを作成したとします。\n'
                'ファイルの作成は3つの部分操作で構成され、それぞれに更新レコードがあります。\n'
                '同じトランザクションの更新レコードは通常ログ内で隣接しないため、各レコードは同じトランザクションの一つ前のレコードを指すポインターを持ちます。</p>\n'
                '<p>NTFS のトランザクションテーブルは、未コミットのトランザクションごとに、最後に記録した更新レコードの LSN を保持します。\n'
                'この例では、トランザクション2の最後の更新レコードは LSN 4049 です。\n'
                '図11-63に右から左の向きで示すように、NTFS はトランザクション2をロールバックします。</p>',
 'p2-page-733': '<figure><p>ログにはトランザクション1と2のレコードが混在しています。\n'
                'トランザクション2の更新レコードは、取り消し時に LSN 4049、4048、4046 の順にたどります。</p>\n'
                '<table><thead><tr><th>LSN</th><th>再実行</th><th>取り消し</th></tr></thead>\n'
                '<tbody><tr><td>4049</td><td>ビットマップのビット3〜9をセットする</td><td>ビット3〜9をクリアする</td></tr>\n'
                '<tr><td>4048</td><td>ファイル名をインデックスに追加する</td><td>ファイル名をインデックスから削除する</td></tr>\n'
                '<tr><td>4046</td><td>MFT '
                'ファイルレコードを割り当てて初期化する</td><td>ファイルレコードの割り当てを解除する</td></tr></tbody></table>\n'
                '<figcaption>図11-63 トランザクションの取り消し</figcaption></figure>\n'
                '<p>NTFS は LSN 4049 を見つけると、そこに記録された取り消し操作を実行し、割り当てビットマップのビット3〜9をクリアします。\n'
                '次に、直前のレコードを指すポインターをたどって LSN 4048 を読み、対応するファイル名インデックスから新しいファイル名を削除します。\n'
                '最後のポインターをたどって LSN 4046 を読み、そのファイル用に確保した MFT ファイルレコードの割り当てを解除します。\n'
                'これでトランザクション2のロールバックが完了します。\n'
                'ほかに未コミットのトランザクションがあれば、同じ手順でロールバックします。\n'
                '取り消しによってボリュームのファイルシステム構造が変わるため、NTFS は取り消し操作もログファイルに記録します。\n'
                '回復中に再び停電すれば、NTFS は取り消し操作そのものを再実行する必要があるためです。</p>\n'
                '<p>取り消しパスが終わると、ボリュームは整合した状態に戻っています。\n'
                'NTFS はキャッシュ内の変更をディスクへフラッシュできる状態になります。\n'
                'その前に、TxF が LFS のフラッシュ通知を受けるために登録したコールバックを実行します。\n'
                'TxF と NTFS はどちらも先行書き込みログを使うため、TxF は自分のメタデータの整合性を保つよう、NTFS のログがフラッシュされる前に CLFS '
                'を通じて自身のログをフラッシュします。\n'
                '同様に、TOPS ファイルは CLFS が管理するログファイルより先にフラッシュする必要があります。\n'
                'その後 NTFS は「空」の LFS 再開領域を書き込み、ボリュームが整合しており、直後に再び障害が起きても回復処理が不要であることを示します。\n'
                'これで回復は完了します。</p>\n'
                '<p>NTFS の回復処理は、ボリュームを過去の整合した状態に戻します。\n'
                'その状態は、クラッシュ直前の状態より古いことがあります。\n'
                '性能のために<strong>遅延コミット</strong>を使い、トランザクションのコミットを示すレコードを書き込むたびに、ログファイルを直ちにディスクへフラッシュするわけではないためです。\n'
                'キャッシュマネージャーが LFS にログファイルのフラッシュを要求したとき、または LFS '
                'が5秒に1回のチェックポイントレコードを書き込むときに、複数のコミットレコードをまとめてディスクへ書き出します。\n'
                'システムがクラッシュした時点で複数のトランザクションが並行して進んでいると、一部のコミットレコードだけがディスクに書き込まれていることもあります。\n'
                '回復後のボリュームに反映されるのは、コミットレコードがディスクに書き込まれた更新だけです。</p>',
 'p2-page-734': '<p>NTFS はシステム障害後のボリュームの回復に加え、通常のファイル I/O 中に起きるファイルシステムエラーの処理にもログファイルを使います。\n'
                '一般に、ファイルシステムはこうしたエラーから回復するために多くのコードを必要とします。\n'
                'NTFS はボリューム構造を変更するトランザクションをすべて記録しているので、エラーが発生した際にそのログを使って回復でき、エラー処理のコードを大幅に簡素化できます。\n'
                '先に説明したログファイルの容量不足は、その一例です。</p>\n'
                '<p>プログラムが受け取る I/O エラーの大半はファイルシステムのエラーではないため、NTFS だけでは解決できません。\n'
                'たとえばファイルの作成を要求されると、NTFS はまず MFT にファイルレコードを作り、ディレクトリのインデックスに新しいファイル名を追加することがあります。\n'
                'その後、ビットマップでファイルの領域を割り当てようとした時点で、ディスクが満杯で、作成要求を完了できないことが判明する場合があります。\n'
                'その場合、NTFS はログの情報を使って完了済みの操作を取り消し、そのファイル用に確保したデータ構造の割り当てを解除します。\n'
                '次にディスクの容量不足を呼び出し元に返し、呼び出し元がエラーに対処します。</p>\n'
                '<h5>NTFS の不良クラスターからの回復</h5>\n'
                '<p>Windows のボリュームマネージャー（VolMgr）は、フォールトトレラントなボリュームの不良セクターからデータを回復できます。\n'
                'ただし、ハードディスクが不良セクターの再マッピングを行わないか、予備のセクターを使い切っていると、ボリュームマネージャーは不良セクターを置き換えられません。\n'
                'ファイルシステムがそのセクターを読み取ると、ボリュームマネージャーはデータを回復して返し、そのデータのコピーが一つしかないことを警告します。</p>\n'
                '<p>FAT はこの警告に対処しません。\n'
                'FAT もボリュームマネージャーも不良セクターを追跡しないので、同じデータの回復が繰り返されないよう、ユーザーは <code>Chkdsk</code> または '
                '<code>Format</code> を実行する必要があります。\n'
                'ただし、<code>Chkdsk</code> は不良セクターを検出し、使用対象から除外するのに時間がかかることがあり、<code>Format</code> '
                'は対象パーティションのデータをすべて消去します。</p>\n'
                '<p>NTFS はボリュームマネージャーが不良セクターを置き換えられないとき、ファイルシステム側で、そのセクターを含むクラスターを動的に置き換えます。\n'
                'また、その不良クラスターを記録し、再利用されないようにします。\n'
                'NTFS は移植性を保つため、物理セクターではなく論理クラスターを指定します。\n'
                'ボリュームマネージャーから不良セクターの警告を受け取るか、ハードディスクドライバーから不良セクターのエラーを受け取ると、NTFS '
                'はそのセクターを含むクラスターに代わる新しいクラスターを割り当てます。\n'
                'ボリュームマネージャーが回復したデータを新しいクラスターにコピーし、データの冗長性を取り戻します。</p>\n'
                '<p>図11-64には、データラン内に不良クラスターが生じたユーザーファイルの MFT レコードが示されています。\n'
                '図の初期状態は、クラスターが不良になる前の配置です。\n'
                '不良セクターのエラーを受けると、NTFS はそのセクターを含むクラスターを不良クラスターファイル <code>$BadClus</code> に割り当て直します。\n'
                'これにより、そのクラスターがほかのファイルに割り当てられなくなります。\n'
                '次にそのファイルへ新しいクラスターを割り当て、ファイルの VCN と LCN の対応を更新して、新しいクラスターを指すようにします。\n'
                '図11-64は、本章で前述した不良クラスターの再マッピングを示します。\n'
                '不良セクターを含むクラスター1357を、正常なクラスターに置き換えます。</p>',
 'p2-page-735': '<figure><p>ユーザーファイルの MFT レコードには標準情報、ファイル名、データの各属性があります。\n'
                'データ属性は3クラスターずつの2つのランを指しています。</p>\n'
                '<table><thead><tr><th>開始 VCN</th><th>開始 LCN</th><th>クラスター数</th><th>状態</th></tr></thead>\n'
                '<tbody><tr><td>0</td><td>1355</td><td>3</td><td>VCN 2（LCN 1357）が不良</td></tr>\n'
                '<tr><td>3</td><td>1588</td><td>3</td><td>正常</td></tr></tbody></table>\n'
                '<figcaption>図11-64 不良クラスターを含むユーザーファイルの MFT レコード</figcaption></figure>\n'
                '<p>不良セクターのエラーが発生したときは、NTFS とボリュームマネージャーが連携して対処します。\n'
                '不良セクターが冗長構成のボリューム上にあれば、ボリュームマネージャーがデータを回復し、可能であればセクターを置き換えます。\n'
                '置き換えられなければ NTFS に警告を返し、NTFS が不良セクターを含むクラスターを置き換えます。</p>\n'
                '<p>冗長構成でないボリュームでは、不良セクターにあったデータを回復できません。\n'
                'FAT でフォーマットしたボリュームでボリュームマネージャーがデータを回復できない場合、不良セクターを読み取った結果は不定です。\n'
                'そこにファイルシステムの制御構造の一部があると、ファイル全体や複数のファイル、場合によってはディスク全体が失われます。\n'
                '被害が小さい場合でも、対象ファイルのデータの一部が失われ、多くの場合は不良セクターより後ろのすべてのデータが失われます。\n'
                'さらに、FAT が同じ不良セクターをボリューム上の同じファイルや別のファイルに再割り当てし、問題が再発する可能性があります。</p>\n'
                '<p>ほかのファイルシステムと同様、NTFS もボリュームマネージャーの助けなしに不良セクターからデータを回復することはできませんが、被害は大幅に抑えられます。\n'
                '読み取り中に不良セクターを見つけると、図11-65に示すように、そのセクターを含むクラスターを再マッピングします。\n'
                'ボリュームが冗長構成でなければ、呼び出し元プログラムにデータの読み取りエラーを返します。\n'
                'そのクラスターのデータは失われますが、ファイルの残りの部分とファイルシステムは維持されます。\n'
                '呼び出し元はデータの損失に対処でき、不良クラスターは以後の割り当てに使われません。\n'
                '書き込み中に不良クラスターを見つけた場合は、NTFS が書き込み前に再マッピングするため、データは失われず、エラーも発生しません。</p>\n'
                '<p>ファイルシステムのデータを格納するセクターが不良になった場合も、同じ手順で回復します。\n'
                '冗長構成のボリュームでは、ボリュームマネージャーが回復したデータを使い、NTFS がクラスターを動的に置き換えます。\n'
                '冗長構成でなければデータは回復できないため、NTFS は <code>$Volume</code> メタデータファイルで、ボリュームの破損を示すビットをセットします。\n'
                '次のシステム起動時に NTFS の <code>Chkdsk</code> ユーティリティがこのビットを確認し、セットされていれば実行されます。\n'
                '<code>Chkdsk</code> は NTFS のメタデータを再構築して、ファイルシステムの破損を修復します。</p>',
 'p2-page-736': '<figure>\n'
                '<p>不良クラスターファイルとユーザーファイルは、それぞれ標準情報属性とファイル名属性を持ちます。\n'
                '不良クラスターファイルの代替データストリーム <code>$Bad</code> に不良クラスターが移り、ユーザーファイルの <code>$DATA</code> は代替の LCN '
                '1049 を指すようになります。</p>\n'
                '<table><thead><tr><th>ストリーム</th><th>開始 VCN</th><th>開始 LCN</th><th>クラスター数</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td><code>$Bad</code></td><td>0</td><td>1357</td><td>1</td></tr>\n'
                '<tr><td><code>$DATA</code></td><td>0</td><td>1355</td><td>2</td></tr>\n'
                '<tr><td><code>$DATA</code></td><td>2</td><td>1049</td><td>1</td></tr>\n'
                '<tr><td><code>$DATA</code></td><td>3</td><td>1588</td><td>3</td></tr>\n'
                '</tbody></table>\n'
                '<figcaption>図11-65 不良クラスターの再マッピング</figcaption></figure>\n'
                '<p>フォールトトレラントなディスク構成でも、まれにファイルシステムが破損します。\n'
                '障害が重なると、ファイルシステムのデータと、そのデータを再構築する手段の両方が失われることがあります。\n'
                'たとえば、ファイル名インデックスやログファイルの MFT '
                'ファイルレコードをミラーに書き込んでいる間にシステムがクラッシュすると、ミラー上のコピーの更新が完了していない場合があります。\n'
                '再起動後、ミラー上で書き込みが途中だった箇所とまったく同じ位置でプライマリディスクに不良セクターエラーが発生すると、NTFS はミラーから正しいデータを回復できません。</p>\n'
                '<p>NTFS はファイルシステムデータのこの種の破損を検出する仕組みを備えています。\n'
                '不整合を検出するとボリュームファイルの破損ビットをセットし、次回の再起動時に <code>Chkdsk</code> が NTFS のメタデータを再構築します。\n'
                'フォールトトレラントなディスク構成ではファイルシステムの破損がまれなので、<code>Chkdsk</code> が必要になることもまれです。\n'
                '<code>Chkdsk</code> は、通常の回復手段では対処できない場合に備えて用意されています。</p>\n'
                '<p>NTFS と FAT では <code>Chkdsk</code> の実行条件が大きく異なります。\n'
                'FAT はディスクへの書き込み前にボリュームのダーティビットをセットし、変更が完了した後にクリアします。\n'
                'I/O 操作中にクラッシュするとビットがセットされたまま残り、再起動時に <code>Chkdsk</code> が実行されます。\n'
                'NTFS で <code>Chkdsk</code> '
                'が実行されるのは、想定外の形式のファイルシステムデータや読み取れないデータが見つかり、冗長構成のボリュームや、同じボリューム内の冗長なファイルシステム構造を使っても回復できない場合だけです。</p>',
 'p2-page-737': '<p>システムのブートセクターのコピーは、ボリュームの最終セクターにあります。\n'
                'システムの起動と NTFS の回復処理に必要な MFT の部分も、<code>$MftMirr</code> に複製されています。\n'
                'この冗長性によって、NTFS は起動と回復に必要なデータを確保します。</p>\n'
                '<p>表11-11は、Windows '
                'がサポートするファイルシステムでフォーマットしたディスクボリュームでセクターが不良になったときの動作を、ここまで説明した条件別に示します。</p>\n'
                '<table><caption>表11-11 NTFS のデータ回復の概要</caption>\n'
                '<thead><tr><th>構成</th><th>不良セクターの再マッピングに対応し、予備セクターが残っているディスク</th><th>不良セクターを再マッピングしない、または予備セクターがないディスク</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><th scope="row">フォールトトレラントなボリューム（注1）</th>\n'
                '<td><ol><li>ボリュームマネージャーがデータを回復します。</li><li>ボリュームマネージャーが不良セクターを置き換えます。</li><li>ファイルシステムにはエラーが通知されません。</li></ol></td>\n'
                '<td><ol><li>ボリュームマネージャーがデータを回復します。</li><li>ボリュームマネージャーがデータと不良セクターのエラーをファイルシステムに返します。</li><li>NTFS '
                'がクラスターを再マッピングします。</li></ol></td></tr>\n'
                '<tr><th scope="row">フォールトトレラントでないボリューム</th>\n'
                '<td><ol><li>ボリュームマネージャーはデータを回復できません。</li><li>ボリュームマネージャーが不良セクターのエラーをファイルシステムに返します。</li><li>NTFS '
                'がクラスターを再マッピングします。データは失われます（注2）。</li></ol></td>\n'
                '<td><ol><li>ボリュームマネージャーはデータを回復できません。</li><li>ボリュームマネージャーが不良セクターのエラーをファイルシステムに返します。</li><li>NTFS '
                'がクラスターを再マッピングします。データは失われます。</li></ol></td></tr>\n'
                '</tbody></table>\n'
                '<p>注1\u3000ここでいうフォールトトレラントなボリュームは、ミラーセット（RAID-1）または RAID-5 セットです。</p>\n'
                '<p>注2\u3000書き込みではデータは失われません。NTFS が書き込みの前にクラスターを再マッピングするためです。</p>\n'
                '<p>不良セクターがあるボリュームがフォールトトレラントな構成（RAID-1 '
                'のミラー、RAID-5、RAID-6）であり、ディスクが不良セクターの置き換えに対応していて予備セクターも残っている場合、FAT と NTFS '
                'のどちらを使っていても同じ結果になります。\n'
                'ボリュームマネージャーが、ユーザーやファイルシステムの介入なしに不良セクターを置き換えます。</p>\n'
                '<p>不良セクターを置き換えられないディスクでは、ファイルシステムが不良セクターを、NTFS の場合はそのセクターを含むクラスターを再マッピングする必要があります。\n'
                'FAT はセクターもクラスターも再マッピングしません。\n'
                'NTFS のクラスター再マッピングにより、ファイルやファイルシステムに被害を及ぼさずに不良箇所を置き換えられ、不良クラスターが再利用されることもありません。</p>\n'
                '<h5>自己修復</h5>\n'
                '<p>数テラバイトのストレージでは、整合性を検査するためにボリュームをオフラインにすると、サービスが何時間も停止することがあります。\n'
                'ディスクの破損の多くは、単一のファイルかメタデータの一部に限られます。\n'
                'NTFS の<strong>自己修復</strong>は、ボリュームをオンラインに保ったまま破損を修復します。\n'
                '破損を検出すると、NTFS は対象ファイルへのアクセスを止め、システムワーカースレッドを作ります。\n'
                'このスレッドは <code>Chkdsk</code> と同様に破損したデータ構造を修復し、完了後に対象ファイルへ再びアクセスできるようにします。\n'
                'その間もほかのファイルには通常どおりアクセスできるため、サービスへの影響が抑えられます。</p>\n'
                '<p><code>fsutil repair set</code> で、表11-12に示すボリュームの修復オプションを表示、設定できます。\n'
                'Fsutil は <code>FSCTL_SET_REPAIR</code> ファイルシステム制御コードで設定を変更します。\n'
                '設定はボリュームの VCB に保存されます。</p>',
 'p2-page-738': '<table><caption>表11-12 NTFS の自己修復の動作</caption>\n'
                '<thead><tr><th>フラグ</th><th>動作</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td><code>SET_REPAIR_ENABLED</code></td><td>ボリュームの自己修復を有効にします。</td></tr>\n'
                '<tr><td><code>SET_REPAIR_WARN_ABOUT_DATA_LOSS</code></td><td>自己修復でファイルを完全に回復できない場合に、ユーザーに警告を表示するかどうかを指定します。</td></tr>\n'
                '<tr><td><code>SET_REPAIR_DISABLED_AND_BUGCHECK_ON_CORRUPTION</code></td><td><code>fsutil '
                'behavior set NtfsBugCheckOnCorrupt 1</code> で NTFS のレジストリ値 '
                '<code>NtfsBugCheckOnCorrupt</code> を設定し、このフラグも設定すると、ファイルシステムの破損時に停止エラー <code>0x24</code> '
                'でシステムが停止します。再起動を繰り返さないよう、この設定は起動時に自動で解除されます。</td></tr>\n'
                '</tbody></table>\n'
                '<p>NTFS は、警告の表示が無効な場合（既定）も含め、実行した自己修復をすべてシステムイベントログに記録します。</p>\n'
                '<p>NTFS は定期的な自動自己修復に加え、手動で開始する自己修復（プロアクティブ修復）もサポートします。\n'
                '制御コード <code>FSCTL_INITIATE_REPAIR</code> と <code>FSCTL_WAIT_FOR_REPAIR</code> は、それぞれ '
                '<code>fsutil repair initiate</code> と <code>fsutil repair wait</code> で利用できます。\n'
                'ユーザーは特定のファイルの修復を開始し、その完了を待てます。</p>\n'
                '<p>自己修復の状態を調べるには、制御コード <code>FSCTL_QUERY_REPAIR</code> または <code>fsutil repair query</code> '
                'コマンドを使います。</p>\n'
                '<pre><code>C:&#92;&gt;fsutil repair query c:\n'
                'C: の自己修復状態: 0x9\n'
                '\n'
                '値:\n'
                '0x1  通常の修復を有効にする。\n'
                '0x9  修復を有効にし、データが失われる可能性を警告する。\n'
                '0x10 修復を無効にし、最初の破損時に一度だけシステムを停止する。</code></pre>\n'
                '<h5>オンラインディスク検査と高速修復</h5>\n'
                '<p>NTFS ドライバーが自己修復やログファイルサービスなどでディスクの破損に対処できない場合は、Windows '
                'のチェックディスクツールを実行し、ボリュームをオフラインにする必要があります。\n'
                'これはまれですが、ハードディスクのメディアエラーや一時的なメモリエラーなど、さまざまな原因でファイルシステムのメタデータが破損します。\n'
                '数テラバイトのディスク領域を持つ大規模なファイルサーバーでは、ディスク全体を検査すると数日かかることがあります。\n'
                'このような環境でボリュームをそれほど長くオフラインにすることは、通常許容できません。</p>\n'
                '<p>Windows 8より前の NTFS では、<code>$VOLUME_INFORMATION</code> '
                '属性に格納したダーティビットで、ボリュームが正常かどうかを表していました。\n'
                'この方式では、ファイルシステムの破損を修復し、正常な状態に戻るまでボリュームをオフラインにしていました。\n'
                '停止時間は、ボリューム内のファイル数に比例しました。\n'
                'Windows 8では、ファイルシステムの破損による停止時間を短縮または解消するため、NTFS の正常性の管理モデルとディスク検査を再設計しました。</p>\n'
                '<p>新しいモデルでは、複数のコンポーネントが連携してオンラインでディスクを検査し、ファイルシステムに深刻な破損が見つかった場合の停止時間を大幅に短縮します。\n'
                'NTFS ドライバーは通常のシステム I/O の最中に複数の種類の破損を検出できます。</p>',
 'p2-page-739': '<p>破損を検出すると、NTFS は前述の自己修復を試みます。\n'
                '修復できなければ、NTFS ドライバーは <code>&#92;$Extend&#92;$RmMetadata&#92;$Repair</code> ファイルの '
                '<code>$Verify</code> ストリームに新しい破損レコードを書き込みます。</p>\n'
                '<p><strong>破損レコード</strong>は、NTFS がメタデータの破損を記述するために使う共通のデータ構造です。\n'
                'メモリとディスクの両方で同じ構造を使います。\n'
                '固定長のヘッダーには、バージョン情報、フラグ、レコードの種類を一意に識別する GUID が入ります。\n'
                'その後に、発生した破損の種類を表す可変長の記述と、必要に応じてコンテキストが続きます。</p>\n'
                '<p>エントリの追加が完了すると、NTFS はイベントプロバイダー <code>Microsoft-Windows-Ntfs-UBPM</code> を通じて ETW '
                'イベントを発行します。\n'
                'サービスコントロールマネージャーはこのイベントを受けて Spot Verifier サービスを起動します。\n'
                'トリガーで起動するサービスについては、第10章を参照してください。</p>\n'
                '<p>Spot Verifier サービスは <code>Svsvc.dll</code> に実装されており、通知された破損が誤検出かどうかを確認します。\n'
                'メモリの問題で一時的な不整合が生じ、ディスク上のデータは実際には破損していない場合があるためです。\n'
                'Spot Verifier が検証を進める際、対象のエントリは <code>$Verify</code> ストリームから削除されます。\n'
                '破損が誤検出でなければ、Spot Verifier はボリュームの <code>$VOLUME_INFORMATION</code> 属性でプロアクティブスキャンビット（P '
                'ビット）をセットし、ファイルシステムのオンラインスキャンを要求します。\n'
                'オンラインスキャンを実行するのはプロアクティブスキャナーです。\n'
                '図11-66のように、メンテナンスタスクは <code>Microsoft&#92;Windows&#92;Chkdsk</code> にあり、Windows '
                'のタスクスケジューラが適切な時点で起動します。</p>\n'
                '<figure><img loading="lazy" width="684" height="480" '
                'src="assets/e4354145afbf02b951f627cd.webp" alt="タスクスケジューラで Chkdsk のプロアクティブスキャンタスクを表示した画面">\n'
                '<figcaption>図11-66 プロアクティブスキャンのメンテナンスタスク</figcaption></figure>',
 'p2-page-740': '<p>プロアクティブスキャナーは、Windows のチェックディスクツール（<code>Chkdsk.exe</code>）が読み込む <code>Untfs.dll</code> '
                'に実装されています。\n'
                'スキャナーは実行時に、ボリュームシャドウコピーサービスで対象ボリュームのスナップショットを取り、シャドウボリュームに対して完全なディスク検査を実行します。\n'
                '検査処理はシャドウボリュームが読み取り専用であることを検出し、NTFS の自己修復機能を使って破損の自動修復を試みます。\n'
                '修復に失敗すると、ファイルシステムドライバーに <code>FSCTL_CORRUPTION_HANDLING</code> を送ります。\n'
                'ドライバーはメタデータファイル <code>&#92;$Extend&#92;$RmMetadata&#92;$Repair</code> の '
                '<code>$Corrupt</code> ストリームにエントリを作り、ボリュームのダーティビットをセットします。</p>\n'
                '<p>ダーティビットの意味は、以前の Windows とは少し異なります。\n'
                'NTFS のルート名前空間の <code>$VOLUME_INFORMATION</code> 属性には従来のダーティビットに加え、プロアクティブスキャンを要求する P '
                'ビットと、深刻な破損のために完全なディスク検査を要求する F ビットがあります。\n'
                'ファイルシステムドライバーは、P ビットか F ビットがセットされている場合、または <code>$Corrupt</code> '
                'ストリームに破損レコードが1件以上ある場合に、ダーティビットを1にします。</p>\n'
                '<p>それでも破損が解消されなければ、以降はボリュームをオフラインにして修復する必要があります。\n'
                'すぐにボリュームをアンマウントする必要はありません。\n'
                'Spot Fixer は、チェックディスクと Autocheck が共用する新しいコンポーネントです。\n'
                'プロアクティブスキャナーが <code>$Corrupt</code> ストリームに追加したレコードを処理します。\n'
                '起動時、ネイティブアプリケーションの Autocheck はボリュームのダーティビットを検出し、<code>$Corrupt</code> '
                'ストリームに記録された箇所だけを修復します。\n'
                'ボリューム全体の検査を省けるため、修復は数秒で終わります。\n'
                '図11-67に、ここまでに説明した各コンポーネントの修復手順を示します。</p>\n'
                '<figure><img loading="lazy" width="568" height="359" '
                'src="assets/9561936b97b1cc1fe4a569e3.webp" alt="自己修復、Spot Verifier、プロアクティブスキャナー、Spot Fixer '
                'が連携する流れ">\n'
                '<figcaption>図11-67 NTFS ボリュームのオンライン検査と高速修復に関わるコンポーネント</figcaption></figure>\n'
                '<p><code>chkdsk /scan</code> コマンドで、ボリュームのプロアクティブスキャンを手動で開始できます。\n'
                'チェックディスクツールに <code>/spotfix</code> を指定すれば、Spot Fixer を実行できます。</p>',
 'p2-page-741': '<h6>実験\u3000オンラインでディスクを検査する</h6>\n'
                '<p>D: ボリュームをオンラインで検査しながら、そのボリュームにアクセスし続けられることを確認します。\n'
                'まず D: ドライブにある大きな動画を再生します。\n'
                '再生中に管理者としてコマンドプロンプトを開き、次のコマンドでオンライン検査を始めます。</p>\n'
                '<pre><code>C:&#92;&gt;chkdsk d: /scan\n'
                'ファイルシステムの種類は NTFS です。\n'
                'ボリュームラベルは DATA です。\n'
                '\n'
                'ステージ1: 基本のファイルシステム構造を検査しています...\n'
                '4041984 個のファイルレコードを処理しました。\n'
                'ファイルの検査を完了しました。\n'
                '3778 個の大きなファイルレコードを処理しました。\n'
                '0 個の不良ファイルレコードを処理しました。\n'
                '\n'
                'ステージ2: ファイル名のリンクを検査しています...\n'
                '進捗: 4056090 件中 3454102 件完了。ステージ: 85%。全体: 51%。残り時間: 0:00:43 ...</code></pre>\n'
                '<p>検査中も動画は中断せず、滑らかに再生されます。\n'
                'ボリュームをマウントしたまま修正できないエラーが見つかると、オンライン検査はエラーをシステムファイル <code>$Repair</code> の '
                '<code>$Corrupt</code> ストリームに記録します。\n'
                '修復にはボリュームのアンマウントが必要ですが、修復そのものは短時間で終わります。\n'
                'システムを再起動するか、次のコマンドで Spot Fixer を手動で実行できます。</p>\n'
                '<pre><code>C:&#92;&gt;chkdsk d: /spotfix</code></pre>\n'
                '<p>Spot Fixer を実行すると、ボリュームをアンマウントするため、動画の再生は中断します。</p>\n'
                '<h4>暗号化ファイルシステム</h4>\n'
                '<p>Windows には、ボリューム全体を暗号化する Windows BitLocker ドライブ暗号化が備わっています。\n'
                'BitLocker はボリュームを暗号化してオフライン攻撃から守ります。\n'
                '起動後のシステム上では、暗号化ファイルシステム（EFS）が、個々のファイルやディレクトリを他の認証済みユーザーから保護します。\n'
                'BitLocker と EFS はそれぞれ異なる脅威に対応し、両方を組み合わせるとデータを多層防御できます。</p>\n'
                '<p>EFS はファイルやディレクトリを共通鍵暗号で暗号化します。\n'
                '共通鍵暗号では、ファイルの暗号化と復号に同じ鍵を使います。\n'
                'EFS は、ファイルへのアクセスを許可されたユーザーごとに、その共通鍵を公開鍵暗号で暗号化します。\n'
                '公開鍵暗号では、暗号化に使う公開鍵と、復号に使う秘密鍵が異なります。\n'
                'これらの暗号方式の理論と詳細は本書の範囲外です。\n'
                '入門資料として、<a '
                'href="https://docs.microsoft.com/en-us/windows/desktop/SecCrypto/cryptography-essentials">Microsoft '
                'の暗号化の基礎</a>を参照してください。</p>',
 'p2-page-742': '<p>EFS は Windows の Cryptography Next Generation（CNG）API を利用します。\n'
                'そのため、CNG がサポートするアルゴリズムや、CNG に追加されたアルゴリズムを使うように設定できます。\n'
                '既定では、共通鍵暗号に256ビット鍵の AES（Advanced Encryption Standard）を、公開鍵暗号に2048ビット鍵の '
                'RSA（Rivest–Shamir–Adleman）を使います。</p>\n'
                '<p>エクスプローラーでファイルを暗号化するには、ファイルのプロパティを開き、「詳細設定」をクリックして「内容を暗号化してデータをセキュリティで保護する」を選びます（図11-68）。\n'
                '1つのファイルに暗号化と圧縮を同時に適用することはできません。\n'
                'コマンドラインユーティリティの '
                'Cipher（<code>%SystemRoot%&#92;System32&#92;Cipher.exe</code>）や、<code>EncryptFile</code> と '
                '<code>AddUsersToEncryptedFile</code> などの Windows API も利用できます。</p>\n'
                '<p>暗号化対象として指定されたディレクトリに置いたファイルは、Windows が自動的に暗号化します。\n'
                'ファイルを暗号化するとき、EFS はファイルごとに乱数を生成します。\n'
                'この値を<strong>ファイル暗号化キー</strong>（FEK）と呼び、共通鍵としてファイルの内容を暗号化するために使います。\n'
                '次に EFS は、ユーザーの公開鍵で FEK を暗号化し、ファイルの <code>$EFS</code> 代替データストリームに格納します。\n'
                '管理者は割り当て済みの X.509 証明書やスマートカードを公開鍵の取得元として指定できます。\n'
                '新しくランダムに生成することもでき、その場合はユーザーの証明書ストアに追加されます。\n'
                'ストアは証明書マネージャー（<code>%SystemRoot%&#92;System32&#92;Certmgr.msc</code>）で確認できます。\n'
                '暗号化後、ファイルの内容を復号するには復号済みの FEK が必要で、その FEK を復号できるのは対応する秘密鍵を持つユーザーです。</p>\n'
                '<figure><img loading="lazy" width="324" height="251" '
                'src="assets/ee647f70f32af547939a9b42.webp" alt="詳細属性のダイアログで、内容を暗号化してデータを保護する設定を選ぶ画面">\n'
                '<figcaption>図11-68 詳細属性のダイアログでファイルを暗号化する</figcaption></figure>\n'
                '<p>共通鍵暗号は一般に高速で、ファイルのような大量のデータを暗号化するのに適しています。\n'
                'その一方で、鍵を取得した人は誰でもデータを復号できます。\n'
                '共通鍵暗号だけで保護したファイルを複数のユーザーで共有する場合、全員がファイルの FEK を取得できる必要があります。\n'
                'FEK を平文のまま置けば保護が失われます。\n'
                'FEK を一度だけ暗号化する方法でも、全員がその FEK を復号する同じ鍵を共有する必要があり、鍵の管理が難しくなります。</p>\n'
                '<p>EFS は公開鍵暗号を組み合わせて FEK を保護します。\n'
                'アクセスを許可されたユーザーごとに同じファイルの FEK を個別に暗号化することで、暗号化されたファイルを複数のユーザーで共有できます。\n'
                'EFS はユーザーそれぞれの公開鍵で FEK を暗号化し、その結果をファイルの <code>$EFS</code> データストリームに格納できます。\n'
                'ユーザーの公開鍵は誰でも取得できます。</p>',
 'p2-page-743': '<p>公開鍵で暗号化したデータを、その公開鍵で復号することはできません。\n'
                'ファイルを復号するには、OS がユーザーの秘密鍵にアクセスし、そのユーザー向けに暗号化されたファイル暗号化キー（FEK）を復号する必要があります。\n'
                '公開鍵暗号のアルゴリズムは一般に低速ですが、EFS がこれを使うのは FEK の暗号化だけです。\n'
                '公開できる鍵と秘密にする鍵に役割を分けることで、共通鍵暗号だけの場合に比べて鍵の管理が容易になり、FEK を保護したままファイルを共有できます。</p>\n'
                '<p>図11-69のアーキテクチャに示すように、EFS は複数のコンポーネントが連携して動作します。\n'
                'EFS のサポートは NTFS ドライバーに組み込まれています。\n'
                'NTFS が暗号化されたファイルを扱うときは、ドライバー内の EFS 関数を実行します。\n'
                'アプリケーションが暗号化ファイルにアクセスする際に、EFS 関数がファイルデータを暗号化または復号します。\n'
                'EFS はファイルのデータとともに FEK を格納しますが、その FEK はユーザーの公開鍵で暗号化されています。\n'
                'ファイルデータを暗号化または復号するには、ユーザーモードにある CNG の鍵管理サービスを使って FEK を復号する必要があります。</p>\n'
                '<figure>\n'
                '<ul>\n'
                '<li>ユーザーはログオンし、<code>CreateFile</code> や EFS API を使います。ファイル I/O ではアプリケーションが平文を扱い、カーネルの NTFS '
                'と EFS カーネル補助ライブラリを経由して、ディスクには暗号文が書き込まれます。</li>\n'
                '<li>Windows 10 クライアントと旧バージョンのクライアントは EFSRPC を使います。図には RPC クライアント、EFSRPC の転送、および EFSRPC '
                '用のファイルシステム制御（FSCTL）も示されています。</li>\n'
                '<li>ユーザーの鍵ストアは鍵を保持します。グループポリシー、レジストリ、LSA のドメインポリシーストアは設定や EFS の回復ポリシーに関わります。LSA と Kerberos '
                'の経路には、スマートカードログオン、PIN、証明書が示されています。EFS サービスはユーザーの機密情報と EFS キャッシュを扱います。</li>\n'
                '</ul>\n'
                '<figcaption>図11-69 EFS のアーキテクチャ</figcaption></figure>\n'
                '<p>ローカルセキュリティ機関サブシステム（LSASS、<code>%SystemRoot%&#92;System32&#92;Lsass.exe</code>）は、ログオンセッションを管理し、EFS '
                'サービス（<code>Efssvc.dll</code>）もホストします。\n'
                'たとえばユーザーが読みたいファイルのデータを復号するために FEK の復号が必要になると、NTFS は LSASS 内の EFS サービスに要求を送ります。</p>',
 'p2-page-744': '<h5>ファイルを初めて暗号化する</h5>\n'
                '<p>NTFS ドライバーは暗号化ファイルに遭遇すると EFS の補助関数を呼び出します。\n'
                '本章で前述した圧縮状態と同様に、暗号化されていることはファイルの属性に記録されます。\n'
                'NTFS はファイルを暗号化されていない状態から暗号化済みの状態に変換する専用のインターフェイスを備えていますが、処理を主導するのはユーザーモードのコンポーネントです。\n'
                '前述のように、Windows ではコマンドラインの <code>cipher</code> '
                'を使うか、エクスプローラーのファイルの詳細属性ダイアログで「内容を暗号化してデータをセキュリティで保護する」を選んで暗号化できます。\n'
                'エクスプローラーも <code>cipher</code> も Windows API の <code>EncryptFile</code> を使います。</p>\n'
                '<p>EFS は暗号化ファイルに1つの情報ブロックを格納します。\n'
                'このブロックにはファイルを共有するユーザーごとに<strong>キーエントリ</strong>があり、EFS はこれらをファイルの EFS '
                'データ内の<strong>データ復号フィールド</strong>（DDF）に格納します。\n'
                'EFS では暗号化ファイルを複数のユーザーで共有できるため、複数のキーエントリをまとめたものを<strong>キーリング</strong>と呼びます。</p>\n'
                '<p>図11-70にファイルの EFS 情報とキーエントリの形式を示します。\n'
                'キーエントリの前半には、ユーザーの公開鍵を正確に識別できる情報が入ります。\n'
                '具体的には、ユーザーのセキュリティ識別子（SID）、鍵を格納するコンテナーの名前、暗号化プロバイダーの名前、公開鍵と秘密鍵のペアに対応する証明書のハッシュです。\n'
                'SID が入っていない場合もあります。\n'
                '復号処理が前半の情報から使うのは、証明書のハッシュだけです。\n'
                'キーエントリの後半には暗号化済みのファイル暗号化キー（FEK）が入ります。\n'
                'EFS は CNG を使い、選択された公開鍵暗号アルゴリズムとユーザーの公開鍵で FEK を暗号化します。</p>\n'
                '<figure>\n'
                '<table><thead><tr><th>EFS 情報の領域</th><th>内容</th></tr></thead>\n'
                '<tbody><tr><td>ヘッダー</td><td>バージョン、チェックサム</td></tr>\n'
                '<tr><td>データ復号フィールド（DDF）</td><td>DDF のキーエントリ数、DDF キーエントリ1、DDF キーエントリ2</td></tr>\n'
                '<tr><td>データ回復フィールド（DRF）</td><td>DRF のキーエントリ数、DRF キーエントリ1</td></tr></tbody></table>\n'
                '<p>キーエントリの例には、ユーザー '
                'SID（<code>S-1-5-21-...</code>）、コンテナー名（<code>ee341-2144-55ba...</code>）、プロバイダー名（<code>Microsoft '
                'Base Cryptographic Provider 1.0</code>）、EFS 証明書のハッシュ（<code>cb3e4e...</code>）、暗号化済みの '
                'FEK（<code>03fe4f3c...</code>）が入ります。</p>\n'
                '<figcaption>図11-70 EFS 情報とキーエントリの形式</figcaption></figure>\n'
                '<p>EFS は回復用のキーエントリを、ファイルの<strong>データ回復フィールド</strong>（DRF）に格納します。\n'
                'DRF のエントリ形式は DDF と同じです。\n'
                '管理権限でユーザーのデータにアクセスする必要がある場合に、指定されたアカウントである<strong>回復エージェント</strong>がファイルを復号できるようにするのが DRF '
                'の役割です。\n'
                'たとえば社員がログオンパスワードを忘れた場合、管理者はパスワードをリセットできます。\n'
                '回復エージェントがいなければ、そのユーザーの暗号化データを回復できる人はいません。</p>',
 'p2-page-745': '<p>回復エージェントは、ローカルコンピューターまたはドメインの「暗号化データ回復エージェント」セキュリティポリシーで定義します。\n'
                '図11-71に示すように、このポリシーは「ローカル セキュリティ ポリシー」MMC スナップインで設定できます。\n'
                '「暗号化ファイル システム」を右クリックし、「データ回復エージェントの追加」をクリックすると、回復エージェントの追加ウィザードが開きます。\n'
                'ウィザードでは、回復エージェントを追加し、EFS の回復に使う公開鍵と秘密鍵のペアを証明書で指定できます。\n'
                'ローカルセキュリティ機関サービスの Lsasrv は、初期化時と回復ポリシーの変更通知を受けたときに、ポリシーを解釈します。\n'
                'Lsasrv については第1巻の第7章を参照してください。\n'
                'EFS は、EFS の回復用に登録された暗号化プロバイダーを使い、回復エージェントごとに DRF キーエントリを作成します。</p>\n'
                '<figure><img loading="lazy" width="665" height="320" '
                'src="assets/6780e191ed21244fd23d8b8f.webp" alt="暗号化データ回復エージェントのポリシーを表示した管理画面">\n'
                '<figcaption>図11-71 暗号化データ回復エージェントのグループポリシー</figcaption></figure>\n'
                '<p>ユーザーは <code>cipher /r</code> で独自のデータ回復エージェント（DRA）証明書を作成できます。\n'
                '生成された秘密鍵付きの証明書ファイルは、回復エージェントのウィザードや、ドメインコントローラーまたは管理者がファイルを復号するコンピューターの「証明書」スナップインにインポートできます。</p>\n'
                '<p>ファイルの EFS 情報を作成する最後の段階で、Lsasrv は Base Cryptographic Provider 1.0 の MD5 ハッシュ機能を使って DDF と '
                'DRF のチェックサムを計算し、EFS 情報のヘッダーに格納します。\n'
                '復号時、EFS はこのチェックサムを参照し、EFS 情報の内容が破損または改変されていないことを確認します。</p>\n'
                '<h5>ファイルデータの暗号化</h5>\n'
                '<p>ユーザーが既存のファイルを暗号化すると、次の処理が行われます。</p>\n'
                '<ol>\n'
                '<li>EFS サービスが排他アクセスでファイルを開きます。</li>\n'
                '<li>ファイルのすべてのデータストリームを、システムの一時ディレクトリに作成した平文の一時ファイルにコピーします。</li>\n'
                '<li>ファイル暗号化キー（FEK）をランダムに生成し、その鍵でファイルを AES-256 で暗号化します。</li>\n'
                '</ol>',
 'p2-page-746': '<ol start="4">\n'
                '<li>ユーザーの公開鍵で暗号化した FEK を保持するために DDF を作成します。\n'
                'EFS はユーザーの X.509 バージョン3のファイル暗号化証明書から公開鍵を自動的に取得します。</li>\n'
                '<li>グループポリシーで回復エージェントが指定されている場合は、RSA と回復エージェントの公開鍵で暗号化した FEK を保持するために DRF を作成します。</li>\n'
                '<li>EFS は、EFS 回復ポリシーに格納されている回復エージェントの X.509 バージョン3証明書から、ファイル回復用の公開鍵を自動的に取得します。\n'
                '回復エージェントが複数いる場合は、それぞれの公開鍵で FEK のコピーを暗号化し、暗号化した FEK をそれぞれ DRF に格納します。\n'
                '<blockquote><p><strong>注記</strong> 証明書のファイル回復プロパティは、拡張キー使用法（EKU）の一例です。\n'
                'EKU の拡張フィールドと拡張プロパティは、証明書を使用できる目的を指定し、制限します。\n'
                'ファイル回復は、Microsoft が自社の公開鍵基盤（PKI）の一部として定義した EKU の一つです。</p></blockquote></li>\n'
                '<li>EFS は暗号化したデータと DDF、DRF をファイルに書き戻します。\n'
                '共通鍵暗号でデータの長さは増えないため、暗号化後のサイズの増加はわずかです。\n'
                '主に暗号化された FEK からなるメタデータは、通常1 KB未満です。\n'
                '表示されるファイルサイズは通常、暗号化の前後で同じです。</li>\n'
                '<li>平文の一時ファイルを削除します。</li>\n'
                '</ol>\n'
                '<p>暗号化が設定されたフォルダーにファイルを保存した場合も、同様の処理が行われます。\n'
                'このとき一時ファイルは作成されません。</p>\n'
                '<h5>復号処理</h5>\n'
                '<p>アプリケーションが暗号化ファイルにアクセスすると、次のように復号します。</p>\n'
                '<ol>\n'
                '<li>NTFS はファイルが暗号化されていることを認識し、EFS ドライバーに要求を送ります。</li>\n'
                '<li>EFS ドライバーは DDF を取得し、EFS サービスに渡します。</li>\n'
                '<li>EFS サービスはユーザープロファイルからユーザーの秘密鍵を取得し、それを使って DDF 内の暗号化済み FEK を復号します。</li>\n'
                '<li>EFS サービスは FEK を EFS ドライバーに返します。</li>\n'
                '<li>EFS ドライバーはその FEK を使い、アプリケーションが必要とするファイルの部分を復号します。</li>\n'
                '</ol>\n'
                '<blockquote><p><strong>注記</strong> EFS '
                'は暗号ブロック連鎖（CBC）を使うため、アプリケーションがファイルを開いたときは、使用する部分だけを復号します。\n'
                'ユーザーがファイルの暗号化属性を解除した場合は、ファイル全体を復号し、平文で書き直します。</p></blockquote>',
 'p2-page-747': '<ol start="6"><li>EFS ドライバーは復号したデータを NTFS に返し、NTFS が要求元のアプリケーションに渡します。</li></ol>\n'
                '<h5>暗号化されたファイルのバックアップ</h5>\n'
                '<p>ファイル暗号化の設計では、暗号化機能を介してアクセスするアプリケーションだけが、ファイルの平文を取得できることが重要です。\n'
                'この制約は、アーカイブ用のメディアにファイルを保存するバックアップユーティリティにも関わります。\n'
                'EFS は、ファイルを暗号化した状態のままバックアップし、復元するための手段を提供します。\n'
                'これにより、バックアップユーティリティはバックアップ時にファイルを復号したり、改めて暗号化したりする必要がありません。</p>\n'
                '<p>バックアップユーティリティは、Windows の EFS API である '
                '<code>OpenEncryptedFileRaw</code>、<code>ReadEncryptedFileRaw</code>、<code>WriteEncryptedFileRaw</code>、<code>CloseEncryptedFileRaw</code> '
                'で、ファイルの暗号化された内容にアクセスします。\n'
                'バックアップ時は、ファイルを暗号化されたまま扱うモードで開き、<code>ReadEncryptedFileRaw</code> を呼び出してデータを取得します。\n'
                'これらのバックアップ用 API はすべて、NTFS にファイルシステム制御コード（FSCTL）を発行します。\n'
                'たとえば <code>ReadEncryptedFileRaw</code> は最初に <code>FSCTL_ENCRYPTION_FSCTL_IO</code> を NTFS '
                'ドライバーに発行して <code>$EFS</code> ストリームを読み取り、次に <code>$DATA</code> '
                'や代替データストリームを含むファイルのすべてのストリームを読み取ります。\n'
                'ストリームが暗号化されている場合は、<code>FSCTL_READ_RAW_ENCRYPTED</code> '
                'によって暗号化されたままのストリームデータをドライバーに要求します。</p>\n'
                '<h6>実験\u3000EFS 情報を表示する</h6>\n'
                '<p>EFS は、暗号化ファイルを操作するための API をほかにも提供します。\n'
                'たとえばアプリケーションは、<code>AddUsersToEncryptedFile</code> '
                'を使ってアクセスを許可するユーザーを追加し、<code>RemoveUsersFromEncryptedFile</code> を使ってアクセスを取り消せます。\n'
                '<code>QueryUsersOnEncryptedFile</code> はファイルの DDF と DRF '
                'のキーエントリについて、SID、証明書のハッシュ値、表示情報を返します。\n'
                '次の例では、Sysinternals の EFSDump に、暗号化されたファイルをコマンドライン引数として渡しています。</p>\n'
                '<pre><code>C:&#92;Andrea&gt;efsdump Test.txt\n'
                'EFS 情報ダンプツール v1.02\n'
                'Copyright (C) 1999 Mark Russinovich\n'
                'Systems Internals - http://www.sysinternals.com\n'
                '\n'
                'C:&#92;Andrea&#92;Test.txt:\n'
                'DDF エントリ:\n'
                'WIN-46E4EFTBP6Q&#92;Andrea:    Andrea(Andrea@WIN-46E4EFTBP6Q)\n'
                '不明なユーザー:              Tony(Tony@WIN-46E4EFTBP6Q)\n'
                'DRF エントリ:\n'
                '不明なユーザー:              EFS データ回復</code></pre>',
 'p2-page-748': '<p><code>Test.txt</code> には、ユーザー Andrea と Tony に対応する2つの DDF エントリと、EFS データ回復エージェントに対応する1つの '
                'DRF エントリがあります。\n'
                'このエージェントは、現在システムに登録されている唯一の回復エージェントです。\n'
                '<code>cipher</code> ツールを使うと、ファイルの DDF エントリにユーザーを追加したり、そこから削除したりできます。\n'
                'たとえば次のコマンドは <code>Test.txt</code> の DDF にエントリを追加し、ユーザー Tony が暗号化ファイルにアクセスできるようにします。</p>\n'
                '<pre><code>cipher /adduser /user:Tony Test.txt</code></pre>\n'
                '<h5>暗号化ファイルのコピー</h5>\n'
                '<p>暗号化ファイルをコピーするとき、システムは暗号化されたデータと EFS の代替データストリームを、そのまま指定された宛先にコピーします。\n'
                'コピー元で復号し、コピー先で再暗号化する処理は行いません。\n'
                'ただし、コピー先が代替データストリームに対応しない場合は、ストリームが失われるため通常どおりにコピーできません。\n'
                'たとえば、コピー先が FAT などの NTFS 以外のボリュームである場合や、ネットワーク共有である場合が該当します。\n'
                'この場合、共有先のボリュームが NTFS であっても同じです。</p>\n'
                '<p>エクスプローラーでコピーすると、コピー先が暗号化に対応していないことを知らせるダイアログが表示され、ファイルを暗号化せずにコピーするかどうかを尋ねられます。\n'
                'ユーザーが同意すると、ファイルは復号され、指定された宛先にコピーされます。\n'
                'コマンドプロンプトからコピーした場合は処理が失敗し、「指定されたファイルを暗号化できませんでした」というエラーが返ります。</p>\n'
                '<h5>BitLocker への暗号化処理のオフロード</h5>\n'
                '<p>NTFS ドライバーは暗号化ファイルシステム（EFS）が提供する機能を使って、ファイルを暗号化または復号します。\n'
                'カーネルモードの EFS 機能はユーザーモードの EFS サービス（<code>Efssvc.dll</code>）と通信し、NTFS はコールバックを介してその機能を使います。\n'
                'ユーザーやアプリケーションが初めてファイルを暗号化すると、EFS サービスは <code>FSCTL_SET_ENCRYPTION</code> 制御コードを NTFS '
                'ドライバーに送ります。\n'
                'NTFS ドライバーは EFS の書き込みコールバックを使い、元のファイルのデータをメモリ内で暗号化します。</p>\n'
                '<p>ファイルの内容は通常2 MBのブロックで処理し、暗号化の際は各ブロックを512バイトずつに分割します。\n'
                'EFS ライブラリは <code>BCryptEncrypt</code> API を使って各部分を暗号化します。\n'
                '暗号化エンジンを提供するカーネルの CNG ドライバー（<code>Cng.sys</code>）は、EFS が使う AES や 3DES '
                'に加え、ほかにも多くのアルゴリズムをサポートします。\n'
                '512バイトは標準的なハードディスクセクターの最小の物理サイズです。\n'
                'EFS '
                'は512バイト分を暗号化するたびに、処理中のブロックのバイトオフセットを使い、暗号化結果に変化を持たせる128ビットの初期化ベクトル（IV、原文ではソルト値とも呼んでいます）を更新します。</p>\n'
                '<p>Windows 10では、BitLocker への暗号化処理のオフロードにより性能が向上しました。\n'
                'BitLocker が有効な場合、ストレージスタックにはボリューム全体の暗号化を担うドライバー（<code>Fvevol.sys</code>）が作ったデバイスが含まれます。\n'
                'ボリュームが暗号化されていれば、このデバイスは物理ディスクセクターの暗号化と復号をリアルタイムに行います。\n'
                '暗号化されていない場合、I/O 要求をそのまま下位に渡します。</p>',
 'p2-page-749': '<p>NTFS ドライバーは IRP 拡張を使って、ファイルの暗号化を下位のドライバーに委ねられます。\n'
                'IRP 拡張は I/O マネージャーが提供する仕組みで、さまざまな追加情報を IRP に格納できます。\n'
                'I/O マネージャーについては第1巻の第6章を参照してください。\n'
                'ファイルの作成時に EFS ドライバーは <code>IOCTL_FVE_GET_CDOPATH</code> 制御コードを使い、デバイススタックに BitLocker '
                'の制御デバイスオブジェクト（CDO）があるかを調べます。\n'
                '見つかると、ストリームが暗号化のオフロードに対応していることを示すフラグを SCB に設定します。</p>\n'
                '<p>暗号化済みのファイルを読み書きするときや、ファイルを初めて暗号化するとき、NTFS '
                'ドライバーはフラグを見て、ファイルの各ブロックを自分で暗号化または復号する必要があるかを判断します。\n'
                'オフロードが有効な場合、NTFS は EFS の呼び出しを省き、物理 I/O を処理するボリュームデバイスに送る IRP に拡張を追加します。\n'
                'IRP 拡張には、ストレージドライバーが読み書きするファイルブロックの開始仮想バイトオフセット、サイズ、フラグを格納します。\n'
                '最後に NTFS は <code>IoCallDriver</code> API で対象のボリュームデバイスに I/O を発行します。</p>\n'
                '<p>ボリュームマネージャーは IRP を解析し、該当するストレージドライバーに送ります。\n'
                'BitLocker ドライバーは IRP 拡張を認識し、NTFS がデバイススタックの下位へ送ったデータを、物理セクターを処理する自身のルーチンで暗号化します。\n'
                'BitLocker はボリュームフィルタードライバーなので、ファイルやディレクトリという単位は扱いません。</p>\n'
                '<p>動的ディスクを提供する論理ディスクマネージャードライバー（<code>VolmgrX.sys</code>）など、一部のストレージドライバーはボリュームデバイスオブジェクトに接続するフィルタードライバーです。\n'
                'これらはボリュームマネージャーより下、BitLocker ドライバーより上に位置し、データの冗長化、ストライピング、ストレージ仮想化を提供できます。\n'
                '一般に、元の IRP を複数の二次 IRP に分けて異なる物理ディスクデバイスへ発行することで実装します。\n'
                'このとき分割に伴うオフセットの変化を反映しなければ、BitLocker が二次 I/O '
                'を受け取った際に本来とは異なる初期化ベクトルでデータが暗号化され、ファイルデータが破損します。</p>\n'
                '<p>IRP 拡張は<strong>IRP の伝播</strong>に対応しており、元の IRP '
                'が分割されるたびに、拡張に格納されたファイルの仮想バイトオフセットを自動で調整します。\n'
                'EFS ドライバーは通常512バイト境界でファイルブロックを暗号化し、IRP の分割位置も少なくともセクター境界にそろえる必要があります。\n'
                'これにより、BitLocker は破損を起こさずデータを暗号化、復号できます。</p>\n'
                '<p>BitLocker ドライバーの多くのルーチンは、メモリ割り当てに失敗すると処理を続けられません。\n'
                'IRP の分割時には、IRP 拡張を非ページプールから動的に割り当てるため、この割り当てが失敗することがあります。\n'
                'I/O マネージャーは <code>IoAllocateIrpEx</code> ルーチンでこの問題を解決します。\n'
                'カーネルドライバーは、従来の <code>IoAllocateIrp</code> と同様にこのルーチンで IRP を割り当てられます。\n'
                '新しいルーチンは追加のスタック位置を割り当て、IRP 拡張をそこに格納します。\n'
                '新しい API で割り当てた IRP に対して拡張を要求するドライバーは、非ページプールから改めてメモリを割り当てる必要がありません。</p>\n'
                '<blockquote><p><strong>注記</strong> ストレージドライバーは複数の物理デバイスへ I/O を送る場合に加え、別の理由でも IRP を分割できます。\n'
                'たとえば、ボリュームシャドウコピードライバー（<code>Volsnap.sys</code>）は、コピーオンライト方式のシャドウコピーからファイルを読み取る際、データが現行ボリュームとシャドウコピーの差分ファイルに分かれていれば '
                'I/O を分割します。\n'
                '差分ファイルは隠しディレクトリ <code>System Volume Information</code> にあります。</p></blockquote>',
 'p2-page-750': '<h5>オンライン暗号化</h5>\n'
                '<p>通常、ファイルのストリームを暗号化または復号する間、NTFS ドライバーはそのストリームを排他的にロックします。\n'
                '処理が終わるまで、アプリケーションはファイルにアクセスできません。\n'
                '大きなファイルでは数秒から数分にわたってアクセスできなくなることがあり、大規模なファイルサーバーでは問題になります。</p>\n'
                '<p>これに対応するため、Windows 10の後期バージョンでは<strong>オンライン暗号化</strong>が導入されました。\n'
                'NTFS ドライバーはアクセスを適切に同期し、ファイルを処理中ずっと排他的にロックすることなく暗号化や復号を行えます。\n'
                'EFS がオンライン暗号化を有効にするのは、対象が名前付きまたは名前なしのデータストリームで、かつ非常駐の場合です。\n'
                '条件を満たさない場合は通常の暗号化を行います。\n'
                '両方の条件を満たす場合、EFS サービスは <code>FSCTL_SET_ENCRYPTION</code> を NTFS '
                'ドライバーに送り、オンライン暗号化を有効にするフラグを設定します。</p>\n'
                '<p>オンライン暗号化は、<code>$LOGGED_UTILITY_STREAM</code> 型の <code>$EfsBackup</code> '
                '属性と、ファイルの一部だけを排他モードまたは共有モードでロックする<strong>範囲ロック</strong>を使います。\n'
                'オンライン暗号化が有効になると、内部関数 <code>NtfsEncryptDecryptOnline</code> は <code>$EfsBackup</code> 属性とその '
                'SCB を作成し、ファイルの先頭2 MBの範囲に共有ロックを取得して処理を開始します。\n'
                '共有ロック中も複数の読み取り元はその範囲を読めます。\n'
                '書き込み元がその範囲に新しいデータを書き込むには、暗号化または復号が終わるまで待つ必要があります。</p>\n'
                '<p>NTFS ドライバーは非ページプールに2 MBのバッファーを確保し、ボリューム上で2 MB分のクラスターを予約します。\n'
                '必要な数はボリュームのクラスターサイズで変わります。\n'
                'オンライン暗号化の関数は物理ディスクから元のデータを読み、確保したバッファーに格納します。\n'
                '前節で説明した BitLocker への暗号化のオフロードが無効なら、EFS の機能でバッファーを暗号化します。\n'
                '有効なら、バッファーを予約済みクラスターに書き込む際に BitLocker ドライバーがデータを暗号化します。</p>\n'
                '<p>次に NTFS は、クラスターの割り当てを切り替える間だけファイル全体を排他的にロックします。\n'
                '元のストリームのエクステントテーブルから平文を含むクラスターを外し、非常駐の <code>$EfsBackup</code> 属性に割り当てます。\n'
                '元のエクステントテーブルから取り除いた範囲には、新しく暗号化したデータを含むクラスターを割り当てます。\n'
                '排他ロックを解除する前に、NTFS ドライバーは処理済み範囲の新しい境界値（ハイウォーターマーク）を計算します。\n'
                'その値を元のファイルのメモリ上の SCB と、<code>$EFS</code> 代替データストリーム内の EFS データの両方に記録し、排他ロックを解除します。\n'
                '元のデータを含むクラスターはまずゼロで埋めます。\n'
                '処理すべきブロックがもうなければクラスターを解放し、残っていれば次の2 MBで処理を繰り返します。</p>\n'
                '<p>ハイウォーターマークは暗号化済みデータと未暗号化データの境界を示すファイルオフセットです。\n'
                '境界より先への並行書き込みは平文のまま行えますが、境界より前に書き込むデータは暗号化する必要があります。\n'
                '現在ロックされている範囲には書き込めません。\n'
                '図11-72は、16 MBのファイルをオンラインで暗号化している例です。\n'
                '2 MBずつの最初の2ブロックは暗号化済みで、4 MBの位置にあるハイウォーターマークが暗号化済みの部分と未暗号化の部分を分けています。\n'
                'その直後の2 MBのブロックには範囲ロックが設定されています。\n'
                'アプリケーションはロックされたブロックを読み取れますが、新しいデータを書き込むにはロックの解除を待つ必要があります。</p>',
 'p2-page-751': '<p>処理中のブロックのデータを暗号化し、予約済みクラスターに格納します。\n'
                'ファイルを排他的にロックしたら、元のエクステントテーブルの該当エントリを削除または分割し、<code>$EfsBackup</code> '
                '属性へ新しいエントリを挿入して、元のクラスターを <code>$EfsBackup</code> ストリームに割り当て直します。\n'
                '元のクラスターがあった範囲には、新しいクラスターを割り当てます。\n'
                'ハイウォーターマークを進めてファイルのロックを解除すると、次は6 MBのオフセットから暗号化を続けます。\n'
                '<code>$EfsBackup</code> 内の元のクラスターは並行してゼロで埋められ、以後の処理で再利用できます。</p>\n'
                '<figure>\n'
                '<table><thead><tr><th>段階</th><th>暗号化済み範囲</th><th>ハイウォーターマーク</th><th>未暗号化範囲と範囲ロック</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>現在のサイクルの前</td><td>0〜4 MB</td><td>4 MB</td><td>4〜16 MBのうち、4〜6 MBをロック</td></tr>\n'
                '<tr><td>現在のサイクルの後</td><td>0〜6 MB。4〜6 MBには暗号化済みデータを含む新しいクラスターを割り当て済み</td><td>6 '
                'MB</td><td>6〜16 MB。元の4〜6 MBのクラスターは <code>$EfsBackup</code> へ移動</td></tr>\n'
                '<tr><td>次のサイクルの前</td><td>0〜6 MB</td><td>6 MB</td><td>6〜16 MBのうち、6〜8 MBをロック</td></tr>\n'
                '</tbody></table>\n'
                '<figcaption>図11-72 16 MBのファイルをオンラインで暗号化する例。各行は <code>$DATA</code> '
                'ストリームの状態を示します。</figcaption></figure>\n'
                '<p>この実装により、NTFS はファイルをその場で暗号化または復号でき、「ファイルデータの暗号化」で説明した一時ファイルが不要になります。\n'
                '暗号化や復号の最中も、ほかのアプリケーションは対象ストリームを使用し、変更できます。\n'
                '排他ロックを保持する時間は短く、ファイルを使用するアプリケーションからはほとんど分かりません。</p>\n'
                '<h4>直接アクセス（DAX）ディスク</h4>\n'
                '<p><strong>永続メモリ</strong>は、ソリッドステートディスク技術から発展した不揮発性の記憶媒体です。\n'
                'RAM のように低遅延かつ広帯域で、メモリバス（DDR）に接続し、標準的なディスクデバイスとして使えます。</p>\n'
                '<p>Windows ではこの種の永続メモリ技術を<strong>直接アクセスディスク</strong>（DAX）と呼びます。\n'
                'ストレージクラスメモリ（SCM）とも呼ばれます。\n'
                '図11-73の不揮発性デュアルインラインメモリモジュール（NVDIMM）は、その一例です。\n'
                'NVDIMM は電源を切っても内容を保持します。\n'
                '「デュアルインライン」は、DIMM のパッケージ形式を使うことを示しています。\n'
                '本書の執筆時点で NVDIMM には3種類あります。\n'
                'NVDIMM-F はフラッシュストレージだけを備え、NVDIMM-N が最も普及しています。</p>',
 'p2-page-752': '<p>NVDIMM-N は、フラッシュストレージと従来の DRAM チップを同じモジュールに載せたものです。\n'
                'NVDIMM-P は永続性のある DRAM チップを備え、電源が失われてもデータを保持します。</p>\n'
                '<p>DAX の性能を支える主な特徴の一つが、永続メモリへのゼロコピーアクセスです。\n'
                'DAX は従来のストレージとはアクセス方法が異なるため、ファイルシステムドライバーやメモリマネージャーなど、多くのコンポーネントに対応が必要です。</p>\n'
                '<p>Windows で DAX を最初にサポートしたのは Windows Server 2016 です。\n'
                'このストレージモデルは既存のアプリケーションの大半と互換性があり、それらのアプリケーションは変更せずに DAX ディスクを利用できます。\n'
                '最高の性能を得るには、ボリュームを専用の DAX モードでフォーマットし、メモリマッピング API でボリューム上のファイルやディレクトリをメモリにマップする必要があります。\n'
                '本書の執筆時点では、DAX ボリュームに対応しているファイルシステムは NTFS だけです。</p>\n'
                '<figure><img loading="lazy" width="407" height="313" '
                'src="assets/86549de2b3ef636ce07c0129.webp" alt="DRAM チップとフラッシュチップを搭載した NVDIMM">\n'
                '<figcaption>図11-73 DRAM とフラッシュを搭載した NVDIMM。DRAM '
                'のデータを保持するには、外付けのバッテリーか基板上のスーパーキャパシターが必要です。</figcaption></figure>\n'
                '<p>以下の節では、直接アクセスディスクの動作、新しいドライバーモデルの構成、および DAX ボリュームに対応する主要コンポーネントの変更を説明します。\n'
                '該当するのは NTFS ドライバー、メモリマネージャー、キャッシュマネージャー、I/O マネージャーです。\n'
                'DAX の機能を十分に活用するには、Windows 標準とサードパーティー製のファイルシステムフィルタードライバー（ミニフィルターを含む）も、個別に対応する必要があります。</p>\n'
                '<h5>DAX ドライバーモデル</h5>\n'
                '<p>Windows は DAX ボリュームに対応するため、新しいストレージドライバーモデルを導入しました。\n'
                'SCM バスドライバー（<code>Scmbus.sys</code>）は、システムのメモリバスに接続された物理および論理の永続メモリ（PM）デバイスを、ACPI の NFIT '
                'テーブルを使って列挙します。\n'
                'このドライバーは I/O 経路には含まれず、ACPI 列挙子が管理する主要なバスドライバーです。\n'
                'ACPI 列挙子は、ハードウェア抽象化レイヤー（HAL）がハードウェアデータベースのレジストリキー '
                '<code>HKLM&#92;SYSTEM&#92;CurrentControlSet&#92;Enum&#92;ACPI</code> を通じて提供します。\n'
                'プラグアンドプレイのデバイス列挙については、第1巻の第6章を参照してください。</p>',
 'p2-page-753': '<p>図11-74に SCM ストレージドライバーモデルの構成を示します。\n'
                'SCM バスドライバーは2種類のデバイスオブジェクトを作ります。</p>\n'
                '<ul>\n'
                '<li><strong>物理デバイスオブジェクト</strong>（PDO）は物理的な永続メモリデバイスを表します。\n'
                '通常、NVDIMM デバイスは1枚の NVDIMM-N モジュール、または複数枚をインターリーブした構成です。\n'
                '1枚の場合、SCM バスドライバーは NVDIMM を表す PDO を1つ作ります。\n'
                '複数枚の場合、原文の例では、各 NVDIMM-N モジュールを表す別々のデバイスを2つ作ります。\n'
                'すべての物理デバイスを管理するミニポートドライバー <code>Nvdimm.sys</code> は、物理 NVDIMM を制御し、正常性を監視します。</li>\n'
                '<li><strong>機能デバイスオブジェクト</strong>（FDO）は、永続メモリドライバー <code>Pmem.sys</code> が管理する個々の DAX '
                'ディスクを表します。\n'
                'このドライバーはバイト単位でアドレス指定できるインターリーブセットを制御し、DAX ボリュームへのすべての I/O を処理します。\n'
                '永続メモリドライバーは各 DAX ディスクのクラスドライバーで、従来のストレージスタックの <code>Disk.sys</code> に当たります。</li>\n'
                '</ul>\n'
                '<p>SCM バスドライバーと NVDIMM ミニポートドライバーは、永続メモリクラスドライバーとの通信用インターフェイスを公開します。\n'
                'これらはメジャー機能コード <code>IRP_MJ_PNP</code> の <code>IRP_MN_QUERY_INTERFACE</code> 要求を通じて利用します。\n'
                '呼び出し元がインターフェイス GUID <code>{8de064ff-b630-42e4-ea88-6f24c8641175}</code> を指定した場合、SCM '
                'バスドライバーは自身の通信用インターフェイスを公開します。\n'
                '永続メモリドライバーは同様に、GUID <code>{0079c21b-917e-405e-cea9-0732b5bbcebd}</code> を指定して NVDIMM '
                'デバイスとの通信用インターフェイスを要求します。</p>\n'
                '<figure>\n'
                '<p>図ではユーザーモードから論理ディスクの状態管理とブロック I/O および DAX I/O を扱い、物理 NVDIMM の状態管理は種類ごとのドライバーが担います。\n'
                'カーネルモードには <code>ACPI.sys</code>、<code>Scmbus.sys</code>、<code>Nvdimm.sys</code> '
                'と、共通の永続メモリディスクドライバーである <code>Pmem.sys</code> があります。\n'
                '<code>Pmem.sys</code> は NVDIMM に直接 I/O を行います。</p>\n'
                '<figcaption>図11-74 SCM ストレージドライバーモデル</figcaption></figure>\n'
                '<p>永続メモリクラスドライバーは論理ディスクのオープン、クローズ、読み書き、メモリマッピングなどを担います。\n'
                'NVDIMM ドライバーは物理デバイスを管理し、その正常性を監視します。\n'
                'この分担により、新しい種類の NVDIMM への対応は <code>Nvdimm.sys</code> の更新だけで済み、<code>Pmem.sys</code> '
                'を変更する必要はありません。</p>\n'
                '<h5>DAX ボリューム</h5>\n'
                '<p>DAX ストレージドライバーモデルは、DAX ボリュームという種類のボリュームを導入します。\n'
                '<code>Format</code> ツールでパーティションを初めてフォーマットする際、コマンドラインに <code>/DAX</code> を指定できます。\n'
                '基盤のメディアが DAX ディスクで、GPT 形式でパーティション分割されている場合、ツールは NTFS '
                'に必要な基本データ構造を作る前に、<code>GPT_BASIC_DATA_ATTRIBUTE_DAX</code> 属性を書き込みます。</p>\n'
                '<figure><img loading="lazy" width="192" height="149" '
                'src="assets/653e131a0cc3dc6dc0c89a40.webp" alt="SCM ストレージドライバーモデルの図の一部（原文の図1）"></figure>',
 'p2-page-754': '<p>このフラグは対象ボリュームの GPT パーティションエントリのビット58に対応します。\n'
                'パーティションテーブルの構造については、<a href="https://en.wikipedia.org/wiki/GUID_Partition_Table">GUID '
                'パーティションテーブルの解説</a>を参照してください。</p>\n'
                '<p>NTFS ドライバーはボリュームをマウントするときにこのフラグを検出し、下位のストレージドライバーに <code>STORAGE_QUERY_PROPERTY</code> '
                'の制御要求を送ります。\n'
                'SCM バスドライバーがこの IOCTL を認識し、基盤のディスクが DAX ディスクであることを示す別のフラグをファイルシステムドライバーに返します。\n'
                'このフラグを設定できるのは SCM バスドライバーだけです。\n'
                '両方のフラグを確認し、レジストリ値 '
                '<code>HKLM&#92;System&#92;CurrentControlSet&#92;Control&#92;FileSystem&#92;NtfsEnableDirectAccess</code> '
                'で DAX が無効化されていなければ、NTFS はボリュームを DAX モードで使用できるようにします。</p>\n'
                '<p>DAX ボリュームの主な特徴は、永続メモリへのゼロコピーアクセスです。\n'
                'アプリケーションはファイルをメモリにマップしたビューを通じて、基盤となるハードウェアのディスクセクターに直接アクセスできます。\n'
                'I/O を仲介するコンポーネントがないため、高い性能を得られます。\n'
                '前述のように、この性質はミニフィルターなどのファイルシステムフィルタードライバーに影響することがあります。</p>\n'
                '<p>アプリケーションが DAX ボリューム上のファイルを基盤とするメモリマップ用セクションを作成するとき、メモリマネージャーは DAX '
                'モードでセクションを作るべきかをファイルシステムに問い合わせます。\n'
                'ボリューム自体が DAX モードでフォーマットされている場合に限り、DAX モードで作成します。\n'
                'その後 <code>MapViewOfFile</code> API '
                'でファイルをマップすると、メモリマネージャーは要求されたファイル範囲に対応する物理メモリ範囲をファイルシステムに問い合わせます。\n'
                'ファイルシステムドライバーは、要求されたファイル範囲をボリューム相対の1つ以上のエクステント（セクターオフセットと長さ）に変換し、永続メモリディスクのクラスドライバーに、それらを物理メモリ範囲に変換するよう要求します。\n'
                'メモリマネージャーは、受け取った物理メモリ範囲を使って対象プロセスのページテーブルを更新し、セクションを永続ストレージに直接マップします。\n'
                'これでアプリケーションは永続メモリにゼロコピーで直接アクセスできます。\n'
                'ページングの読み書きは発生せず、キャッシュマネージャーも関与しません。\n'
                'この違いが何に影響するかは、本章の後半で説明します。</p>\n'
                '<p>アプリケーションは <code>GetVolumeInformation</code> API で DAX ボリュームを識別できます。\n'
                '結果のフラグに <code>FILE_DAX_VOLUME</code> が含まれれば、ボリュームは DAX 対応ファイルシステム（本書執筆時点では NTFS '
                'のみ）でフォーマットされています。\n'
                '同様に、<code>GetVolumeInformationByHandle</code> API でファイルが DAX ディスク上にあるかを確認できます。</p>\n'
                '<h5>DAX ボリュームのキャッシュ I/O と非キャッシュ I/O</h5>\n'
                '<p>DAX ボリュームではメモリマップ I/O によってストレージにゼロコピーでアクセスできるほか、従来の <code>ReadFile</code> や '
                '<code>WriteFile</code> API でも読み書きできます。\n'
                '本章の冒頭で説明したように、Windows の通常の I/O にはキャッシュ I/O と非キャッシュ I/O があります。\n'
                'どちらも DAX ボリュームに発行すると、従来のボリュームとは大きく動作が異なります。</p>\n'
                '<p>キャッシュ I/O には DAX でもキャッシュマネージャーが関与します。\n'
                'ファイルの共有キャッシュマップを作るとき、キャッシュマネージャーは永続メモリのハードウェアに直接マップするセクションオブジェクトを作るようメモリマネージャーに要求します。\n'
                'NTFS は新しい <code>CcInitializeCacheMapEx</code> ルーチンを通じて、対象ファイルが DAX '
                'モードであることをキャッシュマネージャーに伝えられます。\n'
                'キャッシュマネージャーはユーザーバッファーから永続メモリへデータをコピーするため、キャッシュ I/O の書き込みに必要なコピーは1回です。\n'
                'キャッシュマネージャーはメモリマップ I/O と同じセクションを使うので、両者の内容は整合します。</p>',
 'p2-page-755': '<p>メモリマップ I/O と同じく、ページングの読み書きは発生しないため、レイジーライタースレッドやアクセスパターンに応じた先読みは有効になりません。</p>\n'
                '<p>直接マッピングでは、<code>NtWriteFile</code> の完了時点で、キャッシュマネージャーによる書き込みが DAX ディスクに直接反映されています。\n'
                'そのため、DAX 上のキャッシュ I/O は、実質的には非キャッシュ I/O と同様に動作します。\n'
                'ファイルシステムは非キャッシュ I/O 要求をキャッシュ I/O に変換し、キャッシュマネージャーがユーザーのバッファーと永続メモリの間でデータを直接コピーします。\n'
                'この経路でも、キャッシュ I/O やメモリマップ I/O との整合性は保たれます。</p>\n'
                '<p>NTFS は、自身のメタデータファイルを更新する際には引き続き標準の I/O を使います。\n'
                'ファイルを DAX モードで読み書きするかは、ストリームの作成時にストリーム制御ブロックのフラグで決めます。\n'
                'システムのメタデータファイルにはこのフラグを設定しません。\n'
                'そのため、キャッシュマネージャーがそのファイルをマップするときは、ファイルを基盤とする通常の非 DAX '
                'セクションを作り、標準のストレージスタックがページングの読み書きを処理します。\n'
                '最終的に <code>Pmem.sys</code> は、ブロックボリュームの場合と同じく、セクター単位の原子性を保つアルゴリズムで各 I/O を処理します。\n'
                '詳しくは「ブロックボリューム」を参照してください。\n'
                'この動作は先行書き込みログと両立させるために必要です。\n'
                '対応するログをフラッシュする前に、メタデータをディスクへ永続化してはいけません。\n'
                'メタデータファイルを DAX モードでマップすると、この書き込み順序を守れなくなります。</p>\n'
                '<h5>ファイルシステムの機能への影響</h5>\n'
                '<p>DAX では通常のページング I/O が発生せず、アプリケーションが永続メモリに直接アクセスします。\n'
                'そのため、ファイルシステムやフィルターが従来の機能を実装するために I/O を捕捉していた箇所がなくなります。\n'
                'DAX ボリュームでは、ファイル暗号化、圧縮ファイルとスパースファイル、スナップショット、USN ジャーナルによる通常の変更追跡などの機能に制約が生じます。</p>\n'
                '<p>DAX モードでは、書き込み可能なメモリマップファイルがいつ変更されたかをファイルシステムが把握できません。\n'
                'メモリセクションを初めて作成した時点で、NTFS ドライバーはファイルの変更日時とアクセス日時を更新し、USN 変更ジャーナルにファイルが変更されたことを記録します。\n'
                '同時にディレクトリの変更を通知します。\n'
                'DAX ボリュームは従来型のフィルタードライバーとは互換性がなく、フィルターマネージャーのクライアントであるミニフィルターにも大きな影響があります。\n'
                'BitLocker やボリュームシャドウコピードライバー（<code>Volsnap.sys</code>）などは DAX ボリュームで動作せず、デバイススタックから外されます。\n'
                'ミニフィルターがファイルの変更を検知できないため、前述のような、ファイルアクセス時に動作するマルウェア検査も、対象を再検査すべきかを判断できません。\n'
                'ファイルハンドルが閉じられるたびに、変更された可能性があるとみなす必要があります。\n'
                'この処理は性能に大きく影響するため、ミニフィルターは DAX ボリュームのサポートを明示的に有効にする必要があります。</p>\n'
                '<h5>実行可能イメージのマッピング</h5>\n'
                '<p>Windows のローダーは、実行可能イメージをメモリにマップする際にメモリマネージャーの機能を使います。\n'
                '<code>NtCreateSection</code> API に <code>SEC_IMAGE</code> '
                'フラグを指定して、メモリにマップするイメージセクションを作成します。\n'
                'このフラグは、セクションをイメージとしてマップし、必要なアドレス補正をすべて適用することを指定します。\n'
                'DAX モードでは、通常の方法で補正すると、再配置とアドレス補正が永続メモリディスク上の元のイメージファイルに直接適用されるため、別の処理が必要です。</p>',
 'p2-page-756': '<p>DAX モードのボリュームにある実行可能イメージをマップするとき、メモリマネージャーは次のいずれかの方法を選びます。</p>\n'
                '<ul>\n'
                '<li>バイナリファイルのデータセクションを表す制御領域がすでに存在する場合、つまりアプリケーションがイメージをバイナリデータとして読み取るために開いている場合は、メモリを基盤とする空のイメージセクションを作ります。\n'
                '既存のデータセクションから新しいイメージセクションへデータをコピーし、その後に必要なアドレス補正を適用します。</li>\n'
                '<li>ファイルのデータセクションが存在しない場合は、通常の非 DAX イメージセクションを作ります。\n'
                'このとき、通常の無効なプロトタイプ PTE が作られます（詳しくは第1巻の第5章を参照）。\n'
                'イメージに対応するセクション内のアドレスにアクセスして、無効な PTE によるページフォールトが起きた場合は、メモリマネージャーが <code>Pmem.sys</code> '
                'の標準の読み書きルーチンを使ってデータをメモリに取り込みます。</li>\n'
                '</ul>\n'
                '<p>本書の執筆時点で Windows 10は、DAX ストレージ上のイメージをローダーが直接実行する、その場での実行（XIP）には対応していません。\n'
                'DAX モードのボリュームはもともとデータを高速に格納するための設計なので、この制限はその用途には影響しません。\n'
                '原文では、将来の Windows リリースで DAX ボリューム上の XIP に対応する予定としています。</p>\n'
                '<h6>実験\u3000Process Monitor で DAX の I/O を確認する</h6>\n'
                '<p>Sysinternals の Process Monitor と、本書のダウンロード資料にある <code>FsTool.exe</code> を使うと、DAX の I/O '
                'を確認できます。\n'
                'アプリケーションが DAX モードのボリュームにあるメモリマップファイルを読み書きしても、システムはページング I/O を生成しません。\n'
                'そのため、NTFS ドライバーにも、その上下に接続されているミニフィルターにも、その読み書きは見えません。</p>\n'
                '<p>この動作を確認するには Process Monitor を開きます。\n'
                '通常のボリュームを P: ドライブに、DAX モードのボリュームを Q: ドライブにマウントしているものとして、次の画面と同様にフィルターを設定します。</p>\n'
                '<figure><img loading="lazy" width="432" height="273" '
                'src="assets/f3c83fd3c9afc92dc3150123.webp" alt="Process Monitor のフィルター設定画面。通常の P: ドライブと DAX '
                'モードの Q: ドライブを比較する設定です。"></figure>',
 'p2-page-757': '<p>DAX モードのボリュームで I/O を発生させるには、FsTool で DAX を使うコピーを実行します。\n'
                '次の例では、ブロックモードの DAX ボリューム P: にある ISO イメージを、DAX モードのドライブ Q: にコピーします。\n'
                'コピー元には、通常のディスク上に作った標準のボリュームも使えます。</p>\n'
                '<pre><code>P:&#92;&gt;fstool.exe /daxcopy p:&#92;Big_image.iso q:&#92;test.iso\n'
                'NTFS / ReFS Tool v0.1\n'
                'Copyright (C) 2018 Andrea Allievi (AaLl86)\n'
                '\n'
                'DAX コピーを開始しています...\n'
                'コピー元のファイルパス: p:&#92;Big_image.iso\n'
                'コピー先のファイルパス: q:&#92;test.iso\n'
                'コピー元のボリューム: p:&#92;、ファイルシステム: NTFS、DAX モード: 無効\n'
                'コピー先のボリューム: q:&#92;、ファイルシステム: NTFS、DAX モード: 有効\n'
                '\n'
                'コピー元ファイルのサイズ: 4.34 GB\n'
                '\n'
                'ファイルをコピーしています... 成功\n'
                '合計実行時間: 8秒\n'
                'コピー速度: 489.67 MB/s\n'
                '\n'
                '何かキーを押すと終了します...</code></pre>\n'
                '<p>Process Monitor で DAX コピーのトレースを取得すると、想定した結果を確認できます。</p>\n'
                '<figure><img loading="lazy" width="649" height="317" '
                'src="assets/7fec64b5d2699bd91826ac64.webp" alt="Process Monitor のトレース。コピー先には '
                'CreateFileMapping が表示され、ページング I/O はコピー元にだけ表示されています。"></figure>\n'
                '<p>トレースを見ると、コピー先ファイル（<code>Q:&#92;test.iso</code>）で捕捉されたのは <code>CreateFileMapping</code> '
                'だけで、<code>WriteFile</code> イベントはありません。\n'
                'コピー中に Process Monitor が検出したページング I/O は、コピー元ファイルに対するものだけです。\n'
                'アプリケーションがメモリマップファイルにアクセスしてページフォールトが発生し、メモリマネージャーがコピー元のボリュームからデータを読み込むために、これらの I/O '
                'を発行しました。</p>',
 'p2-page-758': '<p>メモリマップ I/O と通常のキャッシュ I/O の違いを比較するため、同じファイルを通常のファイルコピーで再度コピーします。\n'
                'コピー元のファイルへのページング I/O を観察するには、事前にシステムを再起動します。\n'
                '再起動しないと、コピー元のデータがキャッシュに残ります。</p>\n'
                '<pre><code>P:&#92;&gt;fstool.exe /copy p:&#92;Big_image.iso q:&#92;test.iso\n'
                'NTFS / ReFS Tool v0.1\n'
                'Copyright (C) 2018 Andrea Allievi (AaLl86)\n'
                '\n'
                '「Big_image.iso」を「test.iso」にコピーしています... 成功\n'
                'ファイルコピーの合計実行時間: 13秒、転送速度: 313.71 MB/s\n'
                '何かキーを押すと終了します...</code></pre>\n'
                '<p>Process Monitor で取得したトレースを前のトレースと比べると、キャッシュ I/O ではコピーが1回で済むことが分かります。\n'
                'キャッシュマネージャーはアプリケーションのバッファーとシステムキャッシュの間でデータをコピーします。\n'
                'このシステムキャッシュは DAX ディスクに直接マップされています。\n'
                '今回もコピー先ファイルに対するページング I/O は表示されていません。</p>\n'
                '<figure><img loading="lazy" width="648" height="318" '
                'src="assets/54553dee72455f7afaff2ad4.webp" alt="通常のファイルコピーを記録した Process Monitor '
                'のトレース"></figure>\n'
                '<p>最後に、同じ DAX モードのボリューム内、または別々の DAX モードのボリューム間で、DAX コピーを試します。</p>\n'
                '<pre><code>P:&#92;&gt;fstool /daxcopy q:&#92;test.iso q:&#92;test_copy_2.iso\n'
                'TFS / ReFS Tool v0.1\n'
                'Copyright (C) 2018 Andrea Allievi (AaLl86)\n'
                '\n'
                'DAX コピーを開始しています...\n'
                'コピー元のファイルパス: q:&#92;test.iso\n'
                'コピー先のファイルパス: q:&#92;test_copy_2.iso\n'
                'コピー元のボリューム: q:&#92;、ファイルシステム: NTFS、DAX モード: 有効\n'
                'コピー先のボリューム: q:&#92;、ファイルシステム: NTFS、DAX モード: 有効\n'
                'コピー元とコピー先の両方が DAX ボリューム上にあります。\n'
                'システムの速度を最大限に使ってコピーします。</code></pre>',
 'p2-page-759': '<pre><code>コピー元ファイルのサイズ: 4.34 GB\n'
                '\n'
                'ファイルをコピーしています... 成功\n'
                '合計実行時間: 8秒\n'
                'コピー速度: 501.60 MB/s\n'
                '\n'
                '何かキーを押すと終了します...</code></pre>\n'
                '<p>最後の実験で取得したトレースから、DAX ボリューム上のメモリマップ I/O ではページング I/O が発生しないことが分かります。\n'
                'コピー元とコピー先のどちらのファイルにも、<code>WriteFile</code> や <code>ReadFile</code> のイベントは表示されません。</p>\n'
                '<figure><img loading="lazy" width="649" height="318" '
                'src="assets/a56d2ec4e0ee8d95c234dcd5.webp" alt="DAX コピーの Process Monitor トレース。コピー元にもコピー先にも '
                'WriteFile や ReadFile のイベントはありません。"></figure>\n'
                '<h5>ブロックボリューム</h5>\n'
                '<p>DAX ボリュームの制約を許容できない用途もあります。\n'
                'Windows は永続メモリ（PM）ハードウェアで従来の動作を提供するため、<strong>ブロックモードのボリューム</strong>を使えます。\n'
                'このボリュームは、回転式ハードディスクや SSD 上の通常のボリュームと同様に、従来の I/O スタック全体で管理されます。\n'
                'すべての I/O 操作はストレージスタックを通って永続メモリディスクのクラスドライバーに届くため、従来のストレージと同じように動作します。\n'
                'ミニポートドライバーは不要です。\n'
                '既存のアプリケーション、従来型のフィルター、ミニフィルタードライバーとも互換性があります。</p>\n'
                '<p>永続メモリストレージでは、バイト単位でアドレスを指定できます。\n'
                '厳密には、I/O はキャッシュライン単位で行われます。\n'
                'キャッシュラインの大きさはアーキテクチャに依存しますが、通常は64バイトです。\n'
                '一方、ブロックモードのボリュームは、512バイトまたは4 KBのセクター単位で I/O を行う標準ボリュームとして公開されます。\n'
                'DAX ボリュームへの書き込み中に突然電源が失われると、1つのセクターに書き込み前と書き込み後のデータが混在することがあります。\n'
                '一般のアプリケーションはこのような状態への対処を想定していません。\n'
                'ブロックモードでは、永続メモリディスクのクラスドライバーが<strong>ブロック変換テーブル</strong>（BTT）のアルゴリズムを実装し、セクター単位の原子性を保証します。</p>',
 'p2-page-760': '<p>Intel が開発した BTT アルゴリズムは、利用可能なディスク領域を<strong>アリーナ</strong>と呼ばれる最大512 GBの区画に分けます。\n'
                'アリーナごとに、論理ブロックアドレス（LBA）をそのアリーナ内のブロックに対応付ける変換テーブルを保持します。\n'
                'テーブルの各エントリは32ビットで、上位2ビットにブロックの状態（有効、ゼロ化済み、エラーのいずれか）を記録します。\n'
                'LBA ごとの状態はこのテーブルに保持しますが、セクター単位の原子性を担うのは <code>nfree</code> ブロックの配列を格納した <code>flog</code> '
                '領域です。</p>\n'
                '<p><code>nfree</code> ブロックには、セクター単位の原子性を保証するためにアルゴリズムが必要とするデータがすべて含まれます。\n'
                '配列には32バイトのエントリが256個あるので、<code>flog</code> 領域の大きさは8 KBです。\n'
                '各エントリは1つの CPU が使用するため、エントリの数がアリーナで同時に処理できる原子的な I/O の数を決めます。\n'
                '図11-75に、ブロックモードでフォーマットされた DAX ディスクの配置を示します。\n'
                'BTT のデータ構造はファイルシステムドライバーから見えません。\n'
                'BTT により、セクターの一部だけが書き換わった状態が残ることを防げます。\n'
                '前述のように、DAX モードでフォーマットしたボリュームでも、ファイルシステムのメタデータを書き込む際には BTT が必要です。</p>\n'
                '<figure><p>基盤ストレージはアリーナ0、アリーナ1、以降のアリーナに分かれます。\n'
                '図のアリーナは各512 GBです。\n'
                'アリーナ内には先頭から、アリーナ情報ブロック（4 KB）、データブロック、<code>nfree</code> の予約ブロック、BTT マップ、BTT の '
                '<code>flog</code>（8 KB）、情報ブロックのコピー（4 KB）が並びます。</p>\n'
                '<figcaption>図11-75 BTT によってセクター単位の原子性を保証する DAX ディスクの配置</figcaption></figure>\n'
                '<p>ブロックモードのボリュームでは、パーティションエントリに <code>GPT_BASIC_DATA_ATTRIBUTE_DAX</code> フラグがありません。\n'
                'NTFS は通常のボリュームと同様に、キャッシュ I/O にはキャッシュマネージャーを使い、非キャッシュ I/O は永続メモリディスクのクラスドライバーを通して処理します。\n'
                '<code>Pmem.sys</code> '
                'が提供する読み書きの関数は、ユーザーバッファーとデバイスの物理ブロックアドレスのそれぞれにメモリ記述子リスト（MDL）を作り、直接メモリアクセス（DMA）で転送します。\n'
                'MDL については第1巻の第5章を参照してください。\n'
                'セクター単位の原子性は BTT アルゴリズムが保証します。\n'
                '図11-76に、従来のボリューム、DAX ボリューム、ブロックボリュームの I/O スタックを示します。</p>',
 'p2-page-761': '<figure>\n'
                '<table>\n'
                '<thead><tr><th>ボリュームの種類</th><th>ユーザーモードのアプリケーションから記憶媒体までの経路</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>従来のボリューム</td><td>アプリケーション → NTFS → Volsnap → Volmgr／Partmgr → Disk／ClassPnP → '
                'StorPort → ミニポート → SSD または HDD</td></tr>\n'
                '<tr><td>永続メモリのブロックモードボリューム</td><td>アプリケーション → NTFS → Volsnap → Volmgr／Partmgr → '
                '永続メモリディスクドライバー → 永続メモリ</td></tr>\n'
                '<tr><td>DAX ボリューム</td><td>メモリマップされたデータにはアプリケーションから直接アクセスします。図にはキャッシュ I/O '
                'と、NTFS、Volmgr／Partmgr、永続メモリディスクドライバーからなるカーネルモードのスタックも示されています。</td></tr>\n'
                '</tbody></table>\n'
                '<figcaption>図11-76 従来のボリューム、ブロックモードのボリューム、DAX ボリュームのデバイス I/O スタックの比較</figcaption></figure>\n'
                '<h5>ファイルシステムフィルタードライバーと DAX</h5>\n'
                '<p>従来型のフィルタードライバーと、DAX に対応していないミニフィルターは、DAX ボリューム上で動作しません。\n'
                'こうしたドライバーは通常、ファイルシステムドライバーが扱う操作に関与して、ファイルシステムの機能を拡張します。\n'
                'ウイルス対策、暗号化、レプリケーション、圧縮、階層型ストレージ管理（HSM）など、機能を追加したり既存の機能を変更したりするフィルターがあります。\n'
                'DAX のドライバーモデルでは、ボリュームとこれらのフィルターとの関係が大きく変わります。</p>\n'
                '<p>前述のように、DAX モードでファイルをメモリにマップすると、ファイルシステムは、そのマッピングを通じた読み書きの I/O 要求を受け取りません。\n'
                'ファイルシステムドライバーの上下にあるフィルタードライバーも、同じ要求を受け取りません。\n'
                'そのため、データを捕捉することが前提のフィルターは機能しません。\n'
                '互換性の問題を抑えるため、既存のミニフィルターには DAX ボリュームのマウント時に <code>InstanceSetup</code> コールバックによる通知が届きません。\n'
                'DAX ボリュームを扱う新規または更新済みのミニフィルターは、カーネル API の <code>FltRegisterFilter</code> '
                'でフィルターマネージャーに登録する際、<code>FLTFL_REGISTRATION_SUPPORT_DAX_VOLUME</code> フラグを指定する必要があります。</p>\n'
                '<p>DAX に対応するミニフィルターでも、ページング I/O は一切捕捉できません。\n'
                '暗号化や圧縮など、データを変換するフィルターは、メモリマップされたファイルに対して正しく動作できません。\n'
                'マルウェア対策フィルターも影響を受けます。</p>',
 'p2-page-762': '<p>前述のマルウェア対策フィルターは、実際に書き込みが発生したかどうかを判別できなくなるため、ファイルを開くたび、閉じるたびに検査する必要があります。\n'
                '主に影響を受けるのは、ファイルの最終更新時刻を検出する処理です。\n'
                '従来型のフィルターには互換性がありません。\n'
                'ドライバーが <code>IoAttachDeviceToDeviceStack</code> などを呼び出すと、I/O マネージャーは要求を失敗させ、ETW '
                'イベントを記録します。</p>\n'
                '<h5>DAX モードの I/O のフラッシュ</h5>\n'
                '<p>従来型のディスク（HDD、SSD、NVMe）には、全体の性能を高めるためのキャッシュがあります。\n'
                'ストレージドライバーが書き込み I/O を発行すると、データはまずキャッシュに転送され、後で永続メディアに書き込まれます。\n'
                'OS は、データを最終的な記憶媒体に書き込むフラッシュと、書き込みの順序を保証します。\n'
                '通常のキャッシュ I/O では、アプリケーションが <code>FlushFileBuffers</code> を呼び出すことで、データがディスクに保存されたことを保証できます。\n'
                'この呼び出しでは、NTFS ドライバーが処理するメジャー機能コード <code>IRP_MJ_FLUSH_BUFFERS</code> の IRP が生成されます。\n'
                '本文の説明では、非キャッシュ I/O は NTFS が直接ディスクへ書き込むため、順序やフラッシュを別途考慮する必要がありません。</p>\n'
                '<p>DAX モードでは、ファイルをメモリにマップした後、どのデータがディスクへ書き込まれるかを NTFS ドライバーが把握できません。\n'
                'アプリケーションが重要なデータ構造を書き込んでいる間に電源が失われると、すべてのデータ構造が正しく記憶媒体に書き込まれた保証も、要求した順に書き込まれた保証もありません。\n'
                'CPU から見ると永続メモリは通常の物理メモリと同じであり、DAX ボリュームの読み書きにも CPU のキャッシュが使われるためです。</p>\n'
                '<p>Windows 10の後期バージョンでは、DAX でマップされた領域の内容を CPU キャッシュから効率よく書き出すための API が追加されました。\n'
                'これらはユーザーモードのアプリケーションとカーネルモードのドライバーの両方で利用でき、CPU アーキテクチャに応じて最適化されています。\n'
                'たとえば標準的な x64 システムでは <code>CLFLUSH</code> や <code>CLWB</code> 命令を使います。\n'
                'DAX ボリュームで書き込み順序とフラッシュを制御するアプリケーションは、永続メモリにマップされた領域を指定して '
                '<code>RtlGetNonVolatileToken</code> を呼び出せます。\n'
                'この関数が返す不揮発性メモリ用のトークンは、<code>RtlFlushNonVolatileMemory</code> または '
                '<code>RtlFlushNonVolatileMemoryRanges</code> に渡せます。\n'
                'どちらの API も、CPU キャッシュから永続メモリデバイスへデータを実際に書き出します。</p>\n'
                '<p>標準の OS 関数によるメモリコピーは、既定ではテンポラルコピーです。\n'
                'データは CPU キャッシュを通り、実行順序が保たれます。\n'
                '非テンポラルコピーでは、CPU アーキテクチャ固有の命令（たとえば x64 の <code>MOVNTI</code>）を使い、CPU キャッシュを経由しません。\n'
                'この方式は高速ですが、順序は保たれません。\n'
                '<code>RtlWriteNonVolatileMemory</code> は、不揮発性メモリとの間でデータをコピーする API です。\n'
                '既定ではテンポラルコピーを行いますが、アプリケーションは <code>WRITE_NV_MEMORY_FLAG_NON_TEMPORAL</code> '
                'を指定することで、より高速な非テンポラルコピーを要求できます。</p>',
 'p2-page-763': '<h5>ラージページとヒュージページのサポート</h5>\n'
                '<p>メモリマネージャーは、DAX ボリューム上のファイルをメモリマップされたセクション経由で読み書きする場合も、非 DAX セクションと同じように扱います。\n'
                'マッピング時に <code>MEM_LARGE_PAGES</code> フラグが指定され、NTFS '
                'が割り当てた1つ以上のファイルエクステントが、境界にそろった十分な大きさの連続した物理領域を指していれば、その物理領域を2 MBのラージページまたは1 '
                'GBのヒュージページでマップします。\n'
                'メモリマネージャーとラージページについては第1巻の第5章を参照してください。</p>\n'
                '<p>ラージページとヒュージページを使うと、従来の4 '
                'KBページに比べ、プロセッサーがページテーブルを参照する回数と、アドレス変換キャッシュ（TLB）に必要なエントリ数を減らせます。\n'
                'このため、DAX 上のファイルにアクセスする処理が速くなります。\n'
                '大量のメモリにランダムアクセスするアプリケーションでは、CPU が TLB を検索し、TLB ミスのたびに階層化されたページテーブルを読み書きするのに時間がかかることがあります。\n'
                'また、コミット済みメモリの使用量も大幅に減らせます。\n'
                '計上が必要なのはページディレクトリの上位階層と、ラージページの場合のページディレクトリだけです。\n'
                '仮想アドレス空間の末端の2 MBごとに必要だった4 KBのページテーブル領域は、計上も確保も不要です。\n'
                'たとえば2 TBのファイルをマッピングする場合、ラージページやヒュージページを使うと、コミット済みメモリを4 GB節約できます。</p>\n'
                '<p>NTFS ドライバーはメモリマネージャーと連携し、DAX ボリューム上のファイルをマッピングする際にラージページとヒュージページを使えるようにします。</p>\n'
                '<ul>\n'
                '<li>各 DAX パーティションは、既定で2 MB境界にそろえられます。</li>\n'
                '<li>NTFS は2 MBのクラスターに対応します。\n'
                '2 MBのクラスターでフォーマットした DAX ボリュームでは、どのファイルもラージページだけでマッピングできます。</li>\n'
                '<li>NTFS は1 GBのクラスターに対応しません。\n'
                'DAX ボリューム上のファイルが1 GBを超え、1つ以上のエクステントが十分な大きさの連続した物理領域を占める場合は、メモリマネージャーがヒュージページでマッピングします。\n'
                'ラージページではページマップを3階層使いますが、ヒュージページでは2階層だけです。</li>\n'
                '</ul>\n'
                '<p>第5章で説明した通常のメモリを基盤とするセクションと同様に、メモリマネージャーがラージページやヒュージページを使うのは、永続メモリのページを記述するエクステントが DAX '
                'ボリューム上の境界に正しくそろっている場合だけです。\n'
                '境界はボリュームの LCN を基準とし、ファイルの VCN には依存しません。\n'
                'エクステントの開始位置は、ラージページでは2 MB境界、ヒュージページでは1 GB境界である必要があります。\n'
                'ファイル全体が境界にそろっていない場合、境界にそろったブロックにはラージページまたはヒュージページを使い、残りは通常の4 KBページでマップします。</p>\n'
                '<p>ラージページの利用を増やすため、NTFS は制御コード <code>FSCTL_SET_DAX_ALLOC_ALIGNMENT_HINT</code> を提供します。\n'
                'アプリケーションはこれを使い、新しく割り当てるファイルエクステントの希望アラインメントを指定できます。\n'
                '指定するのは希望アラインメント、適用を開始するオフセット、フラグです。\n'
                '通常は新規ファイルの作成後、マッピング前にこの要求をファイルシステムドライバーへ送ります。\n'
                'これにより、NTFS はファイルの領域を割り当てる際に、希望する境界条件を満たす空きクラスターを選びます。</p>\n'
                '<p>ボリュームの断片化が進んでいるなどの理由で希望するアラインメントを確保できない場合に備え、要求を失敗させるか、入力パラメーターで指定した代替アラインメントを使うかも、この制御コードで指定できます。</p>',
 'p2-page-764': '<p>既存のファイルにもこの制御コードを使い、新たに割り当てるエクステントの境界条件を指定できます。\n'
                'ファイルに属するすべてのエクステントのアラインメントは、制御コード <code>FSCTL_QUERY_FILE_REGIONS</code> または <code>fsutil '
                'dax queryFileAlignment</code> で照会できます。</p>\n'
                '<h6>実験\u3000DAX 上のファイルのアラインメントを確認する</h6>\n'
                '<p>本書のダウンロード資料にある FsTool を使い、DAX 上のファイルのアラインメントの違いを確認します。\n'
                'この実験には DAX ボリュームを用意してください。\n'
                'コマンドプロンプトを開き、FsTool で大きなファイル（4 GB以上を推奨）を DAX ボリュームにコピーします。\n'
                '次の例では2つの DAX ディスクを P: と Q: にマウントし、FsTool の通常のコピー操作で ISO イメージを Q: ボリュームにコピーします。</p>\n'
                '<pre><code>D:&#92;&gt;fstool.exe /copy p:&#92;Big_DVD_Image.iso q:&#92;test.iso\n'
                'NTFS / ReFS Tool v0.1\n'
                'Copyright (C) 2018 Andrea Allievi (AaLl86)\n'
                '\n'
                '「Big_DVD_Image.iso」を「test.iso」にコピーしています... 成功\n'
                'ファイルコピーの合計実行時間: 10秒、転送速度: 495.52 MB/s\n'
                '何かキーを押すと終了します...</code></pre>\n'
                '<p>できあがった <code>test.iso</code> のアラインメントは、<code>FsTool.exe</code> の '
                '<code>/queryalign</code> オプション、または Windows 標準の <code>fsutil.exe</code> の '
                '<code>queryFileAlignment</code> サブコマンドで確認できます。</p>\n'
                '<pre><code>D:&#92;&gt;fsutil dax queryFileAlignment q:&#92;test.iso</code></pre>\n'
                '<table><caption>ファイル領域のアラインメント</caption>\n'
                '<thead><tr><th>領域</th><th>アラインメント</th><th>開始オフセット</th><th>長さ（バイト）</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>0</td><td>その他</td><td><code>0</code></td><td><code>0x1fd000</code></td></tr>\n'
                '<tr><td>1</td><td>ラージ</td><td><code>0x1fd000</code></td><td><code>0x3b800000</code></td></tr>\n'
                '<tr><td>2</td><td>ヒュージ</td><td><code>0x3b9fd000</code></td><td><code>0xc0000000</code></td></tr>\n'
                '<tr><td>3</td><td>ラージ</td><td><code>0xfb9fd000</code></td><td><code>0x13e00000</code></td></tr>\n'
                '<tr><td>4</td><td>その他</td><td><code>0x10f7fd000</code></td><td><code>0x17e000</code></td></tr>\n'
                '</tbody></table>\n'
                '<p>結果を見ると、ファイルの先頭部分は4 KB境界にそろったクラスターに格納されています。\n'
                '表示されるオフセットは、ファイル内の位置を示し、VCN に対応します。\n'
                'ボリューム内の位置を示す LCN とは基準が異なります。\n'
                'ラージページやヒュージページでマッピングするための境界は、ボリューム上のページオフセットを基準に判定されるため、この違いは重要です。\n'
                'ファイルが大きくなると、2 MBまたは1 GB境界にそろったボリューム上の位置から一部のクラスターが割り当てられます。\n'
                'メモリマネージャーは、その部分をラージページまたはヒュージページでマップできます。</p>\n'
                '<p>前の実験と同様に、今度はコピー先のアラインメントを指定して DAX コピーを実行します。</p>\n'
                '<pre><code>P:&#92;&gt;fstool.exe /daxcopy p:&#92;Big_DVD_Image.iso q:&#92;test.iso '
                '/align:1GB\n'
                'NTFS / ReFS Tool v0.1\n'
                'Copyright (C) 2018 Andrea Allievi (AaLl86)\n'
                '\n'
                'DAX コピーを開始しています...\n'
                'コピー元のファイルパス: p:&#92;Big_DVD_Image.iso\n'
                'コピー先のファイルパス: q:&#92;test.iso\n'
                'コピー元のボリューム: p:&#92;、ファイルシステム: NTFS、DAX モード: 有効</code></pre>',
 'p2-page-765': '<pre><code>コピー先のボリューム: q:&#92;、ファイルシステム: NTFS、DAX モード: 無効\n'
                '\n'
                'コピー元ファイルのサイズ: 4.34 GB\n'
                'コピー先のアラインメント（1 GB）を設定しました。\n'
                '\n'
                'ファイルをコピーしています... 成功\n'
                '合計実行時間: 6秒\n'
                'コピー速度: 618.81 MB/s\n'
                '\n'
                '何かキーを押すと終了します...</code></pre>\n'
                '<pre><code>P:&#92;&gt;fsutil dax queryFileAlignment q:&#92;test.iso</code></pre>\n'
                '<table><caption>ファイル領域のアラインメント</caption>\n'
                '<thead><tr><th>領域</th><th>アラインメント</th><th>開始オフセット</th><th>長さ（バイト）</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>0</td><td>ヒュージ</td><td><code>0</code></td><td><code>0x100000000</code></td></tr>\n'
                '<tr><td>1</td><td>ラージ</td><td><code>0x100000000</code></td><td><code>0xf800000</code></td></tr>\n'
                '<tr><td>2</td><td>その他</td><td><code>0x10f800000</code></td><td><code>0x17b000</code></td></tr>\n'
                '</tbody></table>\n'
                '<p>後者のコピーでは、1 GB境界にそろった次のクラスターから、すぐに領域が割り当てられました。\n'
                'ファイルの先頭4 GB（<code>0x100000000</code> バイト）は連続した領域に格納されています。\n'
                'メモリマネージャーはこの部分をマップする際、2048個のページテーブルを使う代わりに、ページディレクトリポインターテーブル（PDPT）の4エントリだけを使います。\n'
                'これにより物理メモリを節約し、プロセッサーが DAX セクション内のデータにアクセスする際の性能を大幅に高められます。\n'
                '大きなページが実際に使われることを確認するには、カーネルデバッガーを接続し、FsTool に <code>/debug</code> を指定します。\n'
                'ローカルカーネルデバッガーでも確認できます。</p>\n'
                '<pre><code>P:&#92;&gt;fstool.exe /daxcopy p:&#92;Big_DVD_Image.iso q:&#92;test.iso '
                '/align:1GB /debug\n'
                'NTFS / ReFS Tool v0.1\n'
                'Copyright (C) 2018 Andrea Allievi (AaLl86)\n'
                '\n'
                'DAX コピーを開始しています...\n'
                'コピー元のファイルパス: p:&#92;Big_DVD_Image.iso\n'
                'コピー先のファイルパス: q:&#92;test.iso\n'
                'コピー元のボリューム: p:&#92;、ファイルシステム: NTFS、DAX モード: 無効\n'
                'コピー先のボリューム: q:&#92;、ファイルシステム: NTFS、DAX モード: 有効\n'
                '\n'
                'コピー元ファイルのサイズ: 4.34 GB\n'
                'コピー先のアラインメント（1 GB）を設定しました。\n'
                '\n'
                'ファイルをコピーしています...\n'
                '[デバッグ] (PID: 10412) コピー元とコピー先のファイルをマップしました。\n'
                'コピー元のマッピングアドレス: 0x000001F1C0000000（DAX モード: 1）\n'
                'コピー先のマッピングアドレス: 0x000001F2C0000000（DAX モード: 1）\n'
                'ファイルオフセット: 0x0、アラインメント: 1 GB\n'
                '\n'
                'Enter キーを押すとコピーを開始します...\n'
                '\n'
                '[デバッグ] (PID: 10412) ファイルの一部分のコピーに成功しました。\n'
                'Enter キーを押すと次の部分に進むか、ファイルをフラッシュします...</code></pre>',
 'p2-page-766': '<p>実際のメモリマッピングは、デバッガーの <code>!pte</code> 拡張コマンドで確認できます。\n'
                'まず <code>.process</code> コマンドで対象プロセスのコンテキストに切り替え、次に FsTool が表示した仮想アドレスを調べます。</p>\n'
                '<pre><code>8: kd&gt; !process 0n10412 0\n'
                'Cid が 28ac のプロセスを検索しています\n'
                'PROCESS ffffd28124121080\n'
                'SessionId: 2  Cid: 28ac    Peb: a29717c000  ParentCid: 31bc\n'
                'DirBase: 4cc491000  ObjectTable: ffff950f94060000  HandleCount:  49.\n'
                'Image: FsTool.exe\n'
                '\n'
                '8: kd&gt; .process /i ffffd28124121080\n'
                'You need to continue execution (press &#x27;g&#x27; &lt;enter&gt;) for the context\n'
                'to be switched. When the debugger breaks in again, you will be in\n'
                'the new process context.\n'
                '\n'
                '8: kd&gt; g\n'
                'ブレーク命令の例外、コード 80000003（初回通知）\n'
                'nt!DbgBreakPointWithStatus:\n'
                'fffff804`3d7e8e50 cc              int     3\n'
                '\n'
                '8: kd&gt; !pte 0x000001F2C0000000\n'
                '                                             VA 000001f2c0000000\n'
                'PXE at FFFFB8DC6E371018    PPE at FFFFB8DC6E203E58    PDE at FFFFB8DC407CB000\n'
                'contains 0A0000D57CEA8867  contains 8A000152400008E7  contains 0000000000000000\n'
                'pfn d57cea8   ---DA--UWEV  pfn 15240000  --LDA--UW-V\n'
                '                                                         LARGE PAGE pfn 15240000\n'
                '\n'
                'PTE at FFFFB880F9600000\n'
                'contains 0000000000000000\n'
                'LARGE PAGE pfn 15240000</code></pre>\n'
                '<p><code>!pte</code> の結果から、DAX ファイルの先頭1 GB がヒュージページを使ってマップされていることを確認できます。\n'
                'ページディレクトリもページテーブルもありません。\n'
                'FsTool は既存のファイルのアラインメントを指定するためにも使えます。\n'
                '<code>FSCTL_SET_DAX_ALLOC_ALIGNMENT_HINT</code> '
                'は既存のデータを移動せず、以後ファイルが拡張され、新しいエクステントが割り当てられる際のヒントを提供します。</p>\n'
                '<pre><code>D:&#92;&gt;fstool e:&#92;test.iso /align:2MB /offset:0\n'
                'NTFS / ReFS Tool v0.1\n'
                'Copyright (C) 2018 Andrea Allievi (AaLl86)\n'
                '\n'
                '「test.iso」にアラインメントを設定しています（オフセット 0x0）... 成功\n'
                '何かキーを押すと終了します...\n'
                '\n'
                'D:&#92;&gt;fsutil dax queryfileAlignment e:&#92;test.iso</code></pre>\n'
                '<table><caption>ファイル領域のアラインメント</caption>\n'
                '<thead><tr><th>領域</th><th>アラインメント</th><th>開始オフセット</th><th>長さ（バイト）</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>0</td><td>ヒュージ</td><td><code>0</code></td><td><code>0x100000000</code></td></tr>\n'
                '<tr><td>1</td><td>ラージ</td><td><code>0x100000000</code></td><td><code>0xf800000</code></td></tr>\n'
                '<tr><td>2</td><td>その他</td><td><code>0x10f800000</code></td><td><code>0x17b000</code></td></tr>\n'
                '</tbody></table>',
 'p2-page-767': '<h5>仮想永続メモリディスクと記憶域スペース</h5>\n'
                '<p>永続メモリはサーバーシステムや、短い応答時間で毎秒数千件のクエリを処理する大規模な SQL データベースなど、停止が許されないアプリケーションのために設計されました。\n'
                'この種のサーバーでは、Hyper-V の仮想マシン上でアプリケーションを実行することがよくあります。\n'
                'Windows Server 2019は、新しい種類の仮想ハードディスクである<strong>仮想永続メモリディスク</strong>をサポートします。\n'
                '仮想ディスクの実体は VHDPMEM ファイルです。\n'
                '本書の執筆時点では、VHDPMEM ファイルの作成や通常の VHD ファイルからの変換には Windows PowerShell が必要です。\n'
                '仮想永続メモリディスクは、ホストに搭載された実際の DAX ディスク上の領域を、VHDPMEM ファイルを介して直接マップします。\n'
                'VHDPMEM ファイルは、その DAX ボリューム上に置く必要があります。</p>\n'
                '<p>仮想永続メモリディスクを仮想マシンに接続すると、Hyper-V はゲストに仮想永続メモリデバイス（VPMEM）を公開します。\n'
                'デバイスの情報は、仮想 UEFI BIOS の NVDIMM ファームウェアインターフェイステーブル（NFIT）にあります。\n'
                'NFIT の詳細は ACPI 6.2仕様を参照してください。\n'
                'SCM バスドライバーはこのテーブルを読み、仮想 NVDIMM デバイスと永続メモリディスクを表す通常のデバイスオブジェクトを作ります。\n'
                '永続メモリディスクのクラスドライバーである <code>Pmem.sys</code> '
                'は、仮想ディスクを通常の永続メモリディスクと同じ方法で管理し、その上に仮想ボリュームを作ります。\n'
                'Windows ハイパーバイザーとその構成要素については第9章を参照してください。</p>\n'
                '<figure><p>ホストのワーカープロセスは VHDPMEM ファイルを開きます。\n'
                'ファイルはホストの NTFS（DAX）と永続メモリドライバースタックを経由して、ホストの物理アドレス空間にある NVDIMM の永続領域に対応します。\n'
                'ホスト側には VID、BIOS VDEV、VPMEM VDEV が示されています。\n'
                'ゲストに提供される ACPI NFIT が NVDIMM の配置を記述し、ゲストの永続メモリドライバースタックは仮想永続メモリデバイスを扱います。\n'
                'その上に永続メモリ対応のファイルシステム（図では NTFS の DAX モード）と永続メモリディスクが示されています。\n'
                '原図の濃い灰色は仮想化固有のコンポーネント、薄い灰色はゲストとホストパーティションに共通するコンポーネントです。</p>\n'
                '<figcaption>図11-77 仮想永続メモリのアーキテクチャ</figcaption></figure>\n'
                '<p>仮想永続メモリデバイスは、ホスト上の領域を仮想化し、ゲストに連続したアドレス空間を公開します。\n'
                'ホスト上の VHDPMEM ファイルが連続した領域を占める必要はありません。\n'
                'DAX モードとブロックモードの両方に対応し、ホストと同様にボリュームのフォーマット時にモードを選びます。\n'
                'ラージページとヒュージページも、ホストと同じ方法で使えます。\n'
                '仮想永続メモリデバイスと VHDPMEM ファイルのマッピングに対応するのは、第2世代の仮想マシンだけです。</p>\n'
                '<p>Windows Server 2019の記憶域スペースダイレクト（Storage Spaces Direct）も、仮想ストレージプール内の DAX ディスクをサポートします。\n'
                '種類の異なるディスクをまとめたアレイに、1台以上の DAX ディスクを組み込めます。\n'
                'アレイ内の永続メモリディスクは、より大きな階層化仮想ディスクの容量層やパフォーマンス層、あるいは高速なキャッシュとして構成できます。\n'
                '記憶域スペースについては本章の後半で説明します。</p>',
 'p2-page-768': '<h6>実験\u3000VHDPMEM イメージを作成して接続する</h6>\n'
                '<p>前述のように、PowerShell で仮想永続メモリディスクを作成、変換し、Hyper-V 仮想マシンに割り当てられます。\n'
                '実験には DAX ディスクと、Windows 10 October Update（RS5）以降をインストールした第2世代の仮想マシンが必要です。\n'
                '仮想マシンの作成手順はこの実験では扱いません。\n'
                '管理者として Windows PowerShell を開き、DAX モードのディスク（この例では Q: ドライブ）に移動して、仮想永続メモリディスクを作成します。</p>\n'
                '<pre><code>PS Q:&#92;&gt; New-VHD VmPmemDis.vhdpmem -Fixed -SizeBytes 256GB '
                '-PhysicalSectorSizeBytes 4096\n'
                '\n'
                'ComputerName\n'
                '                         : 37-4611k2635\n'
                'Path\n'
                '                         : Q:\\VmPmemDis.vhdpmem\n'
                'VhdFormat\n'
                '                         : VHDX\n'
                'VhdType\n'
                '                         : Fixed\n'
                'FileSize\n'
                '                         : 274882101248\n'
                'Size\n'
                '                         : 274877906944\n'
                'MinimumSize             :\n'
                'LogicalSectorSize\n'
                '                         : 4096\n'
                'PhysicalSectorSize\n'
                '                         : 4096\n'
                'BlockSize               : 0\n'
                'ParentPath              :\n'
                'DiskIdentifier\n'
                '                         : 3AA0017F-03AF-4948-80BE-B40B4AA6BE24\n'
                'FragmentationPercentage : 0\n'
                'Alignment               : 1\n'
                'Attached\n'
                '                         : False\n'
                'DiskNumber              :\n'
                'IsPMEMCompatible        : True\n'
                'AddressAbstractionType  : None\n'
                'Number                  :</code></pre>\n'
                '<p>仮想永続メモリディスクは仕様上、固定サイズに限られ、指定した容量全体が割り当てられます。\n'
                '次に、仮想永続メモリコントローラーを作成して仮想マシンに追加します。\n'
                '仮想マシンが停止していることを確認し、<code>TestPmVm</code> を対象の仮想マシン名に置き換えて、次のコマンドを実行します。</p>\n'
                '<pre><code>PS Q:&#92;&gt; Add-VMPmemController -VMName "TestPmVm"</code></pre>\n'
                '<p>作成した仮想ディスクを、仮想マシンの永続メモリコントローラーに接続します。\n'
                '次のコマンドでは、前の手順で指定した仮想マシン名に統一しています。</p>\n'
                '<pre><code>PS Q:&#92;&gt; Add-VMHardDiskDrive "TestPmVm" PMEM -ControllerLocation 1 -Path '
                "'Q:&#92;VmPmemDis.vhdpmem'</code></pre>\n"
                '<p><code>Get-VMPmemController</code> で接続結果を確認できます。</p>\n'
                '<pre><code>PS Q:&#92;&gt; Get-VMPmemController -VMName "TestPmVm"\n'
                '\n'
                'VMName     ControllerNumber Drives\n'
                '------     ---------------- ------\n'
                'TestPmVm   0\n'
                '                            {PMEM コントローラー番号0、位置1の永続メモリデバイス}</code></pre>\n'
                '<p>仮想マシンを起動すると、ゲストの Windows が新しい仮想ディスクを検出します。\n'
                '仮想マシンで「ディスクの管理」MMC スナップイン（<code>diskmgmt.msc</code>）を開き、ディスクを GPT で初期化します。\n'
                '次にシンプルボリュームを作成してドライブ文字を割り当てます。\n'
                'この時点ではフォーマットしません。</p>',
 'p2-page-769': '<figure>\n'
                '<img loading="lazy" width="591" height="550" src="assets/eb8b4c11da62709f175e3f14.webp" '
                'alt="仮想永続メモリディスクの初期化後の画面">\n'
                '<img loading="lazy" width="59" height="550" src="assets/33e4c73b721e87434db41d01.webp" '
                'alt="">\n'
                '</figure>\n'
                '<p>次に仮想永続メモリディスクを DAX モードでフォーマットします。\n'
                '仮想マシンで管理者としてコマンドプロンプトを開きます。\n'
                '前の手順で仮想永続メモリディスクに割り当てたドライブ文字が E: の場合は、次のコマンドを実行します。</p>\n'
                '<pre><code>C:&#92;&gt;format e: /DAX /fs:NTFS /q\n'
                'ファイルシステムの種類は RAW です。\n'
                '新しいファイルシステムは NTFS です。\n'
                '\n'
                '警告: 固定ディスクのドライブ E: にあるデータはすべて失われます。\n'
                'フォーマットを続行しますか（Y/N）? y\n'
                '256.0 GB をクイックフォーマットしています。\n'
                'ボリュームラベル（32文字まで。指定しない場合は Enter）? DAX-In-Vm\n'
                'ファイルシステムの構造を作成しています。\n'
                'フォーマットが完了しました。\n'
                'ディスクの総容量: 256.0 GB\n'
                '利用可能な容量: 255.9 GB</code></pre>',
 'p2-page-770': '<p>仮想ディスクが DAX モードでフォーマットされたことは、Windows 標準の <code>fsutil.exe</code> に <code>fsinfo '
                'volumeinfo</code> を指定して確認できます。\n'
                '次の例では、前の手順で仮想ディスクに割り当てたドライブ文字 E: を指定します。</p>\n'
                '<pre><code>C:&#92;&gt;fsutil fsinfo volumeinfo E:\n'
                'ボリューム名: DAX-In-Vm\n'
                'ボリュームのシリアル番号: 0x1a1bdc32\n'
                'パス構成要素の最大長: 255\n'
                'ファイルシステム名: NTFS\n'
                '読み書き可能\n'
                'シンプロビジョニングなし\n'
                'ファイル名の大文字と小文字を区別\n'
                'ファイル名の大文字と小文字を保持\n'
                'ファイル名に Unicode を使用可能\n'
                'ACL を保持し適用\n'
                'ディスククォータに対応\n'
                '再解析ポイントに対応\n'
                'ハンドルを閉じた結果の情報を返す\n'
                'POSIX 形式のリンク解除と改名に対応\n'
                'オブジェクト識別子に対応\n'
                '名前付きストリームに対応\n'
                'ハードリンクに対応\n'
                '拡張属性に対応\n'
                'ファイル ID によるオープンに対応\n'
                'USN ジャーナルに対応\n'
                'DAX ボリューム</code></pre>\n'
                '<h3>回復性のあるファイルシステム（ReFS）</h3>\n'
                '<p>Windows Server 2012 R2 のリリースでは、回復性のあるファイルシステム（Resilient File System、ReFS）が導入されました。\n'
                'このファイルシステムは、記憶域スペース（Storage Spaces）というストレージアーキテクチャの一部です。\n'
                '記憶域スペースでは、たとえば SSD と回転式ハードディスクを組み合わせた階層化仮想ボリュームを作れます。\n'
                '記憶域スペースとストレージの階層化については、本章の後半で説明します。</p>\n'
                '<p>ReFS はメタデータを別の場所に書く方式を採用しています。\n'
                'ファイルシステムのメタデータを更新すると、新しい内容を別の場所に書き込み、古い内容に削除済みの印を付けます。\n'
                'この方式はデータの整合性を保つ仕組みの一つです。\n'
                'ReFS の当初の設計目標は次のとおりです。</p>\n'
                '<ol>\n'
                '<li>自己修復と、ボリュームをオンラインに保ったままの検査および修復により、ファイルシステムの破損による停止時間をほぼゼロにすること。ライトスルーもサポートします。ライトスルーについては、この節の後半で説明します。</li>\n'
                '<li>ハードウェアとソフトウェアの両面で、すべてのユーザーデータの整合性を保つこと。</li>\n'
                '<li>ブロッククローンを使い、ファイルのスナップショットを効率よく高速に作成すること。</li>\n'
                '<li>エクサバイト規模のボリュームと、非常に大きなファイルをサポートすること。</li>\n'
                '<li>データとメタデータを自動で階層化し、瓦記録方式（SMR）や将来の SSD に対応すること。</li>\n'
                '</ol>',
 'p2-page-771': '<p>ReFS には複数のバージョンがあります。\n'
                '本書で扱うのは、Windows Server 2016で初めて実装された ReFS v2 です。\n'
                '図11-78に NTFS と ReFS の実装の違いを示します。\n'
                'ReFS の開発では、NTFS 全体を書き直す代わりに、ディスク上の形式を扱う部分と、その形式に依存しない部分に実装を分けました。</p>\n'
                '<figure><table>\n'
                '<thead><tr><th>層</th><th><code>NTFS.SYS</code></th><th><code>ReFS.SYS</code></th></tr></thead>\n'
                '<tbody>\n'
                '<tr><th scope="row">上位層</th><td>API とファイルシステムの動作を実装するエンジン</td><td>NTFS '
                'から受け継いだ上位層のエンジン</td></tr>\n'
                '<tr><th scope="row">ディスク上の格納を扱う層</th><td>NTFS '
                'の格納エンジン</td><td>新しい格納エンジン（Minstore）</td></tr>\n'
                '</tbody>\n'
                '</table><figcaption>図11-78 ReFS と NTFS の実装の比較</figcaption></figure>\n'
                '<p>ReFS はディスク上の格納エンジンを Minstore に置き換えています。\n'
                'Minstore は回復可能なオブジェクトストアのライブラリです。\n'
                '呼び出し元にはキーと値からなるテーブルのインターフェイスを提供します。\n'
                'テーブルを変更するときは書き込み先の領域を新たに割り当て、Windows のキャッシュマネージャーとも連携します。\n'
                'Minstore は、大規模なストレージにも対応できるコピーオンライト方式のファイルシステムの中核を実装しています。\n'
                'ReFS はこのライブラリを使い、ファイルやディレクトリなどを実装します。</p>\n'
                '<h4>Minstore のアーキテクチャ</h4>\n'
                '<p>Minstore はすべてをテーブルとして扱います。\n'
                'テーブルは複数の行で構成され、各行はキーと値の組です。\n'
                'ディスク上では Minstore のテーブルを B+ 木で表し、揮発性メモリ（RAM）上ではハッシュテーブルで表します。\n'
                '平衡木の一種である B+ 木には、次の性質があります。</p>\n'
                '<ol>\n'
                '<li>通常、1つのノードが多数の子ノードを持ちます。</li>\n'
                '<li>キーに対応する値を含むディスク上のファイルブロックへのポインターは、葉ノードだけが持ちます。</li>\n'
                '<li>ルートノードからどの葉ノードまでたどっても、経路の長さは同じです。</li>\n'
                '</ol>',
 'p2-page-772': '<p>NTFS などのファイルシステムでは一般に、二分探索木を一般化したデータ構造である B 木を使います。\n'
                'B 木では各ノードにキーとデータへのポインターを一緒に格納します。\n'
                'そのため、1つのノードに詰め込めるエントリの数が大きく減り、木の階層が増えてレコードの検索に時間がかかります。</p>\n'
                '<p>図11-79に B+ 木の例を示します。\n'
                'ルートノードと内部ノードにはキーがあり、データを保持する葉ノードへたどるために使われます。\n'
                '葉ノードはすべて同じ深さにあり、通常は互いにリンクされています。\n'
                'そのため、要素を探すのに多数の I/O を発行する必要はありません。</p>\n'
                '<p>たとえば Minstore がキー20を検索するとします。\n'
                'ルートノードには索引用のキーが1つあります。\n'
                '13以上のキーは右のポインターが指す部分木に、13未満のキーは左のポインターが指す部分木にあります。\n'
                'Minstore が実データを保持する葉に着くと、木全体を走査せずに、同じ葉にあるキー16と25のデータにもアクセスできます。</p>\n'
                '<p>葉ノード同士は通常、連結リストでつながっています。\n'
                'たとえば図の葉の値がすべてフォルダー内のファイルを表すとすると、木が大きくても、Minstore '
                'はルートと中間ノードに一度アクセスしてから葉を順にたどり、そのフォルダーの全ファイルを列挙できます。\n'
                'Minstore はファイルやディレクトリ以外のオブジェクトを表すときにも B+ 木を使います。</p>\n'
                '<figure><p>ルートのキーは13です。\n'
                '左の内部ノードのキーは9と11で、キー1と4、キー9と10、キー11と12を持つ葉を指します。\n'
                '右の内部ノードのキーは16で、キー13と15を持つ葉、およびキー16、20、25を持つ葉を指します。\n'
                'データへのポインターを持つのは葉ノードだけで、子を指すノードは子へのリンクで探索を導きます。</p>\n'
                '<figcaption>図11-79 B+ 木の例</figcaption></figure>\n'
                '<p>本書では B+ 木と B+ テーブルを同じ意味で使います。\n'
                'Minstore は複数の種類のテーブルを定義します。\n'
                'テーブルを作成し、行を追加、削除、更新できます。\n'
                '外部の呼び出し元はテーブルの行を列挙したり、1行を検索したりできます。\n'
                'Minstore の中核となる<strong>オブジェクトテーブル</strong>には、ボリューム上でほかの木に埋め込まれていない、すべての B+ '
                '木のルートの位置が記録されています。\n'
                'B+ 木は別の木に埋め込むこともでき、その場合は親の木の行に子の木のルートを格納します。</p>\n'
                '<p>Minstore の各テーブルは<strong>コンポジット</strong>と<strong>スキーマ</strong>によって定義されます。\n'
                'コンポジットは、ルートノード（場合によっては子ノードも）の振る舞いと、B+ テーブルの各ノードを検索、操作する方法を定める規則の集まりです。\n'
                'Minstore は2種類のルートノードをサポートし、それぞれを対応するコンポジットで管理します。</p>',
 'p2-page-773': '<ul>\n'
                '<li><strong>コピーオンライト（CoW）</strong>。木を変更すると、この種類のルートノードの格納位置が変わります。\n'
                '変更時には新しい B+ 木を書き込み、古い木に削除対象の印を付けます。\n'
                '対応するコンポジットは、テーブルを書き込む際に使うオブジェクト ID を保持します。</li>\n'
                '<li><strong>埋め込み</strong>。この種類のルートノードは、別の B+ 木のインデックスエントリのデータ部分（葉ノードの値）に格納されます。\n'
                '埋め込み用のコンポジットは、そのインデックスエントリへの参照を保持します。</li>\n'
                '</ul>\n'
                '<p>テーブルの作成時にスキーマを指定すると、Minstore はキーの型、ルートノードと葉ノードの大きさ、テーブル内の行の配置を判断できます。\n'
                'ReFS はファイルとディレクトリに異なるスキーマを使います。\n'
                'ディレクトリはオブジェクトテーブルから参照される B+ テーブルのオブジェクトで、ファイル、リンク、ファイル ID の3種類の行を格納できます。\n'
                '各行のキーは、ファイル、リンク、またはファイル ID の名前を表します。\n'
                'ファイルもテーブルであり、各行に属性コードと値の組を格納します。</p>\n'
                '<p>テーブルを閉じる、変更する、ディスクに書き込む、削除するといった操作は、すべて Minstore のトランザクションとして表されます。\n'
                'データベースのトランザクションと同様に、複数の操作を含むこともある作業単位で、全体が成功するか、全体が失敗するかのどちらかです。\n'
                'テーブルをディスクに書き込む処理を、木の更新と呼びます。\n'
                '木の更新を要求すると、その木で実行中のトランザクションがすべて完了するのを待ち、更新が終わるまでは新しいトランザクションを開始させません。</p>\n'
                '<p>ReFS は、別の B+ 木の行にルートノードを格納した B+ 木を<strong>埋め込みテーブル</strong>として広く使います。\n'
                'たとえば、各ファイルは B+ 木で、そのルートはディレクトリの行に埋め込まれます。\n'
                '埋め込みテーブルを移動して親テーブルを変更することもできます。\n'
                'ルートノードは固定長で、その大きさはテーブルのスキーマで決まります。</p>\n'
                '<h5>B+ 木の物理配置</h5>\n'
                '<p>Minstore の B+ 木は、一般的な B+ 木のノードに相当する<strong>バケット</strong>で構成されます。\n'
                '葉のバケットは木が格納するデータを保持します。\n'
                '中間バケットは探索を案内するノードで、次の階層を参照するために使います。\n'
                '図11-79では各ノードがバケットです。\n'
                '中間ノードの役割は探索を子バケットへ案内することなので、子のキーをそのまま複製する必要はなく、2つのバケットのキー範囲の間にある値を使えます。\n'
                'ReFS におけるキーは通常、圧縮したファイル名です。\n'
                '中間バケットのデータには参照先の論理クラスター番号（LCN）と、そのバケットのチェックサムが入ります。\n'
                'ReFS はこのチェックサムを自己修復に使います。\n'
                'Minstore のテーブルは、葉にデータブロックのハッシュを持ち、それ以外の各ノードに子ノードのハッシュから計算した暗号学的ハッシュを持つマークル木にたとえられます。</p>\n'
                '<p>各バケットには、バケットを記述するインデックスヘッダーと、正しい順序でインデックスエントリを指すオフセットの配列であるフッターがあります。\n'
                'インデックスエントリはこの間にあります。\n'
                '各エントリは B+ テーブルの1行に対応し、同じバケット内にあるキーとデータそれぞれの位置とサイズを示します。\n'
                '図11-80は葉バケットの3行をフッターのオフセットで索引付けした例です。\n'
                '葉のページでは、各行がキーと実データ（またはほかの埋め込み木のルート）を持ちます。</p>',
 'p2-page-774': '<figure><p>ヘッダーには行数、空きバイト数、先頭行のオフセット、行オフセット配列の開始位置があります。\n'
                '格納順は行1、行3、行2ですが、フッターの配列には行1、行2、行3を指すオフセット（<code>0x20</code>、<code>0x100</code>、<code>0x80</code>）が順に並びます。</p>\n'
                '<figcaption>図11-80 3件のインデックスエントリをフッターのオフセット配列で順序付けた葉バケット</figcaption></figure>\n'
                '<h5>アロケーター</h5>\n'
                '<p>ファイルシステムが Minstore にバケットの割り当てを要求する場合、Minstore は基盤メディアの空き領域を追跡する必要があります。\n'
                'B+ テーブルがバケットを要求する処理を、バケットのピン留めと呼びます。\n'
                '初期の Minstore は、複数のアロケーターがそれぞれ親から領域を割り当てられる階層型アロケーターを使っていました。\n'
                'ルートアロケーターがボリューム全体の領域を対応付け、各アロケーターは <code>lcn-count</code> テーブルスキーマを使う B+ 木になりました。\n'
                'このスキーマでは、行のキーはアロケーターが親ノードから取得した LCN の範囲を、値はアロケーターの領域を表します。\n'
                '当初の実装では、領域内の各区画について、子ノードに対して空きか割り当て済みかと、所有オブジェクトの ID を記録していました。</p>\n'
                '<p>図11-81は、当初の階層型アロケーターの実装を単純化したものです。\n'
                '大きいアロケーターにはセットされた割り当て単位のビットが1つあります。\n'
                'そのビットが表す領域は子である中規模アロケーターに割り当てられており、子の領域は現在空いています。</p>\n'
                '<figure><table><thead><tr><th>キー</th><th>値</th></tr></thead>\n'
                '<tbody><tr><td><code>{0 - '
                '0x3FFFFF}</code></td><td><code>{10000000000000000000000000000…}</code></td></tr>\n'
                '<tr><td><code>{0x400000 - '
                '…}</code></td><td><code>{00000000000000000000000000000…}</code></td></tr>\n'
                '<tr><td><code>{0 - '
                '0x000FFF}</code></td><td><code>{00000000000000000000000000000…}</code></td></tr></tbody></table>\n'
                '<figcaption>図11-81 従来の階層型アロケーター</figcaption></figure>\n'
                '<p>B+ テーブルは、新しいバケットの取得や、コピーオンライトで既存のバケットを新しい場所に書き込むための領域の確保に、アロケーターを利用します。\n'
                '本書で扱う新しい Minstore では、ファイルシステム内の一か所でストレージの階層化を扱えるように、階層型アロケーターをポリシーに従うアロケーターに置き換えました。\n'
                '階層はストレージデバイスの種類を表します。</p>',
 'p2-page-775': '<p>階層を構成するデバイスの例には、SSD、NVMe デバイス、回転式ハードディスクがあります。\n'
                '階層化については本章の後半で説明します。\n'
                '階層化により、高速にランダムアクセスできる領域と、低速でシーケンシャルアクセスに限られる領域を1つのディスクとして扱えます。\n'
                '高速な領域は通常、低速な領域より小さくなります。</p>\n'
                '<p>ポリシーに従う新しいアロケーターは、毎秒大量の割り当てを処理できるように最適化され、要求された階層、つまり基盤ストレージの種類ごとに異なる割り当て領域を定義します。\n'
                'ファイルシステムが新しいデータの領域を要求すると、中央のアロケーターがポリシーに従って割り当て元の領域を選びます。\n'
                'ポリシーエンジンはストレージの階層を認識します。\n'
                'メタデータはランダムに書き込まれるため、常にパフォーマンス層に書き込み、SMR の容量層には書き込みません。\n'
                'このエンジンは ReFS のバンドに対応し、遅延割り当てロジック（DAL）を実装します。</p>\n'
                '<p>ファイルを作成するとき、ファイルシステムは通常、その内容に必要な領域も割り当てます。\n'
                '遅延割り当てでは Minstore は LCN の範囲をすぐに返す代わりに、空き容量がなくなっても必要な領域を確保できるよう、領域の予約を表すトークンを返します。\n'
                '実際にファイルが書き込まれる段階で、アロケーターはファイルの内容に LCN を割り当て、メタデータを更新します。\n'
                'これにより、本章の後半で扱う SMR ディスクの制約に対処でき、ReFS は64 TB以上の大きなファイルも1秒未満で作成できます。</p>\n'
                '<p>ポリシーに従うアロケーターは、3つのアロケーターで構成されます。\n'
                'ディスク上ではそれぞれをボリューム全体で使う B+ テーブルとして実装し、メモリに読み込むと AVL 木で表します。\n'
                'AVL 木は自己平衡二分木の一種です。本書では詳しく扱いません。\n'
                'B+ テーブルの各行は従来どおり範囲で索引付けされます。\n'
                '行のデータにはビットマップを格納できます。\n'
                '割り当て済み領域が連続している場合は、最適化として割り当て済みクラスター数だけを格納できます。\n'
                '3つのアロケーターの役割は次のとおりです。</p>\n'
                '<ul>\n'
                '<li><strong>中規模アロケーター（MAA）</strong>は、ほかのアロケーターが領域を割り当てる一部の B+ '
                'テーブルを除き、名前空間内の各ファイルの領域を割り当てます。\n'
                'MAA 自身も B+ テーブルなので、メタデータを新しい場所へ書き込む際には別途領域が必要です。\n'
                'その領域は小規模アロケーターが割り当てます。</li>\n'
                '<li><strong>小規模アロケーター（SAA）</strong>は、自身と MAA '
                'のほか、整合性ストリームを支える整合性状態テーブルと、ファイルのブロッククローンを支えるブロック参照カウンターテーブルの領域を割り当てます。</li>\n'
                '<li><strong>コンテナーアロケーター（CAA）</strong>は、クラスターの仮想化を支え、コンテナーの圧縮整理にも使われるコンテナーテーブルの領域を割り当てます。\n'
                '詳細は後続の節で説明します。\n'
                'CAA は、自身が使う領域を記述するエントリも1つ以上保持します。</li>\n'
                '</ul>\n'
                '<p><code>Format</code> ツールは、ReFS の基本データ構造を初めて作るときに、3つのアロケーターを作成します。\n'
                '最初は MAA がボリュームの全クラスターを記述します。\n'
                'SAA と CAA のメタデータは B+ テーブルで、この時点に限り、両者の領域を MAA から割り当てます。\n'
                'MAA 自身が使う領域を記述するエントリは SAA に追加します。\n'
                '作成後は、ReFS がアロケーター自体の破損を検出した場合を除き、SAA と CAA の追加エントリの領域を MAA から割り当てることはありません。</p>',
 'p2-page-776': '<p>ファイルのデータを新しい場所に書き込むには、ReFS はまず MAA に問い合わせて書き込み先の空き領域を探します。\n'
                '階層化された構成では各領域の階層も考慮します。\n'
                '書き込みが成功すると、対象ストリームのエクステントテーブルにエクステントの新しい位置を記録し、ファイルのメタデータを更新します。\n'
                '次に、新しい B+ 木をディスクの空きブロックへ書き込み、古いテーブルの領域を解放します。\n'
                '書き込みがライトスルーに指定されており、クラッシュ後にも書き込みが行われたことを確認できる必要がある場合は、新しい場所への書き込みをログレコードに記録します。\n'
                '詳しくは本章後半の「ReFS のライトスルー」を参照してください。</p>\n'
                '<h5>ページテーブル</h5>\n'
                '<p>Minstore が子ノードを移動したりテーブルに行を追加したりして B+ 木のバケットを更新すると、通常は親ノード（探索を案内するノード）も更新する必要があります。\n'
                '厳密には、Minstore はノードごとに新旧の子バケットを指す別々のリンクを使います。\n'
                '前述のとおり、親ノードは参照先のバケットのチェックサムを保持します。\n'
                '葉ノード自体が移動したり削除されたりする場合もあります。</p>\n'
                '<p>この構造では、たとえばあるスレッドが B+ 木を読み取っている最中に別のスレッドが行を削除する場合に、アクセスを同期する必要があります。\n'
                '木全体をロックして変更のたびに物理メディアに書き込む方法は、負荷が大きすぎます。\n'
                'そこで Minstore は、木の状態をメモリ上のハッシュテーブルで管理します。\n'
                'この<strong>Minstore '
                'のページテーブル</strong>は、通常はディレクトリやファイルのテーブルであるルートテーブルごとにあり、変更済み、解放済み、削除済みのバケットを追跡します。\n'
                'CPU が使うページテーブルとは別物です。\n'
                'このテーブルがディスクに保存されることはありません。</p>\n'
                '<p>Minstore では「バケット」と「ページ」は同じ概念を指します。\n'
                '通常、メモリ上にあるものをページ、ディスクに格納したものをバケットと呼びます。\n'
                '「木」と「テーブル」も同じ意味で使うため、この構造をページテーブルと呼びます。\n'
                '各行のキーは対象バケットの LCN で、値はページの状態を追跡し、B+ 木の同期を支えるデータ構造です。</p>\n'
                '<p>ページを初めて読み込むか作成すると、ハッシュテーブルに新しいエントリが追加されます。\n'
                'エントリを削除できるのは、次の条件をすべて満たす場合だけです。</p>\n'
                '<ul>\n'
                '<li>ページにアクセスしている実行中のトランザクションがない。</li>\n'
                '<li>ページはクリーンで、未反映の変更がない。</li>\n'
                '<li>ページは、以前のページをコピーオンライトで更新して作った新しいページではない。</li>\n'
                '</ul>\n'
                '<p>クリーンなページは通常、ページテーブルへの追加と削除を繰り返します。\n'
                '変更済みのページは、B+ 木が更新され、ディスクへ書き込まれるまでページテーブルに残ります。\n'
                '木を永続メディアへ書き出す処理は、その時点のページテーブルの状態に大きく依存します。\n'
                '図11-82に示すとおり、Minstore はページテーブルをメモリ上のキャッシュに使い、各ページの状態とその遷移を暗黙の状態機械として管理します。</p>',
 'p2-page-777': '<figure>\n'
                '<p>ページに変更が加わると、ページはダーティ状態になります。\n'
                'コピーオンライトでページを複製すると、コピー済みの状態に移ります。\n'
                'ディスク上のページ領域を解放すると、解放済みの状態になります。\n'
                'B+ 木をディスクに書き込むとページはクリーン状態になり、ページテーブルから取り除けるのはこの状態だけです。</p>\n'
                '<figcaption>図11-82 ページテーブル内のダーティページ（バケット）の状態。既存のページをコピーオンライトで更新するときや、B+ '
                '木が成長してバケットの格納領域を増やす必要があるときに、新しいページが作られます。</figcaption></figure>\n'
                '<h5>Minstore の I/O</h5>\n'
                '<p>Minstore が物理メディア上の B+ 木を読み取る方法と、書き込む方法は異なります。\n'
                '通常、読み取るのは木の一部分だけで、たとえば葉のバケットをいくつか読み取ります。\n'
                '読み取りはトランザクションの一環として、または後続のアクセスに備えた先読みとして行います。\n'
                'バケットをキャッシュに読み込んだ後も、チェックサムを検証するまではデータを解釈できません。\n'
                'キャッシュへの読み込みについては、本章前半の「キャッシュマネージャー」を参照してください。</p>\n'
                '<p>期待するチェックサムは親ノードに格納されています。\n'
                'Minstore の上位にある ReFS ドライバーが読み込まれたデータを受け取る時点では、そのノードはまだ検証されていません。\n'
                '子にたどり着くまでに親ノードを経由しているため、子のチェックサムを持つ親ノードはすでにキャッシュにあります。\n'
                'これにより、Minstore はバケットのデータが正しいことを検証できます。\n'
                'ページテーブルに登録されていても、チェックサムが未検証で、内容にまだアクセスしていないページもあります。</p>\n'
                '<p>Minstore は B+ 木全体の更新を一つのトランザクションとして扱い、変更されたページを物理ディスクに書き込みます。\n'
                'アプリケーションが明示的に変更をフラッシュした場合、システムの空きメモリが少なくなった場合、キャッシュマネージャーがキャッシュ済みのデータをディスクに書き出す場合などに、木の更新が要求されます。\n'
                '通常はレイジーライタースレッドが更新された木を遅延書き込みします。\n'
                '前述のとおり、ダーティページの数がしきい値に達した場合など、レイジーライターが動き出す条件は複数あります。</p>\n'
                '<p>Minstore は、なぜ木の更新が要求されたかを知る必要はありません。\n'
                'まず同期プリミティブを使い、ほかのトランザクションが木を変更していないことを確認します。\n'
                '最初の同期が済むと、ダーティページの書き込みと、削除された古いページの処理を始めます。</p>',
 'p2-page-778': '<p>新しい場所に書き込む方式では、新しいページは内容が変更されたバケットを表し、解放済みのページは親からリンクを外す必要がある古いページを表します。\n'
                'トランザクションが葉ノードを変更する場合は、まずルートバケットと対象の葉ページをメモリ内でコピーします。\n'
                'Minstore は対応するエントリをページテーブルに作りますが、この段階ではリンクを変更しません。</p>\n'
                '<p>木を更新するアルゴリズムはページテーブルの各ページを列挙します。\n'
                'ページテーブルには各ページが B+ 木のどの階層に属するかの情報がないため、アルゴリズムは木も調べ、最も外側のノード（通常は葉）からルートへ向かって処理します。\n'
                '各ページで次の手順を実行します。</p>\n'
                '<ol>\n'
                '<li>ページの状態を調べます。\n'
                '解放済みなら処理を飛ばします。\n'
                'ダーティページなら、親ノード内の参照先ポインターとチェックサムを更新し、そのページを書き込み対象の内部リストに追加します。</li>\n'
                '<li>古いページを破棄します。</li>\n'
                '</ol>\n'
                '<p>ルートノードに達したら、オブジェクトテーブル内でルートへのポインターとチェックサムを直接更新し、ルートバケットも書き込みリストに追加します。\n'
                'これで Minstore は、古い木を元の場所に残したまま、新しい木をボリュームの空き領域に書き込めます。\n'
                '古い木は解放済みと記録されますが、物理メディア上にはまだ残っています。\n'
                '更新内容を新しい場所に書き込むこの方式により、Minstore の上位にある ReFS は、ボリュームをオンラインに保ったまま回復する機能を実装できます。</p>\n'
                '<figure><p>新しい葉ページ A′ と B′ は書き込みリストに入り、そのチェックサムが親ノードに記録されます。\n'
                '親ノードの更新後、オブジェクトテーブルにルートの新しい参照とチェックサムが記録されます。\n'
                '原図では、ページテーブルにあるページを薄い色で、古いページを濃い色で示しています。</p>\n'
                '<figcaption>図11-83 Minstore による木の更新</figcaption></figure>',
 'p2-page-779': '<p>木の更新中に排他アクセスを維持すると、その間はほかの処理が B+ 木を読み書きできず、性能が低下することがあります。\n'
                '本書の執筆時点で新しい Windows 10では、Minstore の各 B+ 木に世代番号が付きます。\n'
                'これにより、ページがどの世代でダーティになったかを追跡できます。\n'
                'ある世代でだけダーティなページは、その世代の木がまだディスクに書き込まれていないため、コピーオンライトを行わず直接更新できます。</p>\n'
                '<p>新しい方式では、通常、木の更新を次の2段階に分けます。</p>\n'
                '<ul>\n'
                '<li><strong>失敗し得る段階</strong>。Minstore は木の排他ロックを取得し、世代番号を増やします。\n'
                '更新に必要なメモリ量を計算して確保し、最後にロックを共有モードへ切り替えます。</li>\n'
                '<li><strong>失敗しない段階</strong>。共有ロックで実行するため、ほかの I/O は木を読み取れます。\n'
                'Minstore は探索を案内するノードのリンクと木全体のチェックサムを更新し、完成した木をディスクに書き込みます。\n'
                '書き込み中に別のトランザクションが木を変更しようとすると、世代番号が増えていることを検出し、再びコピーオンライトで木を更新します。</li>\n'
                '</ul>\n'
                '<p>この方式で排他ロックを保持するのは、失敗し得る段階だけです。\n'
                'そのため、木の更新を別の Minstore トランザクションと並行して処理でき、全体の性能が大幅に向上します。</p>\n'
                '<h4>ReFS のアーキテクチャ</h4>\n'
                '<p>ReFS は NTFS の実装と Minstore を組み合わせたファイルシステムです。\n'
                'ファイルとディレクトリは、それぞれ所定のスキーマで構成された B+ 木です。\n'
                'ファイルシステムのボリュームは、ディレクトリのフラットな名前空間として構成されます。\n'
                '前述のとおり、NTFS は次の部分からなります。</p>\n'
                '<ul>\n'
                '<li><strong>ファイルシステムの基本機能</strong>。キャッシュマネージャーや I/O '
                'サブシステムなどとのインターフェイスを定義し、ファイルの作成、オープン、読み書き、クローズなどの操作を提供します。</li>\n'
                '<li><strong>ファイルシステムの上位機能</strong>。ファイル圧縮、ファイルのリンク、クォータ追跡、再解析ポイント、ファイル暗号化、回復などを提供します。</li>\n'
                '<li><strong>ディスク上の形式に依存するコンポーネントとデータ構造</strong>。MFT '
                'とファイルレコード、クラスター、インデックスを扱う機構、常駐属性と非常駐属性などが含まれます。\n'
                '詳しくは本章前半の「NT ファイルシステム（NTFS）」を参照してください。</li>\n'
                '</ul>\n'
                '<p>図11-84に示すように、ReFS は最初の2つをほぼそのまま引き継ぎ、ディスク上の形式に依存するコンポーネントを Minstore で置き換えています。</p>',
 'p2-page-780': '<figure>\n'
                '<p>上位層は、システムインターフェイス（<code>IRP_MJ_XYZ</code> '
                'など）、オブジェクトの存続期間や改名などを扱うインターフェイス、変更ジャーナル、クォータなどを提供します。\n'
                '図の形式依存部分には、インデックス、ファイルレコード属性、ビットマップ、MFT を扱う各パッケージとログマネージャーが示されています。\n'
                'ReFS ではこの形式依存部分を Minstore で置き換えます。</p>\n'
                '<figcaption>図11-84 ReFS のアーキテクチャ</figcaption></figure>\n'
                '<p>本章の「NTFS ドライバー」では、ファイルハンドルとディスク上のファイルシステム構造を結び付けるデータ構造を紹介しました。\n'
                'NTFS のストリーム制御ブロックは呼び出し元が読み取ろうとしている属性を表し、ファイル制御ブロックはディスク上の MFT 内のファイルレコードを指すポインターを持ちます。\n'
                'ReFS ドライバーでもこれらのデータ構造は使われますが、永続ストレージ上の構造との対応が異なります。\n'
                'これらのオブジェクトへの変更は Minstore を経由して反映されます。\n'
                'NTFS では、変更がディスク上の MFT への変更に直接変換されます。\n'
                '図11-85に示すように、ReFS ではそれぞれの制御ブロックが次の役割を持ちます。</p>\n'
                '<ul>\n'
                '<li><strong>ファイル制御ブロック</strong>（FCB）は1つのファイルまたはディレクトリを表します。\n'
                'Minstore の B+ 木へのポインター、親ディレクトリのストリーム制御ブロックへの参照、およびキー（ディレクトリ名）を持ちます。\n'
                'ファイルオブジェクトの <code>FsContext2</code> フィールドが FCB を指します。</li>\n'
                '<li><strong>ストリーム制御ブロック</strong>（SCB）は、ファイルオブジェクトで開いているストリームを表します。\n'
                'ReFS の SCB は NTFS のデータ構造を簡略化したものです。\n'
                'ディレクトリを表す場合、SCB は、そのディレクトリを表す B+ 木にあるインデックスへのリンクを持ちます。\n'
                'ファイルオブジェクトの <code>FsContext</code> フィールドが SCB を指します。</li>\n'
                '<li><strong>ボリューム制御ブロック</strong>（VCB）は、マウント中の ReFS ボリュームを表します。\n'
                'ReFS ドライバーは適切にフォーマットされたボリュームを認識すると、VCB を作成してボリュームデバイスオブジェクトの拡張領域に取り付けます。\n'
                'さらに、ReFS ドライバーが初期化時に確保したグローバルデータ構造のリストにリンクします。\n'
                'VCB は、そのボリュームで現在開かれているすべてのディレクトリの FCB を、参照 ID で索引付けしたテーブルを持ちます。</li>\n'
                '</ul>',
 'p2-page-781': '<figure><p>ディレクトリのファイルオブジェクトは、FCB とインデックス用の SCB を参照します。\n'
                'FCB は埋め込み B+ 木に、SCB はインデックスの B+ 木につながります。\n'
                'ファイルのファイルオブジェクトは、FCB とデータ用の SCB を参照し、ファイルレコードは埋め込み B+ 木で表されます。</p>\n'
                '<figcaption>図11-85 ReFS のファイルとディレクトリを表すメモリ上のデータ構造</figcaption></figure>\n'
                '<p>ReFS では開いているファイルごとにメモリ上に1つの FCB があり、開いているストリームの数に応じて、複数の SCB が同じ FCB を指すことがあります。\n'
                'NTFS では、属性を更新するために FCB が知る必要があるのは、そのファイルの MFT エントリです。\n'
                'ReFS の FCB は、ファイルレコードを表す B+ 木を指します。\n'
                'ファイルの B+ 木の各行は、ID、完全な名前、エクステントテーブルなど、それぞれ1つのファイル属性を表します。\n'
                '行のキーは整数の属性コードです。</p>\n'
                '<p>ファイルレコードは、ファイルが属するディレクトリのエントリです。\n'
                'ファイルを表す B+ 木のルートノードは、ディレクトリエントリの値に埋め込まれており、オブジェクトテーブルには現れません。\n'
                'ファイルのデータストリームを表すエクステントテーブルも、ファイルレコードに埋め込まれた B+ 木です。\n'
                'エクステントテーブルは範囲で索引付けされ、各行のキーは VCN の範囲、値はファイルエクステントの LCN です。\n'
                'ReFS のエクステントテーブルは通常の B+ 木なので、大きくできます。\n'
                'これにより、NTFS の制限を超える大きさのファイルを扱えます。</p>\n'
                '<p>図11-86は、ReFS の名前空間を構成するオブジェクトテーブル、ファイル、ディレクトリ、ファイルのエクステントテーブルを示します。\n'
                'いずれも B+ 木で表されます。</p>\n'
                '<figure>\n'
                '<p>オブジェクトテーブルの各行はオブジェクト ID をディスク上の位置に対応付けます。\n'
                'ディレクトリの各行はファイル名をキーとし、値にはファイルレコードのインデックスが入ります。\n'
                'ファイルレコードのルートは親のディレクトリテーブルの行に埋め込まれます。\n'
                '図のファイルレコードには、標準情報（キー10）、ファイル名（キー30）、エクステントのインデックス（キー80）などがあります。\n'
                'エクステントテーブルのルートも、親のファイルレコードの行に埋め込まれます。</p>\n'
                '<table><thead><tr><th>VCN の範囲</th><th>開始 LCN</th></tr></thead>\n'
                '<tbody><tr><td>0〜100</td><td>5004</td></tr><tr><td>101〜200</td><td>9550</td></tr><tr><td>300〜304</td><td>1000</td></tr></tbody></table>\n'
                '<figcaption>図11-86 ReFS のファイルとディレクトリ。表は図中のファイルエクステントを示します。</figcaption></figure>',
 'p2-page-782': '<p>ディレクトリは、単一のフラットな名前空間を構成する Minstore の B+ 木です。\n'
                'ReFS のディレクトリには次の項目を格納できます。</p>\n'
                '<ul><li>ファイル</li><li>ディレクトリへのリンク</li><li>ほかのファイルへのリンク（ファイル ID）</li></ul>\n'
                '<p>ディレクトリの B+ 木の各行は <code>&lt;キー, &lt;型, 値&gt;&gt;</code> の組で構成されます。\n'
                'キーはエントリの名前で、値の内容はディレクトリエントリの型によって異なります。\n'
                'Minstore は照会やその他の上位機能を支えるため、ディレクトリ内の通常は見えない行にも内部データを格納します。\n'
                'これらの行のキーは Unicode のヌル文字で始まります。\n'
                'ディレクトリには、自身のファイルレコードを格納するファイル行もあります。\n'
                'ReFS は、あらかじめ定められたゼロのキーで、そのディレクトリ自身にファイル行を格納します。</p>\n'
                '<p>この違いは、ReFS がディレクトリのためにメモリ上で維持するデータ構造にも影響します。\n'
                'NTFS では、インデックスルートとインデックス割り当ての属性によって、ディレクトリをファイルレコードの一部として表します。\n'
                'ReFS では、ディレクトリ自身に格納するファイルレコードで、これを<strong>ディレクトリインデックスレコード</strong>と呼びます。\n'
                'このため、ReFS がディレクトリ内のファイルを操作または参照するときは、ディレクトリインデックスを開いてメモリに読み込んでおく必要があります。\n'
                'ディレクトリを更新できるよう、開いているストリームの制御ブロックに、ディレクトリインデックスレコードを指すポインターを格納します。</p>\n'
                '<p>ここまで説明した B+ 木の構成のままでは、ディレクトリ内のファイルを列挙するたびに、個々のファイルの B+ 木を開いて解析する必要があります。\n'
                '基盤メディア上のさまざまな位置に多数の I/O 要求を発行することになり、回転式ディスクでは性能が大きく低下します。</p>\n'
                '<p>この問題に対処するため、ReFS は <code>STANDARD_INFORMATION</code> データ構造を、ファイルの B+ '
                '木の行ではなく、そのファイルの埋め込みテーブルのルートノードに格納します。\n'
                'この構造には、アクセス日時、サイズ、属性、セキュリティ記述子の ID、更新シーケンス番号など、ファイルの列挙に必要な情報がすべて入ります。\n'
                'ファイルの埋め込みルートノードは、親ディレクトリの B+ 木の葉バケットに格納されます。\n'
                'そのため、ディレクトリ内のファイルを列挙するときは、そのディレクトリの B+ 木にあるエントリだけを解析すれば済み、個々のファイルの B+ テーブルにはアクセスしません。\n'
                'ディレクトリを表す B+ 木はすでにページテーブルにあるため、列挙は高速です。</p>\n'
                '<h4>ReFS のディスク上の構造</h4>\n'
                '<p>ここでは、先の NTFS の節と同様に、ReFS ボリュームのディスク上の構造を説明します。\n'
                'NTFS と ReFS の違いを中心に扱います。</p>\n'
                '<p>ReFS ボリュームのブートセクターは小さなデータ構造です。\n'
                'NTFS と同様に、シリアル番号やクラスターサイズなどの基本的なボリューム情報、ファイルシステム識別子（ReFS の OEM 文字列とバージョン）、ReFS '
                'のコンテナーサイズが入ります。\n'
                'コンテナーサイズについては、本章後半の「瓦記録方式（SMR）のボリューム」を参照してください。\n'
                'ボリュームで最も重要なデータ構造は<strong>ボリュームスーパーブロック</strong>です。\n'
                'ここには最新のボリュームチェックポイントレコードのオフセットなどが入ります。</p>',
 'p2-page-783': '<p>ボリュームスーパーブロックは、3つの異なるクラスターに複製されます。\n'
                'ボリュームをマウントする際、ReFS はボリュームチェックポイントの一つを読み取ります。\n'
                'レコードに含まれるチェックサムで検証してから解析し、各グローバルテーブルのオフセットを取得します。</p>\n'
                '<p>マウント処理では、オブジェクトテーブルを開き、ルートディレクトリを読み取るのに必要な情報を取得します。\n'
                'ルートディレクトリには、ボリュームの名前空間を構成するすべてのディレクトリ木があります。\n'
                'オブジェクトテーブルとコンテナーテーブルは、すべてのボリュームメタデータにアクセスする起点です。\n'
                'コンテナーテーブルはクラスターの仮想化に使う名前空間を提供します。\n'
                'このテーブルを使って、ReFS は各クラスターの最終的な格納位置を特定します。</p>\n'
                '<p>Minstore のクライアントは、必要に応じてオブジェクトテーブルの各行に独自の情報を格納できます。\n'
                '図11-87に示すように、行の値は Minstore が管理する部分と ReFS が管理する部分に分かれます。\n'
                'ReFS は親オブジェクトの情報と、ディレクトリ内における USN の上限値を格納します。\n'
                '詳しくは本章後半の「セキュリティと変更ジャーナル」を参照してください。</p>\n'
                '<figure><table>\n'
                '<thead><tr><th>部分</th><th>フィールド</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>キー</td><td>オブジェクト ID</td></tr>\n'
                '<tr><td>値のうち Minstore の管理部分（図の上段）</td><td>ルートの位置、ルートのチェックサム、最後に書き込んだログの番号</td></tr>\n'
                '<tr><td>値のうち ReFS の管理部分（図の下段）</td><td>最後の USN、親オブジェクト ID</td></tr>\n'
                '</tbody></table>\n'
                '<figcaption>図11-87 オブジェクトテーブルのエントリ</figcaption></figure>\n'
                '<h5>オブジェクト ID</h5>\n'
                '<p>ReFS には、ファイル ID を扱う仕組みも必要です。\n'
                '主な目的は、ファイルのメタデータを名前空間に結び付けずに効率よく追跡、格納することです。\n'
                'そのため、アプリケーションが <code>OpenFileById</code> などの API を使って、ファイル ID でファイルを開けるようにします。\n'
                'NTFS は <code>$Extend&#92;$ObjId</code> ファイルの <code>$O</code> インデックスルート属性でこれを実現します。\n'
                '詳しくは前述の NTFS の節を参照してください。</p>\n'
                '<p>ReFS でディレクトリに ID を割り当てるのは簡単です。\n'
                'Minstore は、ディレクトリのオブジェクト ID をオブジェクトテーブルに格納します。\n'
                'ファイルに ID を割り当てる場合は、ReFS に NTFS のようなファイル ID の中央リポジトリがないため、別の仕組みが必要です。\n'
                'ディレクトリ木にあるファイル ID を検索できるよう、ReFS はファイル ID をディレクトリ部分とファイル部分に分けます。\n'
                'ディレクトリ部分に入るディレクトリ ID は、オブジェクトテーブルの行のキーとして索引付けされます。\n'
                'ファイル部分は、そのディレクトリ内のファイル ID の範囲から割り当てられます。\n'
                'ディレクトリを表す ID のファイル部分は通常ゼロです。\n'
                '同じディレクトリ内のすべてのファイルは、共通のディレクトリ部分を持ちます。\n'
                'ReFS はディレクトリの B+ 木に <code>&lt;FileId, FileName&gt;</code> の組からなる別の行を追加し、そのディレクトリ内でファイル ID '
                'をファイル名に対応付けます。</p>',
 'p2-page-784': '<p>ReFS ボリューム上のファイルをファイル ID で開く要求を受け取ると、ReFS は次の手順で処理します。</p>\n'
                '<ol>\n'
                '<li>ファイル ID のディレクトリ部分が指すディレクトリを開きます。</li>\n'
                '<li>ディレクトリの B+ 木で、ファイル部分に対応するキーを持つ <code>FileId</code> 行を検索します。</li>\n'
                '<li>取得したファイル名をキーに、同じディレクトリの B+ 木を検索します。</li>\n'
                '</ol>\n'
                '<p>ファイルを改名して別のディレクトリに移しても、以前のファイル ID で同じファイルを開ける必要があります。\n'
                '移動先のディレクトリ ID は、元のファイル ID のディレクトリ部分とは異なります。\n'
                'このため、ReFS は移動元のディレクトリの B+ 木にある元のファイル ID エントリを、<strong>トゥームストーン</strong>と呼ばれるエントリに置き換えます。\n'
                'その値にはファイル名の代わりに、ディレクトリ部分とファイル部分の両方を更新した新しいファイル ID を入れます。\n'
                '移動先のディレクトリの B+ 木には、新しいローカルファイル ID を割り当てるためのエントリを追加します。\n'
                'さらに別のディレクトリに移す場合は、2番目のディレクトリの ID エントリが不要になるため削除します。\n'
                '1つのファイルに存在するトゥームストーンは最大1件です。</p>\n'
                '<h5>セキュリティと変更ジャーナル</h5>\n'
                '<p>ファイルシステムで Windows のオブジェクトセキュリティを支える処理の大半は、NTFS から引き継いだ上位コンポーネントが担います。\n'
                'ディスク上の実装は変わりましたが、提供する動作は同じです。\n'
                'ReFS はオブジェクトのセキュリティ記述子を、ボリューム全体で使うセキュリティディレクトリの B+ テーブルに格納します。\n'
                '自己相対形式の記述子だけを扱う独自のアルゴリズムで各記述子のハッシュを計算し、それぞれに ID を割り当てます。</p>\n'
                '<p>新しいセキュリティ記述子をファイルに付けるとき、ReFS ドライバーは記述子のハッシュを求め、ボリューム全体のセキュリティテーブルに存在するかを調べます。\n'
                '存在する場合、対応する ID を取得し、ファイルの B+ 木の埋め込みルートノード内の <code>STANDARD_INFORMATION</code> データ構造に格納します。\n'
                '存在しなければ、まず新しい記述子を B+ 木に追加して ID を生成し、その ID を同じように格納します。</p>\n'
                '<p>セキュリティテーブルの各行は、<code>&lt;&lt;ハッシュ, ID&gt;, &lt;セキュリティ記述子, 参照数&gt;&gt;</code> の形式です。\n'
                'ハッシュと ID は前述のとおりです。\n'
                'セキュリティ記述子には記述子そのもののバイト列が入り、参照数はボリューム上でその記述子を使っているオブジェクト数の概算です。</p>\n'
                '<p>前述のように、NTFS の変更ジャーナルを使うと、アプリケーションやサービスはボリューム内の過去のファイル変更を照会できます。\n'
                'ReFS の変更ジャーナルは NTFS と互換性がありますが、内部の実装は少し異なります。\n'
                '変更エントリは変更ジャーナルファイルに格納されます。\n'
                'このファイルは、ボリューム全体で使う別の Minstore B+ 木であるメタデータディレクトリテーブルにあります。\n'
                'ReFS が変更ジャーナルファイルを開いて解析するのは、ボリュームをマウントした後です。\n'
                'ジャーナルの最大サイズは、ジャーナルファイルの <code>$USN_MAX</code> 属性に格納されます。</p>',
 'p2-page-785': '<p>ReFS では、各ファイルとディレクトリの最後の USN（更新シーケンス番号）を、親ディレクトリ内に埋め込まれたルートノードの '
                '<code>STANDARD_INFORMATION</code> 構造に記録します。\n'
                'ReFS はジャーナルファイルと各ファイルおよびディレクトリの USN '
                'を使い、ボリュームのジャーナルを読み取ったり、対応するファイルを列挙したりするための3つの制御コード（FSCTL）を提供します。</p>\n'
                '<ul>\n'
                '<li><code>FSCTL_READ_USN_JOURNAL</code> は USN ジャーナルを直接読み取ります。\n'
                '呼び出し元は対象のジャーナル ID と、読み始める USN レコードの番号を指定します。</li>\n'
                '<li><code>FSCTL_READ_FILE_USN_DATA</code> は指定されたファイルまたはディレクトリの USN 変更ジャーナル情報を取得します。</li>\n'
                '<li><code>FSCTL_ENUM_USN_DATA</code> はファイルレコードを調べ、ジャーナルを最後に更新したレコードの USN '
                'が、呼び出し元の指定した範囲に入るファイルだけを列挙します。\n'
                'ReFS はオブジェクトテーブルを走査し、そこから参照される各ディレクトリを調べて、指定範囲内のファイルを返せます。\n'
                'ただし、ディレクトリの B+ 木はディスク上に分散していることがあり、ディレクトリを一つずつ開いて調べると時間がかかります。\n'
                'そこで ReFS は、ディレクトリ内の全ファイルのうち最大の USN を、そのディレクトリのオブジェクトテーブルエントリに記録します。\n'
                'この値を使えば、指定範囲に該当し得るディレクトリだけを調べれば済みます。</li>\n'
                '</ul>\n'
                '<h4>ReFS の高度な機能</h4>\n'
                '<p>以下では、Azure の基盤で使われるような大規模なサーバーシステムに ReFS が適している理由を、その機能から説明します。</p>\n'
                '<h5>ファイルのブロッククローン（スナップショット）とスパース VDL</h5>\n'
                '<p>従来、ストレージシステムはボリューム単位でスナップショットとクローンを実装してきました。\n'
                'ダイナミックボリュームはその一例です。\n'
                '現在のデータセンターでは、数百台の仮想マシンを稼働させ、そのデータを1つのボリュームに置くことがあり、ボリューム単位の方式ではその規模に対応できません。\n'
                '仮想マシンは通常、ホストのストレージ上の1つまたは数個のファイルに対応します。\n'
                'このため ReFS は設計当初から、ファイル単位のスナップショットと、大規模な環境でも使えるクローンを目標に、ファイル全体や一部の範囲を高速にクローンできるようにしました。</p>\n'
                '<p>あるファイルのブロック範囲を別のファイルの指定範囲にクローンできれば、ファイル単位のスナップショットを作れるほか、アプリケーションは1つ以上のファイル内でブロックを細かい単位で組み替えられます。\n'
                'VHD の差分ディスクのマージが一例です。</p>\n'
                '<p>ReFS の制御コード <code>FSCTL_DUPLICATE_EXTENTS_TO_FILE</code> '
                'は、ファイルのブロック範囲を同じファイルの別の範囲や別のファイルに複製します。\n'
                'クローン後にどちらかのファイルの共有範囲へ書き込むと、元のブロックを保持したまま、新しい場所にデータを書き込みます。\n'
                '参照が1つだけになったブロックは、その場で書き換えられます。\n'
                'パラメーターには、コピー元とコピー先のファイルハンドル、コピー元のブロック範囲、コピー先の範囲を指定します。</p>',
 'p2-page-786': '<p>前述のように、ReFS はファイルのデータストリームを構成する LCN をエクステントインデックスに登録します。\n'
                'このテーブルはファイルレコードの行に埋め込まれた B+ 木です。\n'
                'ブロッククローンを支えるため、Minstore はボリューム全体で使う別の B+ '
                '木である<strong>ブロック参照カウンターテーブル</strong>に、現在クローンされている各ブロック範囲の参照数を記録します。\n'
                'テーブルは最初は空です。\n'
                '初回のクローンが成功すると、1件以上の行が追加され、対象ブロックの参照数が2になります。\n'
                'そのブロックを参照するファイルの片方から参照がなくなると、対応する行は削除されます。</p>\n'
                '<p>ファイルに書き込む際はこのテーブルを参照し、新しい場所に書き込む必要があるか、その場で書き換えられるかを判定します。\n'
                'アロケーターでブロックを空きとして記録する前にも、このテーブルを参照します。\n'
                'ファイルのクラスターを解放するときは対象範囲の参照数を減らし、参照数がゼロになった時点で領域を空きとして記録します。</p>\n'
                '<p>図11-88はファイル全体をクローンした例です。\n'
                'ファイル1とファイル2のエクステントテーブルは同じ内容になり、Minstore '
                'のブロック参照カウンターテーブルには、ボリューム上の両方のエクステントに参照が2つずつあることが記録されます。</p>\n'
                '<figure><table>\n'
                '<thead><tr><th>ファイル内のブロック範囲</th><th>ファイル1が指すボリューム上の範囲</th><th>ファイル2が指すボリューム上の範囲</th><th>参照数</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>1〜4</td><td>a〜b</td><td>a〜b</td><td>2</td></tr>\n'
                '<tr><td>5〜8</td><td>x〜y</td><td>x〜y</td><td>2</td></tr>\n'
                '</tbody></table>\n'
                '<figcaption>図11-88 ReFS ファイルのクローン</figcaption></figure>\n'
                '<p>Minstore はブロック参照カウンターテーブルを小さく保つため、可能な場合は行を自動で結合します。\n'
                'Windows Server 2016 の Hyper-V は、このクローン用の制御コード（FSCTL）を使います。\n'
                'その結果、仮想マシンの複製や、複数のスナップショットのマージを短時間で行えます。</p>\n'
                '<p>ReFS には NTFS と同様、ファイルの<strong>有効データ長</strong>（VDL）の概念があります。\n'
                'ReFS はファイルの <code>$$ZeroRangeInStream</code> データストリームを使い、割り当て済みの各データブロックが有効かどうかを追跡します。\n'
                'ファイルに新しく割り当てた領域は無効で、最初の書き込みによって有効になります。\n'
                '無効な範囲への読み取りには、ゼロで埋めたデータを返します。\n'
                'この手法は前述の遅延割り当てロジック（DAL）に似ています。\n'
                'アプリケーションは制御コード <code>FSCTL_SET_ZERO_DATA</code> によって、実際にデータを書き込まずに、ファイルの一部を論理的にゼロで埋められます。\n'
                'Hyper-V はこの機能を使い、固定サイズの VHD を短時間で作成します。</p>',
 'p2-page-787': '<h6>実験\u3000Hyper-V で ReFS のスナップショットを確認する</h6>\n'
                '<p>この実験では Hyper-V を使い、ReFS のスナップショット機能を確認します。\n'
                'Hyper-V マネージャーで仮想マシンを作成し、任意の OS をインストールします。\n'
                '初回起動時に仮想マシン名を右クリックし、メニューから「チェックポイント」を選びます。\n'
                '続いて仮想マシンにいくつかのアプリケーションをインストールし、もう一度チェックポイントを作成します。\n'
                '次の例では、Windows Server 2012 に Office をインストールしています。</p>\n'
                '<figure><img loading="lazy" width="600" height="612" '
                'src="assets/3ed88a3ff409fe4a19e70876.webp" alt="Hyper-V '
                'マネージャーに表示された仮想マシンのチェックポイント"></figure>',
 'p2-page-788': '<p>仮想マシンを停止し、エクスプローラーで仮想ハードディスクファイルがあるフォルダーを開きます。\n'
                '仮想ハードディスクのほかに、現在のチェックポイントと前のチェックポイントとの差分を表すファイルがいくつかあります。</p>\n'
                '<figure><img loading="lazy" width="648" height="319" '
                'src="assets/4acf21f0defdc42a0a96ee85.webp" '
                'alt="エクスプローラーに表示された仮想ハードディスクとチェックポイントの差分ファイル"></figure>\n'
                '<p>Hyper-V マネージャーを開き直し、最初のチェックポイントを右クリックして「チェックポイント サブツリーの削除」を選び、チェックポイントのツリー全体を削除します。\n'
                'マージは数秒で完了します。\n'
                'Hyper-V は <code>FSCTL_DUPLICATE_EXTENTS_TO_FILE</code> 制御コードで ReFS '
                'のブロッククローンを利用し、チェックポイントの内容を基底の仮想ハードディスクファイルにマージします。\n'
                '前述のとおり、ブロッククローンではデータそのものを移動しません。\n'
                'exFAT または NTFS でフォーマットしたボリュームで同じ手順を試すと、チェックポイントのマージにずっと時間がかかります。</p>\n'
                '<h5>ReFS のライトスルー</h5>\n'
                '<p>ReFS の設計目標の一つは、ファイルシステムの破損による停止時間をほぼゼロにすることです。\n'
                '次節では、ReFS がディスクの破損から回復するために使うオンライン修復の方法を説明します。\n'
                'その前に、ReFS がトランザクションを基盤メディアに書き込む際のライトスルーの実装を説明します。</p>\n'
                '<p><strong>ライトスルー</strong>とは、ファイルの作成や拡張、ブロックの書き込みなど、クラッシュから回復した後も結果が見えることをシステムが合理的に保証してから完了する、基本的な変更操作を指します。\n'
                'ライトスルーの性能はさまざまな I/O で重要です。\n'
                '対象となるファイルシステムの操作は、データに対するものとメタデータに対するものに分けられます。</p>',
 'p2-page-789': '<p>すでに領域を割り当てたファイルを長さを変えずに上書きする場合など、メタデータを変更せずにファイルをその場で更新できる場合、ライトスルーの負荷はわずかです。\n'
                'ReFS はメタデータの更新時に新しい書き込み先を割り当てるため、メタデータを変更する操作にライトスルーの保証を与えるにはコストがかかります。\n'
                'たとえば、ファイルの改名を確実に反映させるには、ファイルシステムのルートからファイル名を記述するブロックまでのメタデータブロックを新しい場所へ書き込む必要があります。\n'
                'この方式では更新前のメタデータが元の場所に残るため、システムの回復時に、NTFS のような取り消し処理を行う必要がありません。</p>\n'
                '<p>Minstore はライトスルーを実現するため、<strong>先行書き込みログ</strong>（WAL）を使います。\n'
                '図11-89に示すように、システムは論理的に無限の長さを持つログにレコードを追加し、回復時にログを読み取って再実行します。\n'
                'Minstore はアロケーターテーブルを除くすべてのテーブルについて、論理的な再実行用のトランザクションレコードを記録します。\n'
                'ログレコード1件は、回復時に再実行するトランザクション全体を記述します。\n'
                '各トランザクションレコードは、実際に行う上位の操作（たとえば、テーブル X にキー K と値 V の組を挿入する操作）を記述した再実行レコードを1件以上含みます。\n'
                '回復処理はトランザクションレコードで各トランザクションを区別し、原子性の単位として扱います。\n'
                'トランザクションの一部だけを再実行することはありません。</p>\n'
                '<p>論理上、各 ReFS トランザクションはログレコードを入れる小さなバッファーを持ちます。\n'
                'トランザクションがコミットされると、バッファーの内容をメモリ上のボリュームログに追加し、後でディスクに書き込みます。\n'
                'トランザクションが中止された場合は内部バッファーを破棄します。\n'
                'ライトスルーのトランザクションは、ログエンジンから、そのトランザクションの位置までログがコミットされたという確認を受けるまで待ちます。\n'
                'それ以外のトランザクションは確認を待たずに処理を続けられます。</p>\n'
                '<figure><p>B+ 木に対する各トランザクションは、操作の再実行レコードをまとめたトランザクションレコードを木のログに持ちます。\n'
                'コミット済みのレコードは、ボリューム全体のログに追加されます。</p>\n'
                '<figcaption>図11-89 Minstore の先行書き込みログの構成</figcaption></figure>\n'
                '<p>ReFS はチェックポイントも使い、システムの状態の一部をディスクに確定します。\n'
                'これにより、それまでに書き込んだログレコードの一部が不要になります。\n'
                'トランザクションの影響を受けた木の状態がチェックポイントでディスクに確定すると、そのトランザクションの再実行ログを適用し直す必要はありません。\n'
                'ログエンジンが破棄できるレコードの範囲は、チェックポイントによって決まります。</p>',
 'p2-page-790': '<h5>ReFS の回復機能</h5>\n'
                '<p>ReFS はボリュームを継続して利用できるよう、複数の回復手法を使います。\n'
                'NTFS にも同様の回復機能がありますが、ReFS の目標は、大規模なディスクでは実行に何時間もかかり、OS の再起動も必要になるオフライン検査ツール（NTFS の '
                '<code>Chkdsk</code> など）を不要にすることです。\n'
                'ReFS の主な回復手法は次の4つです。</p>\n'
                '<ul>\n'
                '<li>チェックサムと誤り訂正符号でメタデータの破損を検出します。\n'
                '整合性ストリームは、実際のファイル内容のチェックサムをファイルの B+ テーブルの行に格納します。\n'
                'これによりメタデータに加えてファイルのデータ自体の整合性も検証し、維持します。</li>\n'
                '<li>破損を検出したデータに正常なコピーがあれば、それを使って修復します。\n'
                'オブジェクトテーブルなど重要なメタデータのコピーは ReFS 自身が保持します。\n'
                '本章後半の「記憶域スペース」で説明するボリュームの冗長化によってコピーを利用できる場合もあります。</li>\n'
                '<li>ボリュームをオンラインに保ったまま、破損したデータをファイルシステムの名前空間から取り除く救済処理を行います。</li>\n'
                '<li>失われたメタデータを、残っている情報から可能な限り再構築します。</li>\n'
                '</ul>\n'
                '<p>最初の2つは ReFS の基盤である Minstore が提供する機能です。\n'
                '整合性ストリームについては、この節の後半で説明します。\n'
                'オブジェクトテーブルとボリューム全体で使う Minstore の各 B+ '
                'テーブルでは、別のディスクブロックにある子ノード（探索を案内するノードを含む）へのリンクごとにチェックサムを保持します。\n'
                'ブロックの内容が期待したものと異なる場合、Minstore は利用できる複製から自動修復を試みます。\n'
                '複製がなければ ReFS の上位層にエラーを返し、ReFS はオンラインでの救済処理を開始します。</p>\n'
                '<p><strong>救済処理</strong>（salvage）は、ディレクトリの B+ 木でメタデータの破損を検出した際、できる限り多くのデータを復元するための修復を指します。\n'
                'これは従来の zap 方式を発展させたものです。\n'
                'zap 方式では、破損データの損失を許容してボリュームを再び利用できるようにします。\n'
                '破損したメタデータを名前空間からすべて取り除き、修復が済んだ名前空間を利用可能にします。</p>\n'
                '<p>ディレクトリの B+ 木で探索を案内する中間ノードが破損したとします。\n'
                'zap 処理は、親ノードから子へのリンクを書き直して木のバランスを取り直し、親を修復します。\n'
                'ただし、破損したノードが指していたデータはすべて失われます。\n'
                'Minstore には、そのノードを経由して参照していたエントリを復元するための情報がありません。</p>\n'
                '<p>救済処理でディレクトリ木を復元するには、中間ノードの破損などによりディレクトリテーブル自体にアクセスできなくても、ReFS '
                'がサブディレクトリの識別子を取得できる必要があります。\n'
                'ボリューム全体で使う<strong>親子関係テーブル</strong>はディレクトリの情報を重複して保持し、失われた木の一部を復元できるようにします。\n'
                '親子関係テーブルのキーは親テーブルの ID で、値には子テーブルの ID の一覧が入ります。\n'
                '救済処理はこのテーブルを走査して子テーブルの一覧を読み取り、破損したノードに属していたサブディレクトリをすべて含む、新しい正常な B+ 木を作ります。</p>',
 'p2-page-791': '<p>破損した親ディレクトリを復元するには、もともと親の B+ 木のキーに格納されていた子テーブルの名前も必要です。\n'
                '子テーブルには、自身へのディレクトリリンクを表す自己レコードがあり、そこに名前が記録されています。\n'
                '救済処理は回復した子テーブルを開き、自己レコードを読み取り、親テーブルにディレクトリリンクを挿入し直します。\n'
                'この方法で、破損した中間ノードまたはルートノードの下にあったサブディレクトリをすべて回復できます。\n'
                'そのノードに直接属していたファイルは、この方法では回復できません。</p>\n'
                '<figure><p>図の例では、<code>Foo</code> の下にある <code>Bar</code> を表すルートノードが破損しています。\n'
                '<code>Bar</code> には <code>A.txt</code>、<code>B.txt</code>、サブディレクトリ <code>Subdir1</code> '
                'があり、<code>Subdir1</code> には <code>Important file.doc</code> と <code>Important '
                'file.jpeg</code> があります。\n'
                '救済処理では <code>Subdir1</code> へのリンクを復元するため、<code>Bar</code> '
                '直下の2ファイルだけを失い、ファイルシステムをすばやくオンラインに戻せます。</p>\n'
                '<figcaption>図11-90 zap 処理と救済処理の比較</figcaption></figure>\n'
                '<p>救済処理の完了後、ReFS は残っている情報を使い、失われた情報を可能な限り再構築します。\n'
                'たとえば、ファイル ID とファイルテーブルを別々に並べる照合規則を利用し、他のバケットから情報を読み出して失われたファイル ID を回復できる場合があります。\n'
                'ReFS は修復を速めるため、Minstore のオブジェクトテーブルにも少量の追加情報を格納します。\n'
                'これらの手法があっても、データを失わずに修復できるかどうかは、主にメタデータとストレージスタックの冗長性に依存します。</p>\n'
                '<p>重要なメタデータが破損するまれなケースでは、ReFS がボリュームを読み取り専用でマウントできる場合があります。\n'
                'ただし、コンテナーテーブルとその複製がすべて破損している場合などは、読み取り専用でもマウントできません。\n'
                '破損したテーブルを飛ばしてマウントできる場合、ファイルシステムはアロケーターなどのグローバルテーブルを使わずに済み、ユーザーにはデータを回収する機会が残ります。</p>\n'
                '<p>ReFS はファイルの<strong>整合性ストリーム</strong>もサポートします。\n'
                'チェックサムで、ファイルシステムのメタデータに加え、ファイルのデータ自体の整合性を検証します。\n'
                'ReFS はファイルのエクステントテーブルを構成するランごとのチェックサムを、そのテーブルの行のデータ部分に格納します。\n'
                '整合性ストリームが有効なデータを返す前に、ReFS は読み取ったデータのチェックサムを計算し、ファイルのメタデータに保存された値と比較します。\n'
                '両者が一致しなければ、データは破損しています。</p>\n'
                '<p>ReFS はスクラバー（データ整合性スキャナー）が使う制御コード <code>FSCTL_SCRUB_DATA</code> を提供します。\n'
                'スキャナーは <code>Discan.dll</code> に実装され、タスクスケジューラのタスクとしてシステム起動時と毎週実行されます。\n'
                'スクラバーから制御コードを受け取ると、ReFS ドライバーはボリューム全体の整合性検査を開始し、ブート領域、各グローバル B+ 木、ファイルシステムのメタデータを検査します。</p>',
 'p2-page-792': '<blockquote><p><strong>注記</strong> この節で説明したオンライン救済処理とは別に、Windows 標準の '
                '<code>refsutil.exe</code> が行うオフライン救済処理があります。\n'
                'このツールは、読み取り専用でもマウントできないほどボリュームが破損した場合に使います。このような破損はまれです。\n'
                'オフライン救済処理はボリュームの全クラスターを走査してメタデータページとみられる領域を探し、見つかった情報を組み合わせて可能な限り再構築します。</p></blockquote>\n'
                '<h5>リークの検出</h5>\n'
                '<p><strong>クラスターリーク</strong>とは、割り当て済みと記録されているクラスターを参照するものがない状態です。\n'
                'ReFS では、複数の原因で発生します。\n'
                'ディレクトリの破損を検出すると、オンライン救済処理は破損箇所を切り離して木を再構築し、損失をそのディレクトリの直下にあった一部のファイルに抑えられます。\n'
                'また、木の更新アルゴリズムが Minstore のトランザクションをディスクに書き込む前にシステムがクラッシュすると、ファイル名が失われることがあります。\n'
                'この場合、ファイルのデータはディスクに正しく書き込まれていますが、ReFS にはそのデータを指すメタデータがありません。\n'
                'ファイルを表す B+ テーブルがディスク上に残っていても、その埋め込みテーブルへのリンクは、どのディレクトリの B+ 木にもありません。</p>\n'
                '<p>Windows 標準の <code>refsutil.exe</code> は、ボリューム全体をスキャンし、Minstore '
                'を使って名前空間全体をたどるリーク検出機能を備えています。\n'
                'ツールは、識別用ヘッダーを含む既知のデータ構造を手がかりに、名前空間で見つけた B+ 木を一覧にします。\n'
                '次に Minstore のアロケーターに問い合わせ、その一覧と、アロケーターが有効としている木の一覧を比較します。\n'
                '不一致が見つかると ReFS ドライバーに通知し、ドライバーはリークした木に割り当てられていたクラスターを解放済みとして記録します。</p>\n'
                '<p>ブロック参照カウンターテーブルでもリークが起きることがあります。\n'
                'たとえば、ある行が表すクラスター範囲の参照数が、実際にその範囲を参照するファイルの数より多い場合です。\n'
                'リーク検出ツールは実際の参照数を数え直し、記録を修正できます。</p>\n'
                '<p>リークを正しく検出して修正するには、ツールはオフラインのボリュームを対象にする必要があります。\n'
                'ただし、NTFS のオンラインスキャンと同様に、ボリュームシャドウコピーサービスが提供する対象ボリュームの読み取り専用スナップショットも使えます。</p>',
 'p2-page-793': '<h6>実験\u3000Refsutil で ReFS ボリュームのリークを検出して修復する</h6>\n'
                '<p>Windows 標準の <code>refsutil.exe</code> を使って、ReFS ボリュームのクラスターリークを検出し、修復します。\n'
                '既定では読み取り専用のスナップショットを対象にするので、ボリュームをアンマウントする必要はありません。\n'
                '検出したリークを修復する場合は、コマンドラインに <code>/x</code> を指定してこの既定の動作を変更します。\n'
                '管理者としてコマンドプロンプトを開き、次のコマンドを入力します。\n'
                'この例では1 TBの ReFS ボリュームを E: にマウントしています。<code>/v</code> は詳細な出力を有効にします。</p>\n'
                '<pre><code>C:&#92;&gt;refsutil leak /v e:\n'
                'ドライブ &#92;&#92;?&#92;Volume{92aa4440-51de-4566-8c00-bc73e0671b92} のスナップショットを作成しています...\n'
                '作業用ファイルを作成しています...\n'
                'ボリュームのスキャンを開始します。時間がかかる場合があります...\n'
                '\n'
                'リーク検査パス1（クラスターリーク）を開始します...\n'
                'パス1が完了しました。ボリューム上のリークしたクラスターは0個です。\n'
                '\n'
                'リーク検査パス2（参照数のリーク）を開始します...\n'
                'パス2が完了しました。ボリューム上のリークした参照は0件です。\n'
                '\n'
                'リーク検査パス3（コンパクション済みクラスターのリーク）を開始します...\n'
                'パス3が完了しました。\n'
                '\n'
                'リーク検査パス4（残りのクラスターリーク）を開始します...\n'
                'パス4が完了しました。このパスで修復したリークは0件です。\n'
                '\n'
                '完了。\n'
                '検出したクラスターリーク: 0\n'
                '検出した参照のリーク: 0\n'
                '修復したクラスターの総数: 0</code></pre>\n'
                '<h5>瓦記録方式（SMR）のボリューム</h5>\n'
                '<p>本書の執筆時点で、従来の回転式ハードディスクが直面する大きな課題の一つは、磁気記録の物理的な制約です。\n'
                '容量を増やすにはプラッターの面記録密度を高める必要があり、小さな記録単位を読み書きするにつれてヘッドも小型化します。\n'
                'その結果、ビットの反転に必要なエネルギーの障壁が下がり、周囲の熱エネルギーによって意図せずビットが反転しやすくなり、データの整合性が損なわれます。\n'
                'SSD は広く普及していますが、大規模ストレージサーバーでは低コストでさらに多くの容量を必要とするため、回転式ディスクも引き続き使われます。</p>\n'
                '<p>この問題への対策の一つが、図11-91に示す<strong>瓦記録方式</strong>（SMR）です。\n'
                '平行なトラックを使う垂直磁気記録方式（PMR）と異なり、SMR ディスクでは読み取りヘッドが書き込みヘッドより小さくなっています。\n'
                '大きな書き込みヘッドを使えば、読み取りやすさや安定性を損なわず、記録媒体をより効果的に磁化して書き込めます。</p>',
 'p2-page-794': '<figure><p>トラック N、N＋1、N＋2、N＋3 は瓦のように一部が重なります。\n'
                '書き込みヘッドは隣のトラックにもかかりますが、読み取りヘッドは各トラックの残った部分を読み取れる幅です。</p>\n'
                '<figcaption>図11-91 SMR ディスクでは、書き込みヘッドが記録する幅は読み取りヘッドが読む幅より広い</figcaption></figure>\n'
                '<p>この配置では、あるトラックに書き込むと、直後のトラックのデータも一部書き換わります。\n'
                'この問題に対処するため、SMR ディスクはドライブを<strong>バンド</strong>と呼ばれるゾーンに分けます。\n'
                'ゾーンには主に2種類あります。</p>\n'
                '<ul>\n'
                '<li><strong>従来型ゾーン（高速ゾーン）</strong>は、従来の PMR ディスクと同様、ランダム書き込みが可能です。</li>\n'
                '<li><strong>書き込みポインター付きゾーン</strong>は、バンドごとに書き込み位置を示すポインターを持ち、原則として順次書き込みが必要です。\n'
                'ただし、ホスト認識型 SMR ディスクには、順次書き込みを推奨しつつランダム書き込みも許すゾーンがあります。\n'
                'ReFS はこの種のゾーンを使いません。</li>\n'
                '</ul>\n'
                '<p>SMR ディスクのバンドは通常256 MBで、I/O の基本単位です。\n'
                'あるバンドに書き込んでも、次のバンドには影響しません。\n'
                'SMR ディスクには次の3種類があります。</p>\n'
                '<ul>\n'
                '<li><strong>ドライブ管理型</strong>は、ホストから見ると瓦記録を使わないドライブと同じです。\n'
                'データ、ゾーン、順次書き込みの制約はデバイスのファームウェアが管理するため、ホストは特別なプロトコルに従う必要がありません。\n'
                '互換性は高いものの、ランダム書き込みを順次書き込みに変換するディスクキャッシュの容量は限られ、バンドの整理と順次書き込みの検出も複雑です。\n'
                'これらの制約が性能に影響します。</li>\n'
                '<li><strong>ホスト管理型</strong>は、ホストに専用の I/O 規則を厳格に守るよう要求します。\n'
                '既存データを破壊しないよう、ホストは順次書き込みを行います。\n'
                'ドライブは規則に違反するコマンドの実行を拒否します。\n'
                'この種のドライブが対応するのは、順次書き込みゾーンと従来型ゾーンです。\n'
                '従来型ゾーンには非 SMR メディア、ドライブ管理型 SMR、フラッシュなどを使えます。</li>\n'
                '<li><strong>ホスト認識型</strong>は、ドライブ管理型とホスト管理型の特徴を併せ持ちます。\n'
                'ドライブが瓦記録を管理し、ホストからのコマンドを、順次アクセスかどうかにかかわらず実行します。\n'
                'ホストはドライブが瓦記録方式であることを認識し、ゾーンの情報を問い合わせられます。\n'
                'そのため、互換性を保ちつつ、ホストは瓦記録に合わせて書き込みを最適化できます。\n'
                'ホスト認識型は順次書き込み優先ゾーンに対応します。</li>\n'
                '</ul>\n'
                '<p>本書の執筆時点で、ホスト管理型 SMR ディスクを標準で扱えるファイルシステムは ReFS だけです。\n'
                'こうしたドライブは20 TB以上の大容量にできます。\n'
                'ReFS は、通常は記憶域スペースで作る階層化ボリュームと同じ方式でこれらのドライブに対応します。\n'
                '記憶域スペースについては本章の最後の節を参照してください。</p>',
 'p2-page-795': '<h5>ReFS の階層化ボリュームと SMR のサポート</h5>\n'
                '<p>階層化ボリュームはホスト認識型 SMR ディスクと似ています。\n'
                '典型的な構成では、SSD などを使う高速なランダムアクセス領域と、より低速な順次書き込み領域を組み合わせます。\n'
                'ただし、この組み合わせは必須ではありません。\n'
                '異なるランダムアクセスディスクだけで階層を構成でき、各ディスクが同じ速度でもかまいません。</p>\n'
                '<p>ReFS は、ファイルとディレクトリの名前空間と、その下にあるボリュームの名前空間の間に論理的な間接層を設け、階層化ボリュームと SMR ディスクを管理します。\n'
                'この層はボリュームを重なり合わない論理コンテナーに分けます。\n'
                'したがって、1つのクラスターが同時に属するコンテナーは1つだけです。\n'
                '各コンテナーはボリューム内の領域を表し、同じボリュームではすべてのコンテナーが同じ大きさです。\n'
                '大きさは基盤ディスクの種類で決まり、標準的な階層化ディスクでは64 MB、SMR ディスクでは256 MBです。\n'
                'SMR ディスクではコンテナーと SMR バンドの大きさが一致し、1対1で対応するため、コンテナーを<strong>ReFS バンド</strong>と呼びます。</p>\n'
                '<p>図11-92に示すように、この間接層はボリューム全体で使う<strong>コンテナーテーブル</strong>で構成されます。\n'
                '各行のキーはコンテナーの ID と種類を保持します。\n'
                '行の値は、圧縮整理済み、データ圧縮済みなど、コンテナーの種類によって異なります。\n'
                '圧縮整理されていないコンテナーの場合、行の値には、そのコンテナーが指すクラスター範囲への対応を記録したデータ構造が入ります。\n'
                '圧縮整理については次節を参照してください。\n'
                'この対応によって、ReFS は仮想 LCN を実 LCN に変換できます。</p>\n'
                '<figure>\n'
                '<p>ファイルのエクステントテーブル（B+ 木）は、クラスターに分割されたバンドを仮想 LCN で参照します。\n'
                'コンテナーテーブルのキーはバンドの ID と種類（図の例では ID 194〜197、種類は <code>Base</code>）です。\n'
                '値には実 LCN が入り、図には '
                '<code>0x12E400</code>、<code>0x12E800</code>、<code>0x12F000</code>、<code>0x12EC00</code> '
                'が示されています。</p>\n'
                '<figcaption>図11-92 コンテナーテーブルで仮想 LCN を実 LCN に変換する</figcaption></figure>\n'
                '<p>ごく一部を除き、ReFS と Minstore が管理するすべてのデータへのアクセスはコンテナーテーブルを経由します。\n'
                'そのため、ReFS はこのテーブルのコピーを複数保持します。\n'
                'ブロックに対して I/O を行うとき、ReFS はまず、対象のエクステントが属するコンテナーの位置を調べます。</p>',
 'p2-page-796': '<p>データの実際の格納位置を求めるには、まずエクステントテーブルの行の値から、対象のクラスター範囲の仮想 LCN を取得します。\n'
                'ReFS はその LCN から計算でコンテナー ID を求め、コンテナーの位置を調べます。\n'
                'この間接層があるため、ファイルのエクステントテーブルを参照したり更新したりせずに、コンテナーの格納位置を変更できます。</p>\n'
                '<p>ReFS は、記憶域スペースが作る階層、ハードウェアが提供する階層化ボリューム、SMR ディスクの階層を利用します。\n'
                '小さなランダム I/O を高速層の一部に振り分け、書き込みをまとめて、低速層へコンテナー単位で順次書き込みします。\n'
                'ReFS でいう<strong>高速層</strong>（フラッシュ層）はランダムアクセス領域を指し、SMR ディスクの従来型バンドや SSD、NVMe '
                'デバイス全体で構成できます。\n'
                '<strong>低速層</strong>（HDD 層）は順次書き込み用バンドや回転式ディスクを指します。\n'
                'ReFS の動作は基盤メディアの種類によって異なります。\n'
                '非 SMR ディスクには順次書き込みの制約がないため、ボリューム内のどこからでもクラスターを割り当てられます。\n'
                'SMR ディスクでは前述のように厳密に順次書き込みを行う必要があるため、ReFS は低速層にランダム書き込みを行いません。</p>\n'
                '<p>既定では、ReFS が使うメタデータはすべて高速層に置き、通常の書き込み要求にも高速層を使おうとします。\n'
                '非 SMR ディスクでは、フラッシュ上のコンテナーが埋まると、ReFS はコンテナーをフラッシュから HDD に移します。\n'
                '書き込みが続く負荷では、この移動も継続します。\n'
                '必要に応じて逆方向にも移動できます。\n'
                'HDD 上のコンテナーを選んでフラッシュに移し、以後の書き込みに使います。\n'
                'この機能を<strong>コンテナーローテーション</strong>と呼び、2段階で実行します。\n'
                'まずストレージドライバーが実データをコピーし、その後 ReFS がコンテナーの LCN の対応を更新します。\n'
                '各ファイルのエクステントテーブルは変更する必要がありません。</p>\n'
                '<p>コンテナーローテーションは非 SMR ディスクに限られます。\n'
                'SMR ディスクでは、ReFS ドライバーはデータを階層間で自動的に移しません。\n'
                'SMR を認識するアプリケーションが SMR の容量層にデータを書き込むには、ファイルハンドルに対して '
                '<code>FSCTL_SET_REFS_FILE_STRICTLY_SEQUENTIAL</code> を発行します。\n'
                '以後、ReFS ドライバーはそのファイルへの新しいデータをすべてボリュームの容量層に書き込みます。</p>\n'
                '<h6>実験\u3000SMR ディスクの階層を確認する</h6>\n'
                '<p>Windows 標準の Fsutil で、SMR ディスクの各階層の大きさ、利用可能な領域や空き領域などを照会できます。\n'
                '管理者としてコマンドプロンプトを開きます。\n'
                '原文の例では Cortana の検索ボックスで <code>cmd</code> を検索し、「コマンド プロンプト」を右クリックして「管理者として実行」を選びます。\n'
                '次のコマンドの <code>&lt;VolumeDrive&gt;</code> を SMR ディスクのドライブ文字に置き換えて実行します。</p>\n'
                '<pre><code>fsutil volume smrInfo &lt;VolumeDrive&gt;</code></pre>',
 'p2-page-797': '<figure><img loading="lazy" width="649" height="276" '
                'src="assets/1cb47d895bd4f7fc32255b7d.webp" alt="Fsutil で照会した SMR ボリュームの階層情報"></figure>\n'
                '<p>次のコマンドで、不要になった領域を回収するガベージコレクションを開始することもできます。仕組みは次節で説明します。</p>\n'
                '<pre><code>fsutil volume smrGc &lt;VolumeDrive&gt; Action=startfullspeed</code></pre>\n'
                '<p><code>Action</code> に対応する値を指定すると、ガベージコレクションを停止または一時停止できます。\n'
                'I/O の粒度を指定して実行するには、<code>IoGranularity</code> パラメーターを指定し、<code>startfullspeed</code> の代わりに '
                '<code>start</code> を使います。</p>\n'
                '<h5>コンテナーの圧縮整理</h5>\n'
                '<p>コンテナーローテーションは、とくに1バンドを使い切らない小さなファイルを格納する場合に性能上の問題があります。\n'
                '前述のとおり、SMR ディスクではコンテナーローテーション自体を行いません。\n'
                '各 SMR バンドにはハードウェアが管理する書き込みポインターがあり、次に順次書き込みを行う位置を示します。\n'
                'ポインターが指す位置を飛び越えたり、その手前に戻ったりして書き込むと、別のクラスターのデータを破損させるため、SMR のファームウェアはそのような書き込みを拒否します。</p>\n'
                '<p>ReFS は2種類のコンテナーを使います。\n'
                '<strong>ベースコンテナー</strong>は仮想クラスターの範囲を物理領域に直接対応付けます。\n'
                '<strong>圧縮整理済みコンテナー</strong>は1つの仮想コンテナーを複数のベースコンテナーに対応付けます。\n'
                'ReFS は、圧縮整理済みコンテナーが指す領域と、それを構成するベースコンテナーとの対応を管理するため、割り当てビットマップを使います。\n'
                'ビットマップは、圧縮整理済みコンテナー1つにつき1行を持つ、ボリューム全体のコンテナーインデックステーブルに格納します。\n'
                '対応するクラスターが割り当て済みならビットは1、未割り当てなら0です。</p>\n'
                '<p>図11-93では、ベースコンテナー C32 が仮想 LCN の範囲 <code>0x8000</code>〜<code>0x8400</code> を、R46 '
                'で示したボリューム上の実 LCN の範囲 <code>0xB800</code>〜<code>0xBC00</code> に対応付けています。\n'
                '前述のように、ある仮想 LCN 範囲のコンテナー ID は、先頭の仮想クラスター番号から計算します。</p>',
 'p2-page-798': '<p>すべてのコンテナーは仮想アドレス空間上で連続しているため、ReFS は仮想範囲に対応するコンテナー ID を検索せず、計算で求められます。\n'
                '図11-93のコンテナー C32 では、1,024クラスターのうち560クラスター（<code>0x230</code>）だけを連続して割り当てています。\n'
                '通常、ReFS が使えるのはベースコンテナーの末尾にある空き領域です。\n'
                '非 SMR ディスクでは、ベースコンテナーの途中で大きな領域が解放された場合、その領域も再利用できます。\n'
                '非 SMR ディスクでも、再利用する領域は連続している必要があります。</p>\n'
                '<p>小さなファイルのエクステントが解放されるなどしてコンテナーが断片化すると、ReFS はベースコンテナーを圧縮整理済みコンテナーに変換できます。\n'
                'これにより、そのコンテナーのクラスターを使うファイルのエクステントテーブルの行を割り当て直さずに、コンテナー内の空き領域を再利用できます。</p>\n'
                '<figure>\n'
                '<p>クラスターサイズは64 KB、ボリュームサイズは1 TB（<code>0x1000000</code> クラスター）です。\n'
                'コンテナーは1つあたり64 MB（<code>0x400</code> クラスター）です。\n'
                'コンテナーテーブルのキーは ID 32 と種類 <code>Base</code>、値は割り当て済みの <code>0x230</code> クラスターと実 LCN 範囲 '
                '<code>0xB800</code>〜<code>0xBC00</code> です。\n'
                '図では仮想 LCN 範囲 <code>0x8000</code>〜<code>0x8400</code> の C32 が、実 LCN 範囲の R46 に対応します。</p>\n'
                '<table><caption>ファイルのエクステントテーブル</caption>\n'
                '<thead><tr><th>VCN 範囲</th><th>LCN</th><th>コンテナー ID</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td><code>0–0x400</code></td><td><code>0x18400</code></td><td>97</td></tr>\n'
                '<tr><td><code>0x400–0x800</code></td><td><code>0x32000</code></td><td>200</td></tr>\n'
                '<tr><td><code>0x800–0xA00</code></td><td><code>0x61E00</code></td><td>391</td></tr>\n'
                '<tr><td><code>0xA00–0xC00</code></td><td><code>0x11200</code></td><td>68</td></tr>\n'
                '<tr><td><code>0xC00–0xD20</code></td><td><code>0x8110</code></td><td>32</td></tr>\n'
                '</tbody></table>\n'
                '<p>図に示したファイル内の位置の目盛りは、0、64 MB、128 MB、192 MB、210 MB です。</p>\n'
                '<figcaption>図11-93 210 MBのファイルが参照するベースコンテナーの例。C32 は64 MBの領域のうち35 '
                'MBだけを使用しています。</figcaption></figure>\n'
                '<p>ReFS は断片化したコンテナーを整理できます。\n'
                '通常のシステム I/O では、小さなファイルやデータの断片を作成、更新することが多く、低速層のコンテナーには小さな空き領域が散在して、すぐに断片化することがあります。\n'
                '<strong>コンテナーの圧縮整理</strong>は、低速層に新しい空のバンドを作り、コンテナーの断片化を解消します。\n'
                '圧縮整理は階層化ボリュームの容量層だけで実行し、次のページで説明する2つの目的があります。</p>',
 'p2-page-799': '<ul>\n'
                '<li><strong>SMR ディスクの空き領域回収</strong>。ReFS が SMR の容量層で行えるのは順次書き込みだけです。\n'
                '低速層のコンテナーにある小さなデータだけを、その場で更新することはできません。\n'
                'データの位置は SMR の書き込みポインターが指す位置とは異なり、そこへ書き込むと同じバンド内の別のデータを破損させるおそれがあるためです。\n'
                'この場合、データを新しいバンドにコピーします。\n'
                '非 SMR ディスクにはこの制約がなく、ReFS は低速層のデータをその場で更新できます。</li>\n'
                '<li><strong>非 SMR '
                'の階層化ボリュームで、ローテーションの移動先を確保する</strong>。圧縮整理で空いたコンテナーは、高速層から低速層へデータを移す際の移動先として使えます。</li>\n'
                '</ul>\n'
                '<p>ReFS はボリュームをフォーマットする際、容量層から圧縮整理専用のベースコンテナーをいくつか確保します。\n'
                'これらを<strong>圧縮整理用の予約コンテナー</strong>と呼びます。\n'
                '圧縮整理は、まず低速層で断片化したコンテナーを探します。\n'
                'ReFS はコンテナーをシステムメモリに読み込み、使用中のデータを詰め直し、容量層の予約コンテナーに格納します。\n'
                'ファイルのエクステントテーブルが参照する元のコンテナーは、圧縮整理済みコンテナーになります。\n'
                'その範囲は仮想化され、追加の間接層を通じて、別のベースコンテナー（予約コンテナー）が記述する仮想 LCN を指します。\n'
                '圧縮整理の完了後、元の物理コンテナーは解放済みとして記録され、別の用途に再利用されます。\n'
                '新しい予約コンテナーとしても使えます。\n'
                '低速層のコンテナーは比較的短時間で断片化が進むため、圧縮整理によって低速層に多数の空きバンドを作れます。</p>\n'
                '<p>圧縮整理済みコンテナーが割り当てるクラスターは、複数のベースコンテナーに分かれて格納されることがあります。\n'
                'ReFS はコンテナーインデックステーブルと圧縮整理済みコンテナー専用の配置を使い、もう一段の間接層でこれを管理します。\n'
                '図11-94は、図11-93のコンテナーで560クラスターのうち272クラスターが解放され、断片化したために圧縮整理された例です。\n'
                'コンテナーテーブルの行には、圧縮整理済みコンテナーが表すクラスター範囲と、ベースコンテナーが表す仮想クラスターとの対応を格納します。\n'
                '圧縮整理済みコンテナーは、レッグと呼ばれる範囲を最大4つ持てます。\n'
                'この4つのレッグが第2の間接層を構成し、コンテナーの断片化を効率よく解消できるようにします。\n'
                '割り当てビットマップもこの間接層の一部です。\n'
                'ReFS はビットマップで1になっている位置を調べ、圧縮整理済みコンテナー内の各クラスターを正しい格納先に対応付けます。</p>\n'
                '<p>図11-94の例では、最初に1が立っている位置は17（16進数で <code>0x11</code>）です。\n'
                '図では1ビットが16クラスターに対応しますが、実装では1ビットにつき1クラスターです。\n'
                'この例で圧縮整理済みコンテナー C32 のオフセット <code>0x110</code> にある最初の割り当て済みクラスターは、ベースコンテナー C124 内の仮想クラスター '
                '<code>0x1F2E0</code> に格納されます。\n'
                'C32 のオフセット <code>0x230</code> より後ろの空き領域は、ベースコンテナー C56 に対応します。\n'
                'ReFS は物理コンテナー R46 を再マッピングし、ベースコンテナー C180 が参照する空の予約コンテナーに変更しました。</p>',
 'p2-page-800': '<figure>\n'
                '<table><thead><tr><th>コンテナー</th><th>仮想 LCN 範囲</th><th>コンテナーテーブルの内容</th></tr></thead>\n'
                '<tbody>\n'
                '<tr><td>C32（圧縮整理済み）</td><td><code>0x8000–0x8400</code></td><td>ID 32。レッグ1は '
                '<code>0x1F2E0–0x1F400</code>、レッグ2は <code>0x1C400–0x1C6F0</code>。</td></tr>\n'
                '<tr><td>C124（ベース）</td><td><code>0x1F000–0x1F400</code></td><td>ID 124。割り当て済みは '
                '<code>0x400</code> クラスター。実 LCN は R201 の <code>0x32400–0x32800</code>。</td></tr>\n'
                '<tr><td>C56（ベース）</td><td><code>0x1C400–0x1C800</code></td><td>ID 56。割り当て済みは '
                '<code>0x2F0</code> クラスター。実 LCN は R11 の <code>0x2C00–0x3000</code>。</td></tr>\n'
                '<tr><td>C180</td><td><code>0x2D000–0x2D400</code></td><td>実 LCN は R46 の '
                '<code>0xB800–0xBC00</code>。</td></tr>\n'
                '</tbody></table>\n'
                '<p>コンテナーインデックステーブルの C32 のエントリは、キーに ID 32 と圧縮整理済みの種類を持ち、値に割り当てビットマップ <code>0000000000000000 '
                '0111111111111000 00000…</code> を持ちます。\n'
                'この図では1ビットが16クラスターに対応します。</p>\n'
                '<figcaption>図11-94 コンテナー C32 のデータをベースコンテナー C124 と C56 に整理した例</figcaption></figure>\n'
                '<p>SMR ディスクで圧縮整理を開始する処理を、ガベージコレクションと呼びます。\n'
                'アプリケーションはファイルシステム制御コード <code>FSCTL_SET_REFS_SMR_VOLUME_GC_PARAMETERS</code> '
                'で、いつでも手動で開始、停止、一時停止できます。</p>\n'
                '<p>非 SMR ディスクでは、NTFS と異なり、ReFS のボリューム分析エンジンがコンテナーの圧縮整理を自動で開始できます。\n'
                'ReFS は低速層と高速層の空き容量に加え、低速層で書き込みに利用できる空き容量を追跡します。\n'
                '低速層の空き容量と書き込みに利用できる容量の差がしきい値を超えると、ボリューム分析エンジンが圧縮整理を開始します。\n'
                '基盤ストレージを記憶域スペースが提供している場合は、専用のスレッドが定期的に圧縮整理を実行します。</p>\n'
                '<h5>圧縮とゴースト化</h5>\n'
                '<p>ReFS はファイル単位のネイティブな圧縮を提供しませんが、階層化ボリュームではコンテナーを圧縮して、低速層の空きコンテナーを増やせます。\n'
                'ReFS は圧縮整理を行うたびに、断片化したベースコンテナーの元データをメモリに読み込みます。\n'
                '圧縮が有効であれば、そこでデータを圧縮し、データ圧縮済みのコンテナーに書き込みます。\n'
                '対応する圧縮アルゴリズムは LZNT1、LZX、XPRESS、XPRESS_HUFF の4種類です。</p>\n'
                '<p>多くの階層型ストレージ管理（HSM）ソフトウェアは、ファイルを<strong>ゴースト化</strong>する機能を備えています。\n'
                'たとえば HSM がユーザーのファイル全体または一部をクラウドサービスへ移した後、ユーザーが別のデバイスからクラウド上のコピーを変更したとします。\n'
                'このとき HSM のフィルタードライバーは、ファイルのどの部分が変更されたかを追跡し、変更された範囲をゴースト化済みとして記録する必要があります。\n'
                '通常、HSM はフィルタードライバーでこの状態を管理します。\n'
                'ReFS では、フィルタードライバーが <code>FSCTL_GHOST_FILE_EXTENTS</code> を ReFS '
                'ドライバーに送信し、ファイルの指定範囲をゴースト化済みとして設定できます。\n'
                'ゴースト化済みの範囲は、別の制御コード <code>FSCTL_QUERY_GHOSTED_FILE_EXTENTS</code> で照会できます。</p>',
 'p2-page-801': '<p>ReFS は、ゴースト化の状態をファイルのエクステントテーブルに直接記録します。\n'
                '前節で説明したとおり、エクステントテーブルはファイルレコードに埋め込まれたテーブルです。\n'
                'フィルタードライバーは、境界をクラスターにそろえた任意のファイル範囲をゴースト化できます。\n'
                'ReFS ドライバーがゴースト化済みのエクステントに対する読み取り要求を受け取ると、呼び出し元に <code>STATUS_GHOSTED</code> エラーを返します。\n'
                'フィルタードライバーはこのエラーを捕捉し、先ほどの例でいうクラウドなど、データがある場所へ読み取りを振り向けます。</p>\n'
                '<h3>記憶域スペース</h3>\n'
                '<p><strong>記憶域スペース</strong>（Storage Spaces）は、ダイナミックディスクに代わって物理ストレージハードウェアを仮想化する技術です。\n'
                'もともとは大規模なストレージサーバー向けに設計されましたが、Windows 10のクライアントエディションでも利用できます。\n'
                '性能が異なる複数種類の物理メディアを組み合わせ、仮想ディスクを作ることもできます。</p>\n'
                '<p>本書の執筆時点では、NVMe フラッシュディスク、永続メモリ（PM）、SATA または SAS の SSD、従来の回転式ハードディスク（HDD）を扱えます。\n'
                'この分類では NVMe が最も高速で、HDD が最も低速です。\n'
                '記憶域スペースには4つの設計目標があります。</p>\n'
                '<ul>\n'
                '<li><strong>性能</strong>。サーバー側にキャッシュを内蔵し、ストレージの性能を引き出します。\n'
                '階層化ディスクと RAID 0 構成もサポートします。</li>\n'
                '<li><strong>信頼性</strong>。原文がスパンボリュームと呼ぶ RAID 0 '
                'に加え、データを複数の物理ディスクやクラスターの複数ノードへ分散する場合は、ミラー（RAID 1、10）とパリティ（RAID 5、6、50、60）の構成をサポートします。</li>\n'
                '<li><strong>柔軟性</strong>。仮想ディスクをクラスターノード間で自動的に移動したり、実際の容量使用量に応じて自動的に縮小または拡張したりできます。</li>\n'
                '<li><strong>可用性</strong>。記憶域スペースのボリュームは耐障害性を備えます。\n'
                'ドライブや、クラスターを構成するサーバー全体に障害が起きても、ユーザーの介入なしに動作中の別のノードへ I/O を振り向けられます。\n'
                '単一障害点がありません。</li>\n'
                '</ul>\n'
                '<p><strong>記憶域スペースダイレクト</strong>（Storage Spaces Direct）は記憶域スペースを発展させた技術です。\n'
                '性能の異なるディスクを搭載した複数のサーバーで、ストレージプールを作る大規模データセンター向けに設計されています。\n'
                '従来の技術では、JBOD ディスクアレイに接続していないサーバーで構成したクラスターに対応していなかったため、名称に「ダイレクト」が加わりました。\n'
                'すべてのサーバーを、10 GbE や40 GbE などの高速 Ethernet で接続します。\n'
                'リモートのディスクをローカルディスクとして認識させるのは、クラスターミニポートドライバー（<code>Clusport.sys</code>）とクラスターブロックフィルタードライバー（<code>Clusbflt.sys</code>）です。\n'
                '両ドライバーの詳細は本章の範囲外です。\n'
                'ローカルとリモートの物理ディスクはすべて<strong>ストレージプール</strong>に追加します。\n'
                'プールは管理、集約、分離の基本単位であり、プールから仮想ディスクを作れます。</p>\n'
                '<p>記憶域スペースは内部で <code>BluePrint</code> という XML ファイルを使い、ストレージクラスター全体の構成を管理します。\n'
                'このファイルは記憶域スペースの GUI が自動で生成し、クラスター全体の構成要素を木構造で記述します。</p>',
 'p2-page-802': '<p><code>BluePrint</code> で表すストレージ構成要素は、ラック、シャーシ、マシン、JBOD（Just a Bunch of Disks）、ディスクです。\n'
                'これらがクラスターの各階層を構成します。\n'
                'サーバーには複数の JBOD を接続でき、複数のディスクを直接接続することもできます。\n'
                'JBOD はその内部構成を抽象化し、1つの構成要素として表します。\n'
                '同様に、1つのシャーシに複数のマシンが収まり、そのシャーシがサーバーラックに収まることがあります。\n'
                'クラスターは複数のサーバーラックで構成することもできます。\n'
                '記憶域スペースはこの構成情報を使ってクラスター内のすべてのディスクを扱い、ディスク、JBOD、マシンのいずれかに障害が起きた場合は、適切な代替先へ I/O を振り向けます。\n'
                '記憶域スペースダイレクトは、同時に発生した最大2件の障害に耐えられます。</p>\n'
                '<h4>記憶域スペースの内部構成</h4>\n'
                '<p>記憶域スペースとダイナミックディスクの大きな違いの一つは、記憶域スペースが仮想ディスクオブジェクトを作ることです。\n'
                '記憶域スペースのストレージドライバー（<code>Spaceport.sys</code>）は、仮想ディスクを通常のディスクデバイスオブジェクトとしてシステムに公開します。\n'
                'ダイナミックディスクは、より上位の層で仮想ボリュームオブジェクトをシステムに公開します。\n'
                'そのため、ユーザーモードのアプリケーションは元のディスクに引き続きアクセスできます。\n'
                '複数のダイナミックボリュームから1つのボリュームを作成するのはボリュームマネージャーです。\n'
                '記憶域スペースのドライバーはミニフィルターではなく、パーティションマネージャー（<code>Partmgr.sys</code>）とディスククラスドライバーの間にあるフィルタードライバーです。</p>\n'
                '<p>図11-95のように、記憶域スペースは主に、プラットフォームに依存しない中核ライブラリと、実行環境に合わせて中核をシステムにつなぐ環境層で構成されます。\n'
                '環境層は、プラットフォームごとに異なる方法で実装された基本機能を、中核ライブラリに提供します。\n'
                '記憶域スペースを起動に使えるようにするには、Windows のブートローダーとブートマネージャーがその構造を解析できる必要があります。\n'
                'そのため、UEFI と Windows の両方に実装があります。</p>\n'
                '<p>環境層の基本機能には、メモリの割り当て、解放、ロック、ロック解除などのメモリ管理、制御、PnP、読み書きなどのデバイス I/O、および同期処理があります。\n'
                'これらは通常、各システム固有のルーチンを呼び出します。\n'
                'たとえば Windows では、読み取りのために <code>IRP_MJ_READ</code> 型の IRP を作って対象のディスクドライバーに送ります。\n'
                'UEFI では <code>BLOCK_IO_PROTOCOL</code> を使います。</p>\n'
                '<figure><p><code>Spaceport.sys</code> の中核ライブラリには、中核処理、格納、メタデータ、I/O の機能があります。\n'
                '環境層はメモリ管理、デバイス I/O、同期の機能を提供します。</p>\n'
                '<figcaption>図11-95 記憶域スペースのアーキテクチャ</figcaption></figure>',
 'p2-page-803': '<p>記憶域スペースは、起動時や Windows カーネル内に加え、クラッシュダンプの作成時にも利用できる必要があります。\n'
                'クラッシュダンプ用のフィルタードライバー <code>Spacedump.sys</code> がこの機能を提供します。\n'
                '古い Windows で記憶域スペースが作った仮想ディスク（特に VHD ファイル）を扱う場合は、ユーザーモードライブラリ <code>Backspace.dll</code> '
                'を使えます。\n'
                'EFI システムパーティション自体が記憶域スペース上にある場合は、UEFI BIOS が UEFI DXE ドライバーの <code>HyperSpace.efi</code> '
                'を実行できます。\n'
                '一部の新しい Surface では、1台の大容量 SSD として販売されているストレージが、実際には2台以上の高速な NVMe ディスクで構成されています。</p>\n'
                '<p>記憶域スペースの中核はプラットフォームに依存しない静的ライブラリで、どの環境層もこれを取り込みます。\n'
                'ライブラリは4つの層で構成されます。\n'
                '最上位の Core は記憶域スペースが提供するすべてのサービスを実装します。\n'
                'Store は <code>BluePrint</code> ファイルから構築したクラスターデータベースのレコードを読み書きします。\n'
                'Metadata は Store '
                'が読み込んだバイナリレコードを解釈し、データベース全体をプール、ドライブ、スペース、エクステント、列、階層、メタデータの各オブジェクトとして公開します。\n'
                '最下位の I/O 層は、上位層が解析したデータを使って、適切な順序でクラスター内の対象デバイスへ I/O を発行します。</p>\n'
                '<h4>記憶域スペースが提供するサービス</h4>\n'
                '<p>記憶域スペースはさまざまなディスク構成をサポートします。\n'
                '高速なディスク（SSD、NVMe、永続メモリ）のみ、低速なディスクのみ、または対応する4種類すべてを組み合わせた仮想ディスクを作れます。\n'
                '複数種類のデバイスを組み合わせる構成では、クラスターの性能と効率を高めるために次の2つの機能を使えます。</p>\n'
                '<ul>\n'
                '<li><strong>サーバーキャッシュ</strong>。高速ドライブをクラスターから隠し、低速ドライブのキャッシュとして使えます。\n'
                '永続メモリは NVMe や SSD の、NVMe は SSD の、SSD は回転式 HDD のキャッシュにできます。\n'
                'このキャッシュは階層化ディスクと違い、仮想ボリューム上のファイルシステムには見えません。\n'
                'キャッシュ側は、どのファイルが直近にアクセスされたかをファイル単位では把握できません。\n'
                '記憶域スペースは仮想ディスクのブロックごとのアクセス頻度をログで追跡します。\n'
                '頻繁にアクセスするファイルのエクステントはホットブロック、ほとんどアクセスしないものはコールドブロックです。\n'
                'ログはキャッシュをキューとして管理し、ホットブロックを先頭に、コールドブロックを末尾に置きます。\n'
                'キャッシュが満杯になれば、コールドブロックをキャッシュから取り除き、低速なストレージにだけ残せます。\n'
                'ホットブロックは通常、より長くキャッシュに残ります。</li>\n'
                '<li><strong>階層化</strong>。記憶域スペースは、ReFS や NTFS が管理する階層化ディスクを作れます。\n'
                'ReFS は SMR ディスクにも対応しますが、NTFS の階層化ディスクのサポートは記憶域スペースが提供するものに限られます。\n'
                'ファイルシステムはホットブロックとコールドブロックを追跡し、ファイルの使用状況に応じてバンドを階層間で移動します。\n'
                '詳しくは本章前半の「ReFS の階層化ボリュームと SMR のサポート」を参照してください。\n'
                '記憶域スペースは、ファイルを高速層に固定するピン留め機能も提供します。\n'
                'ピン留めを解除するまでファイルは高速層に保持され、その間はバンドを別の階層へ移しません。\n'
                'Windows は OS のアップグレード時にこの機能を使い、新しいファイルを高速層に保存します。</li>\n'
                '</ul>\n'
                '<p>前述のとおり、柔軟性は記憶域スペースの主な目標の一つです。\n'
                '記憶域スペースでは、拡張可能で、割り当てた分だけ物理領域を使う仮想ディスクを作れます。</p>',
 'p2-page-804': '<p>クラスターの物理デバイスから、実際に使う分だけ領域を確保する仮想ディスクを<strong>シンプロビジョニング</strong>のディスクと呼びます。\n'
                '固定プロビジョニングでは指定した全容量を基盤のストレージクラスターから確保します。\n'
                'シンプロビジョニングでは実際に使われる領域だけを割り当てるため、物理クラスターよりはるかに大きな仮想ディスクも作れます。\n'
                '空き容量が少なくなれば、管理者はクラスターにディスクを動的に追加できます。\n'
                '記憶域スペースは、新しい物理ディスクを自動的にプールに加え、新しいディスクも含めて割り当て済みブロックを再分配します。</p>\n'
                '<p>シンプロビジョニングのディスクを支える割り当て単位が<strong>スラブ</strong>です。\n'
                'ReFS のコンテナーに似ていますが、ストレージスタックのより下位にあり、仮想ディスクの割り当て単位として使います。\n'
                '既定のスラブサイズは256 MBです。\n'
                '基盤のストレージクラスターに十分な空き領域があれば、より大きくできます。\n'
                '記憶域スペースの中核は仮想ディスクのスラブを一つずつ追跡し、独自のアロケーターで動的に割り当てたり解放したりします。\n'
                'スラブは信頼性を確保する単位でもあります。\n'
                'ミラー構成やパリティ構成では、スラブ内のデータの冗長性がクラスター内で自動的に確保されます。</p>\n'
                '<p>シンプロビジョニングでも、作成時にディスクサイズを指定します。\n'
                'ファイルシステムはその仮想ディスクサイズを使って新しいボリュームをフォーマットし、必要なメタデータを作成します。\n'
                'ボリュームの準備ができると、記憶域スペースは、新しいデータが実際にディスクへ書き込まれた時点でスラブを割り当てます。\n'
                'この方式を書き込み時割り当てと呼びます。\n'
                '仮想ボリューム上のファイルシステムからは、基盤ディスクのプロビジョニング方式は分かりません。</p>\n'
                '<p>記憶域スペースはミラーやパリティを使って単一障害点をなくします。\n'
                '複数のディスクで構成する大規模ストレージクラスターでは、通常、パリティ方式に RAID 6 を採用します。\n'
                'RAID 6 は最大2台の基盤デバイスの故障に耐え、ユーザーの介入なしにデータを再構築できます。\n'
                'ただし、1台または2台が故障すると、アレイの再構築に時間がかかります。\n'
                '平均修復時間（MTTR）が長く、性能の大幅な低下につながることもあります。</p>\n'
                '<p>記憶域スペースは<strong>ローカル再構築符号</strong>（LRC）を使い、パリティを1単位追加する代わりに、大きなディスクアレイの再構築に必要な読み取りを減らします。\n'
                '図11-96に示すように、LRC はディスクアレイを複数の行に分け、行ごとにパリティを追加します。\n'
                'ディスクが故障した場合、同じ行のほかのディスクだけを読み取ればよく、再構築が速くなります。</p>\n'
                '<figure><p>RAID 6 の例には、データ D0〜D5 とパリティ P0、P1 があります。\n'
                'LRC の例では、データを D0、D2、D4 の行と D1、D3、D5 の行に分け、パリティ P0、P1、P2 を使います。</p>\n'
                '<figcaption>図11-96 RAID 6 と LRC のパリティ</figcaption></figure>\n'
                '<p>図11-96は、8台のドライブで構成するクラスターを例に、通常の RAID 6 と LRC のパリティ実装を比較しています。\n'
                'RAID 6 では、1台または2台が故障すると、失われた情報の再構築にほかの6台を読み取る必要があります。\n'
                'LRC では、故障したディスクと同じ行に属するディスクだけを読み取ります。</p>',
 'p2-page-805': '<h6>実験\u3000階層化ボリュームを作成する</h6>\n'
                '<p>記憶域スペースは Windows のサーバー版と Windows 10 のクライアント版で標準サポートされています。\n'
                '階層化ディスクは GUI または Windows PowerShell で作成できます。\n'
                'この実験では、Windows の起動ディスクに加え、空の SSD と空の回転式 HDD があるワークステーションで仮想階層化ディスクを作ります。\n'
                'Hyper-V でもこの構成を再現できます。その場合は一方の仮想ディスクファイルを SSD に、もう一方を回転式 HDD に置きます。</p>\n'
                '<p>スタートボタンを右クリックし、「Windows PowerShell（管理者）」を開きます。\n'
                'システムが取り付けた各ディスクの種類を認識していることを確認します。</p>\n'
                '<pre><code>PS C:&#92;&gt; Get-PhysicalDisk | FT DeviceId, FriendlyName, UniqueID, Size, '
                'MediaType, CanPool\n'
                'DeviceId FriendlyName\n'
                '                                   UniqueID\n'
                '                                                                  Size MediaType CanPool\n'
                '-------- ------------\n'
                '                                   --------\n'
                '                                                                  ---- --------- -------\n'
                '2\n'
                '         Samsung SSD 960 EVO 1TB eui.0025385C61B074F7 1000204886016 SSD\n'
                '                                                                                    False\n'
                '0\n'
                '         Micron 1100 SATA 512GB  500A071516EBA521\n'
                '                                                          512110190592 SSD\n'
                '                                                                                    True\n'
                '1\n'
                '         TOSHIBA DT01ACA200\n'
                '                                   500003F9E5D69494     2000398934016 HDD\n'
                '                                                                                    '
                'True</code></pre>\n'
                '<p>この例では SSD 2台と回転式 HDD 1台が識別されています。\n'
                '空のディスクの <code>CanPool</code> が <code>True</code> であることを確認します。\n'
                'そうでなければ、この例では有効なパーティションが残っており、プールで使う前に削除する必要があります。\n'
                '仮想環境では、基盤ディスクのメディアの種類をシステムが正しく識別できないことがあります。</p>\n'
                '<pre><code>PS C:&#92;&gt; Get-PhysicalDisk | FT DeviceId, FriendlyName, UniqueID, Size, '
                'MediaType, CanPool\n'
                'DeviceId FriendlyName\n'
                '                           UniqueID\n'
                '                                                                      Size MediaType   '
                'CanPool\n'
                '-------- ------------\n'
                '                           --------\n'
                '                                                                      ---- ---------   '
                '-------\n'
                '2\n'
                '         Msft Virtual Disk 600224802F4EE1E6B94595687DDE774B  137438953472 Unspecified    '
                'True\n'
                '1\n'
                '         Msft Virtual Disk 60022480170766A9A808A30797285D77 1099511627776 Unspecified    '
                'True\n'
                '0\n'
                '         Msft Virtual Disk 6002248048976A586FE149B00A43FC73  274877906944 Unspecified   '
                'False</code></pre>\n'
                '<p>その場合は <code>Set-PhysicalDisk -UniqueId (Get-PhysicalDisk)[&lt;IDX&gt;].UniqueID '
                '-MediaType &lt;Type&gt;</code> で種類を手動指定します。\n'
                '<code>IDX</code> は先ほどの出力における行のインデックスで、<code>Type</code> にはディスクに応じて <code>SSD</code> または '
                '<code>HDD</code> を指定します。</p>\n'
                '<pre><code>PS C:\\&gt; Set-PhysicalDisk -UniqueId (Get-PhysicalDisk)[0].UniqueID -MediaType '
                'SSD\n'
                'PS C:\\&gt; Set-PhysicalDisk -UniqueId (Get-PhysicalDisk)[1].UniqueID -MediaType HDD\n'
                'PS C:\\&gt; Get-PhysicalDisk | FT DeviceId, FriendlyName, UniqueID, Size, MediaType, '
                'CanPool\n'
                'DeviceId FriendlyName\n'
                '                           UniqueID\n'
                '                                                                      Size MediaType   '
                'CanPool\n'
                '-------- ------------\n'
                '                           --------\n'
                '                                                                      ---- ---------   '
                '-------\n'
                '2\n'
                '         Msft Virtual Disk 600224802F4EE1E6B94595687DDE774B  137438953472 SSD\n'
                '                                                                                           '
                'True\n'
                '1\n'
                '         Msft Virtual Disk 60022480170766A9A808A30797285D77 1099511627776 HDD\n'
                '                                                                                           '
                'True\n'
                '0\n'
                '         Msft Virtual Disk 6002248048976A586FE149B00A43FC73  274877906944 Unspecified   '
                'False</code></pre>',
 'p2-page-806': '<p>新しい仮想ディスクを構成する物理ディスクをまとめるストレージプールを作り、その中にストレージ階層を作ります。\n'
                'この例ではプール名を <code>DefaultPool</code> に統一しています。</p>\n'
                '<pre><code>PS C:\\&gt; New-StoragePool -StorageSubSystemId (Get-StorageSubSystem).UniqueId '
                '-FriendlyName DefaultPool -PhysicalDisks (Get-PhysicalDisk -CanPool $true)\n'
                'FriendlyName OperationalStatus HealthStatus IsPrimordial IsReadOnly    Size AllocatedSize\n'
                '------------ ----------------- ------------ ------------ ----------    ---- -------------\n'
                'DefaultPool  OK                Healthy      False\n'
                '                                                                 1.12 TB\n'
                '                                                                                 512 '
                'MB</code></pre>\n'
                '<pre><code>PS C:\\&gt; Get-StoragePool DefaultPool | New-StorageTier -FriendlyName SSD '
                '-MediaType SSD\n'
                '...\n'
                'PS C:\\&gt; Get-StoragePool DefaultPool | New-StorageTier -FriendlyName HDD -MediaType HDD\n'
                '...</code></pre>\n'
                '<p>仮想ディスク名と各階層の容量を指定して、階層化仮想ディスクを作ります。\n'
                '例では <code>TieredVirtualDisk</code> に128 GBのパフォーマンス層と1,000 '
                'GBの容量層を指定します。容量は原文のコマンドに合わせています。</p>\n'
                '<pre><code>PS C:\\&gt; $SSD = Get-StorageTier -FriendlyName SSD\n'
                'PS C:\\&gt; $HDD = Get-StorageTier -FriendlyName HDD\n'
                'PS C:\\&gt; Get-StoragePool DefaultPool | New-VirtualDisk -FriendlyName '
                '&quot;TieredVirtualDisk&quot;\n'
                '-ResiliencySettingName &quot;Simple&quot; -StorageTiers $SSD, $HDD -StorageTierSizes 128GB, '
                '1000GB\n'
                '...\n'
                'PS C:\\&gt; Get-VirtualDisk | FT FriendlyName, OperationalStatus, HealthStatus, Size, '
                'FootprintOnPool\n'
                'FriendlyName\n'
                '                   OperationalStatus HealthStatus\n'
                '                                                             Size FootprintOnPool\n'
                '------------\n'
                '                   ----------------- ------------\n'
                '                                                             ---- ---------------\n'
                'TieredVirtualDisk OK\n'
                '                                      Healthy\n'
                '                                                    1202590842880   '
                '1203664584704</code></pre>\n'
                '<p>仮想ディスクを作成したら、「ディスクの管理」スナップインや <code>Format</code> ツールなどでパーティションを作り、新しいボリュームをフォーマットします。\n'
                '完了後、<code>fsutil.exe</code> で階層化ボリュームになったことを確認できます。</p>\n'
                '<pre><code>PS E:\\&gt; fsutil tiering regionList e:\n'
                'このボリュームの領域数: 2\n'
                'この操作が返した領域数: 2\n'
                '階層 ID: {448ABAB8-F00B-42D6-B345-C8DA68869020}\n'
                '名前: TieredVirtualDisk-SSD\n'
                'オフセット: 0x0000000000000000\n'
                '長さ: 0x0000001dff000000\n'
                '階層 ID: {16A7BB83-CE3E-4996-8FF3-BEE98B68EBE4}\n'
                '名前: TieredVirtualDisk-HDD\n'
                'オフセット: 0x0000001dff000000\n'
                '長さ: 0x000000f9ffe00000</code></pre>',
 'p2-page-807': '<h3>まとめ</h3>\n'
                '<p>Windows はローカルシステムとリモートクライアントがアクセスできる多様なファイルシステム形式をサポートします。\n'
                'ファイルシステムフィルタードライバーによって、ファイルへのアクセスに機能を追加できます。\n'
                'NTFS と ReFS はどちらも、信頼性とセキュリティを備え、大規模化に対応するローカルストレージ用のファイルシステムです。\n'
                '比較的新しい ReFS は大規模サーバー向けの高度な機能を実装しています。\n'
                'NTFS も新しいデバイスや、POSIX 形式の削除、オンラインディスク検査、暗号化などの機能に対応するよう更新されました。</p>\n'
                '<p>キャッシュマネージャーはディスク I/O を減らし、システム全体のスループットを高めます。\n'
                '仮想ブロックを基準にキャッシュするため、ネットワーク上のリモートファイルシステムでも、アクセスの傾向に応じて先読みできます。\n'
                'システム全体を管理するメモリマネージャーのファイルマッピング機能でデータにアクセスすることで、キャッシュマネージャーは高速 I/O を提供し、読み書きに必要な CPU '
                '時間を減らします。\n'
                '物理メモリの管理は Windows のメモリマネージャーに任せるため、コードの重複が減り、効率が上がります。</p>\n'
                '<p>Windows は DAX と永続メモリディスク、記憶域スペースと記憶域スペースダイレクト、階層化ボリューム、SMR '
                'ディスクへの対応を通じて、可用性、信頼性、性能、クラウド規模の拡張性を重視する新しいストレージ構成を支えています。</p>\n'
                '<p>次章では、Windows の起動とシャットダウンを扱います。</p>'}
